void *lsx_malloc(size_t n) { void *p = malloc(n ? n : 1); if (!p) { fprintf(stderr, "out of memory\n"); exit(2); } return p; }
void *lsx_calloc(size_t n, size_t s) { void *p = calloc(n ? n : 1, s ? s : 1); if (!p) { fprintf(stderr, "out of memory\n"); exit(2); } return p; }
void *lsx_realloc(void *p, size_t n) { if (!n) { free(p); return NULL; } p = realloc(p, n); if (!p) { fprintf(stderr, "out of memory\n"); exit(2); } return p; }
char *lsx_strdup(const char *s) { char *r = lsx_malloc(strlen(s) + 1); strcpy(r, s); return r; }

int lsx_strcasecmp(const char *a, const char *b)
{
  while (*a && *b) { int d = tolower((unsigned char)*a) - tolower((unsigned char)*b); if (d) return d; a++; b++; }
  return tolower((unsigned char)*a) - tolower((unsigned char)*b);
}
int lsx_strncasecmp(const char *a, const char *b, size_t n)
{
  while (n && *a && *b) { int d = tolower((unsigned char)*a) - tolower((unsigned char)*b); if (d) return d; a++; b++; n--; }
  return n ? tolower((unsigned char)*a) - tolower((unsigned char)*b) : 0;
}
sox_bool lsx_strends(const char *str, const char *end)
{
  size_t str_len = strlen(str), end_len = strlen(end);
  return str_len >= end_len && !strcmp(str + str_len - end_len, end);
}
const char *lsx_find_file_extension(const char *pathname)
{
  size_t i, len = strlen(pathname);
  const char *p;
  /* skip directory part */
  for (i = len; i > 0 && pathname[i-1] != '/' && pathname[i-1] != '\\'; --i);
  p = strrchr(pathname + i, '.');
  return p ? p + 1 : NULL;
}

char const *lsx_sigfigs3(double number)
{
  static char const symbols[] = "\0kMGTPEZY";
  static char string[16][10];
  static unsigned n;
  unsigned a, b;
  char *s = string[n = (n + 1) & 15];
  for (a = 0; number >= 1000 && a < 8; number /= 1000, ++a);
  if (number < 10 && a) b = 2; else if (number < 10) b = number == (int)number ? 0 : 2;
  else if (number < 100) b = a || number != (int)number ? 1 : 0; else b = 0;
  /* match %.3g-like rounding */
  if (a == 0) {
    sprintf(s, "%.3g", number);
    return s;
  }
  sprintf(s, "%.*f%c", b, number, symbols[a]);
  return s;
}

char const *lsx_sigfigs3p(double percentage)
{
  static char string[16][10];
  static unsigned n;
  char *s = string[n = (n + 1) & 15];
  sprintf(s, "%.1f%%", percentage);
  if (strlen(s) > 5) sprintf(s, "%.0f%%", percentage);
  return s;
}

double lsx_dB_to_linear(double x) { return exp(x * M_LN10 * 0.05); }
double lsx_linear_to_dB(double x) { return log10(x) * 20; }

sox_bool lsx_is_power_of_2(unsigned long x) { return !(x < 2 || (x & (x - 1))); }

/* Parse time or sample count.  Returns pointer to end of parsed text, or NULL on error. */
static const char *parse_one(double rate, const char *str, double *result, int def)
{
  const char *end;
  double samples;
  sox_bool is_time = sox_false;
  const char *p;
  int has_colon = 0;
  for (p = str; *p && *p != '+' && *p != '-'; ++p) if (*p == ':') has_colon = 1;
  /* determine type by suffix */
  if (has_colon) is_time = sox_true;
  else {
    const char *q = p;
    while (q > str && (q[-1] == 't' || q[-1] == 's')) --q;
    if (q < p) {
      if (p - q != 1) return NULL;
      is_time = q[0] == 't';
    } else is_time = def == 't';
  }
  if (is_time) {
    double total = 0;
    char *e;
    if (has_colon) {
      /* [[hh:]mm:]ss */
      const char *q = str;
      int parts = 0;
      for (;;) {
        double v = 0;
        if (*q == ':') { e = (char*)q; }
        else {
          v = strtod(q, &e);
          if (e == q) return NULL;
        }
        total = total * 60 + v;
        ++parts;
        if (*e == ':') { q = e + 1; if (parts >= 3) return NULL; continue; }
        break;
      }
      if (parts > 3) return NULL;
    } else {
      total = strtod(str, &e);
      if (e == str) return NULL;
    }
    if (*e == 't') ++e;
    if (e != p) return NULL;
    samples = total * rate + 0.5;
    *result = floor(samples);
    return p;
  } else {
    char *e;
    double v = strtod(str, &e);
    if (e == str) return NULL;
    if (*e == 's') ++e;
    if (e != p) return NULL;
    if (v != floor(v)) return NULL;
    *result = v;
    return p;
  }
}

char const *lsx_parsesamples(double rate, const char *str, uint64_t *samples, int def)
{
  double total = 0, v;
  const char *end;
  int sign = 1;
  if (!str || !*str) return NULL;
  for (;;) {
    end = parse_one(rate, str, &v, def);
    if (!end) return NULL;
    total += sign * v;
    if (*end == '+') { sign = 1; str = end + 1; }
    else if (*end == '-') { sign = -1; str = end + 1; }
    else break;
    if (!*str) return NULL;
  }
  if (total < 0) total = 0;
  *samples = (uint64_t)total;
  return end;
}

char const *lsx_parseposition(double rate, const char *str, uint64_t *samples, uint64_t latest, uint64_t end, int def)
{
  char anchor = def;
  const char *res;
  uint64_t v;
  if (*str == '=' || *str == '+' || *str == '-') anchor = *str++;
  res = lsx_parsesamples(rate, str, &v, 't');
  if (!res) return NULL;
  if (anchor == '=') *samples = v;
  else if (anchor == '+') *samples = latest + v;
  else {
    if (end == SOX_UNKNOWN_LEN) return NULL;
    *samples = v > end ? 0 : end - v;
  }
  return res;
}

double lsx_parse_frequency_k(const char *text, char **end, int key)
{
  double result;
  if (*text == '%') {
    /* note relative to key */
    result = strtod(text + 1, end);
    if (*end == text + 1) { *end = (char*)text; return 0; }
    if (key == INT_MAX) key = 0;
    return 440 * pow(2., (key + result) / 12.);
  }
  result = strtod(text, end);
  if (*end == text) return 0;
  if (**end == 'k') { result *= 1000; ++*end; }
  return result;
}

const lsx_enum_item *lsx_find_enum_text(const char *text, const lsx_enum_item *items, int flags)
{
  const lsx_enum_item *result = NULL;
  int (*cmp)(const char *, const char *, size_t) = (flags & LSX_FET_CASE) ? strncmp : lsx_strncasecmp;
  size_t len = strlen(text);
  while (items->text) {
    if (!cmp(text, items->text, len)) {
      if (strlen(items->text) == len) return items;  /* exact */
      if (result) return NULL; /* ambiguous */
      result = items;
    }
    ++items;
  }
  return result;
}

const lsx_enum_item *lsx_find_enum_value(unsigned value, const lsx_enum_item *items)
{
  for (; items->text; ++items) if (value == items->value) return items;
  return NULL;
}

int lsx_enum_option(int c, const char *arg, const lsx_enum_item *items)
{
  const lsx_enum_item *p = lsx_find_enum_text(arg, items, 0);
  if (!p) {
    size_t len = 1;
    char *set = lsx_malloc(len);
    *set = 0;
    for (p = items; p->text; ++p) {
      set = lsx_realloc(set, len += 2 + strlen(p->text));
      strcat(set, ", "); strcat(set, p->text);
    }
    lsx_set_subsystem("getopt");
    lsx_fail_impl("-%c: `%s' is not one of: %s.", c, arg, set + 2);
    free(set);
    return INT_MAX;
  }
  return p->value;
}

/* getopt */
int lsx_optind = 1, lsx_opterr = 1, lsx_optopt;
char *lsx_optarg;

void lsx_getopt_init(int argc, char * const *argv, const char *shortopts, const lsx_option_t *longopts, int flags, int first, lsx_getopt_t *state)
{
  state->argc = argc; state->argv = argv; state->shortopts = shortopts; state->longopts = longopts;
  state->flags = flags; state->arg = NULL; state->ind = first; state->opterr = 0; state->lngind = 0; state->curpos = NULL;
}

static int getopt_fail(lsx_getopt_t *state, const char *fmt, ...)
{
  if (state->flags & lsx_getopt_flag_opterr) {
    va_list ap; va_start(ap, fmt);
    lsx_output_message(2, "getopt", fmt, ap);
    va_end(ap);
  }
  return '?';
}

int lsx_getopt_s(lsx_getopt_t *state)
{
  const char *shortopts = state->shortopts;
  int want_arg;
  state->arg = NULL; state->lngind = 0;
  if (!state->curpos || !*state->curpos) {
    const char *cur;
    if (state->ind >= state->argc) return -1;
    cur = state->argv[state->ind];
    if (cur[0] != '-' || !cur[1]) return -1;
    if (!strcmp(cur, "--")) { state->ind++; return -1; }
    if (cur[1] == '-' || (state->flags & lsx_getopt_flag_longonly)) {
      /* long option */
      const char *name = cur + (cur[1] == '-' ? 2 : 1);
      const char *eq = strchr(name, '=');
      size_t len = eq ? (size_t)(eq - name) : strlen(name);
      const lsx_option_t *o, *found = NULL;
      int nfound = 0;
      state->ind++;
      if (state->longopts) for (o = state->longopts; o->name; ++o) {
        if (!strncmp(o->name, name, len)) {
          if (strlen(o->name) == len) { found = o; nfound = 1; break; }
          if (!found) found = o;
          nfound++;
        }
      }
      if (!found || nfound > 1) {
        if (cur[1] != '-' && state->flags & lsx_getopt_flag_longonly && !eq && len == 1) {
          /* fall through to short */
          state->ind--;
        } else {
          state->curpos = NULL;
          return getopt_fail(state, "%s not recognized from `%s'", nfound > 1 ? "ambiguous option" : "parameter", cur);
        }
      } else {
        state->curpos = NULL;
        state->lngind = (int)(found - state->longopts);
        if (found->has_arg == lsx_option_arg_none) {
          if (eq) return getopt_fail(state, "option `%s' doesn't allow an argument", cur);
        } else if (eq) state->arg = (char*)eq + 1;
        else if (found->has_arg == lsx_option_arg_required) {
          if (state->ind >= state->argc) return getopt_fail(state, "missing argument for option `%s'", cur);
          state->arg = state->argv[state->ind++];
        }
        if (found->flag) { *found->flag = found->val; return 0; }
        return found->val;
      }
    }
    state->curpos = (char*)cur + 1;
    state->ind++;
  }
  {
    char c = *state->curpos++;
    const char *p = c == ':' ? NULL : strchr(shortopts, c);
    if (!p) {
      int r = getopt_fail(state, "option `%c' not recognized", c);
      if (!*state->curpos) state->curpos = NULL;
      return r;
    }
    want_arg = p[1] == ':' ? (p[2] == ':' ? 2 : 1) : 0;
    if (want_arg == 2) {
      if (*state->curpos) { state->arg = state->curpos; }
      state->curpos = NULL;
    } else if (want_arg == 1) {
      if (*state->curpos) state->arg = state->curpos;
      else if (state->ind < state->argc) state->arg = state->argv[state->ind++];
      else { state->curpos = NULL; return getopt_fail(state, "missing argument for option `%c'", c); }
      state->curpos = NULL;
    } else if (!*state->curpos) state->curpos = NULL;
    return c;
  }
}

static lsx_getopt_t g_state;
static int g_inited;
int lsx_getopt(int argc, char * const *argv, const char *shortopts, const lsx_option_t *longopts, int *longind)
{
  int r;
  if (!g_inited || g_state.argv != argv || g_state.ind > lsx_optind) {
    int flags = lsx_getopt_flag_opterr;
    if (*shortopts == '+') shortopts++;
    lsx_getopt_init(argc, argv, shortopts, longopts, flags, lsx_optind, &g_state);
    g_inited = 1;
  } else { g_state.ind = lsx_optind; g_state.shortopts = *shortopts == '+' ? shortopts + 1 : shortopts; g_state.longopts = longopts; }
  r = lsx_getopt_s(&g_state);
  lsx_optind = g_state.ind;
  lsx_optarg = g_state.arg;
  if (longind) *longind = g_state.lngind;
  return r;
}
void lsx_getopt_reset(void) { g_inited = 0; lsx_optind = 1; }

/* comments */
size_t sox_num_comments(sox_comments_t comments)
{
  size_t n = 0;
  if (!comments) return 0;
  while (*comments++) ++n;
  return n;
}
void lsx_append_comment(sox_comments_t *comments, const char *item)
{
  size_t n = sox_num_comments(*comments);
  *comments = lsx_realloc(*comments, (n + 2) * sizeof(**comments));
  assert(item);
  (*comments)[n++] = lsx_strdup(item);
  (*comments)[n] = NULL;
}
void lsx_append_comments(sox_comments_t *comments, const char *items)
{
  char *text = lsx_strdup(items), *p, *q;
  for (p = text; *p; p = q) {
    q = strchr(p, '\n');
    if (q) *q++ = 0; else q = p + strlen(p);
    lsx_append_comment(comments, p);
  }
  free(text);
}
sox_comments_t lsx_copy_comments(sox_comments_t comments)
{
  sox_comments_t result = NULL;
  size_t i;
  if (comments) for (i = 0; comments[i]; ++i) lsx_append_comment(&result, comments[i]);
  return result;
}
void lsx_delete_comments(sox_comments_t *comments)
{
  sox_comments_t p = *comments;
  if (!p) return;
  for (; *p; ++p) free(*p);
  free(*comments);
  *comments = NULL;
}
char *lsx_cat_comments(sox_comments_t comments)
{
  sox_comments_t p = comments;
  size_t len = 0;
  char *result;
  if (p) while (*p) len += strlen(*p++) + 1;
  result = lsx_calloc(len ? len : 1, 1);
  if ((p = comments) && *p) {
    strcpy(result, *p);
    while (*++p) strcat(strcat(result, "\n"), *p);
  }
  return result;
}
const char *sox_find_comment(sox_comments_t comments, const char *id)
{
  size_t len = strlen(id);
  if (comments) for (; *comments; ++comments)
    if (!lsx_strncasecmp(*comments, id, len) && (*comments)[len] == '=')
      return *comments + len + 1;
  return NULL;
}
