        state->lngind = (int)(found - state->longopts);
        if (found->has_arg == lsx_option_arg_none) {
          if (eq) return getopt_fail(state, "option `%s' doesn't allow an argument", cur);
        } else if (eq) state->arg = (char*)eq + 1;
        else if (found->has_arg == lsx_option_arg_required) {
          if (state->ind >= state->argc) return getopt_fail(state, "missing argument for option `%s'", cur);
          state->arg = state->argv[state->ind++];
        }
        if (found->flag) { *found->flag = found->val; return 0; }
        return found->val;
      }
    }
    state->curpos = (char*)cur + 1;
    state->ind++;
  }
  {
    char c = *state->curpos++;
    const char *p = c == ':' ? NULL : strchr(shortopts, c);
    if (!p) {
      int r = getopt_fail(state, "option `%c' not recognized", c);
      if (!*state->curpos) state->curpos = NULL;
      return r;
    }
    want_arg = p[1] == ':' ? (p[2] == ':' ? 2 : 1) : 0;
    if (want_arg == 2) {
      if (*state->curpos) { state->arg = state->curpos; }
      state->curpos = NULL;
    } else if (want_arg == 1) {
      if (*state->curpos) state->arg = state->curpos;
      else if (state->ind < state->argc) state->arg = state->argv[state->ind++];
      else { state->curpos = NULL; return getopt_fail(state, "missing argument for option `%c'", c); }
      state->curpos = NULL;
    } else if (!*state->curpos) state->curpos = NULL;
    return c;
  }
}

static lsx_getopt_t g_state;
static int g_inited;
int lsx_getopt(int argc, char * const *argv, const char *shortopts, const lsx_option_t *longopts, int *longind)
{
  int r;
  if (!g_inited || g_state.argv != argv || g_state.ind > lsx_optind) {
    int flags = lsx_getopt_flag_opterr;
    if (*shortopts == '+') shortopts++;
    lsx_getopt_init(argc, argv, shortopts, longopts, flags, lsx_optind, &g_state);
    g_inited = 1;
  } else { g_state.ind = lsx_optind; g_state.shortopts = *shortopts == '+' ? shortopts + 1 : shortopts; g_state.longopts = longopts; }
  r = lsx_getopt_s(&g_state);
  lsx_optind = g_state.ind;
  lsx_optarg = g_state.arg;
  if (longind) *longind = g_state.lngind;
  return r;
}
void lsx_getopt_reset(void) { g_inited = 0; lsx_optind = 1; }

/* comments */
size_t sox_num_comments(sox_comments_t comments)
{
  size_t n = 0;
  if (!comments) return 0;
  while (*comments++) ++n;
  return n;
}
void lsx_append_comment(sox_comments_t *comments, const char *item)
{
  size_t n = sox_num_comments(*comments);
  *comments = lsx_realloc(*comments, (n + 2) * sizeof(**comments));
  assert(item);
  (*comments)[n++] = lsx_strdup(item);
  (*comments)[n] = NULL;
}
void lsx_append_comments(sox_comments_t *comments, const char *items)
{
  char *text = lsx_strdup(items), *p, *q;
  for (p = text; *p; p = q) {
    q = strchr(p, '\n');
    if (q) *q++ = 0; else q = p + strlen(p);
    lsx_append_comment(comments, p);
  }
  free(text);
}
sox_comments_t lsx_copy_comments(sox_comments_t comments)
{
  sox_comments_t result = NULL;
  size_t i;
  if (comments) for (i = 0; comments[i]; ++i) lsx_append_comment(&result, comments[i]);
  return result;
}
void lsx_delete_comments(sox_comments_t *comments)
{
  sox_comments_t p = *comments;
  if (!p) return;
  for (; *p; ++p) free(*p);
  free(*comments);
  *comments = NULL;
}
char *lsx_cat_comments(sox_comments_t comments)
{
  sox_comments_t p = comments;
  size_t len = 0;
  char *result;
  if (p) while (*p) len += strlen(*p++) + 1;
  result = lsx_calloc(len ? len : 1, 1);
  if ((p = comments) && *p) {
    strcpy(result, *p);
    while (*++p) strcat(strcat(result, "\n"), *p);
  }
  return result;
}
const char *sox_find_comment(sox_comments_t comments, const char *id)
{
  size_t len = strlen(id);
  if (comments) for (; *comments; ++comments)
    if (!lsx_strncasecmp(*comments, id, len) && (*comments)[len] == '=')
      return *comments + len + 1;
  return NULL;
}
