#include "g711.h"

#define SIGN_BIT (0x80)
#define QUANT_MASK (0xf)
#define NSEGS (8)
#define SEG_SHIFT (4)
#define SEG_MASK (0x70)
#define BIAS (0x84)
#define CLIP 8159

static const short seg_aend[8] = {0x1F, 0x3F, 0x7F, 0xFF, 0x1FF, 0x3FF, 0x7FF, 0xFFF};
static const short seg_uend[8] = {0x3F, 0x7F, 0xFF, 0x1FF, 0x3FF, 0x7FF, 0xFFF, 0x1FFF};

static int search(int val, const short *table, int size)
{
  int i;
  for (i = 0; i < size; i++) if (val <= *table++) return i;
  return size;
}

/* pcm_val is 13-bit signed */
unsigned char lsx_13linear2alaw(int pcm_val)
{
  int mask, seg;
  unsigned char aval;
  if (pcm_val >= 0) mask = 0xD5;
  else { mask = 0x55; pcm_val = -pcm_val - 1; }
  seg = search(pcm_val, seg_aend, 8);
  if (seg >= 8) return (unsigned char)(0x7F ^ mask);
  aval = (unsigned char)seg << SEG_SHIFT;
  if (seg < 2) aval |= (pcm_val >> 1) & QUANT_MASK;
  else aval |= (pcm_val >> seg) & QUANT_MASK;
  return aval ^ mask;
}

int lsx_alaw2linear16(unsigned char a_val)
{
  int t, seg;
  a_val ^= 0x55;
  t = (a_val & QUANT_MASK) << 4;
  seg = ((unsigned)a_val & SEG_MASK) >> SEG_SHIFT;
  switch (seg) {
  case 0: t += 8; break;
  case 1: t += 0x108; break;
  default: t += 0x108; t <<= seg - 1;
  }
  return (a_val & SIGN_BIT) ? t : -t;
}

/* pcm_val is 14-bit signed */
unsigned char lsx_14linear2ulaw(int pcm_val)
{
  int mask, seg;
  unsigned char uval;
  if (pcm_val < 0) { pcm_val = -pcm_val; mask = 0x7F; }
  else mask = 0xFF;
  if (pcm_val > CLIP) pcm_val = CLIP;
  pcm_val += (BIAS >> 2);
  seg = search(pcm_val, seg_uend, 8);
  if (seg >= 8) return (unsigned char)(0x7F ^ mask);
  uval = (unsigned char)(seg << 4) | ((pcm_val >> (seg + 1)) & 0xF);
  return uval ^ mask;
}

int lsx_ulaw2linear16(unsigned char u_val)
{
  int t;
  u_val = ~u_val;
  t = ((u_val & QUANT_MASK) << 3) + BIAS;
  t <<= ((unsigned)u_val & SEG_MASK) >> SEG_SHIFT;
  return (u_val & SIGN_BIT) ? (BIAS - t) : (t - BIAS);
}

static unsigned char ulaw_tab[16384], alaw_tab[8192];
static short ulaw2lin[256], alaw2lin[256];
static int tabs_inited;
static void init_tabs(void)
{
  int i;
  for (i = 0; i < 16384; i++) ulaw_tab[i] = lsx_14linear2ulaw(i - 8192);
  for (i = 0; i < 8192; i++) alaw_tab[i] = lsx_13linear2alaw(i - 4096);
