#define lsx_subsystem_name "formats"
#include "sox.h"
#include <sys/stat.h>
#include <unistd.h>

void lsx_fail_errno(sox_format_t *ft, int err, const char *fmt, ...)
{
  va_list ap;
  ft->sox_errno = err;
  va_start(ap, fmt);
  if (err == 0 || (err >= SOX_EHDR && err <= SOX_EINVAL) || err == SOX_EOF) {
    vsnprintf(ft->sox_errstr, sizeof ft->sox_errstr, fmt, ap);
  } else {
    char buf[256];
    vsnprintf(buf, sizeof buf, fmt, ap);
    snprintf(ft->sox_errstr, sizeof ft->sox_errstr, "%s: %s", buf, strerror(err));
    /* sox uses strerror text; but keep message simple */
    strcpy(ft->sox_errstr, strerror(err));
  }
  va_end(ap);
  ft->sox_errstr[255] = 0;
}

int lsx_readbuf(sox_format_t *ft, void *buf, size_t len)
{
  size_t ret = fread(buf, 1, len, ft->fp);
  if (ret != len && ferror(ft->fp)) lsx_fail_errno(ft, errno, "lsx_readbuf");
  ft->tell_off += ret;
  return (int)ret;
}
size_t lsx_readbuf_n(sox_format_t *ft, void *buf, size_t len) { return (size_t)lsx_readbuf(ft, buf, len); }

int lsx_skipbytes(sox_format_t *ft, size_t n)
{
  unsigned char trash;
  size_t i;
  for (i = 0; i < n; ++i) if (lsx_readb(ft, &trash) == SOX_EOF) return SOX_EOF;
  return SOX_SUCCESS;
}
int lsx_padbytes(sox_format_t *ft, size_t n)
{
  size_t i;
  for (i = 0; i < n; ++i) if (lsx_writeb(ft, 0) == SOX_EOF) return SOX_EOF;
  return SOX_SUCCESS;
}
int lsx_writebuf(sox_format_t *ft, const void *buf, size_t len)
{
  size_t ret = fwrite(buf, 1, len, ft->fp);
  if (ret != len) { lsx_fail_errno(ft, errno, "error writing output file"); clearerr(ft->fp); }
  ft->tell_off += ret;
  return (int)ret;
}
size_t lsx_writebuf_n(sox_format_t *ft, const void *buf, size_t len) { return (size_t)lsx_writebuf(ft, buf, len); }

uint64_t lsx_filelength(sox_format_t *ft)
{
  struct stat st;
  int fd = fileno(ft->fp);
  return (fd >= 0 && !fstat(fd, &st) && S_ISREG(st.st_mode)) ? (uint64_t)st.st_size : 0;
}
int lsx_flush(sox_format_t *ft) { return fflush(ft->fp); }
int lsx_seeki(sox_format_t *ft, int64_t offset, int whence)
{
  if (ft->seekable == 0) {
    /* can only seek forward on a pipe */
    if (whence == SEEK_SET && (uint64_t)offset >= ft->tell_off) { offset -= ft->tell_off; whence = SEEK_CUR; }
    if (whence != SEEK_CUR || offset < 0) { lsx_fail_errno(ft, SOX_EPERM, "File not seekable"); return SOX_EOF; }
    if (lsx_skipbytes(ft, (size_t)offset) != SOX_SUCCESS) return SOX_EOF;
    return SOX_SUCCESS;
  }
  if (fseeko(ft->fp, (off_t)offset, whence) == -1) { lsx_fail_errno(ft, errno, "%s", strerror(errno)); return SOX_EOF; }
  ft->tell_off = (uint64_t)ftello(ft->fp);
  return SOX_SUCCESS;
}
uint64_t lsx_tell(sox_format_t *ft) { return ft->seekable ? (uint64_t)ftello(ft->fp) : ft->tell_off; }
int lsx_eof(sox_format_t *ft) { return feof(ft->fp); }
int lsx_error(sox_format_t *ft) { return ferror(ft->fp); }
void lsx_rewind(sox_format_t *ft) { rewind(ft->fp); ft->tell_off = 0; }
void lsx_clearerr(sox_format_t *ft) { clearerr(ft->fp); ft->sox_errno = 0; }
int lsx_unreadb(sox_format_t *ft, unsigned ub) { ft->tell_off--; return ungetc((int)ub, ft->fp); }

int lsx_readchars(sox_format_t *ft, char *chars, size_t len)
{
  size_t ret = lsx_readbuf(ft, chars, len);
  if (ret == len) return SOX_SUCCESS;
  if (lsx_error(ft) || ret) lsx_fail_errno(ft, errno, "premature EOF");
  return SOX_EOF;
}
int lsx_reads(sox_format_t *ft, char *c, size_t len)
{
  char *sc = c;
  char in;
  while (len--) {
    if (lsx_readbuf(ft, &in, 1) != 1) { *sc = 0; return SOX_EOF; }
    if (in == 0 || in == '\n') break;
    *sc++ = in;
  }
  *sc = 0;
  return SOX_SUCCESS;
}
int lsx_writes(sox_format_t *ft, const char *c)
{
  if (lsx_writebuf(ft, c, strlen(c)) != (int)strlen(c)) return SOX_EOF;
  return SOX_SUCCESS;
}

static void swapw(uint16_t *x) { *x = (uint16_t)((*x >> 8) | (*x << 8)); }
static void swapdw(uint32_t *x) { *x = (*x >> 24) | ((*x >> 8) & 0xff00) | ((*x << 8) & 0xff0000) | (*x << 24); }
static void swapqw(uint64_t *x) { uint32_t lo = (uint32_t)*x, hi = (uint32_t)(*x >> 32); swapdw(&lo); swapdw(&hi); *x = ((uint64_t)lo << 32) | hi; }
static void swapf(float *f) { uint32_t u; memcpy(&u, f, 4); swapdw(&u); memcpy(f, &u, 4); }
static void swapdf(double *d) { uint64_t u; memcpy(&u, d, 8); swapqw(&u); memcpy(d, &u, 8); }

#define READ1(name, type, swapfn) \
  int name(sox_format_t *ft, type *v) { \
    if (lsx_readbuf(ft, v, sizeof *v) != (int)sizeof *v) { lsx_fail_errno(ft, errno, "premature EOF"); return SOX_EOF; } \
    if (ft->encoding.reverse_bytes) swapfn(v); return SOX_SUCCESS; }
#define WRITE1(name, type, argtype, swapfn) \
  int name(sox_format_t *ft, argtype a) { type v = (type)a; \
    if (ft->encoding.reverse_bytes) swapfn(&v); \
    if (lsx_writebuf(ft, &v, sizeof v) != (int)sizeof v) return SOX_EOF; return SOX_SUCCESS; }

int lsx_readb(sox_format_t *ft, uint8_t *ub)
{
  if (lsx_readbuf(ft, ub, 1) != 1) { lsx_fail_errno(ft, errno, "premature EOF"); return SOX_EOF; }
  return SOX_SUCCESS;
}
int lsx_writeb(sox_format_t *ft, unsigned ub) { uint8_t b = (uint8_t)ub; if (lsx_writebuf(ft, &b, 1) != 1) return SOX_EOF; return SOX_SUCCESS; }
READ1(lsx_readw, uint16_t, swapw)
WRITE1(lsx_writew, uint16_t, unsigned, swapw)
READ1(lsx_readdw, uint32_t, swapdw)
WRITE1(lsx_writedw, uint32_t, unsigned, swapdw)
READ1(lsx_readqw, uint64_t, swapqw)
WRITE1(lsx_writeqw, uint64_t, uint64_t, swapqw)
READ1(lsx_readf, float, swapf)
WRITE1(lsx_writef, float, double, swapf)
READ1(lsx_readdf, double, swapdf)
WRITE1(lsx_writedf, double, double, swapdf)
int lsx_read3(sox_format_t *ft, uint32_t *u3)
{
  uint8_t b[3];
  if (lsx_readbuf(ft, b, 3) != 3) { lsx_fail_errno(ft, errno, "premature EOF"); return SOX_EOF; }
  if (ft->encoding.reverse_bytes) *u3 = ((uint32_t)b[0] << 16) | ((uint32_t)b[1] << 8) | b[2];
  else *u3 = ((uint32_t)b[2] << 16) | ((uint32_t)b[1] << 8) | b[0];
  return SOX_SUCCESS;
}
int lsx_write3(sox_format_t *ft, unsigned u3)
{
  uint8_t b[3];
  if (ft->encoding.reverse_bytes) { b[0] = u3 >> 16; b[1] = u3 >> 8; b[2] = u3; }
  else { b[2] = u3 >> 16; b[1] = u3 >> 8; b[0] = u3; }
  if (lsx_writebuf(ft, b, 3) != 3) return SOX_EOF;
  return SOX_SUCCESS;
}
int lsx_readsb(sox_format_t *ft, int8_t *sb) { return lsx_readb(ft, (uint8_t*)sb); }
int lsx_readsw(sox_format_t *ft, int16_t *sw) { return lsx_readw(ft, (uint16_t*)sw); }
int lsx_writesb(sox_format_t *ft, int sb) { return lsx_writeb(ft, (unsigned)sb); }
int lsx_writesw(sox_format_t *ft, int sw) { return lsx_writew(ft, (unsigned)sw); }

/* buffer versions */
size_t lsx_read_b_buf(sox_format_t *ft, uint8_t *buf, size_t len) { return (size_t)lsx_readbuf(ft, buf, len); }
