static void set_endiannesses(sox_format_t *ft)
{
  const int machine_is_bigendian = 0;
  if (ft->encoding.opposite_endian)
    ft->encoding.reverse_bytes = (ft->handler.flags & SOX_FILE_ENDIAN) ? !(ft->handler.flags & SOX_FILE_ENDBIG) != machine_is_bigendian : sox_true;
  else if (ft->encoding.reverse_bytes == sox_option_default)
    ft->encoding.reverse_bytes = (ft->handler.flags & SOX_FILE_ENDIAN) ? !(ft->handler.flags & SOX_FILE_ENDBIG) == machine_is_bigendian : sox_false;

  if (ft->handler.flags & SOX_FILE_ENDIAN) {
    if (ft->encoding.reverse_bytes == (sox_bool)(!(ft->handler.flags & SOX_FILE_ENDBIG) != machine_is_bigendian))
      lsx_report("`%s': overriding file-type byte-order", ft->filename);
  } else if (ft->encoding.reverse_bytes == sox_true)
    lsx_report("`%s': overriding machine byte-order", ft->filename);

  if (ft->encoding.reverse_bits == sox_option_default)
    ft->encoding.reverse_bits = !!(ft->handler.flags & SOX_FILE_BIT_REV);
  else if (ft->encoding.reverse_bits == !(ft->handler.flags & SOX_FILE_BIT_REV))
    lsx_report("`%s': overriding file-type bit-order", ft->filename);

  if (ft->encoding.reverse_nibbles == sox_option_default)
    ft->encoding.reverse_nibbles = !!(ft->handler.flags & SOX_FILE_NIB_REV);
  else if (ft->encoding.reverse_nibbles == !(ft->handler.flags & SOX_FILE_NIB_REV))
    lsx_report("`%s': overriding file-type nibble-order", ft->filename);
}

static sox_bool is_seekable(sox_format_t *ft)
{
  struct stat st;
  if (!ft->fp) return sox_false;
  fstat(fileno(ft->fp), &st);
  return S_ISREG(st.st_mode);
}

static void sox_format_free(sox_format_t *ft)
{
  if (!ft) return;
  free(ft->priv);
  free(ft->filename);
  free(ft->filetype);
  lsx_delete_comments(&ft->oob.comments);
  free(ft);
}

static sox_bool stdin_in_use;
sox_bool lsx_stdin_in_use;

sox_format_t *sox_open_read(const char *path, const sox_signalinfo_t *signal, const sox_encodinginfo_t *encoding, const char *filetype)
{
  sox_format_t *ft = lsx_calloc(1, sizeof *ft);
  const sox_format_handler_t *handler;
  const char *const io_types[] = {"file", "pipe", "URL"};
  int io_type = 0;

  if (filetype) {
    if (!(handler = sox_find_format(filetype, sox_false))) {
      lsx_fail("no handler for given file type `%s'", filetype);
      goto error;
    }
    ft->handler = *handler;
  }
  if (!(ft->handler.flags & SOX_FILE_NOSTDIO)) {
    if (!strcmp(path, "-")) {
      if (lsx_stdin_in_use) {
        lsx_fail("only one input file can be read from stdin");
        goto error;
      }
      lsx_stdin_in_use = sox_true;
      ft->fp = stdin;
      io_type = 1;
    } else if (*path == '|') {
      ft->fp = popen(path + 1, "r");
      io_type = 1;
      if (!ft->fp) { lsx_fail("can't open input pipe `%s': %s", path, strerror(errno)); goto error; }
    } else {
      ft->fp = fopen(path, "rb");
      if (!ft->fp) { lsx_fail("can't open input file `%s': %s", path, strerror(errno)); goto error; }
    }
    ft->seekable = is_seekable(ft);
    if (io_type == 1 && ft->fp == stdin && ft->seekable) io_type = 0;
  }
  if (!filetype) {
    if (ft->seekable) {
      filetype = auto_detect_format(ft, lsx_find_file_extension(path));
      lsx_rewind(ft);
    } else if (ft->fp) {
      filetype = auto_detect_format(ft, lsx_find_file_extension(path));
      rewind_pipe(ft->fp);
    }
    if (filetype) {
      lsx_report("detected file format type `%s'", filetype);
      if (!(handler = sox_find_format(filetype, sox_false))) {
        lsx_fail("no handler for detected file type `%s'", filetype);
        goto error;
      }
    } else {
      if (!(filetype = lsx_find_file_extension(path))) {
        lsx_fail("can't determine type of %s `%s'", io_type == 1 ? "pipe" : "file", path);
        goto error;
      }
      if (!(handler = sox_find_format(filetype, sox_true))) {
        lsx_fail("no handler for file extension `%s'", filetype);
        goto error;
      }
    }
    ft->handler = *handler;
    if (ft->handler.flags & SOX_FILE_NOSTDIO && ft->fp) { fclose(ft->fp); ft->fp = NULL; }
  }
  if (!ft->handler.startread && !ft->handler.read) {
    lsx_fail("file type `%s' isn't readable", filetype);
    goto error;
  }
  ft->mode = 'r';
  ft->filetype = lsx_strdup(filetype);
  ft->filename = lsx_strdup(path);
  if (signal) ft->signal = *signal;
  if (encoding) ft->encoding = *encoding; else sox_init_encodinginfo(&ft->encoding);
  set_endiannesses(ft);
  ft->priv = lsx_calloc(1, ft->handler.priv_len);
  if (ft->handler.startread && (*ft->handler.startread)(ft) != SOX_SUCCESS) {
    lsx_fail("can't open input %s `%s': %s", io_type == 1 ? "" : io_types[io_type], ft->filename, ft->sox_errstr);
    goto error;
  }
  /* Fill in some defaults */
  if (sox_precision(ft->encoding.encoding, ft->encoding.bits_per_sample))
    ft->signal.precision = sox_precision(ft->encoding.encoding, ft->encoding.bits_per_sample);
  if (!(ft->handler.flags & SOX_FILE_PHONY) && !ft->signal.channels) ft->signal.channels = 1;
  if (ft->signal.rate <= 0 || ft->signal.rate != ft->signal.rate) {
    lsx_fail("bad input format for file `%s': %s", ft->filename, "sample rate zero or negative");
    goto error;
  }
  if (!ft->signal.precision) {
    lsx_fail("bad input format for file `%s': %s", ft->filename, "data encoding or sample size was not specified");
    goto error;
  }
  if (!ft->signal.channels) {
    lsx_fail("bad input format for file `%s': %s", ft->filename, "channel count not specified");
    goto error;
  }
  if (ft->signal.length == SOX_IGNORE_LENGTH) ft->signal.length = SOX_UNSPEC;
  if (ft->encoding.reverse_bytes == sox_option_default) ft->encoding.reverse_bytes = sox_false;
  return ft;

error:
  if (ft->fp && ft->fp != stdin) fclose(ft->fp);
  sox_format_free(ft);
  return NULL;
}

static sox_bool encoding_in_list(const unsigned *list, sox_encoding_t e, unsigned bits, sox_bool check_bits)
{
  unsigned i, s;
  if (!list) return sox_false;
  for (i = 0; list[i]; ++i) {
    if (list[i] == e) {
      if (!check_bits) return sox_true;
      for (s = i + 1; list[s]; ++s) if (list[s] == bits) return sox_true;
    }
    while (list[++i]);
  }
  return sox_false;
}

sox_bool sox_format_supports_encoding(const char *path, const char *filetype, const sox_encodinginfo_t *encoding)
{
  const sox_format_handler_t *handler;
  if (!filetype) {
    filetype = path ? lsx_find_file_extension(path) : NULL;
    if (!filetype) return sox_false;
  }
  handler = sox_find_format(filetype, sox_false);
  if (!handler || !handler->write_formats) return sox_false;
  return encoding_in_list(handler->write_formats, encoding->encoding, encoding->bits_per_sample, encoding->bits_per_sample != 0);
}

/* Choose the best encoding/bits for the output format */
static void set_output_format(sox_format_t *ft)
{
  const unsigned *encodings = ft->handler.write_formats;
  unsigned i, s;
  sox_encoding_t e = ft->encoding.encoding;
  unsigned bits = ft->encoding.bits_per_sample;

  if (ft->handler.write_rates) {
    if (!ft->signal.rate) ft->signal.rate = ft->handler.write_rates[0];
    else {
      for (i = 0; ft->handler.write_rates[i]; ++i) if (ft->handler.write_rates[i] == ft->signal.rate) break;
      if (!ft->handler.write_rates[i]) {
        unsigned nearest = 0;
        double mindiff = HUGE_VAL;
        for (i = 0; ft->handler.write_rates[i]; ++i) {
          double diff = fabs(ft->handler.write_rates[i] - ft->signal.rate);
          if (diff < mindiff) { mindiff = diff; nearest = i; }
        }
        lsx_warn("%s can't encode at %gHz; using %gHz", ft->handler.names[0], ft->signal.rate, ft->handler.write_rates[nearest]);
        ft->signal.rate = ft->handler.write_rates[nearest];
      }
    }
  } else if (!ft->signal.rate) {
    ft->signal.rate = 48000;
    lsx_warn("`%s': sample rate not specified; using %g", ft->filename, ft->signal.rate);
  }
  if (!ft->signal.channels) {
    ft->signal.channels = 2;
    lsx_warn("`%s': # channels not specified; using %u", ft->filename, ft->signal.channels);
  } else if (ft->handler.flags & SOX_FILE_CHANS) {
    unsigned flags = ft->handler.flags;
    if (ft->signal.channels == 1 && !(flags & SOX_FILE_MONO)) {
      ft->signal.channels = (flags & SOX_FILE_STEREO) ? 2 : 4;
      lsx_warn("%s can't encode mono; setting channels to %u", ft->handler.names[0], ft->signal.channels);
    } else if (ft->signal.channels == 2 && !(flags & SOX_FILE_STEREO)) {
      ft->signal.channels = (flags & SOX_FILE_MONO) ? 1 : 4;
      lsx_warn("%s can't encode stereo; setting channels to %u", ft->handler.names[0], ft->signal.channels);
    } else if (ft->signal.channels == 4 && !(flags & SOX_FILE_QUAD)) {
      ft->signal.channels = (flags & SOX_FILE_STEREO) ? 2 : 1;
      lsx_warn("%s can't encode quad; setting channels to %u", ft->handler.names[0], ft->signal.channels);
    }
  }

  if (!encodings) return;

  if (e) {
    if (!encoding_in_list(encodings, e, 0, sox_false)) {
      lsx_warn("%s can't encode %s", ft->handler.names[0], sox_encodings_info[e].desc);
      e = SOX_ENCODING_UNKNOWN;
    } else if (bits && !encoding_in_list(encodings, e, bits, sox_true)) {
      lsx_warn("%s can't encode %s to %u-bit", ft->handler.names[0], sox_encodings_info[e].desc, bits);
      bits = 0;
    }
  }
