    /* first encoding in the list with these bits */
    for (i = 0; encodings[i]; ++i) {
      for (s = i + 1; encodings[s]; ++s) if (encodings[s] == bits) { e = encodings[i]; break; }
      if (e) break;
      i = s;
    }
    if (!e) {
      lsx_warn("%s can't encode to %u-bit", ft->handler.names[0], bits);
      bits = 0;
    }
  }
  if (!e || !bits) {
    /* choose by precision */
    unsigned best_prec_ge = 0, best_prec_lt = 0, best_e_ge = 0, best_e_lt = 0, best_b_ge = 0, best_b_lt = 0;
    unsigned target = ft->signal.precision;
    for (i = 0; encodings[i]; ++i) {
      sox_encoding_t ee = encodings[i];
      if (e && ee != e) { while (encodings[++i]); continue; }
      for (s = i + 1; encodings[s]; ++s) {
        unsigned p = sox_precision(ee, encodings[s]);
        if (p >= target) { if (!best_prec_ge || p < best_prec_ge) { best_prec_ge = p; best_e_ge = ee; best_b_ge = encodings[s]; } }
        else if (p > best_prec_lt) { best_prec_lt = p; best_e_lt = ee; best_b_lt = encodings[s]; }
      }
      i = s;
    }
    if (best_e_ge) { e = best_e_ge; bits = best_b_ge; }
    else if (best_e_lt) { e = best_e_lt; bits = best_b_lt; }
    else { e = encodings[0]; bits = encodings[1]; }
  }
  ft->encoding.encoding = e;
  ft->encoding.bits_per_sample = bits;
}

sox_format_t *sox_open_write(const char *path, const sox_signalinfo_t *signal, const sox_encodinginfo_t *encoding, const char *filetype, const sox_oob_t *oob, sox_bool (*overwrite_permitted)(const char *filename))
{
  sox_format_t *ft = lsx_calloc(1, sizeof *ft);
  const sox_format_handler_t *handler;
  int i;
  sox_bool is_stdout = !strcmp(path, "-");

  if (!filetype) {
    const char *ext = lsx_find_file_extension(path);
    if (!ext) { lsx_fail("can't determine type of `%s'", path); goto error; }
    if (!(handler = sox_find_format(ext, sox_true))) { lsx_fail("no handler for file extension `%s'", ext); goto error; }
    filetype = ext;
  } else if (!(handler = sox_find_format(filetype, sox_false))) {
    lsx_fail("no handler for given file type `%s'", filetype);
    goto error;
  }
  ft->handler = *handler;
  if (!ft->handler.startwrite && !ft->handler.write) {
    lsx_fail("file type `%s' isn't writable", filetype);
    goto error;
  }
  ft->mode = 'w';
  ft->filetype = lsx_strdup(filetype);
  ft->filename = lsx_strdup(path);
  if (signal) ft->signal = *signal;
  if (encoding) ft->encoding = *encoding; else sox_init_encodinginfo(&ft->encoding);
  if (oob) {
    ft->oob = *oob;
    ft->oob.comments = lsx_copy_comments(oob->comments);
  }
  if (!(ft->handler.flags & SOX_FILE_NOSTDIO)) {
    if (is_stdout) {
      ft->fp = stdout;
    } else {
      struct stat st;
      if (!stat(path, &st) && (st.st_mode & S_IFMT) == S_IFREG && !(overwrite_permitted && overwrite_permitted(path))) {
        lsx_fail("permission to overwrite `%s' denied", path);
        goto error;
      }
      ft->fp = fopen(path, "wb");
      if (!ft->fp) { lsx_fail("can't open output file `%s': %s", path, strerror(errno)); goto error; }
    }
    ft->seekable = is_seekable(ft);
  }
  set_output_format(ft);
  set_endiannesses(ft);
  ft->signal.precision = sox_precision(ft->encoding.encoding, ft->encoding.bits_per_sample);
  if (ft->encoding.bits_per_sample == 0 && ft->encoding.encoding == SOX_ENCODING_UNKNOWN) {
    lsx_fail("unable to find a supported encoding for `%s'", path);
    goto error;
  }
  ft->priv = lsx_calloc(1, ft->handler.priv_len);
  if (ft->handler.startwrite && (*ft->handler.startwrite)(ft) != SOX_SUCCESS) {
    lsx_fail("can't open output file `%s': %s", ft->filename, ft->sox_errstr);
    goto error;
  }
  if (ft->signal.length == SOX_IGNORE_LENGTH) ft->signal.length = SOX_UNSPEC;
  return ft;
error:
  if (ft->fp && ft->fp != stdout) fclose(ft->fp);
  sox_format_free(ft);
  return NULL;
}

size_t sox_read(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  size_t actual = ft->handler.read ? (*ft->handler.read)(ft, buf, len) : 0;
  return actual > len ? 0 : actual;
}

size_t sox_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  size_t actual = ft->handler.write ? (*ft->handler.write)(ft, buf, len) : 0;
  ft->olength += actual;
  return actual;
}

int sox_close(sox_format_t *ft)
{
  int result = SOX_SUCCESS;
  if (ft->mode == 'r') result = ft->handler.stopread ? (*ft->handler.stopread)(ft) : SOX_SUCCESS;
  else result = ft->handler.stopwrite ? (*ft->handler.stopwrite)(ft) : SOX_SUCCESS;
  if (ft->fp) {
    if (ft->fp == stdin) { /* leave */ }
    else if (ft->fp == stdout) fflush(stdout);
    else if (ft->filename && *ft->filename == '|') pclose(ft->fp);
    else fclose(ft->fp);
  }
  sox_format_free(ft);
  return result;
}

int sox_seek(sox_format_t *ft, uint64_t offset, int whence)
{
  if (whence != SOX_SEEK_SET) return SOX_EOF;
  if (ft->mode == 'w') return SOX_EOF;
  if (!ft->seekable) return SOX_EOF;
  if (ft->handler.seek) return (*ft->handler.seek)(ft, offset);
  return SOX_EOF;
}

double lsx_bitrate(const sox_format_t *ft)
{
  return 0;
}
