}

static size_t read8(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  uint8_t *data = lsx_malloc(len);
  size_t n, nread = lsx_read_b_buf(ft, data, len);
  SOX_SAMPLE_LOCALS;
  if (ft->encoding.reverse_bits) for (n = 0; n < nread; ++n) data[n] = rev_bits(data[n]);
  if (ft->encoding.reverse_nibbles) for (n = 0; n < nread; ++n) data[n] = (uint8_t)((data[n] & 15) << 4 | data[n] >> 4);
  switch (ft->encoding.encoding) {
    case SOX_ENCODING_SIGN2: for (n = 0; n < nread; ++n) buf[n] = SOX_SIGNED_8BIT_TO_SAMPLE((int8_t)data[n], ft->clips); break;
    case SOX_ENCODING_UNSIGNED: for (n = 0; n < nread; ++n) buf[n] = SOX_UNSIGNED_8BIT_TO_SAMPLE(data[n], ft->clips); break;
    case SOX_ENCODING_ULAW: for (n = 0; n < nread; ++n) buf[n] = SOX_ULAW_BYTE_TO_SAMPLE(data[n], ft->clips); break;
    case SOX_ENCODING_ALAW: for (n = 0; n < nread; ++n) buf[n] = SOX_ALAW_BYTE_TO_SAMPLE(data[n], ft->clips); break;
    default: nread = 0;
  }
  free(data);
  return nread;
}

static size_t write8(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  uint8_t *data = lsx_malloc(len);
  size_t n, nwritten;
  SOX_SAMPLE_LOCALS;
  switch (ft->encoding.encoding) {
    case SOX_ENCODING_SIGN2: for (n = 0; n < len; ++n) data[n] = (uint8_t)SOX_SAMPLE_TO_SIGNED_8BIT(buf[n], ft->clips); break;
    case SOX_ENCODING_UNSIGNED: for (n = 0; n < len; ++n) data[n] = (uint8_t)SOX_SAMPLE_TO_UNSIGNED_8BIT(buf[n], ft->clips); break;
    case SOX_ENCODING_ULAW: for (n = 0; n < len; ++n) data[n] = SOX_SAMPLE_TO_ULAW_BYTE(buf[n], ft->clips); break;
    case SOX_ENCODING_ALAW: for (n = 0; n < len; ++n) data[n] = SOX_SAMPLE_TO_ALAW_BYTE(buf[n], ft->clips); break;
    default: free(data); return 0;
  }
  if (ft->encoding.reverse_nibbles) for (n = 0; n < len; ++n) data[n] = (uint8_t)((data[n] & 15) << 4 | data[n] >> 4);
  if (ft->encoding.reverse_bits) for (n = 0; n < len; ++n) data[n] = rev_bits(data[n]);
