    else if (ft->encoding.encoding == SOX_ENCODING_FLOAT) { float *f = (float*)data; for (n = 0; n < nread; ++n) buf[n] = SOX_FLOAT_32BIT_TO_SAMPLE(f[n], ft->clips); }
    else nread = 0;
    free(data); break; }
  case 64: {
    double *data = lsx_malloc(nsamp * 8);
    nread = lsx_read_df_buf(ft, data, nsamp);
    if (ft->encoding.encoding == SOX_ENCODING_FLOAT) for (n = 0; n < nread; ++n) buf[n] = SOX_FLOAT_64BIT_TO_SAMPLE(data[n], ft->clips);
    else nread = 0;
    free(data); break; }
  default:
    lsx_fail_errno(ft, SOX_EFMT, "this handler does not support this data size");
    return 0;
  }
  return nread;
}

size_t lsx_rawwrite(sox_format_t *ft, const sox_sample_t *buf, size_t nsamp)
{
  size_t n, nw = 0;
  SOX_SAMPLE_LOCALS;
  switch (ft->encoding.bits_per_sample) {
  case 8: return write8(ft, buf, nsamp);
  case 16: {
    uint16_t *data = lsx_malloc(nsamp * 2);
    if (ft->encoding.encoding == SOX_ENCODING_SIGN2) for (n = 0; n < nsamp; ++n) data[n] = (uint16_t)SOX_SAMPLE_TO_SIGNED_16BIT(buf[n], ft->clips);
    else if (ft->encoding.encoding == SOX_ENCODING_UNSIGNED) for (n = 0; n < nsamp; ++n) data[n] = (uint16_t)SOX_SAMPLE_TO_UNSIGNED_16BIT(buf[n], ft->clips);
    else { free(data); return 0; }
    nw = (size_t)lsx_write_w_buf(ft, data, nsamp); free(data); break; }
  case 24: {
    uint32_t *data = lsx_malloc(nsamp * 4);
    if (ft->encoding.encoding == SOX_ENCODING_SIGN2) for (n = 0; n < nsamp; ++n) data[n] = (uint32_t)SOX_SAMPLE_TO_SIGNED_24BIT(buf[n], ft->clips) & 0xffffff;
    else if (ft->encoding.encoding == SOX_ENCODING_UNSIGNED) for (n = 0; n < nsamp; ++n) data[n] = SOX_SAMPLE_TO_UNSIGNED_24BIT(buf[n], ft->clips);
    else { free(data); return 0; }
    nw = (size_t)lsx_write_3_buf(ft, data, nsamp); free(data); break; }
  case 32: {
    uint32_t *data = lsx_malloc(nsamp * 4);
    if (ft->encoding.encoding == SOX_ENCODING_SIGN2) for (n = 0; n < nsamp; ++n) data[n] = (uint32_t)SOX_SAMPLE_TO_SIGNED_32BIT(buf[n], ft->clips);
    else if (ft->encoding.encoding == SOX_ENCODING_UNSIGNED) for (n = 0; n < nsamp; ++n) data[n] = SOX_SAMPLE_TO_UNSIGNED_32BIT(buf[n], ft->clips);
    else if (ft->encoding.encoding == SOX_ENCODING_FLOAT) { float *f = (float*)data; for (n = 0; n < nsamp; ++n) f[n] = SOX_SAMPLE_TO_FLOAT_32BIT(buf[n], ft->clips); }
    else { free(data); return 0; }
    nw = (size_t)lsx_write_dw_buf(ft, data, nsamp); free(data); break; }
  case 64: {
    double *data = lsx_malloc(nsamp * 8);
    if (ft->encoding.encoding == SOX_ENCODING_FLOAT) for (n = 0; n < nsamp; ++n) data[n] = SOX_SAMPLE_TO_FLOAT_64BIT(buf[n], ft->clips);
    else { free(data); return 0; }
    nw = (size_t)lsx_write_df_buf(ft, data, nsamp); free(data); break; }
  default:
    lsx_fail_errno(ft, SOX_EFMT, "this handler does not support this data size");
    return 0;
  }
  return nw;
}

int lsx_rawstartread(sox_format_t *ft)
{
  ft->data_start = lsx_tell(ft);
  return SOX_SUCCESS;
}
int lsx_rawstartwrite(sox_format_t *ft) { return SOX_SUCCESS; }

int lsx_rawstart(sox_format_t *ft, sox_bool default_rate, sox_bool default_channels, sox_bool default_encoding, sox_encoding_t encoding, unsigned bits_per_sample)
{
  if (default_rate && ft->signal.rate == 0) {
    lsx_warn("`%s': sample rate not specified; trying 8kHz", ft->filename);
    ft->signal.rate = 8000;
  }
  if (default_channels && ft->signal.channels == 0) {
    lsx_warn("`%s': # channels not specified; trying mono", ft->filename);
    ft->signal.channels = 1;
  }
  if (encoding != SOX_ENCODING_UNKNOWN) {
    if (ft->mode == 'r' && ft->encoding.encoding != SOX_ENCODING_UNKNOWN && ft->encoding.encoding != encoding)
      lsx_report("`%s': Format options overriding file-type encoding", ft->filename);
    else ft->encoding.encoding = encoding;
  }
  if (bits_per_sample) {
    if (ft->mode == 'r' && ft->encoding.bits_per_sample != 0 && ft->encoding.bits_per_sample != bits_per_sample)
      lsx_report("`%s': Format options overriding file-type sample-size", ft->filename);
    else ft->encoding.bits_per_sample = bits_per_sample;
  }
  return lsx_rawstartread(ft);
}

