}

int lsx_effect_set_imin(sox_effect_t *effp, size_t imin) { effp->imin = imin; return SOX_SUCCESS; }

sox_effects_chain_t *sox_create_effects_chain(const sox_encodinginfo_t *in_enc, const sox_encodinginfo_t *out_enc)
{
