/* per-effect flows: we store the flows for effect n in effects[n] as an array of sox_effect_t */
int sox_add_effect(sox_effects_chain_t *chain, sox_effect_t *effp, sox_signalinfo_t *in, const sox_signalinfo_t *out)
{
  int ret;
  unsigned f;
  sox_effect_t eff0;
  int (*start)(sox_effect_t *) = effp->handler.start;

  effp->in_signal = *in;
  effp->out_signal = *out;
  effp->in_encoding = chain->in_enc;
  effp->out_encoding = chain->out_enc;
  effp->chain = chain;
  if (!(effp->handler.flags & SOX_EFF_CHAN)) effp->out_signal.channels = in->channels;
  if (!(effp->handler.flags & SOX_EFF_RATE)) effp->out_signal.rate = in->rate;
  if (!(effp->handler.flags & SOX_EFF_PREC)) effp->out_signal.precision = (effp->handler.flags & SOX_EFF_MODIFY) ? in->precision : SOX_SAMPLE_PRECISION;
  if (!(effp->handler.flags & SOX_EFF_GAIN)) effp->out_signal.mult = in->mult;

  effp->flows = (effp->handler.flags & SOX_EFF_MCHAN) ? 1 : effp->in_signal.channels;
  effp->clips = 0;
  effp->imin = 0;
  eff0 = *effp;
  eff0.priv = lsx_malloc(eff0.handler.priv_size);
  memcpy(eff0.priv, effp->priv, eff0.handler.priv_size);
  eff0.in_signal.mult = NULL;
  ret = start(effp);
  if (ret == SOX_EFF_NULL) {
    lsx_set_subsystem(effp->handler.name);
    lsx_report_impl("has no effect in this configuration");
    free(eff0.priv);
    free(effp->priv);
    effp->priv = NULL;
    return SOX_SUCCESS;
  }
  if (ret != SOX_SUCCESS) { free(eff0.priv); return SOX_EOF; }
  if (in->mult) { lsx_set_subsystem(effp->handler.name); lsx_debug_impl("mult=%g", *in->mult); }

  if (!(effp->handler.flags & SOX_EFF_LENGTH)) {
    effp->out_signal.length = in->length;
    if (effp->out_signal.length != SOX_UNKNOWN_LEN) {
      if (effp->handler.flags & SOX_EFF_CHAN)
        effp->out_signal.length = effp->out_signal.length / in->channels * effp->out_signal.channels;
      if (effp->handler.flags & SOX_EFF_RATE)
        effp->out_signal.length = (uint64_t)(effp->out_signal.length / in->rate * effp->out_signal.rate + .5);
    }
  }
  *in = effp->out_signal;

  if (chain->length == chain->table_size) {
    chain->table_size += 8;
    lsx_debug_more("sox_add_effect: extending effects table, new size = %lu", (unsigned long)chain->table_size);
    lsx_Realloc(chain->effects, chain->table_size);
  }
  chain->effects[chain->length] = lsx_calloc(effp->flows, sizeof(sox_effect_t));
  chain->effects[chain->length][0] = *effp;
  for (f = 1; f < effp->flows; ++f) {
    chain->effects[chain->length][f] = eff0;
    chain->effects[chain->length][f].flow = f;
    chain->effects[chain->length][f].priv = lsx_malloc(eff0.handler.priv_size);
    memcpy(chain->effects[chain->length][f].priv, eff0.priv, eff0.handler.priv_size);
    if (start(&chain->effects[chain->length][f]) != SOX_SUCCESS) { free(eff0.priv); return SOX_EOF; }
  }
  ++chain->length;
  free(eff0.priv);
  return SOX_SUCCESS;
}

static int flow_effect(sox_effects_chain_t *chain, size_t n)
{
  sox_effect_t *effp1 = &chain->effects[n - 1][0];
  sox_effect_t *effp = &chain->effects[n][0];
  int effstatus = SOX_SUCCESS;
  size_t f = 0;
  size_t idone = effp1->oend - effp1->obeg;
  size_t obeg = sox_globals.bufsiz - effp->oend;

  if (effp->flows == 1) {
    idone -= idone % effp->in_signal.channels;
    effstatus = effp->handler.flow(effp, effp1->obuf + effp1->obeg, effp->obuf + effp->oend, &idone, &obeg);
    if (obeg % effp->out_signal.channels != 0) {
      lsx_fail("multi-channel effect flowed asymmetrically!");
      effstatus = SOX_EOF;
    }
  } else {
    sox_sample_t *obuf = effp->obuf + effp->oend;
    const sox_sample_t *ibuf = effp1->obuf + effp1->obeg;
    size_t i, idone_last = 0, odone_last = 0;
    size_t idonec, odonec;
    for (i = 0; i < idone; i += effp->flows)
      for (f = 0; f < effp->flows; ++f) chain->ibufc[f][i / effp->flows] = *ibuf++;
    for (f = 0; f < effp->flows; ++f) {
      int effstatus_f;
      idonec = idone / effp->flows;
      odonec = obeg / effp->flows;
      effstatus_f = effp->handler.flow(&chain->effects[n][f], chain->ibufc[f], chain->obufc[f], &idonec, &odonec);
      if (f && (idonec != idone_last || odonec != odone_last)) {
        lsx_fail("flowed asymmetrically!");
        effstatus = SOX_EOF;
      }
      idone_last = idonec;
      odone_last = odonec;
      if (effstatus_f != SOX_SUCCESS) effstatus = SOX_EOF;
    }
    for (i = 0; i < odone_last; ++i)
      for (f = 0; f < effp->flows; ++f) *obuf++ = chain->obufc[f][i];
    idone = effp->flows * idone_last;
    obeg = effp->flows * odone_last;
  }
  effp1->obeg += idone;
  if (effp1->obeg == effp1->oend) effp1->obeg = effp1->oend = 0;
  else if (effp1->oend - effp1->obeg < effp->imin) {
    memmove(effp1->obuf, effp1->obuf + effp1->obeg, (effp1->oend - effp1->obeg) * sizeof(*effp1->obuf));
    effp1->oend -= effp1->obeg;
    effp1->obeg = 0;
  }
  effp->oend += obeg;
  return effstatus == SOX_SUCCESS ? SOX_SUCCESS : SOX_EOF;
}

static int drain_effect(sox_effects_chain_t *chain, size_t n)
{
  sox_effect_t *effp = &chain->effects[n][0];
  int effstatus = SOX_SUCCESS;
  size_t f = 0;
  size_t obeg = sox_globals.bufsiz - effp->oend;
  if (effp->flows == 1) {
    effstatus = effp->handler.drain(effp, effp->obuf + effp->oend, &obeg);
  } else {
    sox_sample_t *obuf = effp->obuf + effp->oend;
    size_t i, odone_last = 0;
    for (f = 0; f < effp->flows; ++f) {
      size_t odonec = obeg / effp->flows;
      int effstatus_f = effp->handler.drain(&chain->effects[n][f], chain->obufc[f], &odonec);
      if (f && (odonec != odone_last)) {
        lsx_fail("drained asymmetrically!");
        effstatus = SOX_EOF;
      }
      odone_last = odonec;
      if (effstatus_f != SOX_SUCCESS) effstatus = SOX_EOF;
    }
    for (i = 0; i < odone_last; ++i)
      for (f = 0; f < effp->flows; ++f) *obuf++ = chain->obufc[f][i];
    obeg = effp->flows * odone_last;
  }
  if (!obeg) effstatus = SOX_EOF;
  effp->oend += obeg;
  return effstatus;
}

int sox_flow_effects(sox_effects_chain_t *chain, int (*callback)(sox_bool all_done, void *client_data), void *client_data)
{
  int flow_status = SOX_SUCCESS;
  size_t e, source_e = 0;
  size_t max_flows = 0;
  sox_bool draining = sox_true;

  for (e = 0; e < chain->length; ++e) {
    chain->effects[e][0].obuf = lsx_realloc(chain->effects[e][0].obuf, sox_globals.bufsiz * sizeof(sox_sample_t));
    chain->effects[e][0].obeg = chain->effects[e][0].oend = 0;
    max_flows = max(max_flows, chain->effects[e][0].flows);
  }
  if (max_flows == 1) max_flows = 0;
  chain->ibufc = lsx_calloc(max_flows, sizeof(*chain->ibufc));
  chain->obufc = lsx_calloc(max_flows, sizeof(*chain->obufc));
  for (e = 0; e < max_flows; ++e) {
    chain->ibufc[e] = lsx_calloc(sox_globals.bufsiz / 2 + 1, sizeof(sox_sample_t));
    chain->obufc[e] = lsx_calloc(sox_globals.bufsiz / 2 + 1, sizeof(sox_sample_t));
  }

  e = chain->length - 1;
  while (source_e < chain->length) {
#define have_imin (e > 0 && e < chain->length && chain->effects[e - 1][0].oend - chain->effects[e - 1][0].obeg >= chain->effects[e][0].imin)
    size_t osize = chain->effects[e][0].oend - chain->effects[e][0].obeg;
    if (e == source_e && (draining || !have_imin)) {
      if (drain_effect(chain, e) == SOX_EOF) {
        ++source_e;
        draining = sox_false;
      }
    } else if (have_imin && flow_effect(chain, e) == SOX_EOF) {
      flow_status = SOX_EOF;
      if (e > source_e) {
        source_e = e;
        draining = sox_true;
      }
    }
    if (e < chain->length - 1 && chain->effects[e][0].oend - chain->effects[e][0].obeg > osize)
      ++e;
    else if (e == source_e)
      ++e;
    else
      e = source_e > e - 1 ? source_e : e - 1;
    if (e >= chain->length) e = chain->length - 1;

    if (callback && callback(source_e == chain->length, client_data) != SOX_SUCCESS) {
      flow_status = SOX_EOF;
      break;
    }
  }
  for (e = 0; e < max_flows; ++e) { free(chain->ibufc[e]); free(chain->obufc[e]); }
  free(chain->obufc); free(chain->ibufc);
  chain->obufc = chain->ibufc = NULL;
  return flow_status;
}

uint64_t sox_effects_clips(sox_effects_chain_t *chain)
{
  unsigned i, f;
