    int c;
    int option_index;
    c = lsx_getopt_s(&optstate);
    option_index = optstate.lngind;
    if (c == -1) break;
    switch (c) {
    case 0:
      switch (option_index) {
      case 0: if (optstate.arg) lsx_append_comments(&f->oob.comments, optstate.arg); break;
      case 1:
#define SOX_BUFMIN 16
        { char *end; long n = strtol(optstate.arg, &end, 10);
          if (*end || n <= SOX_BUFMIN) { lsx_fail("Buffer size `%s' must be > %d", optstate.arg, SOX_BUFMIN); exit(1); }
          sox_globals.bufsiz = (size_t)n; }
        break;
      case 2: combine_method = enum_option(optstate.arg, option_index, combine_methods); break;
      case 3: lsx_append_comments(&f->oob.comments, read_comment_file(optstate.arg)); break;
      case 4: lsx_append_comments(&f->oob.comments, optstate.arg); break;
      case 5:
        if (f->encoding.reverse_bytes != sox_option_default || f->encoding.opposite_endian) usage("only one endian option per file is allowed");
        switch (enum_option(optstate.arg, option_index, endian_options)) {
          case ENDIAN_little: f->encoding.reverse_bytes = sox_false; break;
          case ENDIAN_big: f->encoding.reverse_bytes = sox_true; break;
          case ENDIAN_swap: f->encoding.opposite_endian = sox_true; break;
        }
        break;
      case 6:
        { char *end; long n = strtol(optstate.arg, &end, 10);
          if (*end || n <= SOX_BUFMIN) { lsx_fail("Buffer size `%s' must be > %d", optstate.arg, SOX_BUFMIN); exit(1); }
          sox_globals.input_bufsiz = (size_t)n; }
        break;
      case 7: interactive = sox_true; break;
      case 8: usage_effect(optstate.arg); break;
      case 9: usage_format(optstate.arg); break;
      case 10: show_progress = sox_false; show_progress_set = sox_true; break;
      case 11: sox_effects_globals_s.plot = enum_option(optstate.arg, option_index, plot_methods); break;
      case 12: replay_gain_mode = enum_option(optstate.arg, option_index, rg_modes); break;
      case 13: display_SoX_version(stdout); exit(0); break;
      case 14: break;
      case 15: effects_filename = lsx_strdup(optstate.arg); break;
      case 16: sox_globals.tmp_path = lsx_strdup(optstate.arg); break;
      case 17: sox_globals.use_threads = sox_false; break;
      case 18: f->signal.length = SOX_IGNORE_LENGTH; break;
      case 19: do_guarded_norm = is_guarded = sox_true; norm_level = optstate.arg ? lsx_strdup(optstate.arg) : NULL; break;
      case 20: lsx_warn("this build of SoX does not include `magic'"); break;
      case 21: play_rate_arg = lsx_strdup(optstate.arg); break;
      case 22: no_clobber = sox_false; break;
      case 23: no_clobber = sox_true; break;
      case 24: sox_globals.use_threads = sox_true; break;
      case 25: {
        char *end; long n = strtol(optstate.arg, &end, 10);
        if (*end || n < 8 || n > 16) { lsx_fail("Min DFT size must be in range 8 to 16"); exit(1); }
        sox_globals.log2_dft_min_size = (size_t)n; break; }
      case 34: f->no_glob = sox_true; break;
      }
      break;

    case 'G': is_guarded = sox_true; break;
    case 'm': combine_method = sox_mix; break;
    case 'M': combine_method = sox_merge; break;
    case 'T': combine_method = sox_multiply; break;
    case 'R': sox_globals.repeatable = sox_true; break;
    case 'd': case 'n': case 'p':
      optstate.ind--;
      return sox_true;
    case 'h': usage(NULL); break;
    case '?': usage("invalid option"); break;
    case 't':
      f->filetype = optstate.arg;
      if (f->filetype[0] == '.') f->filetype++;
      break;
    case 'r': {
      char k = 0;
      size_t n = sscanf(optstate.arg, "%lf %c", &f->signal.rate, &k);
      if (n < 1 || f->signal.rate <= 0 || (n > 1 && k != 'k') || (n > 1 && (f->signal.rate *= 1000, 0)) || (n == 2 && 0)) {
        lsx_fail("Rate value `%s' is not a positive number", optstate.arg); exit(1);
      }
      break; }
    case 'v':
      if (sscanf(optstate.arg, "%lf", &f->volume) != 1) { lsx_fail("Volume value `%s' is not a number", optstate.arg); exit(1); }
      uservolume = sox_true;
      if (f->volume < 0.0) lsx_report("Volume adjustment is negative; this will result in a phase change");
      break;
    case 'c': {
      char dummy; long n;
      if (sscanf(optstate.arg, "%ld %c", &n, &dummy) != 1 || n <= 0) { lsx_fail("Channels value `%s' is not a positive integer", optstate.arg); exit(1); }
      f->signal.channels = (unsigned)n; break; }
    case 'C':
      if (sscanf(optstate.arg, "%lf", &f->encoding.compression) != 1) { lsx_fail("Compression value `%s' is not a number", optstate.arg); exit(1); }
      break;
    case 'b': {
      char dummy; long n;
      if (sscanf(optstate.arg, "%ld %c", &n, &dummy) != 1 || n <= 0) { lsx_fail("Bits value `%s' is not a positive integer", optstate.arg); exit(1); }
      f->encoding.bits_per_sample = (unsigned)n; break; }
    case 'e': f->encoding.encoding = enum_option(optstate.arg, 31, encodings); break;
    case 'L': case 'B': case 'x':
      if (f->encoding.reverse_bytes != sox_option_default || f->encoding.opposite_endian) usage("only one endian option per file is allowed");
      switch (c) {
        case 'L': f->encoding.reverse_bytes = sox_false; break;
        case 'B': f->encoding.reverse_bytes = sox_true; break;
        case 'x': f->encoding.opposite_endian = sox_true; break;
      }
      break;
    case 'X': f->encoding.reverse_bits = sox_option_yes; break;
    case 'N': f->encoding.reverse_nibbles = sox_option_yes; break;
    case 'S': show_progress = sox_true; show_progress_set = sox_true; break;
    case 'q': show_progress = sox_false; show_progress_set = sox_true; break;
    case 'D': no_dither = sox_true; break;
    case 'V': {
      if (optstate.arg) {
        char *end; long v = strtol(optstate.arg, &end, 10);
        if (*end || v < 0) { lsx_fail("Verbosity value `%s' is not a non-negative integer", optstate.arg); exit(1); }
        sox_globals.verbosity = (unsigned)v;
      } else sox_globals.verbosity++;
      break; }
    default: break;
    }
  }
  return sox_false;
}

static void add_file(const file_t *const opts, const char *filename)
{
  file_t *f = lsx_malloc(sizeof *f);
  *f = *opts;
  if (!filename) usage("missing filename");
  f->filename = lsx_strdup(filename);
  files = lsx_realloc(files, (file_count + 1) * sizeof(*files));
  files[file_count++] = f;
}

static void add_glob_file(const file_t *const opts, const char *filename)
{
  glob_t globbuf;
  size_t i;
  if (opts->no_glob) { add_file(opts, filename); return; }
  if (glob(filename, GLOB_BRACE | GLOB_TILDE | GLOB_NOCHECK, NULL, &globbuf)) {
    lsx_fail("glob: %s", strerror(errno));
    exit(1);
  }
  for (i = 0; i < globbuf.gl_pathc; ++i) add_file(opts, globbuf.gl_pathv[i]);
  globfree(&globbuf);
}

static void set_device(file_t *opts, sox_bool recording)
{
  (void)opts; (void)recording;
  lsx_fail("Sorry, there is no default audio device configured");
  exit(1);
}

static void parse_options_and_filenames(int argc, char **argv)
{
  const char *env_opts = getenv("SOX_OPTS");
  file_t opts, opts_none;
  init_file(&opts), init_file(&opts_none);

  if (env_opts && *env_opts) {
    char **argv2, *mybuf, *p;
    int argc2;
    size_t argv2_size = 0, i;
    mybuf = lsx_strdup(env_opts);
    argv2 = lsx_malloc(sizeof(char*) * (strlen(mybuf) / 2 + 3));
    argv2[0] = argv[0];
    argc2 = 1;
    p = mybuf;
    while (*p) {
      while (*p && isspace((unsigned char)*p)) ++p;
      if (!*p) break;
      argv2[argc2++] = p;
      while (*p && !isspace((unsigned char)*p)) ++p;
      if (*p) *p++ = 0;
    }
    lsx_getopt_init(argc2, argv2, getoptstr + 1, long_options, lsx_getopt_flag_opterr, 1, &optstate);
    if (parse_gopts_and_fopts(&opts)) { lsx_fail("invalid option for SOX_OPTS"); exit(1); }
    if (optstate.ind != argc2) { lsx_fail("SOX_OPTS: Unrecognised option"); exit(1); }
    (void)i; (void)argv2_size;
    free(argv2); 
    init_file(&opts);
  }

  lsx_getopt_init(argc, argv, getoptstr + 1, long_options, lsx_getopt_flag_opterr, 1, &optstate);
  for (; optstate.ind < argc && !sox_find_effect(argv[optstate.ind]); init_file(&opts)) {
    if (parse_gopts_and_fopts(&opts)) {
      const char *arg = argv[optstate.ind++];
      if (!strcmp(arg, "-d")) set_device(&opts, sox_false);
      else if (!strcmp(arg, "-n")) add_file(&opts, "");
      else if (!strcmp(arg, "-p")) { opts.filetype = "sox"; add_file(&opts, "-"); }
      else if (!strcmp(arg, "--null")) add_file(&opts, "");
      else if (!strcmp(arg, "--default-device")) set_device(&opts, sox_false);
      else if (!strcmp(arg, "--sox-pipe")) { opts.filetype = "sox"; add_file(&opts, "-"); }
      else { /* combined short options like -nq: treat as -n */ add_file(&opts, ""); }
      continue;
    }
    if (optstate.ind >= argc || sox_find_effect(argv[optstate.ind])) break;
    if (!strcmp(argv[optstate.ind], "-")) add_file(&opts, argv[optstate.ind++]);
    else add_glob_file(&opts, argv[optstate.ind++]);
  }
  if (memcmp(&opts, &opts_none, sizeof(opts)) != 0) usage("missing filename");
  argc_g = argc; argv_g = argv;
}

/* ---------- effects ---------- */
static void add_eff_chain(void)
{
  lsx_Realloc(user_effargs, eff_chain_count + 1);
  user_effargs[eff_chain_count] = lsx_malloc(sizeof(**user_effargs));
  lsx_Realloc(user_effargs_size, eff_chain_count + 1);
  user_effargs_size[eff_chain_count] = 0;
  lsx_Realloc(nuser_effects, eff_chain_count + 1);
  nuser_effects[eff_chain_count] = 0;
  ++eff_chain_count;
}

static void delete_eff_chains(void)
{
  size_t i, j;
  for (i = 0; i < eff_chain_count; i++) {
    for (j = 0; j < nuser_effects[i]; j++) {
      free(user_effargs[i][j].name);
      free(user_effargs[i][j].argv);
    }
    free(user_effargs[i]);
  }
  free(user_effargs); free(user_effargs_size); free(nuser_effects);
  user_effargs = NULL; nuser_effects = NULL; user_effargs_size = NULL;
  eff_chain_count = 0;
}

static sox_bool is_pseudo_effect(const char *s)
{
  return s && (!strcmp("newfile", s) || !strcmp("restart", s) || !strcmp(":", s));
}

static void parse_effects(int argc, char **argv)
{
  while (optstate.ind < argc) {
    size_t eff_offset, j;
    int newline_mode = 0;
    eff_offset = nuser_effects[eff_chain_count - 1];
    if (eff_offset == user_effargs_size[eff_chain_count - 1]) {
      size_t i = user_effargs_size[eff_chain_count - 1];
      user_effargs_size[eff_chain_count - 1] += 8;
      lsx_Realloc(user_effargs[eff_chain_count - 1], user_effargs_size[eff_chain_count - 1]);
      for (; i < user_effargs_size[eff_chain_count - 1]; ++i) {
        user_effargs[eff_chain_count - 1][i].argv = NULL;
        user_effargs[eff_chain_count - 1][i].argv_size = 0;
      }
    }
    if (strcmp(argv[optstate.ind], ":") == 0) {
      /* Start a new effects chain */
      optstate.ind++;
      add_eff_chain();
      continue;
    }
    if (strcmp(argv[optstate.ind], "newfile") == 0 || strcmp(argv[optstate.ind], "restart") == 0) {
      if (eff_offset != 0 || (optstate.ind + 1 < argc && strcmp(argv[optstate.ind + 1], ":") != 0)) {
        lsx_fail("Pseudo-effect `%s' must be given as the only effect in a chain (i.e. surrounded by `:')", argv[optstate.ind]);
        exit(1);
      }
    }
    if (!sox_find_effect(argv[optstate.ind]) && !is_pseudo_effect(argv[optstate.ind])) {
      lsx_fail("Cannot find an effect called `%s'", argv[optstate.ind]);
      exit(1);
    }
    user_effargs[eff_chain_count - 1][eff_offset].name = lsx_strdup(argv[optstate.ind]);
    optstate.ind++;
    for (j = 0; j < (size_t)(argc - optstate.ind) && !sox_find_effect(argv[optstate.ind + j]) && !is_pseudo_effect(argv[optstate.ind + j]); ++j) {
      if (j >= user_effargs[eff_chain_count - 1][eff_offset].argv_size) {
        user_effargs[eff_chain_count - 1][eff_offset].argv_size += 8;
        lsx_Realloc(user_effargs[eff_chain_count - 1][eff_offset].argv, user_effargs[eff_chain_count - 1][eff_offset].argv_size);
      }
      user_effargs[eff_chain_count - 1][eff_offset].argv[j] = lsx_strdup(argv[optstate.ind + j]);
    }
    user_effargs[eff_chain_count - 1][eff_offset].argc = (int)j;
    optstate.ind += j;
    nuser_effects[eff_chain_count - 1]++;
    (void)newline_mode;
  }
}

static void read_user_effects(const char *filename)
{
  FILE *file = fopen(filename, "r");
  const size_t buffer_size_step = 1024;
  size_t buffer_size = buffer_size_step;
  char *s = lsx_malloc(buffer_size);
  int pos = 0;
  int argc;
  char **argv;
  sox_bool last_was_chain = sox_false;

  delete_eff_chains();
  current_eff_chain = 0;
  add_eff_chain();
  if (!file) { lsx_fail("Cannot open effects file `%s': %s", filename, strerror(errno)); exit(1); }
  lsx_report("Reading effects from file `%s'", filename);
  while (fgets(s + pos, (int)(buffer_size - pos), file)) {
    int len = (int)strlen(s + pos);
    if (len && s[pos + len - 1] == '\n') s[pos + len - 1] = 0, pos = 0;
    else if (pos + len == (int)buffer_size - 1) { lsx_Realloc(s, buffer_size += buffer_size_step); pos += len; continue; }
    else if (len) pos += len, s[pos] = 0, pos = 0;
    /* tokenize */
    {
      char *p = s; argc = 0; argv = NULL;
      while (*p) {
        while (*p && isspace((unsigned char)*p)) ++p;
        if (!*p) break;
        lsx_Realloc(argv, argc + 1);
        if (*p == '"' || *p == '\'') { char q = *p++; argv[argc++] = p; while (*p && *p != q) ++p; if (*p) *p++ = 0; }
        else { argv[argc++] = p; while (*p && !isspace((unsigned char)*p)) ++p; if (*p) *p++ = 0; }
      }
    }
    if (argc) {
      char **argv2 = lsx_malloc((argc + 1) * sizeof(char*));
      int i;
      argv2[0] = (char*)"";
      for (i = 0; i < argc; ++i) argv2[i + 1] = argv[i];
      optstate.ind = 1;
      parse_effects(argc + 1, argv2);
      /* a line in the file is also a chain separator */
      if (strcmp(argv[argc - 1], ":") != 0) add_eff_chain();
      last_was_chain = sox_false;
      free(argv2);
      free(argv);
    } else last_was_chain = sox_false;
  }
  if (ferror(file)) { lsx_fail("Error reading effects file `%s': %s", filename, strerror(errno)); exit(1); }
  fclose(file);
  if (nuser_effects[eff_chain_count - 1] == 0 && eff_chain_count > 1) { --eff_chain_count; }
  free(s);
  (void)last_was_chain;
}

static void create_user_effects(void)
{
  size_t i;
  sox_effect_t *effp;
  size_t num_effects = nuser_effects[current_eff_chain];
  if (user_efftab_size < num_effects) {
    user_efftab_size = num_effects;
    lsx_Realloc(user_efftab, num_effects);
  }
  for (i = 0; i < num_effects; i++) {
    effp = sox_create_effect(sox_find_effect(user_effargs[current_eff_chain][i].name));
    if (effp->handler.flags & SOX_EFF_DEPRECATED)
      lsx_warn("effect `%s' is deprecated; see sox(1) for an alternative", effp->handler.name);
    else if (effp->handler.flags & SOX_EFF_ALPHA)
      lsx_warn("effect `%s' is experimental/incomplete", effp->handler.name);
    else if (effp->handler.flags & SOX_EFF_INTERNAL) {
      lsx_fail("`%s' is a libSoX-only effect", effp->handler.name);
      exit(1);
    }
    if (sox_effect_options(effp, user_effargs[current_eff_chain][i].argc, user_effargs[current_eff_chain][i].argv) == SOX_EOF)
      exit(1);
    user_efftab[i] = effp;
  }
}

/* ---------- combiner (input effect) ---------- */
static sox_bool is_serial(combine_t m) { return m <= sox_concatenate; }
static sox_bool is_parallel(combine_t m) { return !is_serial(m); }

static int total_clips_cb(void);

typedef struct {
  sox_sample_t **ibuf;
  size_t *ilen;
} input_combiner_t;

static void balance_input(sox_sample_t *buf, size_t ws, file_t *f)
{
  size_t s = ws * f->ft->signal.channels;
  if (f->volume != 1) while (s--) {
    double d = *buf * f->volume;
    *buf++ = SOX_ROUND_CLIP_COUNT(d, f->volume_clips);
  }
}

static size_t sox_read_wide(sox_format_t *ft, sox_sample_t *buf, size_t max)
{
  size_t sz = max / ft->signal.channels * ft->signal.channels;
  sz = sox_read(ft, buf, sz) / ft->signal.channels;
  if (!sz && ft->sox_errno) lsx_fail("`%s' %s: %s", ft->filename, ft->sox_errstr, strerror(ft->sox_errno));
  return sz;
}

static sox_bool can_segue(size_t i)
{
  return files[i]->ft->signal.channels == files[i - 1]->ft->signal.channels &&
         files[i]->ft->signal.rate == files[i - 1]->ft->signal.rate;
}

static int combiner_start(sox_effect_t *effp)
{
  input_combiner_t *z = (input_combiner_t *)effp->priv;
  uint64_t ws;
  size_t i;
  if (is_serial(combine_method)) {
    ws = files[current_input]->ft->signal.length != SOX_UNSPEC && files[current_input]->ft->signal.length != SOX_UNKNOWN_LEN ?
      files[current_input]->ft->signal.length / files[current_input]->ft->signal.channels : 0;
    (void)ws;
  } else {
    z->ibuf = lsx_calloc(input_count, sizeof(*z->ibuf));
    z->ilen = lsx_calloc(input_count, sizeof(*z->ilen));
    for (i = 0; i < input_count; i++) z->ibuf[i] = lsx_malloc(sox_globals.bufsiz * sizeof(sox_sample_t));
  }
  return SOX_SUCCESS;
}

static int combiner_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  input_combiner_t *z = (input_combiner_t *)effp->priv;
  size_t ws, s, i;
  size_t olen = 0;

  if (is_serial(combine_method)) {
    while (sox_true) {
      if (!user_skip) olen = sox_read_wide(files[current_input]->ft, obuf, *osamp);
      if (olen == 0) {
        if (current_input + 1 < input_count && (!can_segue(current_input + 1) || combine_method == sox_sequence)) {
          /* sequence: stop this chain; handled by caller */
          if (combine_method == sox_sequence) { *osamp = 0; return SOX_EOF; }
        }
        if (++current_input >= input_count) { current_input--; *osamp = 0; return SOX_EOF; }
        if (combine_method == sox_sequence) { current_input--; *osamp = 0; return SOX_EOF; }
        if (!can_segue(current_input)) { lsx_fail("Input files must have the same # channels and sample-rate"); exit(1); }
        user_skip = sox_false;
        continue;
      }
      balance_input(obuf, olen, files[current_input]);
      break;
    }
  } else {
    sox_sample_t *p = obuf;
    for (i = 0; i < input_count; ++i) {
      z->ilen[i] = sox_read_wide(files[i]->ft, z->ibuf[i], *osamp);
      balance_input(z->ibuf[i], z->ilen[i], files[i]);
      olen = max(olen, z->ilen[i]);
    }
    for (i = 0; i < input_count; ++i)
      for (s = z->ilen[i] * files[i]->ft->signal.channels; s < olen * files[i]->ft->signal.channels; ++s) z->ibuf[i][s] = 0;
    switch (combine_method) {
    case sox_mix: case sox_mix_power:
      for (ws = 0; ws < olen; ++ws) {
        for (s = 0; s < effp->in_signal.channels; ++s) {
          double sample = 0;
          for (i = 0; i < input_count; ++i) {
            unsigned ch = files[i]->ft->signal.channels;
            sample += s < ch ? (double)z->ibuf[i][ws * ch + s] : 0;
          }
          *p++ = SOX_ROUND_CLIP_COUNT(sample, mixing_clips);
        }
      }
      break;
    case sox_multiply:
      for (ws = 0; ws < olen; ++ws) {
        for (s = 0; s < effp->in_signal.channels; ++s) {
          double sample = SOX_SAMPLE_MAX;
          for (i = 0; i < input_count; ++i) {
            unsigned ch = files[i]->ft->signal.channels;
            sample *= (s < ch ? (double)z->ibuf[i][ws * ch + s] : 0) * (1. / SOX_SAMPLE_MAX);
          }
          *p++ = SOX_ROUND_CLIP_COUNT(sample, mixing_clips);
        }
      }
      break;
    case sox_merge:
      for (ws = 0; ws < olen; ++ws)
        for (i = 0; i < input_count; ++i) {
          unsigned ch = files[i]->ft->signal.channels;
          for (s = 0; s < ch; ++s) *p++ = z->ibuf[i][ws * ch + s];
        }
      break;
    default: break;
    }
  }
  read_wide_samples += olen;
  olen *= effp->in_signal.channels;
  *osamp = olen;
  input_eof = olen ? sox_false : sox_true;
  return olen ? SOX_SUCCESS : SOX_EOF;
}

static int combiner_stop(sox_effect_t *effp)
{
  input_combiner_t *z = (input_combiner_t *)effp->priv;
  size_t i;
  if (is_parallel(combine_method)) {
    for (i = 0; i < input_count; i++) free(z->ibuf[i]);
    free(z->ibuf); free(z->ilen);
  }
  return SOX_SUCCESS;
}

static const sox_effect_handler_t *input_combiner_effect_fn(void)
{
  static sox_effect_handler_t handler = { "input", 0, SOX_EFF_MCHAN | SOX_EFF_MODIFY, 0, combiner_start, 0, combiner_drain, combiner_stop, 0, sizeof(input_combiner_t) };
  return &handler;
}

static int ostart(sox_effect_t *effp)
{
  unsigned prec = effp->out_signal.precision;
  if (effp->in_signal.mult && effp->in_signal.precision > prec)
    *effp->in_signal.mult *= 1 - (1 << (31 - prec)) * (1. / SOX_SAMPLE_MAX);
  return SOX_SUCCESS;
}

static int output_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  size_t len;
  (void)obuf;
  if (show_progress) for (len = 0; len < *isamp; len += effp->in_signal.channels) {
    omax[0] = max(omax[0], ibuf[len]);
    omin[0] = min(omin[0], ibuf[len]);
    if (effp->in_signal.channels > 1) {
      omax[1] = max(omax[1], ibuf[len + 1]);
      omin[1] = min(omin[1], ibuf[len + 1]);
    } else { omax[1] = omax[0]; omin[1] = omin[0]; }
  }
  for (*osamp = *isamp; *osamp; ibuf += len, *osamp -= len) {
    len = sox_write(ofile->ft, ibuf, *osamp);
    if (len == 0) {
      lsx_warn("Error writing output: %s", ofile->ft->sox_errstr[0] ? ofile->ft->sox_errstr : "unknown");
      return SOX_EOF;
    }
    output_samples += len / ofile->ft->signal.channels;
  }
  output_eof = sox_false;
  *osamp = 0;
  return SOX_SUCCESS;
}

static const sox_effect_handler_t *output_effect_fn(void)
{
  static sox_effect_handler_t handler = { "output", 0, SOX_EFF_MCHAN | SOX_EFF_MODIFY | SOX_EFF_PREC, NULL, ostart, output_flow, NULL, NULL, NULL, 0 };
  return &handler;
}

static void auto_effect(sox_effects_chain_t *chain, const char *name, int argc, char *argv[], sox_signalinfo_t *signal, int *guard)
{
  sox_effect_t *effp;
  effp = sox_create_effect(sox_find_effect(name));
  if (sox_effect_options(effp, argc, argv) == SOX_EOF) exit(1);
  if (*guard > 0 && !(effp->handler.flags & SOX_EFF_GAIN)) { /* add gain -h ... */ }
  if (sox_add_effect(chain, effp, signal, &ofile->ft->signal) != SOX_SUCCESS) exit(2);
  (void)guard;
}

static void add_effect(sox_effects_chain_t *chain, sox_effect_t *effp, sox_signalinfo_t *in, sox_signalinfo_t *out, int *guard)
{
  int no_guard = -1;
  switch (*guard) {
    case 0: if (!(effp->handler.flags & SOX_EFF_GAIN)) {
      char *args[] = {"-h"};
      auto_effect(chain, "gain", 1, args, in, &no_guard);
      ++*guard;
    } break;
    case 1: if (effp->handler.flags & SOX_EFF_GAIN) {
      char *args[] = {"-r"};
      auto_effect(chain, "gain", 1, args, in, &no_guard);
      --*guard;
    } break;
  }
  if (sox_add_effect(chain, effp, in, out) != SOX_SUCCESS) exit(2);
}

static void init_eff_chains(void)
{
  add_eff_chain();
}

static void add_effects(sox_effects_chain_t *chain)
{
  sox_signalinfo_t signal = combiner_signal;
  int guard = is_guarded - 1;
  size_t i;
  sox_effect_t *effp;
  char *rate_arg = sox_mode == sox_play ? (play_rate_arg ? (char*)play_rate_arg : "-l") : NULL;

  for (i = 0; i < nuser_effects[current_eff_chain] && strcmp(user_efftab[i]->handler.name, "dither"); i++)
    add_effect(chain, user_efftab[i], &signal, &ofile->ft->signal, &guard);

  if (signal.channels < ofile->ft->signal.channels && signal.rate != ofile->ft->signal.rate)
    auto_effect(chain, "rate", rate_arg != NULL, &rate_arg, &signal, &guard);
  if (signal.channels != ofile->ft->signal.channels) auto_effect(chain, "channels", 0, NULL, &signal, &guard);
  if (signal.rate != ofile->ft->signal.rate) auto_effect(chain, "rate", rate_arg != NULL, &rate_arg, &signal, &guard);

  if (is_guarded && (do_guarded_norm || !(signal.mult && *signal.mult == 1))) {
    char *args[2];
    int no_guard = -1;
    args[0] = do_guarded_norm ? "-nh" : guard ? "-rh" : "-h";
    args[1] = norm_level;
    auto_effect(chain, "gain", norm_level ? 2 : 1, args, &signal, &no_guard);
    guard = 1;
  }

  if (i == nuser_effects[current_eff_chain] && !no_dither && signal.precision > ofile->ft->signal.precision && ofile->ft->signal.precision < 24)
    auto_effect(chain, "dither", 0, NULL, &signal, &guard);

  for (; i < nuser_effects[current_eff_chain]; i++)
    add_effect(chain, user_efftab[i], &signal, &ofile->ft->signal, &guard);

  if (!(effp = sox_create_effect(output_effect_fn()))) exit(2);
  if (sox_add_effect(chain, effp, &signal, &ofile->ft->signal) != SOX_SUCCESS) exit(2);

  for (i = 0; i < chain->length; ++i) {
    char const *format = sox_globals.verbosity > 3 ?
      "effects chain: %-10s %7gHz %2u channels %7s %2u bits %s" :
      "effects chain: %-10s %7gHz %2u channels";
    sox_effect_t const *e = &chain->effects[i][0];
    char const *type = e->flows > 1 ? "(multi)" : "";
    (void)type;
    lsx_report(format, e->handler.name, e->out_signal.rate, e->out_signal.channels,
        e->handler.flags & SOX_EFF_MCHAN ? "(multi)" : "", e->out_signal.precision,
        e->out_signal.length != SOX_UNKNOWN_LEN ? str_time(e->out_signal.length / e->out_signal.channels / e->out_signal.rate) : "unknown length");
  }
}

static uint64_t total_clips(void)
{
  size_t i;
  uint64_t clips = 0;
  for (i = 0; i < file_count; ++i) clips += files[i]->ft->clips + files[i]->volume_clips;
  return clips + mixing_clips + sox_effects_clips(effects_chain);
}

static const char *vu_meter_str(double x, sox_bool left)
{
  static char buf[2][16];
  char *s = buf[left ? 0 : 1];
  double dB;
  int h, full, half, i, n = 0;
  memset(s, ' ', 6); s[6] = 0;
  if (x <= 0) return s;
  dB = 20 * log10(x);
  h = (int)floor((dB + 27) / 2);
  if (h < 0) h = 0;
  if (h > 13) h = 13;
  full = h / 2; half = h & 1;
  if (h >= 13) { full = 5; half = 2; }
  {
    char tmp[8];
    for (i = 0; i < full; ++i) tmp[n++] = '=';
    if (half == 1) tmp[n++] = '-';
    else if (half == 2) tmp[n++] = '!';
    tmp[n] = 0;
    if (left) {
      /* right-justified, reversed */
      memset(s, ' ', 6);
      for (i = 0; i < n; ++i) s[6 - n + i] = tmp[n - 1 - i];
    } else {
      memset(s, ' ', 6);
      memcpy(s, tmp, n);
    }
  }
  return s;
}

static sox_bool since(struct timeval *then, double secs, sox_bool always_reset)
{
  sox_bool ret;
  struct timeval now;
  time_t d;
  gettimeofday(&now, NULL);
  d = now.tv_sec - then->tv_sec;
  ret = d > ceil(secs) || now.tv_usec - then->tv_usec + d * 1e6 >= secs * 1e6;
  if (ret || always_reset) *then = now;
  return ret;
}

static void display_status(sox_bool all_done)
{
  static struct timeval then;
  if (!show_progress) return;
  if (all_done || since(&then, .1, sox_false)) {
    double read_time = (double)read_wide_samples / combiner_signal.rate;
    double left_time = 0, in_time = 0, percentage = 0;
    if (input_wide_samples) {
      in_time = (double)input_wide_samples / combiner_signal.rate;
      left_time = max(in_time - read_time, 0);
      percentage = max(100. * read_wide_samples / input_wide_samples, 0);
    }
    fprintf(stderr, "\rIn:%-5s %s [%s] Out:%-5s [%6s|%-6s] %s Clip:%-5s",
        lsx_sigfigs3p(percentage), str_time(read_time), str_time(left_time),
        lsx_sigfigs3((double)output_samples),
        vu_meter_str(max(fabs(omax[0]), fabs(omin[0])) / (SOX_SAMPLE_MAX + 1.), sox_true),
        vu_meter_str(max(fabs(omax[1]), fabs(omin[1])) / (SOX_SAMPLE_MAX + 1.), sox_false),
        "      ", lsx_sigfigs3((double)total_clips()));
    omax[0] = omax[1] = omin[0] = omin[1] = 0;
  }
  if (all_done) fputc('\n', stderr);
}

static int update_status(sox_bool all_done, void *client_data)
{
  (void)client_data;
  if (!all_done && user_abort) return SOX_EOF;
  display_status(all_done || user_abort);
  return user_abort ? SOX_EOF : SOX_SUCCESS;
}

static void optimize_trim(void)
{
  if (input_count == 1 && effects_chain->length > 1 && strcmp(effects_chain->effects[1][0].handler.name, "trim") == 0) {
    if (files[0]->ft->handler.seek && files[0]->ft->seekable) {
      extern uint64_t sox_trim_get_start(sox_effect_t *);
      extern void sox_trim_clear_start(sox_effect_t *);
      uint64_t offset = sox_trim_get_start(&effects_chain->effects[1][0]);
      if (offset && sox_seek(files[0]->ft, offset, SOX_SEEK_SET) == SOX_SUCCESS) {
        read_wide_samples = offset / files[0]->ft->signal.channels;
        sox_trim_clear_start(&effects_chain->effects[1][0]);
        lsx_debug("optimize_trim successful");
      }
    }
  }
}

static sox_bool overwrite_permitted_cb(const char *filename) { return overwrite_permitted(filename); }

static void open_output_file(void)
{
  double factor;
  int i;
  sox_comments_t p = ofile->oob.comments;
  sox_oob_t oob = files[0]->ft->oob;
  char *path = ofile->filename;

  oob.comments = NULL;
  if (!p) lsx_append_comment(&oob.comments, "Processed by SoX");
  else while (*p) lsx_append_comment(&oob.comments, *p++);

  factor = (double)ofile->signal.channels / combiner_signal.channels;
  for (i = 0; i < SOX_MAX_NLOOPS; i++) {
    oob.loops[i].start = (uint64_t)(oob.loops[i].start * factor);
    oob.loops[i].length = (uint64_t)(oob.loops[i].length * factor);
  }

  if (!strcmp(ofile->filename, "-") && !ofile->filetype) {
    /* no type given for stdout */
  }
  if (output_count > 1 || (eff_chain_count > 1 && 0)) { }

  ofile->ft = sox_open_write(path, &ofile->signal, &ofile->encoding, ofile->filetype, &oob, overwrite_permitted_cb);
  lsx_delete_comments(&oob.comments);
  if (!ofile->ft) exit(2);

  if (!sox_globals.verbosity > 2 ? 0 : 0) { }
  if (sox_globals.verbosity > 2) display_file_info(ofile->ft, ofile, sox_true);
  else if (show_progress && 0) display_file_info(ofile->ft, ofile, sox_false);
}

static void calculate_combiner_signal_parameters(void)
{
  size_t i;
  combiner_signal = files[0]->ft->signal;
  if (is_serial(combine_method)) {
    for (i = 1; i < input_count; i++) {
      if (combine_method == sox_concatenate) {
        if (files[i]->ft->signal.channels != combiner_signal.channels) { lsx_fail("Input files must have the same # channels"); exit(1); }
        if (files[i]->ft->signal.rate != combiner_signal.rate) { lsx_fail("Input files must have the same sample-rate"); exit(1); }
      }
      /* precision: max */
      combiner_signal.precision = max(combiner_signal.precision, files[i]->ft->signal.precision);
    }
  } else {
    size_t total_channels = 0, min_channels = SIZE_MAX, max_channels = 0;
    double max_rate = 0;
    for (i = 0; i < input_count; i++) {
      sox_signalinfo_t *s = &files[i]->ft->signal;
      total_channels += s->channels;
      min_channels = min(min_channels, (size_t)s->channels);
      max_channels = max(max_channels, (size_t)s->channels);
      if (s->rate != combiner_signal.rate) { lsx_fail("Input files must have the same sample-rate"); exit(1); }
      if (combine_method != sox_merge && s->channels != combiner_signal.channels && i)
        lsx_warn("Input files don't have the same # channels");
    }
    combiner_signal.channels = combine_method == sox_merge ? (unsigned)total_channels : (unsigned)max_channels;
    if (combine_method != sox_merge) combiner_signal.precision = SOX_SAMPLE_PRECISION;
    else for (i = 1; i < input_count; i++) combiner_signal.precision = max(combiner_signal.precision, files[i]->ft->signal.precision);
    (void)max_rate; (void)min_channels;
  }
  combiner_signal.length = 0;
}

static void set_combiner_and_output_encoding_parameters(void)
{
  if (is_serial(combine_method) || 1) {
    combiner_encoding = files[0]->ft->encoding;
  }
  ofile->encoding = ofile_encoding_options;
  if (ofile->encoding.encoding == SOX_ENCODING_UNKNOWN) {
    sox_encodinginfo_t t = ofile->encoding;
    t.encoding = combiner_encoding.encoding;
    if (!t.bits_per_sample) t.bits_per_sample = combiner_encoding.bits_per_sample;
    if (sox_format_supports_encoding(ofile->filename, ofile->filetype, &t)) ofile->encoding = t;
    else if (!ofile->filetype && !lsx_find_file_extension(ofile->filename)) { }
  }
}

static void calculate_output_signal_parameters(void)
{
  sox_bool known_length = combine_method != sox_sequence;
  size_t i;
  uint64_t olen = 0;

  for (i = 0; i < input_count; i++) {
    report_file_info(files[i]);
    known_length = known_length && files[i]->ft->signal.length != SOX_UNSPEC && files[i]->ft->signal.length != SOX_UNKNOWN_LEN;
    if (combine_method == sox_concatenate) olen += files[i]->ft->signal.length / files[i]->ft->signal.channels;
    else olen = max(olen, files[i]->ft->signal.length / files[i]->ft->signal.channels);
  }

  ofile->signal = ofile_signal_options;
  if (ofile->signal.rate == 0) ofile->signal.rate = combiner_signal.rate;
  if (ofile->signal.channels == 0) ofile->signal.channels = combiner_signal.channels;
  ofile->signal.precision = combiner_signal.precision;

  /* effects that force output rate/channels */
  for (i = 0; i < nuser_effects[current_eff_chain]; i++) {
    sox_effect_t *e = user_efftab[i];
    if (!ofile_signal_options.rate && e->out_signal.rate) ofile->signal.rate = e->out_signal.rate;
    if (!ofile_signal_options.channels && e->out_signal.channels) ofile->signal.channels = e->out_signal.channels;
    if (e->handler.flags & SOX_EFF_LENGTH) known_length = sox_false;
  }
  if (known_length)
    ofile->signal.length = (uint64_t)(olen * ofile->signal.channels * ofile->signal.rate / combiner_signal.rate + .5);
  else ofile->signal.length = SOX_UNSPEC;
  input_wide_samples = 0;
  if (is_serial(combine_method)) {
    for (i = 0; i < input_count; i++) {
      uint64_t l = files[i]->ft->signal.length;
      if (l == SOX_UNSPEC || l == SOX_UNKNOWN_LEN) { input_wide_samples = 0; break; }
      input_wide_samples += l / files[i]->ft->signal.channels;
    }
  } else {
    for (i = 0; i < input_count; i++) {
      uint64_t l = files[i]->ft->signal.length;
      if (l == SOX_UNSPEC || l == SOX_UNKNOWN_LEN) { input_wide_samples = 0; break; }
      input_wide_samples = max(input_wide_samples, l / files[i]->ft->signal.channels);
    }
  }
}

static void sigint(int s)
{
  static struct timeval then;
  if (input_count > 1 && is_serial(combine_method) && since(&then, 1.0, sox_true)) {
    user_skip = sox_true;
    signal(SIGINT, sigint);
  } else user_abort = sox_true;
  (void)s;
}

static void open_input_files(void)
{
  size_t i;
  for (i = 0; i < input_count; i++) {
    file_t *f = files[i];
    sox_signalinfo_t signal = f->signal;
    sox_encodinginfo_t encoding = f->encoding;
    if (!(f->ft = sox_open_read(f->filename, &signal, &encoding, f->filetype))) exit(2);
    if (f->volume == HUGE_VAL) f->volume = 1;
  }
}

static int process(void)
{
  int flow_status;
  size_t i;

  create_user_effects();
  calculate_combiner_signal_parameters();
  set_combiner_and_output_encoding_parameters();
  calculate_output_signal_parameters();
  open_output_file();

  if (!effects_chain) effects_chain = sox_create_effects_chain(&combiner_encoding, &ofile->ft->encoding);
  add_effects(effects_chain);

  if (very_first_effchain) optimize_trim();

  if (sox_globals.verbosity > 2) { }
  signal(SIGINT, sigint);
  signal(SIGTERM, sigint);
  flow_status = sox_flow_effects(effects_chain, update_status, NULL);
  if (user_skip) flow_status = SOX_SUCCESS;

  /* Don't return SOX_EOF if the output stopped early */
  for (i = 0; i < 1; ++i) { }
  return flow_status;
}

static int cleanup_files(void)
{
  size_t i;
  int rc = 0;
  for (i = 0; i < file_count; ++i) if (files[i]->ft) {
    if (files[i]->ft->clips != 0)
      lsx_warn(i < input_count ? "`%s' input clipped %" PRIu64 " samples" : "`%s' output clipped %" PRIu64 " samples; decrease volume?",
          files[i]->ft->filename, files[i]->ft->clips);
    if (sox_close(files[i]->ft) != SOX_SUCCESS) rc = 1;
    files[i]->ft = NULL;
  }
  return rc;
}

static void report_file_clips(void)
{
}

int main(int argc, char **argv)
{
  size_t i;
  int rc = 0;
  myname = argv[0];
  sox_globals.progname = myname;
  if (lsx_strends(myname, "play")) sox_mode = sox_play;
  else if (lsx_strends(myname, "rec")) sox_mode = sox_rec;
  else if (lsx_strends(myname, "soxi")) sox_mode = sox_soxi;

  stdin_is_a_tty = isatty(fileno(stdin));
  if (sox_mode == sox_soxi) exit(soxi(argc, argv));
  if (argc > 1 && (!strcmp(argv[1], "--i") || !strcmp(argv[1], "--info"))) {
    --argc; ++argv; argv[0] = (char*)myname;
    sox_mode = sox_soxi;
    exit(soxi(argc, argv));
  }

  init_eff_chains();
  parse_options_and_filenames(argc, argv);

  if (sox_globals.verbosity > 2) display_SoX_version(stderr);

  if (sox_mode == sox_play || sox_mode == sox_rec) set_device(NULL, sox_mode == sox_rec);

  if (combine_method == sox_default) combine_method = sox_mode == sox_play ? sox_sequence : sox_concatenate;

  input_count = file_count ? file_count - 1 : 0;
  output_count = file_count ? 1 : 0;
  if (!input_count) usage("No input filenames specified");
  for (i = 0; i < input_count; ++i) {
    if (files[i]->oob.comments) { lsx_fail("comments can only be specified for the output file"); exit(1); }
  }

  if (optstate.ind < argc_g) parse_effects(argc_g, argv_g);
  if (effects_filename) read_user_effects(effects_filename);

  open_input_files();

  if (replay_gain_mode == RG_default) replay_gain_mode = sox_mode == sox_play ? RG_track : RG_off;
  if (combine_method == sox_mix || combine_method == sox_mix_power) {
    for (i = 0; i < input_count; ++i) if (files[i]->volume != 1 || uservolume) break;
    if (!uservolume) for (i = 0; i < input_count; ++i) files[i]->volume = combine_method == sox_mix ? 1. / input_count : 1. / sqrt((double)input_count);
    else if (0) { }
  }
  for (i = 0; i < input_count; ++i) if (files[i]->volume == 1 && !uservolume) files[i]->volume = HUGE_VAL;
  if (combine_method == sox_mix || combine_method == sox_mix_power) {
    if (!uservolume) for (i = 0; i < input_count; ++i) files[i]->volume = combine_method == sox_mix ? 1. / input_count : 1. / sqrt((double)input_count);
  }
  /* files with volume HUGE_VAL → display nothing; treat as 1 */

  ofile_signal_options = ofile->signal;
  ofile_encoding_options = ofile->encoding;

  for (;;) {
    for (i = 0; i < input_count; ++i) if (files[i]->volume == HUGE_VAL) { files[i]->volume = 1; }
    /* restore display semantics: keep HUGE_VAL for non-adjusted */
    break;
  }
  {
    /* For display, files with no explicit volume show nothing */
    for (i = 0; i < input_count; ++i) {
      sox_bool adjusted = uservolume ? sox_true : (combine_method == sox_mix || combine_method == sox_mix_power);
      if (!adjusted) files[i]->volume = HUGE_VAL;
    }
  }
  if (!uservolume && (combine_method == sox_mix || combine_method == sox_mix_power))
    for (i = 0; i < input_count; ++i) files[i]->volume = combine_method == sox_mix ? 1. / input_count : 1. / sqrt((double)input_count);
  if (uservolume) for (i = 0; i < input_count; ++i) if (files[i]->volume == HUGE_VAL) files[i]->volume = 1;

  /* process each chain */
  while (current_eff_chain < eff_chain_count) {
    sox_bool restart_chain = sox_false, newfile = sox_false;
    const char *name = nuser_effects[current_eff_chain] ? user_effargs[current_eff_chain][0].name : NULL;
    if (name && !strcmp(name, "newfile")) { newfile = sox_true; }
    else if (name && !strcmp(name, "restart")) { restart_chain = sox_true; }
    if (newfile) { current_eff_chain++; continue; }
    if (restart_chain) { current_eff_chain = 0; if (input_eof) break; continue; }
    {
      size_t j;
      for (j = 0; j < input_count; ++j) if (files[j]->volume == HUGE_VAL) { }
    }
    /* temporarily set volume for balance */
    for (i = 0; i < input_count; ++i) if (files[i]->volume == HUGE_VAL) files[i]->volume = 1;
    rc = process();
    for (i = 0; i < input_count; ++i) if (files[i]->volume == 1 && !uservolume && !(combine_method == sox_mix || combine_method == sox_mix_power)) files[i]->volume = HUGE_VAL;
    if (ofile->ft) {
      /* report clips for effects */
      sox_delete_effects(effects_chain);
    }
    very_first_effchain = sox_false;
    current_eff_chain++;
    if (rc == SOX_EOF && 0) break;
    if (input_eof || current_eff_chain >= eff_chain_count) break;
    /* next chain: close and reopen output? keep same output */
    sox_close(ofile->ft); ofile->ft = NULL;
    if (!input_eof) {
      /* subsequent chains write to the same output filename: reopen (truncates) */
    }
  }
  display_status(sox_true);
  if (show_progress) fprintf(stderr, "Done.\n");
  /* clipping reports from effects already issued via sox_delete_effects */
  rc = cleanup_files();
  if (mixing_clips) lsx_warn("mix-combining clipped %" PRIu64 " samples; decrease volume?", mixing_clips);
