  display_SoX_version(stdout);
  if (strcmp("all", name)) {
    if (!(f = sox_find_format(name, sox_false))) {
      printf("Cannot find a format called `%s'.\n", name);
      display_supported_formats();
    } else usage_format1(f);
  } else {
    unsigned i;
    for (i = 0; sox_format_fns[i]; ++i) {
      sox_format_handler_t const *f = sox_format_fns[i]();
      if (!(f->flags & SOX_FILE_PHONY)) usage_format1(f);
    }
  }
  exit(1);
}

static const char *str_time(double seconds)
{
  static char string[16][50];
  static int i;
  int hours, mins = seconds / 60;
  seconds -= mins * 60;
  hours = mins / 60;
  mins -= hours * 60;
  i = (i + 1) & 15;
  sprintf(string[i], "%02i:%02i:%05.2f", hours, mins, seconds);
  return string[i];
}

static void display_file_info(sox_format_t *ft, file_t *f, sox_bool full)
{
  static const char *const no_yes[] = {"no", "yes"};
  FILE *const output = sox_mode == sox_soxi ? stdout : stderr;
  const char *filetype = lsx_find_file_extension(ft->filename);
  sox_bool show_type = sox_true;
  if (filetype && !lsx_strcasecmp(filetype, ft->filetype)) show_type = sox_false;
  fprintf(output, "\n%s: '%s'", ft->mode == 'r' ? "Input File     " : "Output File    ", ft->filename);
  if (show_type) fprintf(output, " (%s)", ft->filetype);
  fprintf(output, "\nChannels       : %u\nSample Rate    : %g\nPrecision      : %u-bit\n", ft->signal.channels, ft->signal.rate, ft->signal.precision);
  if (ft->signal.length && ft->signal.channels && ft->signal.rate) {
    uint64_t ws = ft->signal.length / ft->signal.channels;
    const char *str = str_time((double)ws / ft->signal.rate);
    fprintf(output, "Duration       : %s = %" PRIu64 " samples %c %g CDDA sectors\n", str, ws,
        "=~"[ws * 75 % (uint64_t)ft->signal.rate != 0], (double)ws * 75 / ft->signal.rate);
  }
  if (ft->mode == 'r' && ft->fp) {
    uint64_t size = lsx_filelength(ft);
    fprintf(output, "File Size      : %s\n", lsx_sigfigs3((double)size));
    if (ft->signal.length && ft->signal.channels && ft->signal.rate)
      fprintf(output, "Bit Rate       : %s\n", lsx_sigfigs3(size * 8 / ((double)(ft->signal.length / ft->signal.channels) / ft->signal.rate)));
    else fprintf(output, "Bit Rate       : %s\n", lsx_sigfigs3(0));
  }
  if (ft->encoding.encoding) {
    char buffer[20] = {'\0'};
    if (ft->encoding.bits_per_sample) sprintf(buffer, "%u-bit ", ft->encoding.bits_per_sample);
    fprintf(output, "Sample Encoding: %s%s\n", buffer, sox_encodings_info[ft->encoding.encoding].desc);
  }
  if (full) {
    if (ft->encoding.bits_per_sample > 8 || (ft->handler.flags & SOX_FILE_ENDIAN))
      fprintf(output, "Endian Type    : %s\n", ft->encoding.reverse_bytes != 0 ? "big" : "little");
    if (ft->encoding.bits_per_sample)
      fprintf(output, "Reverse Nibbles: %s\nReverse Bits   : %s\n", no_yes[ft->encoding.reverse_nibbles], no_yes[ft->encoding.reverse_bits]);
  }
  if (f && f->replay_gain != HUGE_VAL) fprintf(output, "Replay gain    : %+g dB\n", f->replay_gain);
  if (f && f->volume != HUGE_VAL) fprintf(output, "Level adjust   : %g (linear gain)\n", f->volume);
  if (!(ft->handler.flags & SOX_FILE_DEVICE) && ft->oob.comments) {
    if (sox_num_comments(ft->oob.comments) > 1) {
      sox_comments_t p = ft->oob.comments;
      fprintf(output, "Comments       : \n");
      do fprintf(output, "%s\n", *p); while (*++p);
    } else fprintf(output, "Comment        : '%s'\n", ft->oob.comments[0]);
  }
  fprintf(output, "\n");
}

static void report_file_info(file_t *f)
{
  if (sox_globals.verbosity > 2) display_file_info(f->ft, f, sox_true);
  else if (show_progress) display_file_info(f->ft, f, sox_false);
}

/* ---------- soxi ---------- */
static int soxi1(enum { Full, Type, Rate, Channels, Samples, Duration, Duration_secs, Bits, Bitrate, Precision, Encoding, Annotation } const *type, const char *filename, sox_bool total_mode, double *total)
{
  sox_format_t *ft = sox_open_read(filename, NULL, NULL, NULL);
  double secs;
  uint64_t ws;
  char const *text = NULL;
  if (!ft) return 1;
  ws = ft->signal.length / max(ft->signal.channels, 1);
  secs = (double)ws / max(ft->signal.rate, 1);
  switch (*type) {
    case Full: display_file_info(ft, NULL, sox_false); break;
    case Type: printf("%s\n", ft->filetype); break;
    case Rate: printf("%g\n", ft->signal.rate); break;
    case Channels: printf("%u\n", ft->signal.channels); break;
    case Samples: if (total_mode) *total += ws; else printf("%" PRIu64 "\n", ws); break;
    case Duration: if (total_mode) *total += secs; else printf("%s\n", str_time(secs)); break;
    case Duration_secs: if (total_mode) *total += secs; else printf("%f\n", secs); break;
    case Bits: printf("%u\n", ft->encoding.bits_per_sample); break;
    case Bitrate: {
      uint64_t size = lsx_filelength(ft);
      printf("%s\n", lsx_sigfigs3(ws && ft->signal.rate ? size * 8 / secs : 0));
      break; }
    case Precision: printf("%u\n", ft->signal.precision); break;
    case Encoding: printf("%s\n", sox_encodings_info[ft->encoding.encoding].desc); break;
    case Annotation: if (ft->oob.comments) { sox_comments_t p = ft->oob.comments; do printf("%s\n", *p); while (*++p); } break;
  }
  sox_close(ft);
  return 0;
}

static int soxi(int argc, char * const *argv)
{
  static const char *const usage_text = "Usage: soxi [-V[level]] [-T] [-t|-r|-c|-s|-d|-D|-b|-B|-p|-e|-a] infile1 ...\n"
    "\n-V[n]\tIncrement or set verbosity level (default is 2)\n-T\tWith -s, -d or -D, display the total across all given files\n\n"
    "-t\tShow detected file-type\n-r\tShow sample-rate\n-c\tShow number of channels\n-s\tShow number of samples (0 if unavailable)\n"
    "-d\tShow duration in hours, minutes and seconds (0 if unavailable)\n-D\tShow duration in seconds (0 if unavailable)\n"
    "-b\tShow number of bits per sample (0 if not applicable)\n-B\tShow the bitrate averaged over the whole file (0 if unavailable)\n"
    "-p\tShow estimated sample precision in bits\n-e\tShow the name of the audio encoding\n-a\tShow file comments (annotations) if available\n\n"
    "With no options, as much information as is available is shown for\neach given file.\n";
  int type = 0, opt, num_errors = 0;
  sox_bool total_mode = sox_false;
  double total = 0;
  const char *opts = "trcsdDbBpea?TV::";
  lsx_getopt_t state;
  lsx_getopt_init(argc, argv, opts, NULL, lsx_getopt_flag_opterr, 1, &state);
  while ((opt = lsx_getopt_s(&state)) != -1) {
    if (opt == 'V') {
      if (state.arg) {
        char *end; long v = strtol(state.arg, &end, 10);
        if (*end || v < 0) { lsx_fail("Verbosity value `%s' is not a non-negative integer", state.arg); exit(1); }
        sox_globals.verbosity = (unsigned)v;
      } else sox_globals.verbosity++;
    }
    else if (opt == 'T') total_mode = sox_true;
    else if (opt == '?') { display_SoX_version(stdout); printf("\n%s", usage_text); return 1; }
    else {
      const char *p = strchr("\0trcsdDbBpea", opt);
      if (!p) { display_SoX_version(stdout); printf("\n%s", usage_text); return 1; }
      type = (int)(p - "\0trcsdDbBpea");
    }
  }
  if (state.ind >= argc) { display_SoX_version(stdout); printf("\n%s", usage_text); return 0; }
  for (; state.ind < argc; ++state.ind) {
    num_errors += soxi1((void*)&type, argv[state.ind], total_mode, &total);
  }
  if (total_mode) {
    if (type == 5) printf("%s\n", str_time(total));
    else printf("%f\n", total);
  }
  return num_errors;
}

