  effects_chain = NULL;

  for (i = 0; i < file_count; ++i) if (files[i]->ft && files[i]->ft->clips != 0)
    lsx_warn(i < input_count ? "`%s' input clipped %" PRIu64 " samples" : "`%s' output clipped %" PRIu64 " samples; decrease volume?",
        files[i]->ft->filename, files[i]->ft->clips);
  if (mixing_clips > 0) lsx_warn("mix-combining clipped %" PRIu64 " samples; decrease volume?", mixing_clips);
  for (i = 0; i < file_count; i++) if (files[i]->volume_clips > 0)
    lsx_warn("`%s' balancing clipped %" PRIu64 " samples; decrease volume?", files[i]->filename, files[i]->volume_clips);
  if (show_progress) {
