    if (findChunk(ft, "ds64", &len) == SOX_EOF) { lsx_fail_errno(ft, SOX_EHDR, "WAVE file RF64 header is missing ds64 chunk"); return SOX_EOF; }
    lsx_readqw(ft, &qwRiffLength); lsx_readqw(ft, &qwDataLength); lsx_readqw(ft, &qwSampleCount);
    lsx_seeki(ft, (int64_t)(len - 24), SEEK_CUR);
  }

  /* Now look for the format chunk */
  if (findChunk(ft, "fmt ", &len) == SOX_EOF) { lsx_fail_errno(ft, SOX_EHDR, "WAVE chunk fmt not found"); return SOX_EOF; }
  wFmtSize = (unsigned short)len;
  if (wFmtSize < 16) { lsx_fail_errno(ft, SOX_EHDR, "WAVE file fmt chunk is too short"); return SOX_EOF; }
  lsx_readw(ft, &wav->formatTag);
  lsx_readw(ft, &wChannels);
  lsx_readdw(ft, &dwSamplesPerSecond);
  lsx_readdw(ft, &dwAvgBytesPerSec);
  lsx_readw(ft, &wav->blockAlign);
  lsx_readw(ft, &wBitsPerSample);
  len -= 16;

  if (wav->formatTag == WAVE_FORMAT_EXTENSIBLE) {
    uint16_t extensionSize, numberOfValidBits;
    uint32_t speakerPositionMask;
    uint16_t subFormatTag;
    uint8_t dummyByte;
    int i;
    if (wFmtSize < 18) { lsx_fail_errno(ft, SOX_EHDR, "WAVE file fmt chunk is too short"); return SOX_EOF; }
    lsx_readw(ft, &extensionSize); len -= 2;
    if (extensionSize < 22) { lsx_fail_errno(ft, SOX_EHDR, "WAVE file fmt chunk is too short"); return SOX_EOF; }
    lsx_readw(ft, &numberOfValidBits);
    lsx_readdw(ft, &speakerPositionMask);
    lsx_readw(ft, &subFormatTag);
    for (i = 0; i < 14; ++i) lsx_readb(ft, &dummyByte);
    len -= 22;
    if (numberOfValidBits > wBitsPerSample) { lsx_fail_errno(ft, SOX_EHDR, "WAVE file fmt with padded samples is not supported yet"); return SOX_EOF; }
    wBitsPerSample = numberOfValidBits;
    wav->formatTag = subFormatTag;
    lsx_report("EXTENSIBLE");
  }

  switch (wav->formatTag) {
  case WAVE_FORMAT_UNKNOWN: return wavfail(ft, "Microsoft Official Unknown");
  case WAVE_FORMAT_PCM:
    if (wBitsPerSample <= 8) encoding = SOX_ENCODING_UNSIGNED; else encoding = SOX_ENCODING_SIGN2;
    if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN || ft->encoding.encoding == SOX_ENCODING_UNSIGNED || ft->encoding.encoding == SOX_ENCODING_SIGN2) ft->encoding.encoding = encoding;
    break;
  case WAVE_FORMAT_IMA_ADPCM:
    if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN || ft->encoding.encoding == SOX_ENCODING_IMA_ADPCM) ft->encoding.encoding = SOX_ENCODING_IMA_ADPCM;
    else return wavfail(ft, "IMA ADPCM");
    break;
  case WAVE_FORMAT_ADPCM:
    if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN || ft->encoding.encoding == SOX_ENCODING_MS_ADPCM) ft->encoding.encoding = SOX_ENCODING_MS_ADPCM;
    else return wavfail(ft, "Microsoft ADPCM");
    break;
  case WAVE_FORMAT_IEEE_FLOAT:
    if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN || ft->encoding.encoding == SOX_ENCODING_FLOAT) ft->encoding.encoding = SOX_ENCODING_FLOAT;
    else return wavfail(ft, "IEEE Float");
    break;
  case WAVE_FORMAT_ALAW:
    if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN || ft->encoding.encoding == SOX_ENCODING_ALAW) ft->encoding.encoding = SOX_ENCODING_ALAW;
    else return wavfail(ft, "Microsoft A-law");
    break;
  case WAVE_FORMAT_MULAW:
    if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN || ft->encoding.encoding == SOX_ENCODING_ULAW) ft->encoding.encoding = SOX_ENCODING_ULAW;
    else return wavfail(ft, "Microsoft U-law");
    break;
  case WAVE_FORMAT_GSM610:
    return wavfail(ft, "GSM 6.10");
  default: return wavfail(ft, wav_format_str(wav->formatTag));
  }

  if (ft->signal.channels == 0 || ft->signal.channels == wChannels) ft->signal.channels = wChannels;
  else if (wChannels != ft->signal.channels) lsx_report("User options overriding channels read in .wav header");
  if (ft->signal.channels == 0) { lsx_fail_errno(ft, SOX_EHDR, "Channel count is zero"); return SOX_EOF; }

  if (ft->signal.rate == 0 || ft->signal.rate == dwSamplesPerSecond) ft->signal.rate = dwSamplesPerSecond;
  else lsx_report("User options overriding rate read in .wav header");

  wav->lsx_ms_adpcm_i_coefs = NULL;
  wav->packet = NULL;
  wav->samples = NULL;

  switch (wav->formatTag) {
  case WAVE_FORMAT_ADPCM:
    if (wBitsPerSample != 4) { lsx_fail_errno(ft, SOX_EOF, "Can only handle 4-bit MS ADPCM in wav files"); return SOX_EOF; }
    if (len < 4) { lsx_fail_errno(ft, SOX_EHDR, "WAVE file fmt chunk is too short"); return SOX_EOF; }
    lsx_readw(ft, &wExtSize);
    lsx_readw(ft, &wav->samplesPerBlock);
    bytesPerBlock = lsx_ms_adpcm_bytes_per_block(ft->signal.channels, wav->samplesPerBlock);
    if (bytesPerBlock > wav->blockAlign) {
      lsx_fail_errno(ft, SOX_EOF, "format[%s]: samplesPerBlock(%d) incompatible with blockAlign(%d)", wav_format_str(wav->formatTag), wav->samplesPerBlock, wav->blockAlign);
      return SOX_EOF;
    }
    lsx_readw(ft, &wav->nCoefs);
    if (wav->nCoefs < 7 || wav->nCoefs > 0x100) { lsx_fail_errno(ft, SOX_EOF, "ADPCM file nCoefs (%.4hx) makes no sense", wav->nCoefs); return SOX_EOF; }
    wav->packet = lsx_malloc((size_t)wav->blockAlign);
    len -= 6;
    if (wExtSize < 4 + 4 * wav->nCoefs) { lsx_fail_errno(ft, SOX_EOF, "wave header error: wExtSize=%d too small for nCoefs=%d", wExtSize, wav->nCoefs); return SOX_EOF; }
    wav->samples = lsx_malloc(wChannels * wav->samplesPerBlock * sizeof(short));
    wav->lsx_ms_adpcm_i_coefs = lsx_malloc(wav->nCoefs * 2 * sizeof(short));
    {
      int i, errct = 0;
      for (i = 0; len >= 2 && i < 2 * wav->nCoefs; i++) {
        lsx_readsw(ft, &wav->lsx_ms_adpcm_i_coefs[i]);
        len -= 2;
        if (i < 14) errct += (wav->lsx_ms_adpcm_i_coefs[i] != lsx_ms_adpcm_i_coef[i / 2][i % 2]);
      }
      if (errct) lsx_warn("base lsx_ms_adpcm_i_coefs differ in %d/14 positions", errct);
    }
    wav->ms_adpcm_data = lsx_ms_adpcm_alloc(wChannels);
    bytespersample = 2;
    break;
  case WAVE_FORMAT_IMA_ADPCM:
    if (wBitsPerSample != 4) { lsx_fail_errno(ft, SOX_EOF, "Can only handle 4-bit IMA ADPCM in wav files"); return SOX_EOF; }
    if (len < 4) { lsx_fail_errno(ft, SOX_EHDR, "WAVE file fmt chunk is too short"); return SOX_EOF; }
    lsx_readw(ft, &wExtSize);
    lsx_readw(ft, &wav->samplesPerBlock);
    bytesPerBlock = lsx_ima_bytes_per_block(ft->signal.channels, wav->samplesPerBlock);
    if (bytesPerBlock > wav->blockAlign || wav->samplesPerBlock % 8 != 1) {
      lsx_fail_errno(ft, SOX_EOF, "format[%s]: samplesPerBlock(%d) incompatible with blockAlign(%d)", wav_format_str(wav->formatTag), wav->samplesPerBlock, wav->blockAlign);
      return SOX_EOF;
    }
    wav->packet = lsx_malloc((size_t)wav->blockAlign);
    len -= 4;
    wav->samples = lsx_malloc(wChannels * wav->samplesPerBlock * sizeof(short));
    bytespersample = 2;
    break;
  default:
    bytespersample = (wBitsPerSample + 7) / 8;
  }

  switch (bytespersample) {
  case 1: break;
  case 2: case 3: case 4: case 8: break;
  default:
    lsx_fail_errno(ft, SOX_EFMT, "Sorry, don't understand .wav size");
    return SOX_EOF;
  }
  if (wav->formatTag != WAVE_FORMAT_ADPCM && wav->formatTag != WAVE_FORMAT_IMA_ADPCM) {
    if (ft->encoding.bits_per_sample == 0 || ft->encoding.bits_per_sample == wBitsPerSample) ft->encoding.bits_per_sample = wBitsPerSample;
    else lsx_warn("User options overriding size read in .wav header");
  } else ft->encoding.bits_per_sample = wBitsPerSample;

  /* Skip anything left over from fmt chunk */
  lsx_seeki(ft, (int64_t)len, SEEK_CUR);

  /* for non-PCM formats, there's a fact chunk */
  if (wav->formatTag != WAVE_FORMAT_PCM) {
    /* fact chunk is optional; look for it when searching for data */
  }

  /* Now look for the data chunk; also handle LIST chunk etc. */
  for (;;) {
    if (lsx_reads(ft, magic, 4) == SOX_EOF) { lsx_fail_errno(ft, SOX_EHDR, "WAVE file has missing data chunk"); return SOX_EOF; }
    if (lsx_readdw(ft, &len) == SOX_EOF) { lsx_fail_errno(ft, SOX_EHDR, "WAVE file %s chunk is too short", magic); return SOX_EOF; }
    if (strncmp("data", magic, 4) == 0) break;
    if (strncmp("fact", magic, 4) == 0 && len >= 4) {
      lsx_readdw(ft, &dwFact);
      if (len > 4) lsx_seeki(ft, (int64_t)((len + 1) & ~1u) - 4, SEEK_CUR);
      continue;
    }
    if (lsx_seeki(ft, (int64_t)((len + 1) & ~1u), SEEK_CUR) != SOX_SUCCESS) {
      lsx_fail_errno(ft, SOX_EHDR, "WAV chunk appears to have invalid size %d.", len);
      return SOX_EOF;
    }
  }
  dwDataLength = len;
  if (isRF64 && dwDataLength == 0xffffffff) wav->dataLength = qwDataLength;
  else wav->dataLength = dwDataLength;
  (void)dwFact;

  /* Data starts here */
  wav->dataStart = lsx_tell(ft);

  switch (wav->formatTag) {
  case WAVE_FORMAT_ADPCM:
    wav->numSamples = lsx_ms_adpcm_samples_in(wav->dataLength, ft->signal.channels, wav->blockAlign, wav->samplesPerBlock);
    wav->blockSamplesRemaining = 0;
    break;
  case WAVE_FORMAT_IMA_ADPCM:
    wav->numSamples = lsx_ima_samples_in(wav->dataLength, ft->signal.channels, wav->blockAlign, wav->samplesPerBlock);
    wav->blockSamplesRemaining = 0;
    lsx_ima_init_table();
    break;
  default:
    wav->numSamples = wav->dataLength / ft->encoding.bits_per_sample * 8 / ft->signal.channels;
    {
      unsigned bps = ft->encoding.bits_per_sample;
      wav->numSamples = (bps ? wav->dataLength / ((bps + 7) / 8) : 0) / ft->signal.channels;
    }
  }
  if (dwDataLength == 0xffffffff && !isRF64) {
    /* data length unknown */
    wav->ignoreSize = sox_true;
    ft->signal.length = SOX_UNKNOWN_LEN;
    wav->numSamples = 0;
  } else ft->signal.length = wav->numSamples * ft->signal.channels;
  if (wav->ignoreSize && ft->signal.length != SOX_UNKNOWN_LEN) ft->signal.length = SOX_UNSPEC;

  lsx_debug("Found chunk 'fmt ', size %u", (unsigned)wFmtSize);
  lsx_debug("Found chunk 'data', size %u", (unsigned)dwDataLength);
  return lsx_rawstartread(ft) == SOX_SUCCESS ? SOX_SUCCESS : SOX_EOF;
}

static size_t read_samples(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  priv_t *wav = (priv_t *)ft->priv;
  size_t done;
  SOX_SAMPLE_LOCALS;
  if (!wav->ignoreSize && ft->signal.length != SOX_UNKNOWN_LEN) len = min(len, (size_t)(wav->numSamples * ft->signal.channels));
  if (len == 0) return 0;
  switch (wav->formatTag) {
  case WAVE_FORMAT_IMA_ADPCM:
  case WAVE_FORMAT_ADPCM:
    done = 0;
    while (done < len) {
      short *p, *top;
      size_t ct;
      if (wav->blockSamplesRemaining == 0) {
        wav->blockSamplesRemaining = AdpcmReadBlock(ft);
        if (wav->blockSamplesRemaining == 0) {
          wav->numSamples = 0;
          return done;
        }
        wav->samplePtr = wav->samples;
      }
      p = wav->samplePtr;
      top = p + wav->blockSamplesRemaining * ft->signal.channels;
      ct = len - done;
      if (ct > (size_t)(top - p)) ct = top - p;
      top = p + ct;
      while (p < top) *buf++ = SOX_SIGNED_16BIT_TO_SAMPLE(*p++, dummy);
      wav->samplePtr = p;
      wav->blockSamplesRemaining = (unsigned short)((top - p + ct) / ft->signal.channels);
      wav->blockSamplesRemaining = (unsigned short)((wav->samplePtr - wav->samples) ? 0 : 0);
      /* recompute remaining */
      {
        size_t consumed = (size_t)(wav->samplePtr - wav->samples) / ft->signal.channels;
        wav->blockSamplesRemaining = (unsigned short)(wav->samplesPerBlock - consumed);
      }
      done += ct;
    }
    break;
  default:
    done = lsx_rawread(ft, buf, len);
    if (done == 0 && wav->numSamples != 0 && !wav->ignoreSize && ft->signal.length != SOX_UNKNOWN_LEN) lsx_warn("Premature EOF on .wav input file");
  }
  if (!wav->ignoreSize && ft->signal.length != SOX_UNKNOWN_LEN) {
    if (done / ft->signal.channels > wav->numSamples) wav->numSamples = 0;
    else wav->numSamples -= done / ft->signal.channels;
  }
  return done;
}

static int stopread(sox_format_t *ft)
{
  priv_t *wav = (priv_t *)ft->priv;
  free(wav->packet); free(wav->samples); free(wav->lsx_ms_adpcm_i_coefs);
  if (wav->ms_adpcm_data) free(wav->ms_adpcm_data);
  return SOX_SUCCESS;
}

static int wavwritehdr(sox_format_t *ft, int second_header)
{
  priv_t *wav = (priv_t *)ft->priv;
  uint32_t wRiffLength;
  uint16_t wFormatTag = 0;
  uint16_t wChannels;
  uint32_t dwSamplesPerSecond;
  uint32_t dwAvgBytesPerSec;
  uint16_t wBlockAlign;
  uint16_t wBitsPerSample;
  uint32_t dwDataLength;
  uint16_t wExtSize = 0;
  uint16_t wSamplesPerBlock;
  uint16_t wValidBitsPerSample;
  uint32_t dwChannelMask;
  uint16_t wFmtSize;
  sox_bool isExtensible = sox_false;
  uint64_t numSamples;
  sox_bool fact = sox_false;
  sox_bool isRF64 = sox_false;

  wChannels = (uint16_t)ft->signal.channels;
  dwSamplesPerSecond = (uint32_t)(ft->signal.rate + .5);
  wBitsPerSample = (uint16_t)ft->encoding.bits_per_sample;
  wSamplesPerBlock = 1;

  switch (ft->encoding.encoding) {
  case SOX_ENCODING_UNSIGNED:
  case SOX_ENCODING_SIGN2:
    wFormatTag = WAVE_FORMAT_PCM;
    wBlockAlign = (uint16_t)(wChannels * ((wBitsPerSample + 7) / 8));
    break;
  case SOX_ENCODING_FLOAT:
    wFormatTag = WAVE_FORMAT_IEEE_FLOAT;
    wBlockAlign = (uint16_t)(wChannels * ((wBitsPerSample + 7) / 8));
    break;
  case SOX_ENCODING_ALAW:
    wFormatTag = WAVE_FORMAT_ALAW;
    wBlockAlign = wChannels;
    break;
  case SOX_ENCODING_ULAW:
    wFormatTag = WAVE_FORMAT_MULAW;
    wBlockAlign = wChannels;
    break;
  case SOX_ENCODING_IMA_ADPCM:
    if (wChannels > 16) { lsx_fail_errno(ft, SOX_EOF, "Channels(%d) must be <= 16", wChannels); return SOX_EOF; }
    wFormatTag = WAVE_FORMAT_IMA_ADPCM;
    wBlockAlign = (uint16_t)(wChannels * 256);
    wSamplesPerBlock = (uint16_t)(lsx_ima_samples_in((size_t)0, wChannels, wBlockAlign, 0));
    wExtSize = 2;
    break;
  case SOX_ENCODING_MS_ADPCM:
    if (wChannels > 16) { lsx_fail_errno(ft, SOX_EOF, "Channels(%d) must be <= 16", wChannels); return SOX_EOF; }
    wFormatTag = WAVE_FORMAT_ADPCM;
    wBlockAlign = (uint16_t)(wChannels * 128);
    wSamplesPerBlock = (uint16_t)lsx_ms_adpcm_samples_in((size_t)0, wChannels, wBlockAlign, 0);
    wExtSize = (uint16_t)(4 + 4 * 7);
    break;
  default: break;
  }
  wav->formatTag = wFormatTag;
  wav->blockAlign = wBlockAlign;
  wav->samplesPerBlock = wSamplesPerBlock;

  if (!second_header) {
    numSamples = ft->signal.length ? ft->signal.length / wChannels : 0;
    if (ft->signal.length == SOX_UNKNOWN_LEN) numSamples = 0;
  } else numSamples = wav->numSamples;

  if (second_header) dwDataLength = (uint32_t)wav->dataLength;
  else if (!ft->signal.length || ft->signal.length == SOX_UNKNOWN_LEN) dwDataLength = 0xffffffff;
  else switch (wFormatTag) {
    case WAVE_FORMAT_ADPCM: dwDataLength = (uint32_t)(lsx_ms_adpcm_bytes_per_block(wChannels, wSamplesPerBlock) * ((numSamples + wSamplesPerBlock - 1) / wSamplesPerBlock)); break;
    case WAVE_FORMAT_IMA_ADPCM: dwDataLength = (uint32_t)(lsx_ima_bytes_per_block(wChannels, wSamplesPerBlock) * ((numSamples + wSamplesPerBlock - 1) / wSamplesPerBlock)); break;
    default: dwDataLength = (uint32_t)(numSamples * wBlockAlign);
  }
  if (wFormatTag == WAVE_FORMAT_ADPCM || wFormatTag == WAVE_FORMAT_IMA_ADPCM)
    dwAvgBytesPerSec = (uint32_t)((double)wBlockAlign * dwSamplesPerSecond / wSamplesPerBlock + 0.5);
  else dwAvgBytesPerSec = dwSamplesPerSecond * wBlockAlign;

  isExtensible = wFormatTag == WAVE_FORMAT_PCM && (wBitsPerSample > 16 || wChannels > 2);
  if (isExtensible) { wExtSize = 22; wFmtSize = 40; }
  else if (wFormatTag != WAVE_FORMAT_PCM) wFmtSize = 18 + wExtSize;
  else wFmtSize = 16;
  fact = wFormatTag != WAVE_FORMAT_PCM || isExtensible;

  wRiffLength = 4 + (8 + wFmtSize) + (fact ? 12 : 0) + 8 + (dwDataLength == 0xffffffff ? 0 : dwDataLength + (dwDataLength & 1));
  if (dwDataLength == 0xffffffff) wRiffLength = 4 + (8 + wFmtSize) + (fact ? 12 : 0) + 8 ;
  (void)isRF64;

  lsx_writes(ft, "RIFF");
  lsx_writedw(ft, wRiffLength);
  lsx_writes(ft, "WAVE");
  lsx_writes(ft, "fmt ");
  lsx_writedw(ft, wFmtSize);
  lsx_writew(ft, isExtensible ? WAVE_FORMAT_EXTENSIBLE : wFormatTag);
  lsx_writew(ft, wChannels);
  lsx_writedw(ft, dwSamplesPerSecond);
  lsx_writedw(ft, dwAvgBytesPerSec);
  lsx_writew(ft, wBlockAlign);
  lsx_writew(ft, wBitsPerSample);
  if (isExtensible) {
    static const unsigned char guids[][14] = {
      {0x00,0x00,0x00,0x00,0x10,0x00,0x80,0x00,0x00,0xaa,0x00,0x38,0x9b,0x71}
    };
    wValidBitsPerSample = wBitsPerSample;
    dwChannelMask = wChannels == 1 ? 0x4 : wChannels == 2 ? 0x3 : wChannels == 4 ? 0x33 : wChannels == 6 ? 0x3f : wChannels == 8 ? 0x63f : 0;
    lsx_writew(ft, wExtSize);
    lsx_writew(ft, wValidBitsPerSample);
    lsx_writedw(ft, dwChannelMask);
    lsx_writew(ft, wFormatTag);
    lsx_writebuf(ft, guids[0], 14);
  } else if (wFormatTag != WAVE_FORMAT_PCM) lsx_writew(ft, wExtSize);
  switch (wFormatTag) {
  case WAVE_FORMAT_IMA_ADPCM:
    lsx_writew(ft, wSamplesPerBlock);
    break;
  case WAVE_FORMAT_ADPCM: {
    int i;
    lsx_writew(ft, wSamplesPerBlock);
    lsx_writew(ft, 7);
    for (i = 0; i < 7; i++) { lsx_writesw(ft, lsx_ms_adpcm_i_coef[i][0]); lsx_writesw(ft, lsx_ms_adpcm_i_coef[i][1]); }
    break; }
  default: break;
  }
  if (fact) {
    lsx_writes(ft, "fact");
    lsx_writedw(ft, 4);
    lsx_writedw(ft, dwDataLength == 0xffffffff ? 0 : (uint32_t)numSamples);
  }
  lsx_writes(ft, "data");
  lsx_writedw(ft, dwDataLength);

  if (!second_header) {
    lsx_debug("Writing Wave file: %s format, %d channel%s, %d samp/sec", wav_format_str(wFormatTag), wChannels, wChannels == 1 ? "" : "s", dwSamplesPerSecond);
    lsx_debug("        %d byte/sec, %d block align, %d bits/samp", dwAvgBytesPerSec, wBlockAlign, wBitsPerSample);
  } else
    lsx_debug("Finished writing Wave file, %u data bytes %" PRIu64 " samples", dwDataLength, numSamples);
  return SOX_SUCCESS;
}

static const char *wav_format_str_w(unsigned tag)
{
  switch (tag) {
    case WAVE_FORMAT_PCM: return "PCM";
    case WAVE_FORMAT_ADPCM: return "Microsoft ADPCM";
    case WAVE_FORMAT_IEEE_FLOAT: return "IEEE Float";
    case WAVE_FORMAT_ALAW: return "CCITT A-law";
    case WAVE_FORMAT_MULAW: return "CCITT u-law";
    case WAVE_FORMAT_IMA_ADPCM: return "IMA ADPCM";
    default: return wav_format_str(tag);
  }
}

static int startwrite(sox_format_t *ft)
{
  priv_t *wav = (priv_t *)ft->priv;
  int rc;
  ft->sox_errno = SOX_SUCCESS;
  if (ft->encoding.encoding != SOX_ENCODING_MS_ADPCM && ft->encoding.encoding != SOX_ENCODING_IMA_ADPCM) {
    rc = lsx_rawstartwrite(ft);
    if (rc) return rc;
  }
  wav->numSamples = 0;
  wav->dataLength = 0;
  if (!ft->signal.length && !ft->seekable) lsx_warn("Length in output .wav header will be wrong since can't seek to fix it");
  if (ft->signal.length == SOX_UNKNOWN_LEN && !ft->seekable) lsx_warn("Length in output .wav header will be wrong since can't seek to fix it");
  rc = wavwritehdr(ft, 0);
  if (rc != 0) return rc;
  wav->packet = NULL; wav->samples = NULL;
  if (wav->formatTag == WAVE_FORMAT_ADPCM || wav->formatTag == WAVE_FORMAT_IMA_ADPCM) {
    size_t ch, sbsize;
    wav->packet = lsx_malloc((size_t)wav->blockAlign);
    sbsize = ft->signal.channels * wav->samplesPerBlock;
    wav->samples = lsx_malloc(sbsize * sizeof(short));
    wav->sampleTop = wav->samples + sbsize;
    wav->samplePtr = wav->samples;
    for (ch = 0; ch < ft->signal.channels; ch++) wav->state[ch] = 0;
    if (wav->formatTag == WAVE_FORMAT_IMA_ADPCM) lsx_ima_init_table();
  }
  return SOX_SUCCESS;
}

static size_t write_samples(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  priv_t *wav = (priv_t *)ft->priv;
  size_t total_len = len;
  SOX_SAMPLE_LOCALS;
  ft->sox_errno = SOX_SUCCESS;
  switch (wav->formatTag) {
  case WAVE_FORMAT_IMA_ADPCM:
  case WAVE_FORMAT_ADPCM:
    while (len > 0) {
      short *p = wav->samplePtr;
      short *top = wav->sampleTop;
      if (top > p + len) top = p + len;
      len -= top - p;
      for (; p < top; p++) *p = SOX_SAMPLE_TO_SIGNED_16BIT(*buf++, ft->clips);
      wav->samplePtr = p;
      if (p == wav->sampleTop) xxxAdpcmWriteBlock(ft);
    }
    return total_len - len;
  default:
    len = lsx_rawwrite(ft, buf, len);
    wav->numSamples += len / ft->signal.channels;
    wav->dataLength += len * ((ft->encoding.bits_per_sample + 7) / 8);
    return len;
  }
}

static int stopwrite(sox_format_t *ft)
{
  priv_t *wav = (priv_t *)ft->priv;
  if (wav->formatTag == WAVE_FORMAT_ADPCM || wav->formatTag == WAVE_FORMAT_IMA_ADPCM) xxxAdpcmWriteBlock(ft);
  /* pad byte */
  if (wav->dataLength & 1) { lsx_writeb(ft, 0); }
  free(wav->packet); free(wav->samples); free(wav->lsx_ms_adpcm_i_coefs);
  wav->packet = NULL; wav->samples = NULL; wav->lsx_ms_adpcm_i_coefs = NULL;
  if (!ft->seekable) return SOX_SUCCESS;
  if (ft->signal.length && ft->signal.length != SOX_UNKNOWN_LEN && ft->signal.length / ft->signal.channels == wav->numSamples &&
      !(wav->formatTag == WAVE_FORMAT_ADPCM || wav->formatTag == WAVE_FORMAT_IMA_ADPCM)) return SOX_SUCCESS;
  if (lsx_seeki(ft, 0, SEEK_SET) != 0) {
    lsx_fail_errno(ft, SOX_EOF, "Can't rewind output file to rewrite .wav header.");
    return SOX_EOF;
  }
  return wavwritehdr(ft, 1);
}

static int seek(sox_format_t *ft, uint64_t offset)
{
  priv_t *wav = (priv_t *)ft->priv;
  if (ft->encoding.bits_per_sample & 7) {
    lsx_fail_errno(ft, SOX_ENOTSUP, "seeking not supported with this encoding");
    return SOX_EOF;
  }
  if (wav->formatTag == WAVE_FORMAT_ADPCM || wav->formatTag == WAVE_FORMAT_IMA_ADPCM) {
    uint64_t gran = wav->samplesPerBlock;
    uint64_t block = offset / ft->signal.channels / gran;
    uint64_t rem = offset / ft->signal.channels - block * gran;
    int rc = lsx_seeki(ft, (int64_t)(wav->dataStart + block * wav->blockAlign), SEEK_SET);
    if (rc != SOX_SUCCESS) return rc;
    wav->blockSamplesRemaining = 0;
    /* skip within block */
    if (rem) {
      wav->blockSamplesRemaining = AdpcmReadBlock(ft);
      if (wav->blockSamplesRemaining) {
        wav->samplePtr = wav->samples + rem * ft->signal.channels;
        wav->blockSamplesRemaining = (unsigned short)(wav->samplesPerBlock - rem);
      }
    }
    wav->numSamples = lsx_ima_samples_in(wav->dataLength, ft->signal.channels, wav->blockAlign, wav->samplesPerBlock);
    wav->numSamples = wav->numSamples > offset / ft->signal.channels ? wav->numSamples - offset / ft->signal.channels : 0;
    return SOX_SUCCESS;
  } else {
    double wide_sample = offset - (offset % ft->signal.channels);
    double to_d = wide_sample * ft->encoding.bits_per_sample / 8;
    off_t to = (off_t)to_d;
    ft->sox_errno = (to != to_d) ? SOX_EOF : lsx_seeki(ft, (int64_t)(wav->dataStart + to), SEEK_SET);
    if (ft->sox_errno == SOX_SUCCESS) {
      uint64_t total = ft->signal.length != SOX_UNKNOWN_LEN ? ft->signal.length / ft->signal.channels : 0;
      wav->numSamples = total - (uint64_t)(wide_sample / ft->signal.channels);
    }
  }
  return ft->sox_errno;
}

const sox_format_handler_t *lsx_wav_format_fn(void)
{
  static const char *const names[] = {"wav", "wavpcm", "amb", NULL};
  static const unsigned write_encodings[] = {
    SOX_ENCODING_SIGN2, 16, 24, 32, 0,
    SOX_ENCODING_UNSIGNED, 8, 0,
    SOX_ENCODING_ULAW, 8, 0,
    SOX_ENCODING_ALAW, 8, 0,
    SOX_ENCODING_MS_ADPCM, 4, 0,
    SOX_ENCODING_IMA_ADPCM, 4, 0,
    SOX_ENCODING_FLOAT, 32, 64, 0,
    0 };
  static const sox_format_handler_t handler = {
    "Microsoft audio format", names, SOX_FILE_LIT_END,
    startread, read_samples, stopread, startwrite, write_samples, stopwrite, seek,
    write_encodings, NULL, sizeof(priv_t) };
  return &handler;
}
EOF
echo ok"}

