/* MS ADPCM codec */
#define lsx_subsystem_name "adpcm"
#include "adpcms.h"

typedef struct { int nCoef; const short *coef; } ms_priv_t;

const short lsx_ms_adpcm_i_coef[7][2] = { {256, 0}, {512, -256}, {0, 0}, {192, 64}, {240, 0}, {460, -208}, {392, -232} };
static const int stepAdjustTable[] = { 230, 230, 230, 230, 307, 409, 512, 614, 768, 614, 512, 409, 307, 230, 230, 230 };

typedef struct { int step; int iCoef[2]; int sample1, sample2; } MsState_t;

static inline int lsx_ms_adpcm_i_step(int d, int *idelta) { (void)d; return *idelta; }

static void AdpcmDecode(int c, MsState_t *state, const short *coef_unused, int *vp)
{
  int vlin, sample, step;
  (void)coef_unused;
  vlin = (state->sample1 * state->iCoef[0] + state->sample2 * state->iCoef[1]) >> 8;
  sample = vlin + ((c & 8) ? (c - 16) : c) * state->step;
  if (sample > 32767) sample = 32767; else if (sample < -32768) sample = -32768;
  step = (state->step * stepAdjustTable[c & 15]) >> 8;
  if (step < 16) step = 16;
  state->step = step;
  state->sample2 = state->sample1;
  state->sample1 = sample;
  *vp = sample;
}

void *lsx_ms_adpcm_alloc(unsigned chans) { return lsx_calloc(chans ? chans : 1, sizeof(MsState_t)); }

const char *lsx_ms_adpcm_block_expand_i(void *priv, unsigned chans, int nCoef, const short *coef, const unsigned char *ibuff, short *obuff, int n)
{
  const unsigned char *ip;
  unsigned ch;
  const char *errmsg = NULL;
  MsState_t *state = (MsState_t *)priv;
  int i;
  short *op;

  ip = ibuff;
  for (ch = 0; ch < chans; ch++) {
    int bpred = *ip++;
    if (bpred >= nCoef) {
      errmsg = "MSADPCM bpred >= nCoef, arbitrarily using 0\n";
      bpred = 0;
    }
    state[ch].iCoef[0] = coef[bpred * 2 + 0];
    state[ch].iCoef[1] = coef[bpred * 2 + 1];
  }
  for (ch = 0; ch < chans; ch++) { state[ch].step = (short)(ip[0] | (ip[1] << 8)); ip += 2; }
  for (ch = 0; ch < chans; ch++) { state[ch].sample1 = (short)(ip[0] | (ip[1] << 8)); ip += 2; }
  for (ch = 0; ch < chans; ch++) { state[ch].sample2 = (short)(ip[0] | (ip[1] << 8)); ip += 2; }
  /* first two samples come from the header */
  op = obuff;
  for (ch = 0; ch < chans; ch++) *op++ = (short)state[ch].sample2;
  for (ch = 0; ch < chans; ch++) *op++ = (short)state[ch].sample1;
  {
    int tot = n * chans, k;
    unsigned char b = 0;
    int have = 0, c;
    for (k = 2 * (int)chans; k < tot; k++) {
      if (!have) { b = *ip++; c = b >> 4; have = 1; } else { c = b & 15; have = 0; }
      ch = (unsigned)(k % chans);
      {
        int v;
        AdpcmDecode(c, &state[ch], NULL, &v);
        *op++ = (short)v;
      }
    }
  }
  return errmsg;
}

static int AdpcmMashS(unsigned ch, unsigned chans, const short *v, const short *iCoef, const short *ibuff, int n, int *iostep, unsigned char *obuff)
{
  const short *ip, *itop;
  unsigned char *op;
  int ox = 0;
  int i, d, v0, v1, step;
  double d2;

  ip = ibuff + ch;
  itop = ibuff + n * chans;
  v0 = v[0]; v1 = v[1];
  d = *ip - v1; ip += chans;
  d2 = d * d;
  d = *ip - v0; ip += chans;
  d2 += d * d;
  step = *iostep;
  op = obuff;
  if (op) {
    op += chans + 2 * ch + 2 * chans * 1;  /* skip to this channel's sample slots: predictors(chans), then idelta (2 each) */
    /* layout: bpred[chans], idelta[chans], sample1[chans], sample2[chans] */
    op = obuff + chans + 2 * ch;
    op[0] = (unsigned char)step; op[1] = (unsigned char)(step >> 8);
    op = obuff + chans + 2 * chans + 2 * ch;
    op[0] = (unsigned char)v0; op[1] = (unsigned char)(v0 >> 8);
    op = obuff + chans + 4 * chans + 2 * ch;
    op[0] = (unsigned char)v1; op[1] = (unsigned char)(v1 >> 8);
    op = obuff + 7 * chans;
    ox = 4 * ch;
  }
  for (i = 2; i < n; i++) {
    int vlin, d1, c;
    vlin = (v0 * iCoef[0] + v1 * iCoef[1]) >> 8;
    d1 = *ip - vlin;
    ip += chans;
    c = (d1 << 1) / step;
    if (c > 0) c = (c + 1) >> 1; else c = (c - 1) >> 1; /* round */
    c = d1 >= 0 ? (2 * d1 + step) / (2 * step) : -((2 * -d1 + step) / (2 * step));
    if (c < -8) c = -8; else if (c > 7) c = 7;
    {
      int sample = vlin + c * step;
      if (sample > 32767) sample = 32767; else if (sample < -32768) sample = -32768;
      d = *(ip - chans) - sample;
      d2 += (double)d * d;
      v1 = v0; v0 = sample;
    }
    if (op) {
      op[ox >> 3] |= (unsigned char)((ox & 4) ? (c & 15) : ((c & 15) << 4));
      ox += 4 * chans;
    }
    step = (step * stepAdjustTable[c & 15]) >> 8;
    if (step < 16) step = 16;
  }
  d2 /= n;
  *iostep = step;
  return (int)sqrt(d2);
}

