#define lsx_subsystem_name "au"
#include "sox.h"
#include "g711.h"

#define SUN_MAGIC 0x2e736e64
#define SUN_INV_MAGIC 0x646e732e
#define DEC_MAGIC 0x2e736400
#define DEC_INV_MAGIC 0x0064732e
#define SUN_UNSPEC ((unsigned)(~0))

typedef enum {
  Unspecified, Mulaw_8 = 1, Linear_8, Linear_16, Linear_24, Linear_32, Float, Double,
  Indirect, Nested, Dsp_core, Dsp_data_8, Dsp_data_16, Dsp_data_24, Dsp_data_32,
  Unknown1, Display, Mulaw_squelch, Emphasized, Compressed, Compressed_emphasized, Dsp_commands, Dsp_commands_samples,
  Adpcm_g721, Adpcm_g722, Adpcm_g723_3, Adpcm_g723_5, Alaw_8
} ft_encoding_t;

typedef struct { uint32_t data_size; } priv_t;

static ft_encoding_t sox_enc_to_ft_enc(unsigned size, sox_encoding_t encoding)
{
  if (encoding == SOX_ENCODING_ULAW && size == 8) return Mulaw_8;
  if (encoding == SOX_ENCODING_ALAW && size == 8) return Alaw_8;
  if (encoding == SOX_ENCODING_SIGN2) switch (size) {
    case 8: return Linear_8; case 16: return Linear_16; case 24: return Linear_24; case 32: return Linear_32; }
  if (encoding == SOX_ENCODING_FLOAT) switch (size) { case 32: return Float; case 64: return Double; }
  return Unspecified;
}

static sox_encoding_t ft_enc_to_sox_enc(ft_encoding_t ft_encoding, unsigned *size)
{
  switch (ft_encoding) {
    case Mulaw_8: *size = 8; return SOX_ENCODING_ULAW;
    case Alaw_8: *size = 8; return SOX_ENCODING_ALAW;
    case Linear_8: *size = 8; return SOX_ENCODING_SIGN2;
    case Linear_16: *size = 16; return SOX_ENCODING_SIGN2;
    case Linear_24: *size = 24; return SOX_ENCODING_SIGN2;
    case Linear_32: *size = 32; return SOX_ENCODING_SIGN2;
    case Float: *size = 32; return SOX_ENCODING_FLOAT;
    case Double: *size = 64; return SOX_ENCODING_FLOAT;
    case Adpcm_g721: *size = 4; return SOX_ENCODING_G721;
    case Adpcm_g723_3: *size = 3; return SOX_ENCODING_G723;
    case Adpcm_g723_5: *size = 5; return SOX_ENCODING_G723;
    default: return SOX_ENCODING_UNKNOWN;
  }
}

static int startread(sox_format_t *ft)
{
  priv_t *p = (priv_t *)ft->priv;
  uint32_t magic, hdr_size, data_size, ft_encoding, rate, channels;
  unsigned bits_per_sample;
  sox_encoding_t encoding;

  if (lsx_readdw(ft, &magic)) return SOX_EOF;
  if (magic == DEC_INV_MAGIC || magic == SUN_INV_MAGIC) {
    lsx_report("found inverted DEC/Sun magic word");
    ft->encoding.reverse_bytes = !ft->encoding.reverse_bytes;
  } else if (magic == SUN_MAGIC || magic == DEC_MAGIC) {
    lsx_report("found %s-endian `%s' identifier", magic == SUN_MAGIC ? "big" : "little", magic == SUN_MAGIC ? ".snd" : ".sd");
    if (magic == DEC_MAGIC) { /* little endian variant not really handled; keep */ }
  } else {
    lsx_fail_errno(ft, SOX_EHDR, "au: can't find Sun/NeXT/DEC identifier");
    return SOX_EOF;
  }
  if (lsx_readdw(ft, &hdr_size) || lsx_readdw(ft, &data_size) || lsx_readdw(ft, &ft_encoding) || lsx_readdw(ft, &rate) || lsx_readdw(ft, &channels))
    return SOX_EOF;
  if (hdr_size < 24) { lsx_fail_errno(ft, SOX_EHDR, "header size is too small"); return SOX_EOF; }
  if (hdr_size > 24) {
    char *buf = lsx_calloc(1, hdr_size - 24 + 1);
    if (lsx_readchars(ft, buf, hdr_size - 24)) { free(buf); return SOX_EOF; }
    if (*buf) lsx_append_comments(&ft->oob.comments, buf);
    free(buf);
  }
  if (!(encoding = ft_enc_to_sox_enc(ft_encoding, &bits_per_sample))) {
    int n = (int)ft_encoding;
    lsx_fail_errno(ft, SOX_EFMT, "unknown encoding %u (header)", n);
    return SOX_EOF;
  }
  if (encoding == SOX_ENCODING_G721 || encoding == SOX_ENCODING_G723) {
    lsx_fail_errno(ft, SOX_EFMT, "G.72x ADPCM encoding not supported in this build");
    return SOX_EOF;
  }
  p->data_size = data_size;
  return lsx_check_read_params(ft, channels, (double)rate, encoding, bits_per_sample,
      data_size == SUN_UNSPEC ? (uint64_t)0 : (uint64_t)(div_bits(data_size, bits_per_sample)), sox_true) == SOX_SUCCESS ? lsx_rawstartread(ft) : SOX_EOF;
}

static int write_header(sox_format_t *ft)
{
  char *comment = lsx_cat_comments(ft->oob.comments);
  size_t len = strlen(comment) + 1;
  size_t info_len = max(4, (len + 3) & ~3u);
  int i = (int)(info_len - len);
  sox_bool error = sox_false;
  uint64_t size64 = ft->olength ? ft->olength : ft->signal.length;
  uint32_t size = (ft->olength || (ft->signal.length && ft->signal.length != SOX_UNKNOWN_LEN)) ?
    (uint32_t)(size64 * (ft->encoding.bits_per_sample >> 3)) : SUN_UNSPEC;
  if (!ft->olength && (!ft->signal.length || ft->signal.length == SOX_UNKNOWN_LEN)) size = SUN_UNSPEC;
  error |= lsx_writedw(ft, SUN_MAGIC) != SOX_SUCCESS;
  error |= lsx_writedw(ft, (unsigned)(24 + info_len)) != SOX_SUCCESS;
  error |= lsx_writedw(ft, size) != SOX_SUCCESS;
  error |= lsx_writedw(ft, sox_enc_to_ft_enc(ft->encoding.bits_per_sample, ft->encoding.encoding)) != SOX_SUCCESS;
  error |= lsx_writedw(ft, (unsigned)(ft->signal.rate + .5)) != SOX_SUCCESS;
  error |= lsx_writedw(ft, ft->signal.channels) != SOX_SUCCESS;
  error |= lsx_writes(ft, comment) != SOX_SUCCESS;
  error |= lsx_writeb(ft, 0) != SOX_SUCCESS;
  while (i--) error |= lsx_writeb(ft, 0) != SOX_SUCCESS;
  free(comment);
  return error ? SOX_EOF : SOX_SUCCESS;
}

static int startwrite(sox_format_t *ft)
{
  return write_header(ft) == SOX_SUCCESS ? lsx_rawstartwrite(ft) : SOX_EOF;
}

static int stopwrite(sox_format_t *ft)
{
  if (!ft->seekable) return SOX_SUCCESS;
  if (lsx_seeki(ft, 0, SEEK_SET) != SOX_SUCCESS) return SOX_EOF;
  return write_header(ft);
}

static size_t read_samples(sox_format_t *ft, sox_sample_t *buf, size_t len) { return lsx_rawread(ft, buf, len); }
static size_t write_samples(sox_format_t *ft, const sox_sample_t *buf, size_t len) { return lsx_rawwrite(ft, buf, len); }

const sox_format_handler_t *lsx_au_format_fn(void)
{
  static const char *const names[] = {"au", "snd", NULL};
  static const unsigned write_encodings[] = {
    SOX_ENCODING_ULAW, 8, 0, SOX_ENCODING_ALAW, 8, 0,
    SOX_ENCODING_SIGN2, 8, 16, 24, 32, 0,
    SOX_ENCODING_FLOAT, 32, 64, 0, 0 };
  static const sox_format_handler_t handler = {
    "PCM file format used widely on Sun systems", names, SOX_FILE_BIG_END | SOX_FILE_REWIND,
    startread, read_samples, NULL, startwrite, write_samples, stopwrite, lsx_rawseek,
    write_encodings, NULL, sizeof(priv_t) };
  return &handler;
}
