      data_size == SUN_UNSPEC ? (uint64_t)0 : (uint64_t)(div_bits(data_size, bits_per_sample)), sox_true) == SOX_SUCCESS ? lsx_rawstartread(ft) : SOX_EOF;
}

static int write_header(sox_format_t *ft)
{
  char *comment = lsx_cat_comments(ft->oob.comments);
  size_t len = strlen(comment) + 1;
  size_t info_len = max(4, (len + 3) & ~3u);
  int i = (int)(info_len - len);
  sox_bool error = sox_false;
  uint64_t size64 = ft->olength ? ft->olength : ft->signal.length;
  uint32_t size = (ft->olength || (ft->signal.length && ft->signal.length != SOX_UNKNOWN_LEN)) ?
    (uint32_t)(size64 * (ft->encoding.bits_per_sample >> 3)) : SUN_UNSPEC;
  if (!ft->olength && (!ft->signal.length || ft->signal.length == SOX_UNKNOWN_LEN)) size = SUN_UNSPEC;
  error |= lsx_writedw(ft, SUN_MAGIC) != SOX_SUCCESS;
  error |= lsx_writedw(ft, (unsigned)(24 + info_len)) != SOX_SUCCESS;
  error |= lsx_writedw(ft, size) != SOX_SUCCESS;
  error |= lsx_writedw(ft, sox_enc_to_ft_enc(ft->encoding.bits_per_sample, ft->encoding.encoding)) != SOX_SUCCESS;
  error |= lsx_writedw(ft, (unsigned)(ft->signal.rate + .5)) != SOX_SUCCESS;
  error |= lsx_writedw(ft, ft->signal.channels) != SOX_SUCCESS;
  error |= lsx_writes(ft, comment) != SOX_SUCCESS;
  error |= lsx_writeb(ft, 0) != SOX_SUCCESS;
  while (i--) error |= lsx_writeb(ft, 0) != SOX_SUCCESS;
  free(comment);
  return error ? SOX_EOF : SOX_SUCCESS;
}

static int startwrite(sox_format_t *ft)
{
  return write_header(ft) == SOX_SUCCESS ? lsx_rawstartwrite(ft) : SOX_EOF;
}

static int stopwrite(sox_format_t *ft)
{
  if (!ft->seekable) return SOX_SUCCESS;
  if (lsx_seeki(ft, 0, SEEK_SET) != SOX_SUCCESS) return SOX_EOF;
  return write_header(ft);
}

static size_t read_samples(sox_format_t *ft, sox_sample_t *buf, size_t len) { return lsx_rawread(ft, buf, len); }
static size_t write_samples(sox_format_t *ft, const sox_sample_t *buf, size_t len) { return lsx_rawwrite(ft, buf, len); }

