}

static void write_ieee_extended(sox_format_t *ft, double x)
{
  char buf[10];
  ConvertToIeeeExtended(x, buf);
  lsx_writebuf(ft, buf, 10);
}

typedef struct { uint64_t nsamples; } priv_t;

static int textChunk(char **text, const char *chunkDescription, sox_format_t *ft)
{
  uint32_t chunksize;
  if (lsx_readdw(ft, &chunksize) == SOX_EOF) return SOX_EOF;
  *text = lsx_malloc((size_t)chunksize + 1);
  if (lsx_readbuf(ft, *text, (size_t)chunksize) != (int)chunksize) { lsx_fail_errno(ft, SOX_EOF, "Unexpected EOF in %s header", chunkDescription); return SOX_EOF; }
  (*text)[chunksize] = '\0';
  if (chunksize % 2) { char c; if (lsx_readbuf(ft, &c, 1) != 1) { lsx_fail_errno(ft, SOX_EOF, "Unexpected EOF in %s header", chunkDescription); return SOX_EOF; } }
  lsx_debug("%-10s   \"%s\"", chunkDescription, *text);
  return SOX_SUCCESS;
}

static int commentChunk(char **text, const char *chunkDescription, sox_format_t *ft)
{
  uint32_t chunksize;
  unsigned short numComments, commentLength;
  uint32_t timeStamp;
  unsigned short markerId;
  size_t totalCommentLength = 0, totalReadLength = 0;
  unsigned i;
  if (lsx_readdw(ft, &chunksize) == SOX_EOF) return SOX_EOF;
  if (lsx_readw(ft, &numComments) == SOX_EOF) return SOX_EOF;
  totalReadLength += 2;
  for (i = 0; i < numComments; i++) {
    size_t commentIndex;
    if (lsx_readdw(ft, &timeStamp) == SOX_EOF) return SOX_EOF;
    if (lsx_readw(ft, &markerId) == SOX_EOF) return SOX_EOF;
    if (lsx_readw(ft, &commentLength) == SOX_EOF) return SOX_EOF;
    totalReadLength += 8;
    if (commentLength > 0) {
      commentIndex = totalCommentLength;
      totalCommentLength += commentLength;
      *text = lsx_realloc(*text, totalCommentLength + 1);
      if (lsx_readbuf(ft, *text + commentIndex, (size_t)commentLength) != commentLength) {
        lsx_fail_errno(ft, SOX_EOF, "Unexpected EOF in %s header", chunkDescription); return SOX_EOF;
      }
      totalReadLength += commentLength;
      (*text)[totalCommentLength] = '\0';
      if (commentLength % 2) {
        char c;
        if (lsx_readbuf(ft, &c, 1) != 1) { lsx_fail_errno(ft, SOX_EOF, "Unexpected EOF in %s header", chunkDescription); return SOX_EOF; }
        totalReadLength++;
      }
    }
  }
  if (totalReadLength < chunksize) lsx_seeki(ft, (int64_t)(chunksize - totalReadLength), SEEK_CUR);
  if (*text) lsx_debug("%-10s   \"%s\"", chunkDescription, *text);
  return SOX_SUCCESS;
}

