    lsx_writes(ft, "COMT");
    lsx_writedw(ft, (unsigned)(comment_chunk_size - 8));
    lsx_writew(ft, 1);
    timestamp = sox_globals.repeatable ? 0 : (uint32_t)(time(NULL) + 2082844800u);
    lsx_writedw(ft, timestamp);
    lsx_writew(ft, 0);
