static int aiff_startwrite(sox_format_t *ft)
{
  priv_t *p = (priv_t *)ft->priv;
  int rc = lsx_rawstartwrite(ft);
  if (rc) return rc;
  p->nsamples = 0;
  ft->oob.instr.nloops = 0;
  return aiffwriteheader(ft, ft->signal.length != SOX_UNKNOWN_LEN ? ft->signal.length / ft->signal.channels : 0, sox_false);
}

static size_t aiff_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  priv_t *p = (priv_t *)ft->priv;
  p->nsamples += len;
  return lsx_rawwrite(ft, buf, len);
}

static int aiff_stopwrite(sox_format_t *ft)
{
  priv_t *p = (priv_t *)ft->priv;
  if (p->nsamples % ft->signal.channels != 0 || (p->nsamples / ft->signal.channels * (ft->encoding.bits_per_sample >> 3) * ft->signal.channels) & 1) {
    if ((p->nsamples * (ft->encoding.bits_per_sample >> 3)) & 1) lsx_writeb(ft, 0);
  }
  if (!ft->seekable) {
    if (p->nsamples != ft->signal.length) lsx_warn("AIFF header's sample count is wrong; can't seek to fix it");
    return SOX_SUCCESS;
  }
  if (lsx_seeki(ft, 0, SEEK_SET) != 0) { lsx_fail_errno(ft, SOX_EOF, "can't rewind output file to rewrite AIFF header"); return SOX_EOF; }
  return aiffwriteheader(ft, p->nsamples / ft->signal.channels, sox_false);
}

static int aifc_startwrite(sox_format_t *ft)
{
  priv_t *p = (priv_t *)ft->priv;
  int rc = lsx_rawstartwrite(ft);
  if (rc) return rc;
