}

const sox_format_handler_t *lsx_aiff_format_fn(void)
{
  static const char *const names[] = {"aiff", "aif", NULL};
  static const unsigned write_encodings[] = { SOX_ENCODING_SIGN2, 32, 24, 16, 8, 0, 0 };
