#define lsx_subsystem_name "aiff"
#include "sox.h"
#include <time.h>

/* 80-bit IEEE extended conversion */
#define FloatToUnsigned(f) ((uint32_t)(((int32_t)((f) - 2147483648.0)) + 2147483647L) + 1)
#define UnsignedToFloat(u) (((double)((int32_t)((u) - 2147483647L - 1))) + 2147483648.0)

static void ConvertToIeeeExtended(double num, char *bytes)
{
  int sign, expon;
  double fMant, fsMant;
  uint32_t hiMant, loMant;
  if (num < 0) { sign = 0x8000; num *= -1; } else sign = 0;
  if (num == 0) { expon = 0; hiMant = 0; loMant = 0; }
  else {
    fMant = frexp(num, &expon);
    if ((expon > 16384) || !(fMant < 1)) { expon = sign | 0x7FFF; hiMant = 0; loMant = 0; }
    else {
      expon += 16382;
      if (expon < 0) { fMant = ldexp(fMant, expon); expon = 0; }
      expon |= sign;
      fMant = ldexp(fMant, 32);
      fsMant = floor(fMant);
      hiMant = FloatToUnsigned(fsMant);
      fMant = ldexp(fMant - fsMant, 32);
      fsMant = floor(fMant);
      loMant = FloatToUnsigned(fsMant);
    }
  }
  bytes[0] = expon >> 8; bytes[1] = expon;
  bytes[2] = hiMant >> 24; bytes[3] = hiMant >> 16; bytes[4] = hiMant >> 8; bytes[5] = hiMant;
  bytes[6] = loMant >> 24; bytes[7] = loMant >> 16; bytes[8] = loMant >> 8; bytes[9] = loMant;
}

static double ConvertFromIeeeExtended(const unsigned char *bytes)
{
  double f;
  int expon;
  uint32_t hiMant, loMant;
  expon = ((bytes[0] & 0x7F) << 8) | (bytes[1] & 0xFF);
  hiMant = ((uint32_t)(bytes[2] & 0xFF) << 24) | ((uint32_t)(bytes[3] & 0xFF) << 16) | ((uint32_t)(bytes[4] & 0xFF) << 8) | ((uint32_t)(bytes[5] & 0xFF));
  loMant = ((uint32_t)(bytes[6] & 0xFF) << 24) | ((uint32_t)(bytes[7] & 0xFF) << 16) | ((uint32_t)(bytes[8] & 0xFF) << 8) | ((uint32_t)(bytes[9] & 0xFF));
  if (expon == 0 && hiMant == 0 && loMant == 0) f = 0;
  else {
    if (expon == 0x7FFF) f = HUGE_VAL;
    else {
      expon -= 16383;
      f = ldexp(UnsignedToFloat(hiMant), expon -= 31);
      f += ldexp(UnsignedToFloat(loMant), expon -= 32);
    }
  }
  if (bytes[0] & 0x80) return -f;
  return f;
}

static double read_ieee_extended(sox_format_t *ft)
{
  unsigned char buf[10];
  if (lsx_readbuf(ft, buf, 10) != 10) { lsx_fail_errno(ft, SOX_EOF, "EOF while reading IEEE extended number"); return 0; }
  return ConvertFromIeeeExtended(buf);
}

static void write_ieee_extended(sox_format_t *ft, double x)
{
  char buf[10];
  ConvertToIeeeExtended(x, buf);
  lsx_writebuf(ft, buf, 10);
}

typedef struct { uint64_t nsamples; } priv_t;

static int textChunk(char **text, const char *chunkDescription, sox_format_t *ft)
{
  uint32_t chunksize;
  if (lsx_readdw(ft, &chunksize) == SOX_EOF) return SOX_EOF;
  *text = lsx_malloc((size_t)chunksize + 1);
  if (lsx_readbuf(ft, *text, (size_t)chunksize) != (int)chunksize) { lsx_fail_errno(ft, SOX_EOF, "Unexpected EOF in %s header", chunkDescription); return SOX_EOF; }
  (*text)[chunksize] = '\0';
  if (chunksize % 2) { char c; if (lsx_readbuf(ft, &c, 1) != 1) { lsx_fail_errno(ft, SOX_EOF, "Unexpected EOF in %s header", chunkDescription); return SOX_EOF; } }
  lsx_debug("%-10s   \"%s\"", chunkDescription, *text);
  return SOX_SUCCESS;
}

static int commentChunk(char **text, const char *chunkDescription, sox_format_t *ft)
{
  uint32_t chunksize;
  unsigned short numComments, commentLength;
  uint32_t timeStamp;
  unsigned short markerId;
  size_t totalCommentLength = 0, totalReadLength = 0;
  unsigned i;
  if (lsx_readdw(ft, &chunksize) == SOX_EOF) return SOX_EOF;
  if (lsx_readw(ft, &numComments) == SOX_EOF) return SOX_EOF;
  totalReadLength += 2;
  for (i = 0; i < numComments; i++) {
    size_t commentIndex;
    if (lsx_readdw(ft, &timeStamp) == SOX_EOF) return SOX_EOF;
    if (lsx_readw(ft, &markerId) == SOX_EOF) return SOX_EOF;
    if (lsx_readw(ft, &commentLength) == SOX_EOF) return SOX_EOF;
    totalReadLength += 8;
    if (commentLength > 0) {
      commentIndex = totalCommentLength;
      totalCommentLength += commentLength;
      *text = lsx_realloc(*text, totalCommentLength + 1);
      if (lsx_readbuf(ft, *text + commentIndex, (size_t)commentLength) != commentLength) {
        lsx_fail_errno(ft, SOX_EOF, "Unexpected EOF in %s header", chunkDescription); return SOX_EOF;
      }
      totalReadLength += commentLength;
      (*text)[totalCommentLength] = '\0';
      if (commentLength % 2) {
        char c;
        if (lsx_readbuf(ft, &c, 1) != 1) { lsx_fail_errno(ft, SOX_EOF, "Unexpected EOF in %s header", chunkDescription); return SOX_EOF; }
        totalReadLength++;
      }
    }
  }
  if (totalReadLength < chunksize) lsx_seeki(ft, (int64_t)(chunksize - totalReadLength), SEEK_CUR);
  if (*text) lsx_debug("%-10s   \"%s\"", chunkDescription, *text);
  return SOX_SUCCESS;
}

static int aiff_startread(sox_format_t *ft)
{
  priv_t *p = (priv_t *)ft->priv;
  char buf[5];
  uint32_t totalsize, chunksize;
  unsigned short channels = 0, bits = 0;
  sox_encoding_t enc = SOX_ENCODING_SIGN2;
  uint32_t frames = 0;
  double rate = 0.0;
  uint32_t offset = 0, blocksize = 0;
  int foundcomm = 0, foundmark = 0, foundinstr = 0, is_sowt = 0;
  struct mark { unsigned short id; uint32_t position; char name[40]; } marks[32];
  unsigned short looptype;
  int i, j;
  unsigned short nmarks = 0, sustainLoopBegin = 0, sustainLoopEnd = 0, releaseLoopBegin = 0, releaseLoopEnd = 0;
  off_t seekto = 0;
  size_t ssndsize = 0;
  char *annotation, *author, *comment = NULL, *copyright, *nametext;
