      lsx_readb(ft, &trash8);
      lsx_readb(ft, &trash8); ft->oob.instr.MIDIlow = trash8;
      lsx_readb(ft, &trash8); ft->oob.instr.MIDIhi = trash8;
      lsx_readb(ft, &trash8); lsx_readb(ft, &trash8);
      lsx_readw(ft, &trash16);
