    } else if (strncmp(buf, "APPL", 4) == 0) {
      lsx_readdw(ft, &chunksize);
      while (chunksize-- > 0) lsx_readb(ft, &trash8);
    } else if (strncmp(buf, "ALCH", 4) == 0) {
      lsx_readdw(ft, &trash32); lsx_readdw(ft, &trash32); lsx_readdw(ft, &trash32);
    } else if (strncmp(buf, "ANNO", 4) == 0) {
      rc = textChunk(&annotation, "Annotation:", ft);
      if (rc) return rc;
      if (annotation) lsx_append_comments(&ft->oob.comments, annotation);
      free(annotation);
    } else if (strncmp(buf, "COMT", 4) == 0) {
      rc = commentChunk(&comment, "Comment:", ft);
      if (rc) return rc;
      if (comment) lsx_append_comments(&ft->oob.comments, comment);
      free(comment); comment = NULL;
    } else if (strncmp(buf, "AUTH", 4) == 0) {
