  return lsx_rawstartread(ft);
}

static size_t aiff_read(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  priv_t *p = (priv_t *)ft->priv;
  size_t done;
  if (p->nsamples) len = min(len, (size_t)p->nsamples);
  done = lsx_rawread(ft, buf, len);
  if (p->nsamples) p->nsamples -= done;
  return done;
}

static int aiff_seek(sox_format_t *ft, uint64_t offset)
{
  priv_t *p = (priv_t *)ft->priv;
  int rc = lsx_rawseek(ft, offset);
  if (rc == SOX_SUCCESS) p->nsamples = ft->signal.length > offset ? ft->signal.length - offset : 0;
  return rc;
}

static int aiffwriteheader(sox_format_t *ft, uint64_t nframes, sox_bool is_aifc)
{
  int hsize = 8 + 18 + 8 + 12;
  unsigned bits = ft->encoding.bits_per_sample;
  char *comment = lsx_cat_comments(ft->oob.comments);
  size_t comment_size = strlen(comment);
  size_t comment_chunk_size = 0;
  uint32_t timestamp;
  const char *ctype = "NONE", *cname = "not compressed";
  if (comment_size) {
    comment_chunk_size = 8 + 2 + 4 + 2 + 2 + comment_size + (comment_size & 1);
