static int getopts(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *vol = (priv_t *)effp->priv;
  char type_string[11];
  const char *type_ptr = type_string;
  const lsx_enum_item *p;
  char dummy;
  int have_type;
  --argc, ++argv;
  vol->gain = 1;
  vol->uselimiter = sox_false;
  if (argc < 1 || argc > 3) return lsx_usage(effp);
  if (sscanf(argv[0], "%lf %10s %c", &vol->gain, type_string, &dummy) == 2) have_type = 1;
  else if (sscanf(argv[0], "%lf %c", &vol->gain, &dummy) == 1) { have_type = 0; }
  else return lsx_usage(effp);
  if (!have_type && argc > 1) { type_ptr = argv[1]; have_type = 1; --argc; ++argv; }
  else if (have_type && argc > 1 && 0) {}
  if (have_type) {
    p = lsx_find_enum_text(type_ptr, vol_types, 0);
    if (!p) return lsx_usage(effp);
    switch (p->value) {
      case vol_dB: vol->gain = dB_to_linear(vol->gain); break;
      case vol_power:
        if (vol->gain < 0) { lsx_fail("can't use a negative power-gain"); return lsx_usage(effp); }
        vol->gain = sqrt(vol->gain);
        break;
    }
  }
  if (argc > 1) {
    if (sscanf(argv[1], "%lf %c", &vol->limitergain, &dummy) != 1 || vol->limitergain <= 0 || vol->limitergain >= 1) return lsx_usage(effp);
    vol->uselimiter = sox_true;
    vol->limiterthreshhold = SOX_SAMPLE_MAX * (1.0 - vol->limitergain) / (fabs(vol->gain) - vol->limitergain);
    --argc; ++argv;
  }
  if (argc > 1) return lsx_usage(effp);
  return SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *vol = (priv_t *)effp->priv;
  if (vol->gain == 1) return SOX_EFF_NULL;
  if (effp->in_signal.mult) *effp->in_signal.mult *= fabs(vol->gain);
  vol->limited = vol->totalprocessed = 0;
  lsx_debug("mult=%g limit=%g", vol->gain, vol->limiterthreshhold);
  return SOX_SUCCESS;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *vol = (priv_t *)effp->priv;
  double gain = vol->gain;
  double limiterthreshhold = vol->limiterthreshhold;
  double sample;
  size_t len = min(*osamp, *isamp);
  *isamp = *osamp = len;
  if (vol->uselimiter) {
    vol->totalprocessed += len;
    for (; len > 0; len--) {
      sample = *ibuf++;
      if (sample > limiterthreshhold) {
        sample = (SOX_SAMPLE_MAX - vol->limitergain * (SOX_SAMPLE_MAX - sample));
        vol->limited++;
      } else if (sample < -limiterthreshhold) {
        sample = -(SOX_SAMPLE_MAX - vol->limitergain * (SOX_SAMPLE_MAX + sample));
        vol->limited++;
      } else sample = gain * sample;
      SOX_SAMPLE_CLIP_COUNT(sample, effp->clips);
      *obuf++ = (sox_sample_t)sample;
    }
  } else {
    for (; len > 0; len--) {
      sample = gain * *ibuf++;
      SOX_SAMPLE_CLIP_COUNT(sample, effp->clips);
      *obuf++ = (sox_sample_t)sample;
    }
  }
  return SOX_SUCCESS;
}

static int stop(sox_effect_t *effp)
{
  priv_t *vol = (priv_t *)effp->priv;
  if (vol->limited) lsx_warn("limited %" PRIu64 " values (%d percent).", vol->limited, (int)(vol->limited * 100.0 / vol->totalprocessed));
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_vol_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "vol", "GAIN [TYPE [LIMITERGAIN]]\n\t(default TYPE=amplitude: 1 is constant, < 0 change phase;\n\tTYPE=power 1 is constant; TYPE=dB: 0 is constant, +6 doubles ampl.)\n\tThe peak limiter has a gain much less than 1 (e.g. 0.05 or 0.02) and\n\tis only used on peaks (to prevent clipping); default is no limiter.",
    SOX_EFF_MCHAN | SOX_EFF_GAIN, getopts, start, flow, NULL, stop, NULL, sizeof(priv_t) };
  return &handler;
}
