{"command":"cd /workspace/src; cat > trim.c <<'EOF'
#define lsx_subsystem_name "trim"
#include "sox.h"

typedef struct {
  unsigned num_pos;
  struct { uint64_t sample; char *argstr; } *pos;
  unsigned current_pos;
  uint64_t samples_read;
  sox_bool copying;
  uint64_t in_length;
} priv_t;

static int parse(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *p = (priv_t *)effp->priv;
  unsigned i;
  --argc, ++argv;
  p->num_pos = (unsigned)argc;
  lsx_Calloc(p->pos, p->num_pos ? p->num_pos : 1);
  for (i = 0; i < p->num_pos; i++) p->pos[i].argstr = lsx_strdup(argv[i]);
  return SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  uint64_t in_length = effp->in_signal.length != SOX_UNKNOWN_LEN ? effp->in_signal.length / effp->in_signal.channels : SOX_UNKNOWN_LEN;
  uint64_t last_seen = 0;
  unsigned i;
  sox_bool open_end;
  p->copying = sox_false;
  p->samples_read = 0;
  p->current_pos = 0;
  p->in_length = in_length;
  for (i = 0; i < p->num_pos; i++) {
    const char *end;
    uint64_t res;
    if (!p->pos[i].argstr) return SOX_EOF;
    end = lsx_parseposition(effp->in_signal.rate, p->pos[i].argstr, &res, last_seen, in_length, '+');
    if (!end) {
      if (p->pos[i].argstr[0] == '-' && in_length == SOX_UNKNOWN_LEN && p->pos[i].argstr[1] != '0') {
        lsx_fail("Position %u is relative to end of audio, but audio length is unknown", i + 1);
        return SOX_EOF;
      }
      if (p->pos[i].argstr[0] == '-' && in_length == SOX_UNKNOWN_LEN) {
        /* -0 with unknown length: treat as end-of-audio */
        lsx_fail("Position %u is relative to end of audio, but audio length is unknown", i + 1);
        return SOX_EOF;
      }
      lsx_fail("Error parsing position %u", i + 1);
      return lsx_usage(effp);
    }
    if (*end != '\0') { lsx_fail("Error parsing position %u", i + 1); return lsx_usage(effp); }
    if (res < last_seen) { lsx_fail("Position %u is behind the previous position", i + 1); return SOX_EOF; }
    p->pos[i].sample = res;
    last_seen = res;
  }
  if (in_length != SOX_UNKNOWN_LEN) {
    for (i = 0; i < p->num_pos; i++) if (p->pos[i].sample > in_length) {
      lsx_warn("%s position is after expected end of audio.", i % 2 ? "End" : "Start");
      break;
    }
  }
  open_end = p->num_pos % 2;
  /* output length */
  if (in_length != SOX_UNKNOWN_LEN) {
    uint64_t len = 0;
    for (i = 0; i + 1 < p->num_pos; i += 2) {
      uint64_t a = min(p->pos[i].sample, in_length), b = min(p->pos[i + 1].sample, in_length);
      len += b - a;
    }
    if (open_end) len += in_length - min(p->pos[p->num_pos - 1].sample, in_length);
    if (!p->num_pos) len = in_length;
