    if (!p->pos[i].argstr) return SOX_EOF;
    end = lsx_parseposition(effp->in_signal.rate, p->pos[i].argstr, &res, last_seen, in_length, '+');
    if (!end) {
      if (p->pos[i].argstr[0] == '-' && in_length == SOX_UNKNOWN_LEN && p->pos[i].argstr[1] != '0') {
        lsx_fail("Position %u is relative to end of audio, but audio length is unknown", i + 1);
        return SOX_EOF;
      }
      if (p->pos[i].argstr[0] == '-' && in_length == SOX_UNKNOWN_LEN) {
        /* -0 with unknown length: treat as end-of-audio */
