static double fade_gain(uint64_t index, uint64_t range, int type)
{
  double retval = 0.0, findex;
  findex = max(0.0, min(1.0, 1.0 * index / range));
  switch (type) {
    case FADE_TRI: retval = findex; break;
    case FADE_QUARTER: retval = sin(findex * M_PI / 2); break;
    case FADE_HALF: retval = (1 - cos(findex * M_PI)) / 2; break;
    case FADE_LOG: retval = pow(0.1, (1 - findex) * 2); break;
    case FADE_PAR: retval = (1 - (1 - findex) * (1 - findex)); break;
  }
  return retval;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *fade = (priv_t *)effp->priv;
  size_t len, t;
  int result = SOX_SUCCESS;
  len = min(*osamp, *isamp);
  for (t = 0; t < len; t++) {
