}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  if (!p->num_repeats) return SOX_EFF_NULL;
  if (!(p->tmp_file = tmpfile())) { lsx_fail("can't create temporary file: %s", strerror(errno)); return SOX_EOF; }
  p->num_samples = p->remaining_samples = 0;
  p->remaining_repeats = p->num_repeats;
  if (effp->in_signal.length != SOX_UNKNOWN_LEN && p->num_repeats != UINT_MAX)
    effp->out_signal.length = effp->in_signal.length * (p->num_repeats + 1);
  else effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  if (fwrite(ibuf, sizeof(*ibuf), *isamp, p->tmp_file) != *isamp) {
    lsx_fail("error writing temporary file: %s", strerror(errno));
    return SOX_EOF;
  }
  p->num_samples += *isamp;
  (void)obuf;
  *osamp = 0;
  return SOX_SUCCESS;
}

static int drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t odone = 0, n;
  *osamp -= *osamp % effp->in_signal.channels;
  do {
    if (!p->remaining_samples) {
      if (p->remaining_repeats == UINT_MAX) { }
      else if (!p->remaining_repeats + (p->num_samples ? 0 : 1)) break;
      p->remaining_samples = p->num_samples;
      if (p->remaining_repeats != UINT_MAX && p->num_samples) { }
      rewind(p->tmp_file);
    }
    n = min(p->remaining_samples, *osamp - odone);
    if (!n) break;
    if (fread(obuf + odone, sizeof(*obuf), n, p->tmp_file) != n) {
      lsx_fail("error reading temporary file: %s", strerror(errno));
      return SOX_EOF;
    }
    p->remaining_samples -= n;
    odone += n;
    if (!p->remaining_samples) {
      if (p->remaining_repeats != UINT_MAX) {
        if (!p->remaining_repeats) break;
        --p->remaining_repeats;
        if (!p->remaining_repeats) { p->num_samples = 0; }
