#define lsx_subsystem_name "swap"
#include "sox.h"

static int start(sox_effect_t *effp)
{
  return effp->in_signal.channels >= 2 ? SOX_SUCCESS : SOX_EFF_NULL;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  size_t i, len = min(*isamp, *osamp) / effp->in_signal.channels;
  unsigned channels = effp->in_signal.channels;
  *isamp = *osamp = len * channels;
  while (len--) {
    for (i = 0; i < channels; ++i) obuf[i] = ibuf[channels - 1 - i];
    if (channels > 2) {
      /* swap only the first two channels */
      for (i = 0; i < channels; ++i) obuf[i] = ibuf[i];
      obuf[0] = ibuf[1]; obuf[1] = ibuf[0];
    }
    ibuf += channels; obuf += channels;
  }
  return SOX_SUCCESS;
}

