  if (effp->in_signal.channels < p->min_in_channels) {
    lsx_fail("too few input channels");
    return SOX_EOF;
  }
  set_precision(effp);
  if (effp->in_signal.channels == effp->out_signal.channels) {
    unsigned j;
    sox_bool identity = sox_true;
    for (j = 0; j < p->num_out_channels; ++j)
      if (p->out_specs[j].num_in_channels != 1 || p->out_specs[j].in_specs[0].channel_num != j || p->out_specs[j].in_specs[0].multiplier != 1) identity = sox_false;
