}

/* channels */
static int channels_create(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *p = (priv_t *)effp->priv;
  char dummy;
  --argc, ++argv;
  if (argc != 1 || sscanf(*argv, "%u %c", &p->num_out_channels, &dummy) != 1 || !p->num_out_channels) return lsx_usage(effp);
  effp->out_signal.channels = p->num_out_channels;
  return SOX_SUCCESS;
}

static int channels_start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  unsigned i, j, in = effp->in_signal.channels, out = p->num_out_channels;
  if (in == out) return SOX_EFF_NULL;
  if (p->out_specs) { for (i = 0; i < out; ++i) free(p->out_specs[i].in_specs); free(p->out_specs); }
  p->out_specs = lsx_calloc(out, sizeof(*p->out_specs));
  if (in < out) {
    for (i = 0; i < out; ++i) {
      p->out_specs[i].in_specs = lsx_malloc(sizeof(*p->out_specs[i].in_specs));
      p->out_specs[i].in_specs[0].channel_num = i % in;
      p->out_specs[i].in_specs[0].multiplier = 1;
      p->out_specs[i].num_in_channels = 1;
    }
  } else {
    for (i = 0; i < out; ++i) {
      unsigned n = (in - i + out - 1) / out;
      p->out_specs[i].in_specs = lsx_malloc(n * sizeof(*p->out_specs[i].in_specs));
      for (j = 0; j < n; ++j) {
        p->out_specs[i].in_specs[j].channel_num = i + j * out;
        p->out_specs[i].in_specs[j].multiplier = 1. / n;
      }
      p->out_specs[i].num_in_channels = n;
    }
  }
  effp->out_signal.channels = out;
  set_precision(effp);
  return show(p);
}

static int channels_kill(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  unsigned i;
  if (p->out_specs) for (i = 0; i < p->num_out_channels; ++i) free(p->out_specs[i].in_specs);
  free(p->out_specs);
  return SOX_SUCCESS;
}

