      p->out_specs[i].in_specs[0].channel_num = i % in;
      p->out_specs[i].in_specs[0].multiplier = 1;
      p->out_specs[i].num_in_channels = 1;
    }
  } else {
    for (i = 0; i < out; ++i) {
      unsigned n = (in - i + out - 1) / out;
      p->out_specs[i].in_specs = lsx_malloc(n * sizeof(*p->out_specs[i].in_specs));
      for (j = 0; j < n; ++j) {
        p->out_specs[i].in_specs[j].channel_num = i + j * out;
        p->out_specs[i].in_specs[j].multiplier = 1. / n;
      }
      p->out_specs[i].num_in_channels = n;
    }
  }
  effp->out_signal.channels = out;
  set_precision(effp);
  return show(p);
}

