static int oops_create(sox_effect_t *effp, int argc, char **argv)
{
  char *args[] = {"oops", "1,2i", "1,2i"};
  if (argc > 1) { lsx_set_subsystem("oops"); lsx_fail_impl("this effect takes no parameters"); return SOX_EOF; }
  (void)argv;
  return create(effp, 3, args);
}

static int oops_start(sox_effect_t *effp)
{
  if (effp->in_signal.channels != 2) {
    lsx_set_subsystem("oops");
    lsx_fail_impl("can only be used with stereo input");
    return SOX_EOF;
  }
  return start(effp);
}

