      return SOX_EOF;
    }
    p->coefs = f->coefs;
    p->num_coefs = f->len;
  }
  p->depth = (double)(1 << (31 - p->prec));
  p->mask = (1u << (32 - p->prec)) - 1;
  p->pos = 0;
  memset(p->history, 0, sizeof p->history);
  p->r_prev = RANQD1;
  return SOX_SUCCESS;
}

static inline sox_sample_t quantize_round(double d, unsigned prec, uint64_t *clips)
{
  double step = (double)((uint64_t)1 << (32 - prec));
  double q = floor(d / step + .5) * step;
  if (q >= (double)SOX_SAMPLE_MAX + 1 - step) { ++*clips; q = (double)SOX_SAMPLE_MAX + 1 - step; }
  if (q < (double)SOX_SAMPLE_MIN) { ++*clips; q = SOX_SAMPLE_MIN; }
  return (sox_sample_t)q;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t len = *isamp = *osamp = min(*isamp, *osamp);
  while (len--) {
    double d, r;
    sox_sample_t s = *ibuf++;
    sox_bool do_dither = sox_true;
    if (p->auto_detect) {
      p->auto_hist = (p->auto_hist << 1) | !!(s & p->mask);
      do_dither = p->auto_hist != 0;
    }
    if (!do_dither) { *obuf++ = s; continue; }
    if (p->alt_tpdf) {
      int32_t r1 = RANQD1;
      r = ((double)r1 - (double)p->r_prev) * (1. / (65536. * 32768.));
      p->r_prev = r1;
    } else r = DRANQD1 + DRANQD1;
    d = s + r * p->depth;
    if (p->filter_name) {
      int j;
      double e = 0;
      for (j = 0; j < p->num_coefs; ++j) e += p->coefs[j] * p->history[(p->pos + j) % MAX_N];
      d -= e;
      {
        sox_sample_t q = quantize_round(d, p->prec, &effp->clips);
        p->pos = (p->pos + MAX_N - 1) % MAX_N;
        p->history[p->pos] = q - (d - r * p->depth) ;
        *obuf++ = q;
      }
    } else *obuf++ = SOX_ROUND_CLIP_COUNT(d, effp->clips);
  }
  return SOX_SUCCESS;
}

