  if (q >= (double)SOX_SAMPLE_MAX + 1 - step) { ++*clips; q = (double)SOX_SAMPLE_MAX + 1 - step; }
  if (q < (double)SOX_SAMPLE_MIN) { ++*clips; q = SOX_SAMPLE_MIN; }
  return (sox_sample_t)q;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t len = *isamp = *osamp = min(*isamp, *osamp);
  while (len--) {
    double d, r;
    sox_sample_t s = *ibuf++;
    sox_bool do_dither = sox_true;
    if (p->auto_detect) {
      p->auto_hist = (p->auto_hist << 1) | !!(s & p->mask);
      do_dither = p->auto_hist != 0;
    }
    if (!do_dither) { *obuf++ = s; continue; }
    if (p->alt_tpdf) {
      int32_t r1 = RANQD1;
      r = ((double)r1 - (double)p->r_prev) * (1. / (65536. * 32768.));
      p->r_prev = r1;
    } else r = DRANQD1 + DRANQD1;
    d = s + r * p->depth;
    if (p->filter_name) {
      int j;
      double e = 0;
      for (j = 0; j < p->num_coefs; ++j) e += p->coefs[j] * p->history[(p->pos + j) % MAX_N];
      d -= e;
      {
        sox_sample_t q = quantize_round(d, p->prec, &effp->clips);
        p->pos = (p->pos + MAX_N - 1) % MAX_N;
        p->history[p->pos] = q - (d - r * p->depth) ;
        *obuf++ = q;
      }
    } else *obuf++ = SOX_ROUND_CLIP_COUNT(d, effp->clips);
  }
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_dither_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "dither", "[-S|-s|-f filter] [-a] [-p precision]\n  (none)   Use TPDF\n  -S       Use sloped TPDF (without noise shaping)\n  -s       Shape noise (with shibata filter)\n  -f name  Set shaping filter to one of: lipshitz, f-weighted,\n           modified-e-weighted, improved-e-weighted, gesemann,\n           shibata, low-shibata, high-shibata.\n  -a       Automatically turn on & off dithering as needed (use with caution!)\n  -p bits  Override the target sample precision",
    SOX_EFF_PREC, getopts, start, flow, NULL, NULL, NULL, sizeof(priv_t) };
  return &handler;
}
