#define lsx_subsystem_name "synth"
#include "sox.h"
#include <ctype.h>

typedef enum {
  synth_sine, synth_square, synth_sawtooth, synth_triangle, synth_trapezium, synth_trapetz, synth_exp,
  synth_whitenoise, synth_noise, synth_tpdfnoise, synth_pinknoise, synth_brownnoise, synth_pluck
} type_t;

static const lsx_enum_item synth_type[] = {
  LSX_ENUM_ITEM(synth_, sine) LSX_ENUM_ITEM(synth_, square) LSX_ENUM_ITEM(synth_, sawtooth) LSX_ENUM_ITEM(synth_, triangle)
  LSX_ENUM_ITEM(synth_, trapezium) LSX_ENUM_ITEM(synth_, trapetz) LSX_ENUM_ITEM(synth_, exp)
  LSX_ENUM_ITEM(synth_, whitenoise) LSX_ENUM_ITEM(synth_, noise) LSX_ENUM_ITEM(synth_, tpdfnoise)
  LSX_ENUM_ITEM(synth_, pinknoise) LSX_ENUM_ITEM(synth_, brownnoise) LSX_ENUM_ITEM(synth_, pluck) {0, 0}};

typedef enum { synth_create, synth_mix, synth_amod, synth_fmod } combine_t;
static const lsx_enum_item combine_type[] = {
  LSX_ENUM_ITEM(synth_, create) LSX_ENUM_ITEM(synth_, mix) LSX_ENUM_ITEM(synth_, amod) LSX_ENUM_ITEM(synth_, fmod) {0, 0}};

typedef enum { Linear, Square, Exp, Exp_cycle, None } sweep_t;

#define PINK_MAX_RANDOM_ROWS 30
#define PINK_RANDOM_BITS 24
#define PINK_RANDOM_SHIFT ((sizeof(long) * 8) - PINK_RANDOM_BITS)
typedef struct {
  long pink_Rows[PINK_MAX_RANDOM_ROWS];
  long pink_RunningSum;
  int pink_Index, pink_IndexMask;
  float pink_Scalar;
} pink_noise_t;

static void initialize_pink_noise(pink_noise_t *pink, int numRows)
{
  int i; long pmax;
  pink->pink_Index = 0;
  pink->pink_IndexMask = (1 << numRows) - 1;
  pmax = (numRows + 1) * (1 << (PINK_RANDOM_BITS - 1));
  pink->pink_Scalar = 1.0f / pmax;
  for (i = 0; i < numRows; i++) pink->pink_Rows[i] = 0;
  pink->pink_RunningSum = 0;
}

static double generate_pink_noise_sample(pink_noise_t *pink)
{
  long newRandom, sum;
  double output;
  pink->pink_Index = (pink->pink_Index + 1) & pink->pink_IndexMask;
  if (pink->pink_Index != 0) {
    int numZeros = 0, n = pink->pink_Index;
    while ((n & 1) == 0) { n = n >> 1; numZeros++; }
    pink->pink_RunningSum -= pink->pink_Rows[numZeros];
    newRandom = ((long)RANQD1) >> 8;
    pink->pink_RunningSum += newRandom;
    pink->pink_Rows[numZeros] = newRandom;
  }
  newRandom = ((long)RANQD1) >> 8;
  sum = pink->pink_RunningSum + newRandom;
  output = pink->pink_Scalar * sum;
  return output;
}

typedef struct {
  type_t type;
  combine_t combine;
  double freq, freq2, mult;
  sweep_t sweep;
  double offset, phase;
  double p1, p2, p3;
  double lp_last_out, hp_last_out, hp_last_in, ap_last_out, ap_last_in;
  double cycle_start_time_s;
  pink_noise_t pink_noise;
  double *buffer;
  size_t buffer_len, pos;
} channel_t;

typedef struct {
  char *length_str;
  channel_t *getopts_channels;
  size_t getopts_nchannels;
  uint64_t samples_done, samples_to_do;
  channel_t *channels;
  size_t number_of_channels;
  sox_bool no_headroom;
  double gain;
  int key;
} priv_t;

static void create_channel(channel_t *chan)
{
  memset(chan, 0, sizeof(*chan));
  chan->freq = chan->freq2 = 440;
  chan->p1 = chan->p2 = chan->p3 = -1;
}

static void set_default_parameters(channel_t *chan, size_t c)
{
  (void)c;
  switch (chan->type) {
    case synth_square: if (chan->p1 < 0) chan->p1 = 0.5; break;
    case synth_triangle: if (chan->p1 < 0) chan->p1 = 0.5; break;
    case synth_trapezium: case synth_trapetz:
      if (chan->p1 < 0) chan->p1 = 0.1; if (chan->p2 < 0) chan->p2 = 0.5; if (chan->p3 < 0) chan->p3 = 0.6; break;
    case synth_exp: if (chan->p1 < 0) chan->p1 = 0.5; if (chan->p2 < 0) chan->p2 = 50; break;
    case synth_pluck:
      if (chan->p1 < 0) chan->p1 = 0.4; if (chan->p2 < 0) chan->p2 = 0.2; if (chan->p3 < 0) chan->p3 = 0.9; break;
    default: break;
  }
}

static double parse_freq(const char *text, char **end, int key)
{
  return lsx_parse_frequency_k(text, end, key);
}

static int getopts(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *synth = (priv_t *)effp->priv;
  int c, argn = 0;
  char *end_ptr;
  lsx_getopt_t optstate;
  synth->key = INT_MAX;
  lsx_getopt_init(argc, argv, "+j:n", NULL, lsx_getopt_flag_none, 1, &optstate);
  while ((c = lsx_getopt_s(&optstate)) != -1) switch (c) {
    case 'j': {
      double f = parse_freq(optstate.arg, &end_ptr, INT_MAX);
      if (*end_ptr) {
        /* integer semitones */
        char dummy; int k;
        if (sscanf(optstate.arg, "%d %c", &k, &dummy) != 1) return lsx_usage(effp);
        synth->key = k;
      } else {
        if (optstate.arg[0] == '%' || isalpha((unsigned char)optstate.arg[0])) synth->key = (int)floor(12 * log(f / 440) / log(2) + .5);
        else synth->key = (int)f;
      }
      break; }
    case 'n': synth->no_headroom = sox_true; break;
    default: lsx_fail("invalid option `-%c'", optstate.curpos ? optstate.curpos[-1] : '?'); return lsx_usage(effp);
  }
  argc -= optstate.ind, argv += optstate.ind;

  /* Get duration if given (if first arg doesn't start with a letter) */
  if (argc && !isalpha((unsigned char)argv[argn][0])) {
    if (lsx_parsesamples(0., argv[argn], &synth->samples_to_do, 't') == NULL) return lsx_usage(effp);
    synth->length_str = lsx_strdup(argv[argn]);
    argn++;
  }
  while (argn < argc) {
    channel_t *chan;
    const lsx_enum_item *p = lsx_find_enum_text(argv[argn], synth_type, 0);
    if (p == NULL) {
      lsx_fail("no type given");
      return lsx_usage(effp);
    }
    synth->getopts_channels = lsx_realloc(synth->getopts_channels, sizeof(*synth->getopts_channels) * (synth->getopts_nchannels + 1));
    chan = &synth->getopts_channels[synth->getopts_nchannels++];
    create_channel(chan);
    chan->type = p->value;
    if (++argn == argc) break;
    /* maybe there is a combine-type in next arg */
    p = lsx_find_enum_text(argv[argn], combine_type, 0);
    if (p != NULL) {
      chan->combine = p->value;
      if (++argn == argc) break;
    }
    /* read frequencies if given */
    if (!lsx_find_enum_text(argv[argn], synth_type, 0) && argv[argn][0] != '-' + 0 * 1) {
      static const char sweeps[] = ":+/-";
      char *end = NULL;
      if (chan->type >= synth_whitenoise && chan->type != synth_pluck) {
        /* noise: no frequency, but check anyway (skip if parse fails) */
      }
      chan->freq2 = chan->freq = parse_freq(argv[argn], &end, synth->key);
      if (end == argv[argn] || !end) { lsx_fail("invalid freq"); return lsx_usage(effp); }
      if (*end && strchr(sweeps, *end)) {
        chan->sweep = (sweep_t)(strchr(sweeps, *end) - sweeps);
        chan->freq2 = parse_freq(end + 1, &end, synth->key);
        if (!end || *end) { lsx_fail("invalid freq2"); return lsx_usage(effp); }
        if (synth->length_str == NULL) { lsx_fail("length must be given when using freq2"); return lsx_usage(effp); }
      } else if (*end) { lsx_fail("invalid freq"); return lsx_usage(effp); }
      else chan->sweep = None;
      if (++argn == argc) break;
    } else chan->sweep = None;
    /* read rest of parameters */
#define NUMERIC_PARAMETER(p, min, max) { \
      char *end_ptr2; double d; \
      if (argn == argc) break; \
      d = strtod(argv[argn], &end_ptr2); \
      if (end_ptr2 == argv[argn]) break; \
      if (d < min || d > max || *end_ptr2 != '\0') { lsx_fail("parameter error"); return lsx_usage(effp); } \
      chan->p = d / 100; \
      argn++; }
    do {
      NUMERIC_PARAMETER(offset, -100, 100)
      NUMERIC_PARAMETER(phase, 0, 100)
      NUMERIC_PARAMETER(p1, 0, 100)
      NUMERIC_PARAMETER(p2, 0, 100)
      NUMERIC_PARAMETER(p3, 0, 100)
    } while (0);
  }
  /* If no channel parameters were given, create one default channel */
  if (!synth->getopts_nchannels) {
    synth->getopts_channels = lsx_malloc(sizeof(*synth->getopts_channels));
    create_channel(&synth->getopts_channels[synth->getopts_nchannels++]);
  }
  return SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *synth = (priv_t *)effp->priv;
  size_t i;

  synth->samples_done = 0;
  if (synth->length_str) {
    if (lsx_parsesamples(effp->in_signal.rate, synth->length_str, &synth->samples_to_do, 't') == NULL) return lsx_usage(effp);
  }
  synth->number_of_channels = effp->in_signal.channels;
  synth->channels = lsx_calloc(synth->number_of_channels, sizeof(*synth->channels));
  for (i = 0; i < synth->number_of_channels; ++i) {
    channel_t *chan = &synth->channels[i];
    *chan = synth->getopts_channels[i < synth->getopts_nchannels ? i : synth->getopts_nchannels - 1];
    set_default_parameters(chan, i);
    if (chan->type == synth_pinknoise) initialize_pink_noise(&chan->pink_noise, 12);
    else if (chan->type == synth_pluck) {
      double d, colour = pow(2., 4 * (chan->p2 - 1)), alpha = (1 - colour) * .3;
      size_t len = (size_t)(effp->in_signal.rate / chan->freq + .5), j;
      chan->buffer_len = len;
      chan->buffer = lsx_calloc(len ? len : 1, sizeof(*chan->buffer));
      chan->pos = 0;
      for (j = 0, d = 0; j < len; ++j) {
        d = DRANQD1 * alpha + d * (1 - alpha);
        chan->buffer[j] = d;
      }
      chan->lp_last_out = pow(.5, 2. / (chan->p1 * 20 + 1));
      (void)colour;
    }
    switch (chan->sweep) {
      case Linear: chan->mult = synth->samples_to_do ? (chan->freq2 - chan->freq) / synth->samples_to_do / 2 : 0; break;
      case Square: chan->mult = synth->samples_to_do ? (chan->freq2 - chan->freq) / synth->samples_to_do / synth->samples_to_do / 3 : 0; break;
      case Exp: chan->mult = synth->samples_to_do ? log(chan->freq2 / chan->freq) / synth->samples_to_do : 0; break;
      case Exp_cycle: chan->mult = synth->samples_to_do ? log(chan->freq2 / chan->freq) / synth->samples_to_do : 0; break;
      default: chan->mult = 0;
    }
    lsx_debug("type=%s, combine=%s, samples_to_do=%" PRIu64 ", f1=%g, f2=%g, offset=%g, phase=%g, p1=%g, p2=%g, p3=%g mult=%g",
        lsx_find_enum_value(chan->type, synth_type)->text, lsx_find_enum_value(chan->combine, combine_type)->text,
        synth->samples_to_do, chan->freq, chan->freq2, chan->offset, chan->phase, chan->p1, chan->p2, chan->p3, chan->mult);
    chan->freq /= effp->in_signal.rate;
    chan->freq2 /= effp->in_signal.rate;
    chan->cycle_start_time_s = 0;
  }
  synth->gain = 1;
  if (!synth->no_headroom) effp->out_signal.mult = &synth->gain;
  effp->out_signal.length = synth->samples_to_do ? synth->samples_to_do * effp->in_signal.channels : effp->in_signal.length;
  return SOX_SUCCESS;
}

static double do_synth(double synth_input, priv_t *synth, int c)
{
  channel_t *chan = &synth->channels[c];
  double synth_out;
  if (chan->type < synth_whitenoise) {
    double phase;
    double n = (double)synth->samples_done;
    switch (chan->sweep) {
      case Linear: phase = (chan->freq + n * chan->mult) * n; break;
      case Square: phase = (chan->freq + n * n * chan->mult) * n; break;
      case Exp: phase = chan->mult ? chan->freq * (exp(chan->mult * n) - 1) / chan->mult : chan->freq * n; break;
      case Exp_cycle: {
        double cycle_freq;
        double t = n - chan->cycle_start_time_s;
        cycle_freq = chan->freq * exp(chan->mult * chan->cycle_start_time_s);
        phase = cycle_freq * t;
        if (phase >= 1) { chan->cycle_start_time_s = n; phase = 0; }
        break; }
      default: phase = chan->freq * n;
    }
    phase = fmod(phase + chan->phase, 1.0);
    switch (chan->type) {
      case synth_sine: synth_out = sin(2 * M_PI * phase); break;
      case synth_square: synth_out = -1 + 2 * (phase < chan->p1); break;
      case synth_sawtooth: synth_out = -1 + 2 * phase; break;
      case synth_triangle:
        if (phase < chan->p1) synth_out = -1 + 2 * phase / chan->p1;
        else synth_out = 1 - 2 * (phase - chan->p1) / (1 - chan->p1);
        break;
      case synth_trapezium: case synth_trapetz:
        if (phase < chan->p1) synth_out = -1 + 2 * phase / chan->p1;
        else if (phase < chan->p2) synth_out = 1;
        else if (phase < chan->p3) synth_out = 1 - 2 * (phase - chan->p2) / (chan->p3 - chan->p2);
        else synth_out = -1;
        break;
      case synth_exp: {
        double amp = chan->p2 * 200; /* dB range */
        double t = phase < chan->p1 ? phase / chan->p1 : 1 - (phase - chan->p1) / (1 - chan->p1);
        synth_out = dB_to_linear(-amp * (1 - t)) * 2 - 1;
        break; }
      default: synth_out = 0;
    }
  } else switch (chan->type) {
    case synth_whitenoise: case synth_noise: synth_out = DRANQD1; break;
    case synth_tpdfnoise: synth_out = .5 * (DRANQD1 + DRANQD1); break;
    case synth_pinknoise: synth_out = generate_pink_noise_sample(&chan->pink_noise); break;
    case synth_brownnoise:
      do synth_out = chan->lp_last_out + DRANQD1 * (1. / 16); while (fabs(synth_out) > 1);
      chan->lp_last_out = synth_out;
      break;
    case synth_pluck: {
      double d = chan->buffer[chan->pos];
      size_t next = (chan->pos + 1) % chan->buffer_len;
      synth_out = d;
      chan->buffer[chan->pos] = (d + chan->buffer[next]) * .5 * chan->lp_last_out;
      chan->pos = next;
      break; }
    default: synth_out = 0;
  }
  synth_out = synth_out * (1 - fabs(chan->offset)) + chan->offset;
  switch (chan->combine) {
    case synth_create: return synth_out;
    case synth_mix: return (synth_out + synth_input) * 0.5;
    case synth_amod: return (synth_out + 1) * synth_input * 0.5;
    case synth_fmod: return synth_out * synth_input;
  }
  return 0;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *synth = (priv_t *)effp->priv;
  unsigned len = (unsigned)(min(*isamp, *osamp) / effp->in_signal.channels);
  unsigned c, done;
  int result = SOX_SUCCESS;
  SOX_SAMPLE_LOCALS;
  for (done = 0; done < len && result == SOX_SUCCESS; ++done) {
    for (c = 0; c < effp->in_signal.channels; c++) {
      double synth_input = SOX_SAMPLE_TO_FLOAT_64BIT(*ibuf++, effp->clips);
      double synth_out = do_synth(synth_input, synth, (int)c);
      *obuf++ = SOX_FLOAT_64BIT_TO_SAMPLE(synth_out * synth->gain, effp->clips);
    }
    if (++synth->samples_done == synth->samples_to_do) result = SOX_EOF;
  }
  *isamp = *osamp = done * effp->in_signal.channels;
  return result;
}

static int stop(sox_effect_t *effp)
{
  priv_t *synth = (priv_t *)effp->priv;
  size_t i;
  if (synth->channels) for (i = 0; i < synth->number_of_channels; ++i) free(synth->channels[i].buffer);
  free(synth->channels);
  synth->channels = NULL;
  return SOX_SUCCESS;
}

static int lsx_kill(sox_effect_t *effp)
{
  priv_t *synth = (priv_t *)effp->priv;
  free(synth->getopts_channels);
  free(synth->length_str);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_synth_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "synth", "[-j KEY] [-n] [length [offset [phase [p1 [p2 [p3]]]]]]] {type [combine] [[%]freq[k][:|+|/|-[%]freq2[k]] [offset [phase [p1 [p2 [p3]]]]]]}",
    SOX_EFF_MCHAN | SOX_EFF_LENGTH | SOX_EFF_GAIN, getopts, start, flow, NULL, stop, lsx_kill, sizeof(priv_t) };
  return &handler;
}
