#define lsx_subsystem_name "synth"
#include "sox.h"
#include <ctype.h>

typedef enum {
  synth_sine, synth_square, synth_sawtooth, synth_triangle, synth_trapezium, synth_trapetz, synth_exp,
  synth_whitenoise, synth_noise, synth_tpdfnoise, synth_pinknoise, synth_brownnoise, synth_pluck
} type_t;

static const lsx_enum_item synth_type[] = {
  LSX_ENUM_ITEM(synth_, sine) LSX_ENUM_ITEM(synth_, square) LSX_ENUM_ITEM(synth_, sawtooth) LSX_ENUM_ITEM(synth_, triangle)
  LSX_ENUM_ITEM(synth_, trapezium) LSX_ENUM_ITEM(synth_, trapetz) LSX_ENUM_ITEM(synth_, exp)
  LSX_ENUM_ITEM(synth_, whitenoise) LSX_ENUM_ITEM(synth_, noise) LSX_ENUM_ITEM(synth_, tpdfnoise)
  LSX_ENUM_ITEM(synth_, pinknoise) LSX_ENUM_ITEM(synth_, brownnoise) LSX_ENUM_ITEM(synth_, pluck) {0, 0}};

typedef enum { synth_create, synth_mix, synth_amod, synth_fmod } combine_t;
static const lsx_enum_item combine_type[] = {
  LSX_ENUM_ITEM(synth_, create) LSX_ENUM_ITEM(synth_, mix) LSX_ENUM_ITEM(synth_, amod) LSX_ENUM_ITEM(synth_, fmod) {0, 0}};

typedef enum { Linear, Square, Exp, Exp_cycle, None } sweep_t;

#define PINK_MAX_RANDOM_ROWS 30
#define PINK_RANDOM_BITS 24
#define PINK_RANDOM_SHIFT ((sizeof(long) * 8) - PINK_RANDOM_BITS)
typedef struct {
  long pink_Rows[PINK_MAX_RANDOM_ROWS];
  long pink_RunningSum;
  int pink_Index, pink_IndexMask;
  float pink_Scalar;
} pink_noise_t;

static void initialize_pink_noise(pink_noise_t *pink, int numRows)
{
  int i; long pmax;
  pink->pink_Index = 0;
  pink->pink_IndexMask = (1 << numRows) - 1;
  pmax = (numRows + 1) * (1 << (PINK_RANDOM_BITS - 1));
  pink->pink_Scalar = 1.0f / pmax;
  for (i = 0; i < numRows; i++) pink->pink_Rows[i] = 0;
  pink->pink_RunningSum = 0;
}

static double generate_pink_noise_sample(pink_noise_t *pink)
{
  long newRandom, sum;
  double output;
  pink->pink_Index = (pink->pink_Index + 1) & pink->pink_IndexMask;
  if (pink->pink_Index != 0) {
    int numZeros = 0, n = pink->pink_Index;
    while ((n & 1) == 0) { n = n >> 1; numZeros++; }
    pink->pink_RunningSum -= pink->pink_Rows[numZeros];
    newRandom = ((long)RANQD1) >> 8;
    pink->pink_RunningSum += newRandom;
    pink->pink_Rows[numZeros] = newRandom;
  }
  newRandom = ((long)RANQD1) >> 8;
  sum = pink->pink_RunningSum + newRandom;
  output = pink->pink_Scalar * sum;
  return output;
}

typedef struct {
  type_t type;
  combine_t combine;
  double freq, freq2, mult;
  sweep_t sweep;
