  stat->read = 0;
  for (i = 0; i < 4; i++) stat->bin[i] = 0;
  stat->fft_size = 4096;
  stat->re = stat->im = NULL;
  if (stat->fft) {
    stat->fft_offset = 0;
    stat->re = lsx_malloc(sizeof(float) * stat->fft_size);
    stat->im = lsx_malloc(sizeof(float) * stat->fft_size);
  }
  return SOX_SUCCESS;
}

static void print_power_spectrum(unsigned samples, double rate, float *re, float *im)
{
  float ffa = (float)(rate / samples);
  unsigned i;
  double *buf = lsx_malloc(samples * sizeof(double));
  for (i = 0; i < samples; i++) buf[i] = re[i];
  lsx_safe_rdft((int)samples, 1, buf);
  re[0] = (float)(buf[0] * buf[0]);
  for (i = 1; i < samples / 2; i++) re[i] = (float)(buf[2 * i] * buf[2 * i] + buf[2 * i + 1] * buf[2 * i + 1]);
  (void)im;
  for (i = 0; i < samples / 2; i++) fprintf(stderr, "%f  %f\n", ffa * i, re[i]);
  free(buf);
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *stat = (priv_t *)effp->priv;
  int done, x, len = (int)min(*isamp, *osamp);
  short count = 0;
  if (len) {
    if (stat->read == 0) {
      stat->min = stat->max = ibuf[0];
      stat->last = ibuf[0];
    }
    for (done = 0; done < len; done++) {
      double samp, delta;
      x = ibuf[done];
      if (stat->fft) {
        stat->re[stat->fft_offset] = (float)(x / stat->scale);
        stat->im[stat->fft_offset++] = 0;
        if (stat->fft_offset >= stat->fft_size) {
          stat->fft_offset = 0;
          print_power_spectrum((unsigned)stat->fft_size, effp->in_signal.rate, stat->re, stat->im);
        }
      }
      samp = x;
      stat->bin[(x >> 30) + 2]++;
      if (samp < stat->min) stat->min = samp;
      if (samp > stat->max) stat->max = samp;
      stat->asum += fabs(samp);
      stat->sum1 += samp;
      stat->sum2 += samp * samp;
      delta = fabs(samp - stat->last);
      if (delta < stat->dmin) stat->dmin = delta;
      if (delta > stat->dmax) stat->dmax = delta;
      stat->dsum1 += delta;
      stat->dsum2 += delta * delta;
      stat->last = samp;
      if (stat->volume == 2) {
        fprintf(stderr, " %08x", (unsigned)x);
        if (count++ == 5) { fprintf(stderr, "\n"); count = 0; }
      }
      obuf[done] = ibuf[done];
    }
    stat->read += len;
  }
  *isamp = *osamp = len;
  return SOX_SUCCESS;
}

static int drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  priv_t *stat = (priv_t *)effp->priv;
  (void)obuf;
  if (stat->fft && stat->fft_offset) {
    size_t i;
    for (i = stat->fft_offset; i < stat->fft_size; i++) stat->re[i] = 0;
    print_power_spectrum((unsigned)stat->fft_size, effp->in_signal.rate, stat->re, stat->im);
    stat->fft_offset = 0;
  }
  *osamp = 0;
  return SOX_EOF;
}

static int stop(sox_effect_t *effp)
{
  priv_t *stat = (priv_t *)effp->priv;
  double amp, scale, rms = 0, freq;
  double x, ct;
  ct = (double)stat->read;
  if (stat->srms) {
    rms = sqrt(stat->sum2 / ct);
    scale = stat->scale * rms;
  } else scale = stat->scale;
  amp = -stat->min;
  if (amp < stat->max) amp = stat->max;
  if (stat->volume == 1) {
    fprintf(stderr, "%.3f\n", SOX_SAMPLE_MAX / amp);
    return SOX_SUCCESS;
  }
  if (stat->volume == 2) fprintf(stderr, "\n\n");
  fprintf(stderr, "Samples read:      %12" PRIu64 "\n", stat->read);
  fprintf(stderr, "Length (seconds):  %12.6f\n", (double)stat->read / effp->in_signal.rate / effp->in_signal.channels);
  if (stat->srms) fprintf(stderr, "Scaled by rms:     %12.6f\n", rms);
  else fprintf(stderr, "Scaled by:         %12.1f\n", scale);
  fprintf(stderr, "Maximum amplitude: %12.6f\n", stat->max / scale);
  fprintf(stderr, "Minimum amplitude: %12.6f\n", stat->min / scale);
  fprintf(stderr, "Midline amplitude: %12.6f\n", (stat->max + stat->min) / 2.0 / scale);
  fprintf(stderr, "Mean    norm:      %12.6f\n", stat->asum / ct / scale);
  fprintf(stderr, "Mean    amplitude: %12.6f\n", stat->sum1 / ct / scale);
  fprintf(stderr, "RMS     amplitude: %12.6f\n", sqrt(stat->sum2 / ct) / scale);
  fprintf(stderr, "Maximum delta:     %12.6f\n", stat->dmax / scale);
  fprintf(stderr, "Minimum delta:     %12.6f\n", stat->dmin / scale);
  fprintf(stderr, "Mean    delta:     %12.6f\n", stat->dsum1 / (ct - 1) / scale);
  fprintf(stderr, "RMS     delta:     %12.6f\n", sqrt(stat->dsum2 / (ct - 1)) / scale);
  freq = sqrt(stat->dsum2 / stat->sum2) * effp->in_signal.rate / (M_PI * 2);
  fprintf(stderr, "Rough   frequency: %12d\n", (int)freq);
  if (amp > 0) fprintf(stderr, "Volume adjustment: %12.3f\n", SOX_SAMPLE_MAX / amp);
  if (stat->bin[2] == 0 && stat->bin[3] == 0) fprintf(stderr, "\nProbably text, not sound\n");
  else {
    x = (float)(stat->bin[0] + stat->bin[3]) / (float)(stat->bin[1] + stat->bin[2]);
    if (x >= 3.0) fprintf(stderr, "\nTry: -t raw -e unsigned-integer -b 8 \n");
    else if (x <= 1.0 / 3.0) ;
    else fprintf(stderr, "\nCan't guess the type\n");
  }
  free(stat->re); free(stat->im);
  stat->re = stat->im = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_stat_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "stat", "[ -s N ] [ -rms ] [-freq] [ -v ] [ -d ]", SOX_EFF_MCHAN | SOX_EFF_MODIFY,
    getopts, start, flow, drain, stop, NULL, sizeof(priv_t) };
  return &handler;
}
