cat > stats.c <<'EOF'
#define lsx_subsystem_name "stats"
#include "sox.h"

typedef struct {
  int scale_bits, hex_bits;
  double time_constant, scale;
  double last, sigma_x, sigma_x2, avg_sigma_x2, min_sigma_x2, max_sigma_x2;
  double min, max, mult, min_run, min_runs, max_run, max_runs;
  uint64_t num_samples, tc_samples, min_count, max_count;
  uint32_t mask;
} priv_t;

static int getopts(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *p = (priv_t *)effp->priv;
  int c;
  lsx_getopt_t optstate;
  char dummy;
  lsx_getopt_init(argc, argv, "+x:b:w:s:", NULL, lsx_getopt_flag_none, 1, &optstate);
  p->time_constant = .05;
  p->scale = 1;
  while ((c = lsx_getopt_s(&optstate)) != -1) switch (c) {
    case 'x': if (sscanf(optstate.arg, "%d %c", &p->hex_bits, &dummy) != 1 || p->hex_bits < 2 || p->hex_bits > 32) { lsx_fail("parameter `-x' must be between 2 and 32"); return lsx_usage(effp); } break;
    case 'b': if (sscanf(optstate.arg, "%d %c", &p->scale_bits, &dummy) != 1 || p->scale_bits < 2 || p->scale_bits > 32) { lsx_fail("parameter `-b' must be between 2 and 32"); return lsx_usage(effp); } break;
    case 'w': if (sscanf(optstate.arg, "%lf %c", &p->time_constant, &dummy) != 1 || p->time_constant < .01 || p->time_constant > 10) { lsx_fail("parameter `-w' must be between 0.01 and 10"); return lsx_usage(effp); } break;
    case 's': if (sscanf(optstate.arg, "%lf %c", &p->scale, &dummy) != 1 || p->scale < -99 || p->scale > 99) { lsx_fail("parameter `-s' must be between -99 and 99"); return lsx_usage(effp); } break;
    default: lsx_fail("invalid option `-%c'", optstate.curpos ? optstate.curpos[-1] : '?'); return lsx_usage(effp);
  }
  if (p->hex_bits) p->scale_bits = p->hex_bits;
  return optstate.ind != argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  p->last = 0;
  p->mult = exp((-1 / p->time_constant / effp->in_signal.rate));
  p->tc_samples = (uint64_t)(5 * p->time_constant * effp->in_signal.rate + .5);
  p->sigma_x = p->sigma_x2 = p->avg_sigma_x2 = p->max_sigma_x2 = 0;
  p->min_sigma_x2 = 2;
  p->min = 2;
  p->max = -2;
  p->num_samples = 0;
  p->mask = 0;
  p->min_run = p->min_runs = p->max_run = p->max_runs = 0;
  p->min_count = p->max_count = 0;
  return SOX_SUCCESS;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t len = *isamp = *osamp = min(*isamp, *osamp);
  memcpy(obuf, ibuf, len * sizeof(*obuf));
  for (; len--; ++ibuf) {
    double d = SOX_SAMPLE_TO_FLOAT_64BIT(*ibuf, );
    if (d < p->min) p->min = d, p->min_count = 1, p->min_run = 1, p->min_runs = 1;
    else if (d == p->min) {
      ++p->min_count;
      if (p->last == d) ++p->min_run; else ++p->min_runs;
    }
    if (d > p->max) p->max = d, p->max_count = 1, p->max_run = 1, p->max_runs = 1;
    else if (d == p->max) {
      ++p->max_count;
      if (p->last == d) ++p->max_run; else ++p->max_runs;
    }
    p->sigma_x += d;
    p->sigma_x2 += d * d;
    p->avg_sigma_x2 = p->avg_sigma_x2 * p->mult + (1 - p->mult) * d * d;
    if (p->num_samples >= p->tc_samples) {
      if (p->avg_sigma_x2 > p->max_sigma_x2) p->max_sigma_x2 = p->avg_sigma_x2;
      if (p->avg_sigma_x2 < p->min_sigma_x2) p->min_sigma_x2 = p->avg_sigma_x2;
    }
    p->mask |= (uint32_t)*ibuf;
    p->last = d;
    ++p->num_samples;
  }
  return SOX_SUCCESS;
}

static unsigned bit_depth(uint32_t mask, double min, double max, unsigned *depth)
{
  unsigned b1, b2;
  double maxabs = max(fabs(min), fabs(max));
  int64_t m = (int64_t)(maxabs * (SOX_SAMPLE_MAX + 1.));
  for (b1 = 32; b1 && !(mask & 1); --b1, mask >>= 1);
  *depth = b1;
  for (b2 = 0; m > 0; ++b2, m >>= 1);
  if (b2 < 32 - *depth) return 0;
  return b2 - (32 - *depth);
}

static void output(priv_t const *p, double x)
{
  if (p->scale_bits) {
    unsigned long mask_ = ((unsigned long)1 << p->scale_bits) - 1;
    long l = (long)(x * (1 << (p->scale_bits - 1)) + (x < 0 ? -.5 : .5));
    if (p->hex_bits) fprintf(stderr, " %*lx", (p->hex_bits + 3) >> 2, (unsigned long)l & mask_);
    else fprintf(stderr, " %*ld", (int)((p->scale_bits + 2) / 3.33 + 1), l);
  } else fprintf(stderr, " %9.*f", p->scale_bits ? 0 : 6, x * p->scale);
}

static int stop(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  if (!effp->flow) {
    unsigned i, nchans = effp->in_signal.channels;
    double min = 2, max = -2, sigma_x = 0, sigma_x2 = 0, min_sigma_x2 = 2, max_sigma_x2 = 0, min_run = 0, min_runs = 0, max_run = 0, max_runs = 0;
    uint64_t num_samples = 0, min_count = 0, max_count = 0;
    uint32_t mask = 0;
    int b1 = 0, b2;
    priv_t *q;
    char label[32];
    for (i = 0; i < nchans; ++i) {
      q = (priv_t *)(effp + i)->priv;
      min = min(min, q->min); max = max(max, q->max);
      sigma_x += q->sigma_x; sigma_x2 += q->sigma_x2;
      min_sigma_x2 = min(min_sigma_x2, q->min_sigma_x2);
      max_sigma_x2 = max(max_sigma_x2, q->max_sigma_x2);
      min_run += q->min_run; min_runs += q->min_runs; max_run += q->max_run; max_runs += q->max_runs;
      min_count += q->min_count; max_count += q->max_count;
      num_samples += q->num_samples;
      mask |= q->mask;
    }
    if (nchans > 1) {
      fprintf(stderr, "%-11s%9s", "", "Overall");
      for (i = 0; i < nchans; ++i) {
        if (nchans == 2) fprintf(stderr, " %9s", i ? "Right" : "Left");
        else { sprintf(label, "Ch%u", i + 1); fprintf(stderr, " %9s", label); }
      }
      fprintf(stderr, "\n");
    }
#define ROW(name) fprintf(stderr, "%-11s", name)
#define CH(expr) for (i = 0; i < nchans; ++i) { q = (priv_t *)(effp + i)->priv; expr; }
    ROW("DC offset"); if (nchans > 1) output(p, sigma_x / num_samples); CH(output(q, q->sigma_x / q->num_samples)) fprintf(stderr, "\n");
    ROW("Min level"); if (nchans > 1) output(p, min); CH(output(q, q->min)) fprintf(stderr, "\n");
    ROW("Max level"); if (nchans > 1) output(p, max); CH(output(q, q->max)) fprintf(stderr, "\n");
    ROW("Pk lev dB"); if (nchans > 1) fprintf(stderr, " %9.2f", linear_to_dB(max(-min, max))); CH(fprintf(stderr, " %9.2f", linear_to_dB(max(-q->min, q->max)))) fprintf(stderr, "\n");
    ROW("RMS lev dB"); if (nchans > 1) fprintf(stderr, " %9.2f", linear_to_dB(sqrt(sigma_x2 / num_samples))); CH(fprintf(stderr, " %9.2f", linear_to_dB(sqrt(q->sigma_x2 / q->num_samples)))) fprintf(stderr, "\n");
    ROW("RMS Pk dB"); if (nchans > 1) fprintf(stderr, " %9.2f", linear_to_dB(sqrt(max_sigma_x2))); CH(fprintf(stderr, " %9.2f", linear_to_dB(sqrt(q->max_sigma_x2)))) fprintf(stderr, "\n");
    ROW("RMS Tr dB"); if (nchans > 1) fprintf(stderr, " %9.2f", min_sigma_x2 != 2 ? linear_to_dB(sqrt(min_sigma_x2)) : -HUGE_VAL);
      CH(if (q->min_sigma_x2 != 2) fprintf(stderr, " %9.2f", linear_to_dB(sqrt(q->min_sigma_x2))); else fprintf(stderr, " %9s", "-")) fprintf(stderr, "\n");
    ROW("Crest factor"); if (nchans > 1) fprintf(stderr, " %9s", "-");
      CH(fprintf(stderr, " %9.2f", q->sigma_x2 ? max(-q->min, q->max) / sqrt(q->sigma_x2 / q->num_samples) : 1)) fprintf(stderr, "\n");
    ROW("Flat factor"); if (nchans > 1) fprintf(stderr, " %9.2f", linear_to_dB((min_run + max_run) / (min_runs + max_runs ? min_runs + max_runs : 1)));
      CH(fprintf(stderr, " %9.2f", linear_to_dB((q->min_run + q->max_run) / (q->min_runs + q->max_runs ? q->min_runs + q->max_runs : 1)))) fprintf(stderr, "\n");
    ROW("Pk count"); if (nchans > 1) fprintf(stderr, " %9s", lsx_sigfigs3(min_runs + max_runs));
      CH(fprintf(stderr, " %9s", lsx_sigfigs3(q->min_runs + q->max_runs))) fprintf(stderr, "\n");
    ROW("Bit-depth");
    { unsigned d; b1 = (int)bit_depth(mask, min, max, &d); b2 = (int)d; if (nchans > 1) { char buf[16]; sprintf(buf, "%u/%u", b1, b2); fprintf(stderr, " %9s", buf); } }
    CH({ unsigned d; char buf[16]; int bb1 = (int)bit_depth(q->mask, q->min, q->max, &d); sprintf(buf, "%u/%u", bb1, d); fprintf(stderr, " %9s", buf); }) fprintf(stderr, "\n");
    ROW("Num samples"); fprintf(stderr, " %9s\n", lsx_sigfigs3((double)p->num_samples));
    ROW("Length s"); fprintf(stderr, " %9.3f\n", p->num_samples / effp->in_signal.rate);
    ROW("Scale max"); fprintf(stderr, " %9.6f\n", p->scale);
    ROW("Window s"); fprintf(stderr, " %9.3f\n", p->time_constant);
    (void)min_count; (void)max_count;
  }
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_stats_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "stats", "[-b bits|-x bits|-s scale] [-w window-time]", SOX_EFF_MODIFY,
    getopts, start, flow, NULL, stop, NULL, sizeof(priv_t) };
  return &handler;
}
