  fprintf(stderr, "Samples read:      %12" PRIu64 "\n", stat->read);
  fprintf(stderr, "Length (seconds):  %12.6f\n", (double)stat->read / effp->in_signal.rate / effp->in_signal.channels);
  if (stat->srms) fprintf(stderr, "Scaled by rms:     %12.6f\n", rms);
  else fprintf(stderr, "Scaled by:         %12.1f\n", scale);
  fprintf(stderr, "Maximum amplitude: %12.6f\n", stat->max / scale);
  fprintf(stderr, "Minimum amplitude: %12.6f\n", stat->min / scale);
  fprintf(stderr, "Midline amplitude: %12.6f\n", (stat->max + stat->min) / 2.0 / scale);
  fprintf(stderr, "Mean    norm:      %12.6f\n", stat->asum / ct / scale);
  fprintf(stderr, "Mean    amplitude: %12.6f\n", stat->sum1 / ct / scale);
  fprintf(stderr, "RMS     amplitude: %12.6f\n", sqrt(stat->sum2 / ct) / scale);
  fprintf(stderr, "Maximum delta:     %12.6f\n", stat->dmax / scale);
  fprintf(stderr, "Minimum delta:     %12.6f\n", stat->dmin / scale);
  fprintf(stderr, "Mean    delta:     %12.6f\n", stat->dsum1 / (ct - 1) / scale);
  fprintf(stderr, "RMS     delta:     %12.6f\n", sqrt(stat->dsum2 / (ct - 1)) / scale);
  freq = sqrt(stat->dsum2 / stat->sum2) * effp->in_signal.rate / (M_PI * 2);
  fprintf(stderr, "Rough   frequency: %12d\n", (int)freq);
  if (amp > 0) fprintf(stderr, "Volume adjustment: %12.3f\n", SOX_SAMPLE_MAX / amp);
  if (stat->bin[2] == 0 && stat->bin[3] == 0) fprintf(stderr, "\nProbably text, not sound\n");
  else {
    x = (float)(stat->bin[0] + stat->bin[3]) / (float)(stat->bin[1] + stat->bin[2]);
    if (x >= 3.0) fprintf(stderr, "\nTry: -t raw -e unsigned-integer -b 8 \n");
    else if (x <= 1.0 / 3.0) ;
    else fprintf(stderr, "\nCan't guess the type\n");
  }
  free(stat->re); free(stat->im);
  stat->re = stat->im = NULL;
  return SOX_SUCCESS;
}

