    dstsub(m, a, nc, w + nw);
    if (m > 4) { bitrv2(m, ip + 2, a); cftfsub(m, a, w); rftfsub(m, a, nc, w + nw); }
    else if (m == 4) cftfsub(m, a, w);
    a[n - 1] = a[1] - a[0];
    a[1] = a[0] + a[1];
    for (j = m - 2; j >= 2; j -= 2) {
      a[2 * j + 1] = a[j] - a[j + 1];
      a[2 * j - 1] = -a[j] - a[j + 1];
    }
    l = 2;
    m = mh;
    while (m >= 2) {
      dstsub(m, t, nc, w + nw);
      if (m > 4) { bitrv2(m, ip + 2, t); cftfsub(m, t, w); rftfsub(m, t, nc, w + nw); }
      else if (m == 4) cftfsub(m, t, w);
      a[n - l] = t[1] - t[0];
      a[l] = t[0] + t[1];
      k = 0;
      for (j = 2; j < m; j += 2) {
        k += l << 2;
        a[k - l] = -t[j] - t[j + 1];
        a[k + l] = t[j] - t[j + 1];
      }
      l <<= 1;
      mh = m >> 1;
      for (j = 1; j < mh; j++) {
        k = m - j;
        t[j] = t[m + k] + t[m + j];
        t[k] = t[m + k] - t[m + j];
      }
      t[0] = t[m + mh];
      m = mh;
    }
    a[l] = t[0];
  }
  a[0] = 0;
}

/* -------- initializing routines -------- */
static void makewt(int nw, int *ip, double *w)
{
  int j, nwh;
  double delta, x, y;
  ip[0] = nw;
  ip[1] = 1;
  if (nw > 2) {
    nwh = nw >> 1;
    delta = atan(1.0) / nwh;
    w[0] = 1;
    w[1] = 0;
    w[nwh] = cos(delta * nwh);
    w[nwh + 1] = w[nwh];
    if (nwh > 2) {
      for (j = 2; j < nwh; j += 2) {
        x = cos(delta * j);
        y = sin(delta * j);
        w[j] = x;
        w[j + 1] = y;
        w[nw - j] = y;
        w[nw - j + 1] = x;
      }
      bitrv2(nw, ip + 2, w);
    }
  }
}

static void makect(int nc, int *ip, double *c)
{
  int j, nch;
  double delta;
  ip[1] = nc;
  if (nc > 1) {
    nch = nc >> 1;
    delta = atan(1.0) / nch;
    c[0] = cos(delta * nch);
    c[nch] = 0.5 * c[0];
    for (j = 1; j < nch; j++) {
      c[j] = 0.5 * cos(delta * j);
      c[nc - j] = 0.5 * sin(delta * j);
    }
  }
}

/* -------- child routines -------- */
static void bitrv2(int n, int *ip, double *a)
{
  int j, j1, k, k1, l, m, m2;
  double xr, xi, yr, yi;
  ip[0] = 0;
  l = n;
  m = 1;
  while ((m << 3) < l) {
    l >>= 1;
    for (j = 0; j < m; j++) ip[m + j] = ip[j] + l;
    m <<= 1;
  }
  m2 = 2 * m;
  if ((m << 3) == l) {
    for (k = 0; k < m; k++) {
      for (j = 0; j < k; j++) {
        j1 = 2 * j + ip[k];
        k1 = 2 * k + ip[j];
        xr = a[j1]; xi = a[j1 + 1]; yr = a[k1]; yi = a[k1 + 1];
        a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
        j1 += m2; k1 += 2 * m2;
        xr = a[j1]; xi = a[j1 + 1]; yr = a[k1]; yi = a[k1 + 1];
        a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
        j1 += m2; k1 -= m2;
        xr = a[j1]; xi = a[j1 + 1]; yr = a[k1]; yi = a[k1 + 1];
        a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
        j1 += m2; k1 += 2 * m2;
        xr = a[j1]; xi = a[j1 + 1]; yr = a[k1]; yi = a[k1 + 1];
        a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
      }
      j1 = 2 * k + m2 + ip[k];
      k1 = j1 + m2;
      xr = a[j1]; xi = a[j1 + 1]; yr = a[k1]; yi = a[k1 + 1];
      a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
    }
  } else {
    for (k = 1; k < m; k++) {
      for (j = 0; j < k; j++) {
        j1 = 2 * j + ip[k];
        k1 = 2 * k + ip[j];
        xr = a[j1]; xi = a[j1 + 1]; yr = a[k1]; yi = a[k1 + 1];
        a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
        j1 += m2; k1 += m2;
        xr = a[j1]; xi = a[j1 + 1]; yr = a[k1]; yi = a[k1 + 1];
        a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
      }
    }
  }
}

static void bitrv2conj(int n, int *ip, double *a)
{
  int j, j1, k, k1, l, m, m2;
  double xr, xi, yr, yi;
  ip[0] = 0;
  l = n;
  m = 1;
  while ((m << 3) < l) {
    l >>= 1;
    for (j = 0; j < m; j++) ip[m + j] = ip[j] + l;
    m <<= 1;
  }
  m2 = 2 * m;
  if ((m << 3) == l) {
    for (k = 0; k < m; k++) {
      for (j = 0; j < k; j++) {
        j1 = 2 * j + ip[k];
        k1 = 2 * k + ip[j];
        xr = a[j1]; xi = -a[j1 + 1]; yr = a[k1]; yi = -a[k1 + 1];
        a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
        j1 += m2; k1 += 2 * m2;
        xr = a[j1]; xi = -a[j1 + 1]; yr = a[k1]; yi = -a[k1 + 1];
        a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
        j1 += m2; k1 -= m2;
        xr = a[j1]; xi = -a[j1 + 1]; yr = a[k1]; yi = -a[k1 + 1];
        a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
        j1 += m2; k1 += 2 * m2;
        xr = a[j1]; xi = -a[j1 + 1]; yr = a[k1]; yi = -a[k1 + 1];
        a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
      }
      k1 = 2 * k + ip[k];
      a[k1 + 1] = -a[k1 + 1];
      j1 = k1 + m2;
      k1 = j1 + m2;
      xr = a[j1]; xi = -a[j1 + 1]; yr = a[k1]; yi = -a[k1 + 1];
      a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
      k1 += m2;
      a[k1 + 1] = -a[k1 + 1];
    }
  } else {
    a[1] = -a[1];
    a[m2 + 1] = -a[m2 + 1];
    for (k = 1; k < m; k++) {
      for (j = 0; j < k; j++) {
        j1 = 2 * j + ip[k];
        k1 = 2 * k + ip[j];
        xr = a[j1]; xi = -a[j1 + 1]; yr = a[k1]; yi = -a[k1 + 1];
        a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
        j1 += m2; k1 += m2;
        xr = a[j1]; xi = -a[j1 + 1]; yr = a[k1]; yi = -a[k1 + 1];
        a[j1] = yr; a[j1 + 1] = yi; a[k1] = xr; a[k1 + 1] = xi;
      }
      k1 = 2 * k + ip[k];
      a[k1 + 1] = -a[k1 + 1];
      a[k1 + m2 + 1] = -a[k1 + m2 + 1];
    }
  }
}

static void cftfsub(int n, double *a, double *w)
{
  int j, j1, j2, j3, l;
  double x0r, x0i, x1r, x1i, x2r, x2i, x3r, x3i;
  l = 2;
  if (n > 8) {
    cft1st(n, a, w);
    l = 8;
    while ((l << 2) < n) { cftmdl(n, l, a, w); l <<= 2; }
  }
  if ((l << 2) == n) {
    for (j = 0; j < l; j += 2) {
      j1 = j + l; j2 = j1 + l; j3 = j2 + l;
      x0r = a[j] + a[j1]; x0i = a[j + 1] + a[j1 + 1];
      x1r = a[j] - a[j1]; x1i = a[j + 1] - a[j1 + 1];
      x2r = a[j2] + a[j3]; x2i = a[j2 + 1] + a[j3 + 1];
      x3r = a[j2] - a[j3]; x3i = a[j2 + 1] - a[j3 + 1];
      a[j] = x0r + x2r; a[j + 1] = x0i + x2i;
      a[j2] = x0r - x2r; a[j2 + 1] = x0i - x2i;
      a[j1] = x1r - x3i; a[j1 + 1] = x1i + x3r;
      a[j3] = x1r + x3i; a[j3 + 1] = x1i - x3r;
    }
  } else {
    for (j = 0; j < l; j += 2) {
      j1 = j + l;
      x0r = a[j] - a[j1]; x0i = a[j + 1] - a[j1 + 1];
      a[j] += a[j1]; a[j + 1] += a[j1 + 1];
      a[j1] = x0r; a[j1 + 1] = x0i;
    }
  }
}

static void cftbsub(int n, double *a, double *w)
{
  int j, j1, j2, j3, l;
  double x0r, x0i, x1r, x1i, x2r, x2i, x3r, x3i;
  l = 2;
  if (n > 8) {
    cft1st(n, a, w);
    l = 8;
    while ((l << 2) < n) { cftmdl(n, l, a, w); l <<= 2; }
  }
  if ((l << 2) == n) {
    for (j = 0; j < l; j += 2) {
      j1 = j + l; j2 = j1 + l; j3 = j2 + l;
      x0r = a[j] + a[j1]; x0i = -a[j + 1] - a[j1 + 1];
      x1r = a[j] - a[j1]; x1i = -a[j + 1] + a[j1 + 1];
      x2r = a[j2] + a[j3]; x2i = a[j2 + 1] + a[j3 + 1];
      x3r = a[j2] - a[j3]; x3i = a[j2 + 1] - a[j3 + 1];
      a[j] = x0r + x2r; a[j + 1] = x0i - x2i;
      a[j2] = x0r - x2r; a[j2 + 1] = x0i + x2i;
      a[j1] = x1r - x3i; a[j1 + 1] = x1i - x3r;
      a[j3] = x1r + x3i; a[j3 + 1] = x1i + x3r;
    }
  } else {
    for (j = 0; j < l; j += 2) {
      j1 = j + l;
      x0r = a[j] - a[j1]; x0i = -a[j + 1] + a[j1 + 1];
      a[j] += a[j1]; a[j + 1] = -a[j + 1] - a[j1 + 1];
      a[j1] = x0r; a[j1 + 1] = x0i;
    }
  }
}

static void cft1st(int n, double *a, double *w)
{
  int j, k1, k2;
  double wk1r, wk1i, wk2r, wk2i, wk3r, wk3i;
  double x0r, x0i, x1r, x1i, x2r, x2i, x3r, x3i;
  x0r = a[0] + a[2]; x0i = a[1] + a[3];
  x1r = a[0] - a[2]; x1i = a[1] - a[3];
  x2r = a[4] + a[6]; x2i = a[5] + a[7];
  x3r = a[4] - a[6]; x3i = a[5] - a[7];
  a[0] = x0r + x2r; a[1] = x0i + x2i;
  a[4] = x0r - x2r; a[5] = x0i - x2i;
  a[2] = x1r - x3i; a[3] = x1i + x3r;
  a[6] = x1r + x3i; a[7] = x1i - x3r;
  wk1r = w[2];
  x0r = a[8] + a[10]; x0i = a[9] + a[11];
  x1r = a[8] - a[10]; x1i = a[9] - a[11];
  x2r = a[12] + a[14]; x2i = a[13] + a[15];
  x3r = a[12] - a[14]; x3i = a[13] - a[15];
  a[8] = x0r + x2r; a[9] = x0i + x2i;
  a[12] = x2i - x0i; a[13] = x0r - x2r;
  x0r = x1r - x3i; x0i = x1i + x3r;
  a[10] = wk1r * (x0r - x0i); a[11] = wk1r * (x0r + x0i);
  x0r = x3i + x1r; x0i = x3r - x1i;
  a[14] = wk1r * (x0i - x0r); a[15] = wk1r * (x0i + x0r);
  k1 = 0;
  for (j = 16; j < n; j += 16) {
    k1 += 2;
    k2 = 2 * k1;
    wk2r = w[k1]; wk2i = w[k1 + 1];
    wk1r = w[k2]; wk1i = w[k2 + 1];
    wk3r = wk1r - 2 * wk2i * wk1i;
    wk3i = 2 * wk2i * wk1r - wk1i;
    x0r = a[j] + a[j + 2]; x0i = a[j + 1] + a[j + 3];
    x1r = a[j] - a[j + 2]; x1i = a[j + 1] - a[j + 3];
    x2r = a[j + 4] + a[j + 6]; x2i = a[j + 5] + a[j + 7];
    x3r = a[j + 4] - a[j + 6]; x3i = a[j + 5] - a[j + 7];
    a[j] = x0r + x2r; a[j + 1] = x0i + x2i;
    x0r -= x2r; x0i -= x2i;
    a[j + 4] = wk2r * x0r - wk2i * x0i; a[j + 5] = wk2r * x0i + wk2i * x0r;
    x0r = x1r - x3i; x0i = x1i + x3r;
    a[j + 2] = wk1r * x0r - wk1i * x0i; a[j + 3] = wk1r * x0i + wk1i * x0r;
    x0r = x1r + x3i; x0i = x1i - x3r;
    a[j + 6] = wk3r * x0r - wk3i * x0i; a[j + 7] = wk3r * x0i + wk3i * x0r;
    wk1r = w[k2 + 2]; wk1i = w[k2 + 3];
    wk3r = wk1r - 2 * wk2r * wk1i;
    wk3i = 2 * wk2r * wk1r - wk1i;
    x0r = a[j + 8] + a[j + 10]; x0i = a[j + 9] + a[j + 11];
    x1r = a[j + 8] - a[j + 10]; x1i = a[j + 9] - a[j + 11];
    x2r = a[j + 12] + a[j + 14]; x2i = a[j + 13] + a[j + 15];
    x3r = a[j + 12] - a[j + 14]; x3i = a[j + 13] - a[j + 15];
    a[j + 8] = x0r + x2r; a[j + 9] = x0i + x2i;
    x0r -= x2r; x0i -= x2i;
    a[j + 12] = -wk2i * x0r - wk2r * x0i; a[j + 13] = -wk2i * x0i + wk2r * x0r;
    x0r = x1r - x3i; x0i = x1i + x3r;
    a[j + 10] = wk1r * x0r - wk1i * x0i; a[j + 11] = wk1r * x0i + wk1i * x0r;
    x0r = x1r + x3i; x0i = x1i - x3r;
    a[j + 14] = wk3r * x0r - wk3i * x0i; a[j + 15] = wk3r * x0i + wk3i * x0r;
  }
}

static void cftmdl(int n, int l, double *a, double *w)
{
  int j, j1, j2, j3, k, k1, k2, m, m2;
  double wk1r, wk1i, wk2r, wk2i, wk3r, wk3i;
  double x0r, x0i, x1r, x1i, x2r, x2i, x3r, x3i;
  m = l << 2;
  for (j = 0; j < l; j += 2) {
    j1 = j + l; j2 = j1 + l; j3 = j2 + l;
    x0r = a[j] + a[j1]; x0i = a[j + 1] + a[j1 + 1];
    x1r = a[j] - a[j1]; x1i = a[j + 1] - a[j1 + 1];
    x2r = a[j2] + a[j3]; x2i = a[j2 + 1] + a[j3 + 1];
    x3r = a[j2] - a[j3]; x3i = a[j2 + 1] - a[j3 + 1];
    a[j] = x0r + x2r; a[j + 1] = x0i + x2i;
    a[j2] = x0r - x2r; a[j2 + 1] = x0i - x2i;
    a[j1] = x1r - x3i; a[j1 + 1] = x1i + x3r;
    a[j3] = x1r + x3i; a[j3 + 1] = x1i - x3r;
  }
  wk1r = w[2];
  for (j = m; j < l + m; j += 2) {
    j1 = j + l; j2 = j1 + l; j3 = j2 + l;
    x0r = a[j] + a[j1]; x0i = a[j + 1] + a[j1 + 1];
    x1r = a[j] - a[j1]; x1i = a[j + 1] - a[j1 + 1];
    x2r = a[j2] + a[j3]; x2i = a[j2 + 1] + a[j3 + 1];
    x3r = a[j2] - a[j3]; x3i = a[j2 + 1] - a[j3 + 1];
    a[j] = x0r + x2r; a[j + 1] = x0i + x2i;
    a[j2] = x2i - x0i; a[j2 + 1] = x0r - x2r;
    x0r = x1r - x3i; x0i = x1i + x3r;
    a[j1] = wk1r * (x0r - x0i); a[j1 + 1] = wk1r * (x0r + x0i);
    x0r = x3i + x1r; x0i = x3r - x1i;
    a[j3] = wk1r * (x0i - x0r); a[j3 + 1] = wk1r * (x0i + x0r);
  }
  k1 = 0;
  m2 = 2 * m;
  for (k = m2; k < n; k += m2) {
    k1 += 2;
    k2 = 2 * k1;
    wk2r = w[k1]; wk2i = w[k1 + 1];
    wk1r = w[k2]; wk1i = w[k2 + 1];
    wk3r = wk1r - 2 * wk2i * wk1i;
    wk3i = 2 * wk2i * wk1r - wk1i;
    for (j = k; j < l + k; j += 2) {
      j1 = j + l; j2 = j1 + l; j3 = j2 + l;
      x0r = a[j] + a[j1]; x0i = a[j + 1] + a[j1 + 1];
      x1r = a[j] - a[j1]; x1i = a[j + 1] - a[j1 + 1];
      x2r = a[j2] + a[j3]; x2i = a[j2 + 1] + a[j3 + 1];
      x3r = a[j2] - a[j3]; x3i = a[j2 + 1] - a[j3 + 1];
      a[j] = x0r + x2r; a[j + 1] = x0i + x2i;
      x0r -= x2r; x0i -= x2i;
      a[j2] = wk2r * x0r - wk2i * x0i; a[j2 + 1] = wk2r * x0i + wk2i * x0r;
      x0r = x1r - x3i; x0i = x1i + x3r;
      a[j1] = wk1r * x0r - wk1i * x0i; a[j1 + 1] = wk1r * x0i + wk1i * x0r;
      x0r = x1r + x3i; x0i = x1i - x3r;
      a[j3] = wk3r * x0r - wk3i * x0i; a[j3 + 1] = wk3r * x0i + wk3i * x0r;
    }
    wk1r = w[k2 + 2]; wk1i = w[k2 + 3];
    wk3r = wk1r - 2 * wk2r * wk1i;
    wk3i = 2 * wk2r * wk1r - wk1i;
    for (j = k + m; j < l + (k + m); j += 2) {
      j1 = j + l; j2 = j1 + l; j3 = j2 + l;
      x0r = a[j] + a[j1]; x0i = a[j + 1] + a[j1 + 1];
      x1r = a[j] - a[j1]; x1i = a[j + 1] - a[j1 + 1];
      x2r = a[j2] + a[j3]; x2i = a[j2 + 1] + a[j3 + 1];
      x3r = a[j2] - a[j3]; x3i = a[j2 + 1] - a[j3 + 1];
      a[j] = x0r + x2r; a[j + 1] = x0i + x2i;
      x0r -= x2r; x0i -= x2i;
      a[j2] = -wk2i * x0r - wk2r * x0i; a[j2 + 1] = -wk2i * x0i + wk2r * x0r;
      x0r = x1r - x3i; x0i = x1i + x3r;
      a[j1] = wk1r * x0r - wk1i * x0i; a[j1 + 1] = wk1r * x0i + wk1i * x0r;
      x0r = x1r + x3i; x0i = x1i - x3r;
      a[j3] = wk3r * x0r - wk3i * x0i; a[j3 + 1] = wk3r * x0i + wk3i * x0r;
    }
  }
}

static void rftfsub(int n, double *a, int nc, double *c)
{
  int j, k, kk, ks, m;
  double wkr, wki, xr, xi, yr, yi;
  m = n >> 1;
  ks = 2 * nc / m;
  kk = 0;
  for (j = 2; j < m; j += 2) {
    k = n - j;
    kk += ks;
    wkr = 0.5 - c[nc - kk];
    wki = c[kk];
    xr = a[j] - a[k];
    xi = a[j + 1] + a[k + 1];
    yr = wkr * xr - wki * xi;
    yi = wkr * xi + wki * xr;
    a[j] -= yr; a[j + 1] -= yi;
    a[k] += yr; a[k + 1] -= yi;
  }
}

static void rftbsub(int n, double *a, int nc, double *c)
{
  int j, k, kk, ks, m;
  double wkr, wki, xr, xi, yr, yi;
  a[1] = -a[1];
  m = n >> 1;
  ks = 2 * nc / m;
  kk = 0;
  for (j = 2; j < m; j += 2) {
    k = n - j;
    kk += ks;
    wkr = 0.5 - c[nc - kk];
    wki = c[kk];
    xr = a[j] - a[k];
    xi = a[j + 1] + a[k + 1];
    yr = wkr * xr + wki * xi;
    yi = wkr * xi - wki * xr;
    a[j] -= yr; a[j + 1] = yi - a[j + 1];
    a[k] += yr; a[k + 1] = yi - a[k + 1];
  }
  a[m + 1] = -a[m + 1];
}

static void dctsub(int n, double *a, int nc, double *c)
{
  int j, k, kk, ks, m;
  double wkr, wki, xr;
  m = n >> 1;
  ks = nc / n;
  kk = 0;
  for (j = 1; j < m; j++) {
    k = n - j;
    kk += ks;
    wkr = c[kk] - c[nc - kk];
    wki = c[kk] + c[nc - kk];
    xr = wki * a[j] - wkr * a[k];
    a[j] = wkr * a[j] + wki * a[k];
    a[k] = xr;
  }
  a[m] *= c[0];
}

static void dstsub(int n, double *a, int nc, double *c)
{
  int j, k, kk, ks, m;
  double wkr, wki, xr;
  m = n >> 1;
  ks = nc / n;
  kk = 0;
  for (j = 1; j < m; j++) {
    k = n - j;
    kk += ks;
    wkr = c[kk] - c[nc - kk];
    wki = c[kk] + c[nc - kk];
    xr = wki * a[k] - wkr * a[j];
    a[k] = wkr * a[k] + wki * a[j];
    a[j] = xr;
  }
  a[m] *= c[0];
}

/* ---- cached safe wrappers ---- */
static int *lsx_fft_br;
static double *lsx_fft_sc;
static int fft_len = -1;

static void update_fft_cache(int len)
{
  if (!lsx_is_power_of_2((unsigned long)len)) { lsx_fail("FFT length is not a power of 2"); }
  if (len > fft_len) {
    int old_len = fft_len;
    fft_len = len;
    lsx_fft_br = lsx_realloc(lsx_fft_br, (size_t)(2 + (int)sqrt((double)fft_len / 2)) * sizeof(*lsx_fft_br) + 16);
    lsx_fft_sc = lsx_realloc(lsx_fft_sc, (size_t)(fft_len / 2) * sizeof(*lsx_fft_sc) + 16);
    if (old_len < 0) lsx_fft_br[0] = 0;
    else lsx_fft_br[0] = 0;
  }
}

void lsx_init_fft_cache(void) { }
void lsx_clear_fft_cache(void) { free(lsx_fft_br); free(lsx_fft_sc); lsx_fft_br = NULL; lsx_fft_sc = NULL; fft_len = -1; }

void lsx_safe_rdft(int len, int type, double *d)
{
  update_fft_cache(len);
  lsx_rdft(len, type, d, lsx_fft_br, lsx_fft_sc);
}

void lsx_safe_cdft(int len, int type, double *d)
{
  update_fft_cache(len);
  lsx_cdft(len, type, d, lsx_fft_br, lsx_fft_sc);
}
