#define lsx_subsystem_name "dcshift"
#include "sox.h"

typedef struct {
  double dcshift;
  int uselimiter;
  double limiterthreshhold;
  double limitergain;
  uint64_t limited;
  uint64_t totalprocessed;
} priv_t;

static int getopts(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *dcs = (priv_t *)effp->priv;
  --argc, ++argv;
  dcs->dcshift = 1.0;
  dcs->uselimiter = 0;
  dcs->limiterthreshhold = 0;
  dcs->limitergain = 0;
  if (argc < 1 || argc > 2) return lsx_usage(effp);
  if (argc) {
    if (!sscanf(argv[0], "%lf", &dcs->dcshift)) return lsx_usage(effp);
    --argc, ++argv;
  }
  if (argc) {
    if (!sscanf(argv[0], "%lf", &dcs->limitergain)) return lsx_usage(effp);
    dcs->uselimiter = 1;
    dcs->limiterthreshhold = SOX_SAMPLE_MAX * (1.0 - (fabs(dcs->dcshift) - dcs->limitergain));
  }
  return SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *dcs = (priv_t *)effp->priv;
  if (dcs->dcshift == 0) return SOX_EFF_NULL;
  if (dcs->dcshift < -2.0 || dcs->dcshift > 2.0) { lsx_fail("dcshift value must be between -2.0 and 2.0"); return SOX_EOF; }
  dcs->limited = dcs->totalprocessed = 0;
  return SOX_SUCCESS;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *dcs = (priv_t *)effp->priv;
  double dcshift = dcs->dcshift;
  double limitergain = dcs->limitergain;
  double limiterthreshhold = dcs->limiterthreshhold;
  double sample;
  size_t len = min(*osamp, *isamp);
  *isamp = *osamp = len;
  if (dcs->uselimiter) {
    dcs->totalprocessed += len;
    for (; len > 0; len--) {
      sample = *ibuf++;
      if (sample > limiterthreshhold && dcshift > 0) {
        sample = (sample - limiterthreshhold) * limitergain / (SOX_SAMPLE_MAX - limiterthreshhold) + limiterthreshhold + dcshift;
        dcs->limited++;
      } else if (sample < -limiterthreshhold && dcshift < 0) {
        sample = (sample + limiterthreshhold) * limitergain / (SOX_SAMPLE_MAX - limiterthreshhold) - limiterthreshhold + dcshift;
        dcs->limited++;
      } else sample = dcshift * SOX_SAMPLE_MAX + sample;
      SOX_SAMPLE_CLIP_COUNT(sample, effp->clips);
      *obuf++ = (sox_sample_t)sample;
    }
  } else {
    for (; len > 0; len--) {
      double f = dcshift * SOX_SAMPLE_MAX + *ibuf++;
      SOX_SAMPLE_CLIP_COUNT(f, effp->clips);
      *obuf++ = (sox_sample_t)f;
    }
  }
  return SOX_SUCCESS;
}

static int stop(sox_effect_t *effp)
{
  priv_t *dcs = (priv_t *)effp->priv;
  if (dcs->limited) lsx_warn("DCSHIFT limited %" PRIu64 " values (%d percent).", dcs->limited, (int)(dcs->limited * 100.0 / dcs->totalprocessed));
  return SOX_SUCCESS;
}

