static int biquad_getopts(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *p = (priv_t *)effp->priv;
  char dummy;
  --argc, ++argv;
  if (argc != 6 ||
      sscanf(argv[0], "%lf %c", &p->b0, &dummy) != 1 || sscanf(argv[1], "%lf %c", &p->b1, &dummy) != 1 ||
      sscanf(argv[2], "%lf %c", &p->b2, &dummy) != 1 || sscanf(argv[3], "%lf %c", &p->a0, &dummy) != 1 ||
      sscanf(argv[4], "%lf %c", &p->a1, &dummy) != 1 || sscanf(argv[5], "%lf %c", &p->a2, &dummy) != 1)
    return lsx_usage(effp);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_biquad_effect_fn(void)
{
  static sox_effect_handler_t handler = { "biquad", "b0 b1 b2 a0 a1 a2", 0, biquad_getopts, lsx_biquad_start, lsx_biquad_flow, NULL, NULL, NULL, sizeof(biquad_t) };
  return &handler;
}
