#define lsx_subsystem_name "biquad"
#include "sox.h"

typedef biquad_t priv_t;
static const char all_width_types[] = "hkboqs";

int lsx_biquad_getopts(sox_effect_t *effp, int argc, char **argv, int min_args, int max_args, int fc_pos, int width_pos, int gain_pos, const char *allowed_width_types, filter_t filter_type)
{
  priv_t *p = (priv_t *)effp->priv;
  char width_type = *allowed_width_types;
  char dummy, *dummy_p;
  --argc, ++argv;
  p->filter_type = filter_type;
  if (argc < min_args || argc > max_args ||
      (argc > fc_pos && ((p->fc = lsx_parse_frequency(argv[fc_pos], &dummy_p)) <= 0 || *dummy_p)) ||
      (argc > width_pos && ((unsigned)(sscanf(argv[width_pos], "%lf%c %c", &p->width, &width_type, &dummy) - 1) > 1 || p->width <= 0)) ||
      (argc > gain_pos && sscanf(argv[gain_pos], "%lf %c", &p->gain, &dummy) != 1) ||
      !strchr(allowed_width_types, width_type) || (width_type == 's' && p->width > 1))
    return lsx_usage(effp);
  p->width_type = (width_t)(strchr(all_width_types, width_type) - all_width_types);
  if ((int)p->width_type >= (int)strlen(all_width_types)) p->width_type = 0;
  if (p->width_type == width_bw_kHz) { p->width *= 1000.; p->width_type = width_bw_Hz; }
  return SOX_SUCCESS;
}

static void plot_response(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  int plot = sox_effects_globals_s.plot;
  if (plot == sox_plot_octave) {
    printf("%% GNU Octave file (may also work with MATLAB(R) )\nRs=%g;\nb=[%.15g %.15g %.15g];\na=[%.15g %.15g %.15g];\n[h,w]=freqz(b,a,2^11)?;\n",
        effp->in_signal.rate, p->b0, p->b1, p->b2, p->a0, p->a1, p->a2);
    printf("semilogx(w*Rs/(2*pi),20*log10(abs(h)))\ntitle('SoX effect: %s gain=%g frequency=%g width=%g')\nxlabel('Frequency (Hz)')\nylabel('Amplitude Response (dB)')\naxis([1 Rs/2 -35 25])\ngrid on\ndisp('Hit return to continue')\npause\n",
        effp->handler.name, p->gain, p->fc, p->width);
  } else if (plot == sox_plot_gnuplot) {
    printf("# gnuplot file\nset title 'SoX effect: %s gain=%g frequency=%g width=%g'\nset xlabel 'Frequency (Hz)'\nset ylabel 'Amplitude Response (dB)'\nFs=%g\nb0=%.15g; b1=%.15g; b2=%.15g; a1=%.15g; a2=%.15g\no=2*pi/Fs\nH(f)=sqrt((b0*b0+b1*b1+b2*b2+2.*(b0*b1+b1*b2)*cos(f*o)+2.*(b0*b2)*cos(2.*f*o))/(1.+a1*a1+a2*a2+2.*(a1+a1*a2)*cos(f*o)+2.*a2*cos(2.*f*o)))\nset logscale x\nset samples 250\nset grid xtics ytics\nset key off\nplot [f=10:Fs/2] [-35:25] 20*log10(H(f))\npause -1 'Hit return to continue'\n",
        effp->handler.name, p->gain, p->fc, p->width, effp->in_signal.rate, p->b0 / p->a0, p->b1 / p->a0, p->b2 / p->a0, p->a1 / p->a0, p->a2 / p->a0);
  } else if (plot == sox_plot_data) {
    printf("# SoX effect: %s gain=%g frequency=%g width=%g\n# Fs=%g\n# b0=%.15g b1=%.15g b2=%.15g\n# a0=%.15g a1=%.15g a2=%.15g\n",
        effp->handler.name, p->gain, p->fc, p->width, effp->in_signal.rate, p->b0, p->b1, p->b2, p->a0, p->a1, p->a2);
  }
}

int lsx_biquad_start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  if (sox_effects_globals_s.plot != sox_plot_off) {
    plot_response(effp);
    return SOX_EOF;
  }
  p->b2 /= p->a0; p->b1 /= p->a0; p->b0 /= p->a0;
  p->a2 /= p->a0; p->a1 /= p->a0;
  p->o2 = p->o1 = p->i2 = p->i1 = 0;
  return SOX_SUCCESS;
}

int lsx_biquad_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t len = *isamp = *osamp = min(*isamp, *osamp);
  while (len--) {
    double o0 = *ibuf * p->b0 + p->i1 * p->b1 + p->i2 * p->b2 - p->o1 * p->a1 - p->o2 * p->a2;
    p->i2 = p->i1, p->i1 = *ibuf++;
    p->o2 = p->o1, p->o1 = o0;
    *obuf++ = SOX_ROUND_CLIP_COUNT(o0, effp->clips);
  }
  return SOX_SUCCESS;
}

