static void make_poly_from_roots(const double *roots, size_t num_roots, double *poly)
{
  size_t i, j;
  poly[0] = 1;
  poly[1] = -roots[0];
  memset(poly + 2, 0, (num_roots + 1 - 2) * sizeof(*poly));
  for (i = 1; i < num_roots; ++i)
    for (j = num_roots; j > 0; --j) poly[j] -= poly[j - 1] * roots[i];
}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  double w0, A, alpha = 0, mult;
  if (p->filter_type == filter_deemph) {
    if (effp->in_signal.rate == 44100) { p->fc = 5283; p->width = 0.4845; p->gain = -9.477; }
    else if (effp->in_signal.rate == 48000) { p->fc = 5356; p->width = 0.479; p->gain = -9.62; }
    else { lsx_fail("Sample rate must be 44100 (audio-CD) or 48000 (DAT)"); return SOX_EOF; }
  }
  w0 = 2 * M_PI * p->fc / effp->in_signal.rate;
  A = exp(p->gain / 40 * log(10.));
  mult = dB_to_linear(max(p->gain, 0));
  if (w0 > M_PI) { lsx_fail("frequency must be less than half the sample-rate (Nyquist rate)"); return SOX_EOF; }
  p->b0 = p->b1 = p->b2 = p->a1 = p->a2 = 0;
  p->a0 = 1;
  if (p->width) switch (p->width_type) {
    case width_slope: alpha = sin(w0) / 2 * sqrt((A + 1 / A) * (1 / p->width - 1) + 2); break;
    case width_Q: alpha = sin(w0) / (2 * p->width); break;
    case width_bw_oct: alpha = sin(w0) * sinh(log(2.) / 2 * p->width * w0 / sin(w0)); break;
    case width_bw_Hz: alpha = sin(w0) / (2 * p->fc / p->width); break;
    case width_bw_kHz: break;
    case width_bw_old: alpha = tan(M_PI * p->width / effp->in_signal.rate); break;
  }
  switch (p->filter_type) {
  case filter_LPF:
    p->b0 = (1 - cos(w0)) / 2; p->b1 = 1 - cos(w0); p->b2 = (1 - cos(w0)) / 2;
    p->a0 = 1 + alpha; p->a1 = -2 * cos(w0); p->a2 = 1 - alpha;
    break;
  case filter_HPF:
    p->b0 = (1 + cos(w0)) / 2; p->b1 = -(1 + cos(w0)); p->b2 = (1 + cos(w0)) / 2;
    p->a0 = 1 + alpha; p->a1 = -2 * cos(w0); p->a2 = 1 - alpha;
    break;
  case filter_BPF_CSG:
    p->b0 = sin(w0) / 2; p->b1 = 0; p->b2 = -sin(w0) / 2;
    p->a0 = 1 + alpha; p->a1 = -2 * cos(w0); p->a2 = 1 - alpha;
    break;
  case filter_BPF:
    p->b0 = alpha; p->b1 = 0; p->b2 = -alpha;
    p->a0 = 1 + alpha; p->a1 = -2 * cos(w0); p->a2 = 1 - alpha;
    break;
  case filter_notch:
    p->b0 = 1; p->b1 = -2 * cos(w0); p->b2 = 1;
    p->a0 = 1 + alpha; p->a1 = -2 * cos(w0); p->a2 = 1 - alpha;
    break;
  case filter_APF:
    p->b0 = 1 - alpha; p->b1 = -2 * cos(w0); p->b2 = 1 + alpha;
    p->a0 = 1 + alpha; p->a1 = -2 * cos(w0); p->a2 = 1 - alpha;
    break;
  case filter_peakingEQ:
    if (A == 1) return SOX_EFF_NULL;
    p->b0 = 1 + alpha * A; p->b1 = -2 * cos(w0); p->b2 = 1 - alpha * A;
    p->a0 = 1 + alpha / A; p->a1 = -2 * cos(w0); p->a2 = 1 - alpha / A;
    break;
  case filter_lowShelf:
    if (A == 1) return SOX_EFF_NULL;
    p->b0 = A * ((A + 1) - (A - 1) * cos(w0) + 2 * sqrt(A) * alpha);
    p->b1 = 2 * A * ((A - 1) - (A + 1) * cos(w0));
    p->b2 = A * ((A + 1) - (A - 1) * cos(w0) - 2 * sqrt(A) * alpha);
    p->a0 = (A + 1) + (A - 1) * cos(w0) + 2 * sqrt(A) * alpha;
    p->a1 = -2 * ((A - 1) + (A + 1) * cos(w0));
    p->a2 = (A + 1) + (A - 1) * cos(w0) - 2 * sqrt(A) * alpha;
    break;
  case filter_deemph:
  case filter_highShelf:
    if (!A) return SOX_EFF_NULL;
    p->b0 = A * ((A + 1) + (A - 1) * cos(w0) + 2 * sqrt(A) * alpha);
    p->b1 = -2 * A * ((A - 1) + (A + 1) * cos(w0));
    p->b2 = A * ((A + 1) + (A - 1) * cos(w0) - 2 * sqrt(A) * alpha);
    p->a0 = (A + 1) - (A - 1) * cos(w0) + 2 * sqrt(A) * alpha;
    p->a1 = 2 * ((A - 1) - (A + 1) * cos(w0));
    p->a2 = (A + 1) - (A - 1) * cos(w0) - 2 * sqrt(A) * alpha;
    break;
  case filter_LPF_1:
    p->a1 = -exp(-w0);
    p->b0 = 1 + p->a1;
    break;
  case filter_HPF_1:
    p->a1 = -exp(-w0);
    p->b0 = (1 - p->a1) / 2;
    p->b1 = -p->b0;
    break;
  case filter_BPF_SPK: case filter_BPF_SPK_N: {
    double bw_Hz;
    if (!p->width) p->width = p->fc / 2;
    bw_Hz = p->width_type == width_Q ? p->fc / p->width : p->width_type == width_bw_Hz ? p->width : p->fc * (pow(2., p->width) - 1) / pow(2., p->width / 2);
    p->a2 = exp(-2 * M_PI * bw_Hz / effp->in_signal.rate);
    p->a1 = -4 * p->a2 / (1 + p->a2) * cos(w0);
    p->b0 = sqrt(1 - p->a1 * p->a1 / (4 * p->a2)) * (1 - p->a2);
    if (p->filter_type == filter_BPF_SPK_N) {
      mult = sqrt(((1 + p->a2) * (1 + p->a2) - p->a1 * p->a1) * (1 - p->a2) / (1 + p->a2)) / p->b0;
      p->b0 *= mult;
    }
    break; }
  case filter_AP1:
    p->b0 = exp(-w0); p->b1 = -1; p->a1 = -exp(-w0);
    break;
  case filter_AP2:
    p->b0 = 1 - sin(w0); p->b1 = -2 * cos(w0); p->b2 = 1 + sin(w0);
    p->a0 = 1 + sin(w0); p->a1 = -2 * cos(w0); p->a2 = 1 - sin(w0);
    break;
  case filter_riaa: {
    const double *zeros, *poles;
    static const double z44[] = {-0.2014898, 0.9233820}, p44[] = {0.7083149, 0.9924091};
    static const double z48[] = {-0.1766069, 0.9321590}, p48[] = {0.7396325, 0.9931330};
    static const double z88[] = {-0.1168735, 0.9648312}, p88[] = {0.8590646, 0.9964002};
    static const double z96[] = {-0.1141486, 0.9676817}, p96[] = {0.8699137, 0.9966946};
    if (effp->in_signal.rate == 44100) zeros = z44, poles = p44;
    else if (effp->in_signal.rate == 48000) zeros = z48, poles = p48;
    else if (effp->in_signal.rate == 88200) zeros = z88, poles = p88;
    else if (effp->in_signal.rate == 96000) zeros = z96, poles = p96;
    else { lsx_fail("Sample rate must be 44.1k, 48k, 88.2k, or 96k"); return SOX_EOF; }
    make_poly_from_roots(zeros, 2, &p->b0);
    make_poly_from_roots(poles, 2, &p->a0);
    {
      double y = 2 * M_PI * 1000 / effp->in_signal.rate;
      double b_re = p->b0 + p->b1 * cos(-y) + p->b2 * cos(-2 * y);
      double a_re = p->a0 + p->a1 * cos(-y) + p->a2 * cos(-2 * y);
      double b_im = p->b1 * sin(-y) + p->b2 * sin(-2 * y);
      double a_im = p->a1 * sin(-y) + p->a2 * sin(-2 * y);
      double g = 1 / sqrt((sqr(b_re) + sqr(b_im)) / (sqr(a_re) + sqr(a_im)));
      p->b0 *= g; p->b1 *= g; p->b2 *= g;
    }
    mult = (p->b0 + p->b1 + p->b2) / (p->a0 + p->a1 + p->a2);
    lsx_debug("gain=%f", linear_to_dB(mult));
    break; }
  }
  if (effp->in_signal.mult) *effp->in_signal.mult /= mult;
  return lsx_biquad_start(effp);
}

