double lsx_kaiser_beta(double att, double tr_bw)
{
  if (att >= 60) {
    static const double coefs[][4] = {
      {-6.784957e-10, 1.02856e-05, 0.1087556, -0.8988365 + .001},
      {-6.897885e-10, 1.027433e-05, 0.10876, -0.8994658 + .002},
      {-1.000683e-09, 1.030092e-05, 0.1087677, -0.9007898 + .003},
      {-3.654474e-10, 1.040631e-05, 0.1087085, -0.8977766 + .006},
      {8.106988e-09, 6.983091e-06, 0.1091387, -0.9172048 + .015},
      {9.519571e-09, 7.272678e-06, 0.1090068, -0.9140768 + .025},
      {-5.626821e-10, 1.342186e-05, 0.1083999, -0.9065452 + .05},
      {-9.965946e-08, 5.073548e-05, 0.1040967, -0.7672778 + .085},
      {1.604808e-07, -5.856462e-05, 0.1185998, -1.34824 + .1},
      {-1.511964e-07, 6.363034e-05, 0.1064627, -0.9876665 + .18},
    };
    double realm = log(tr_bw / .0005) / log(2.);
    const double *c0 = coefs[range_limit((int)realm, 0, (int)array_length(coefs) - 1)];
    const double *c1 = coefs[range_limit(1 + (int)realm, 0, (int)array_length(coefs) - 1)];
    double b0 = ((c0[0] * att + c0[1]) * att + c0[2]) * att + c0[3];
    double b1 = ((c1[0] * att + c1[1]) * att + c1[2]) * att + c1[3];
    return b0 + (b1 - b0) * (realm - (int)realm);
  }
  if (att > 21.) return .5842 * pow(att - 21, .4) + .07886 * (att - 21);
  return 0;
}

void lsx_apply_kaiser(double h[], const int num_points, double beta)
{
  int i, m = num_points - 1;
  for (i = 0; i <= m; ++i) {
    double x = 2. * i / m - 1;
    h[i] *= lsx_bessel_I_0(beta * sqrt(1 - x * x)) / lsx_bessel_I_0(beta);
  }
}

void lsx_apply_dolph(double h[], const int N, double att)
{
  double b = cosh(acosh(pow(10., att / 20)) / (N - 1)), sum, t, c, norm = 0;
  int i, j;
  for (c = 1 - 1 / (b * b), i = (N - 1) / 2; i >= 0; --i) {
    for (sum = !i, b = t = j = 1; j <= i && sum != t; b *= (i - j) * (1. / j), ++j)
      t = sum, sum += (b *= c * (N - i - j) * (1. / j));
    sum /= (N - 1 - i), sum /= b;
    norm = i ? norm : sum;
    h[i] *= sum / norm;
    h[N - 1 - i] *= sum / norm;
  }
}

double *lsx_make_lpf(int num_taps, double Fc, double beta, double rho, double scale, sox_bool dc_norm)
{
  int i, m = num_taps - 1;
  double *h = lsx_malloc(num_taps * sizeof(*h)), sum = 0;
  double mult = scale / lsx_bessel_I_0(beta), mult1 = 1 / (.5 * m + rho);
  lsx_debug("make_lpf(n=%i Fc=%g \u03b2=%g \u03c1=%g dc-norm=%i scale=%g)", num_taps, Fc, beta, rho, dc_norm, scale);
  for (i = 0; i <= m / 2; ++i) {
    double z = i - .5 * m, x = z * M_PI, y = z * mult1;
    h[i] = x ? sin(Fc * x) / x : Fc;
    sum += h[i] *= lsx_bessel_I_0(beta * sqrt(1 - y * y)) * mult;
    if (m - i != i) sum += h[m - i] = h[i];
  }
  for (i = 0; dc_norm && i < num_taps; ++i) h[i] *= scale / sum;
  return h;
}

int lsx_lpf_num_taps(double att, double tr_bw, int k)
{
  int n;
  if (att <= 80) n = (int)(.25 / M_PI * (att - 7.95) / (2.285 * tr_bw) + .5);
  else {
    double n160 = (.0425 * att - 1.4) / tr_bw;
    n = (int)(n160 * (16.556 / (att - 39.17) + .8625) + .5);
  }
  return k ? 2 * n : 2 * (n + (n & 1)) + 1;
}

void lsx_kaiser_params(double att, double Fc, double tr_bw, double *beta, int *num_taps)
{
  *beta = *beta < 0 ? lsx_kaiser_beta(att, tr_bw * .5 / Fc) : *beta;
  att = att < 60 ? (att - 7.95) / (2.285 * M_PI * 2 * tr_bw) : ((.0007528358 - 1.577737e-05 * *beta) * *beta + .6248022) * *beta + .06186902;
  *num_taps = !*num_taps ? (int)ceil(att) : *num_taps;
}

double *lsx_design_lpf(double Fp, double Fs, double Fn, double att, int *num_taps, int k, double beta)
{
  int n = *num_taps, phases = max(k, 1), modulo = max(-k, 1);
  double tr_bw, Fc, rho = phases == 1 ? .5 : att < 120 ? .63 : .75;
  Fp /= fabs(Fn), Fs /= fabs(Fn);
  tr_bw = .5 * (Fs - Fp);
  tr_bw /= phases, Fs /= phases;
  tr_bw = min(tr_bw, .5 * Fs);
  Fc = Fs - tr_bw;
  if (beta < 0) beta = lsx_kaiser_beta(att, tr_bw);
  if (!n) {
    n = lsx_lpf_num_taps(att, tr_bw, 0);
    n = n * phases;
    if (modulo > 1) n = n + (modulo - 1 - (n - 1) % modulo) % modulo;
    if (!(n & 1) && phases == 1) ++n;
  }
  *num_taps = n;
  if (Fn < 0) return 0;
  return lsx_make_lpf(n, Fc, beta, rho, (double)phases, sox_false);
}

