void lsx_kaiser_params(double att, double Fc, double tr_bw, double *beta, int *num_taps)
{
  *beta = *beta < 0 ? lsx_kaiser_beta(att, tr_bw * .5 / Fc) : *beta;
  att = att < 60 ? (att - 7.95) / (2.285 * M_PI * 2 * tr_bw) : ((.0007528358 - 1.577737e-05 * *beta) * *beta + .6248022) * *beta + .06186902;
  *num_taps = !*num_taps ? (int)ceil(att) : *num_taps;
}

double *lsx_design_lpf(double Fp, double Fs, double Fn, double att, int *num_taps, int k, double beta)
{
  int n = *num_taps, phases = max(k, 1), modulo = max(-k, 1);
  double tr_bw, Fc, rho = phases == 1 ? .5 : att < 120 ? .63 : .75;
  Fp /= fabs(Fn), Fs /= fabs(Fn);
  tr_bw = .5 * (Fs - Fp);
  tr_bw /= phases, Fs /= phases;
  tr_bw = min(tr_bw, .5 * Fs);
  Fc = Fs - tr_bw;
  if (beta < 0) beta = lsx_kaiser_beta(att, tr_bw);
  if (!n) {
    n = lsx_lpf_num_taps(att, tr_bw, 0);
    n = n * phases;
    if (modulo > 1) n = n + (modulo - 1 - (n - 1) % modulo) % modulo;
    if (!(n & 1) && phases == 1) ++n;
  }
  *num_taps = n;
  if (Fn < 0) return 0;
  return lsx_make_lpf(n, Fc, beta, rho, (double)phases, sox_false);
}

