#define lsx_subsystem_name "rate"
#include "sox.h"
#include <ctype.h>

typedef enum { Quick, Low, Medium, High, Very } quality_t;

typedef struct {
  /* options */
  double out_rate, bw_0dB_pc, phase;
  quality_t quality;
  sox_bool allow_aliasing, steep;
  /* derived */
  double factor;          /* in_rate / out_rate */
  int L;                  /* phases */
  int tpp;                /* taps per phase */
  double *coefs;          /* [L+1][tpp] (extra phase for interpolation) */
  sox_bool interp_phases;
  /* state */
  double *hist;           /* history ring: tpp + extra */
  size_t hist_len;
  uint64_t in_count, out_count;
  double next_pos;        /* position (in input samples) of next output */
  sox_bool drained;
  uint64_t in_total;
  /* quick mode */
  double q[4];
} priv_t;

static int create(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *p = (priv_t *)effp->priv;
  int c;
  lsx_getopt_t optstate;
  char dummy;
  p->quality = High;
  p->phase = 50;
  p->bw_0dB_pc = 95;
  lsx_getopt_init(argc, argv, "+i:c:b:p:MILaqlmhvs", NULL, lsx_getopt_flag_none, 1, &optstate);
  while ((c = lsx_getopt_s(&optstate)) != -1) switch (c) {
    case 'q': p->quality = Quick; break;
    case 'l': p->quality = Low; break;
    case 'm': p->quality = Medium; break;
    case 'h': p->quality = High; break;
    case 'v': p->quality = Very; break;
    case 'M': p->phase = 0; break;
    case 'I': p->phase = 25; break;
    case 'L': p->phase = 50; break;
    case 's': p->steep = sox_true; break;
    case 'a': p->allow_aliasing = sox_true; break;
    case 'b':
      if (sscanf(optstate.arg, "%lf %c", &p->bw_0dB_pc, &dummy) != 1 || p->bw_0dB_pc < 74 || p->bw_0dB_pc > 99.7) {
        lsx_fail("parameter `-b' must be between 74 and 99.7"); return lsx_usage(effp);
      }
      break;
    case 'p':
      if (sscanf(optstate.arg, "%lf %c", &p->phase, &dummy) != 1 || p->phase < 0 || p->phase > 100) {
        lsx_fail("parameter `-p' must be between 0 and 100"); return lsx_usage(effp);
      }
      break;
    case 'i': case 'c': break;
    default: lsx_fail("invalid option `-%c'", optstate.curpos ? optstate.curpos[-1] : '?'); return lsx_usage(effp);
  }
  argc -= optstate.ind, argv += optstate.ind;
  if (argc) {
    char k = 0;
    int n = sscanf(*argv, "%lf %c %c", &p->out_rate, &k, &dummy);
    if (n < 1 || n > 2 || (n == 2 && k != 'k') || p->out_rate <= 0) return lsx_usage(effp);
    if (n == 2) p->out_rate *= 1000;
    --argc, ++argv;
  }
  if (argc) return lsx_usage(effp);
  if (p->steep) p->bw_0dB_pc = 99;
  effp->out_signal.rate = p->out_rate;
  return SOX_SUCCESS;
}

static unsigned gcd(unsigned a, unsigned b) { while (b) { unsigned t = a % b; a = b; b = t; } return a; }

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  double in_rate = effp->in_signal.rate, out_rate = p->out_rate ? p->out_rate : effp->out_signal.rate;
  double att, Fp, Fs;
  int n, L;
  unsigned iin, iout, g;
  if (!out_rate) out_rate = in_rate;
  effp->out_signal.rate = out_rate;
  if (in_rate == out_rate) return SOX_EFF_NULL;
  p->factor = in_rate / out_rate;
  p->in_count = p->out_count = 0;
  p->next_pos = 0;
  p->drained = sox_false;
  p->in_total = effp->in_signal.length != SOX_UNKNOWN_LEN ? effp->in_signal.length / effp->in_signal.channels : SOX_UNKNOWN_LEN;
  if (effp->in_signal.mult) *effp->in_signal.mult *= .705;
  if (p->quality == Quick) {
    p->L = 0; p->tpp = 4; p->coefs = NULL;
    p->hist_len = 8;
    p->hist = lsx_calloc(p->hist_len, sizeof(*p->hist));
    return SOX_SUCCESS;
  }
  switch (p->quality) {
    case Low: att = 100; break;
    case Medium: att = 100; break;
    case High: att = 22 * linear_to_dB(2.); break;
    default: att = 175; break;
  }
  if (p->quality == Low) p->bw_0dB_pc = 80;
  iin = (unsigned)(in_rate * 1000 + .5); iout = (unsigned)(out_rate * 1000 + .5);
  g = gcd(iin, iout);
  L = (int)(iout / g);
  if (L > 2048 || fabs(in_rate * 1000 - iin) > 1e-6 || fabs(out_rate * 1000 - iout) > 1e-6) { L = 1024; p->interp_phases = sox_true; }
  else p->interp_phases = sox_false;
  p->L = L;
  /* design prototype lowpass at rate L * in_rate; normalise to input Nyquist = 1 */
  if (p->factor > 1) { Fp = p->bw_0dB_pc / 100 / p->factor; Fs = p->allow_aliasing ? (2 - p->bw_0dB_pc / 100) / p->factor : 1 / p->factor; }
  else { Fp = p->bw_0dB_pc / 100; Fs = p->allow_aliasing ? 2 - p->bw_0dB_pc / 100 : 1; }
  if (Fs > 1) Fs = 1;
  n = 0;
  {
    double tr_bw = .5 * (Fs - Fp) / L, Fs1 = Fs / L, Fc;
    double beta;
    int i, m;
    tr_bw = min(tr_bw, .5 * Fs1);
    Fc = Fs1 - tr_bw;
    beta = lsx_kaiser_beta(att, tr_bw);
    n = lsx_lpf_num_taps(att, tr_bw, 1);
    n = (n + L - 1) / L * L;
    if (p->phase != 50) {
      double *h = lsx_make_lpf(n + 1, Fc, beta, .5, (double)L, sox_false);
      int post_len, len = n + 1;
      lsx_fir_to_phase(&h, &len, &post_len, p->phase);
      n = (len + L - 1) / L * L;
      p->coefs = lsx_calloc((size_t)(L + 1) * (n / L), sizeof(*p->coefs));
      m = n / L;
      for (i = 0; i < len; ++i) p->coefs[(i % L) * m + i / L] = h[i];
      free(h);
      p->tpp = m;
      for (i = 0; i < m; ++i) p->coefs[L * m + i] = p->coefs[i];
      /* shift for next-phase interpolation: phase L == phase 0 of next sample */
      lsx_debug("fir_len=%i Fp=%g Fs=%g att=%g phase=%g", len, Fp, Fs, att, p->phase);
    } else {
      double *h = lsx_make_lpf(n + 1, Fc, beta, .5, (double)L, sox_false);
      m = (n + 1 + L - 1) / L;
      p->coefs = lsx_calloc((size_t)(L + 1) * m, sizeof(*p->coefs));
      for (i = 0; i < n + 1; ++i) p->coefs[(i % L) * m + i / L] = h[i];
      free(h);
      p->tpp = m;
      n = n + 1;
      lsx_debug("fir_len=%i Fp=%g Fs=%g att=%g \u03b2=%g", n, Fp, Fs, att, beta);
    }
    /* phase L (for interpolation) = phase 0 shifted by one input sample */
    for (i = 0; i < p->tpp; ++i) p->coefs[L * p->tpp + i] = i + 1 < p->tpp ? p->coefs[i + 1] : 0;
  }
  p->hist_len = (size_t)p->tpp + 2;
  p->hist = lsx_calloc(p->hist_len * 2, sizeof(*p->hist));
  /* initial position: centre of the filter */
  p->next_pos = 0;
  if (effp->in_signal.length != SOX_UNKNOWN_LEN)
    effp->out_signal.length = (uint64_t)ceil(effp->in_signal.length / effp->in_signal.channels / p->factor - 1e-9) * effp->in_signal.channels;
  return SOX_SUCCESS;
}

/* history is a flat buffer holding the most recent samples; index 0 = oldest */
static void push_sample(priv_t *p, double d)
{
  memmove(p->hist, p->hist + 1, (p->hist_len - 1) * sizeof(*p->hist));
  p->hist[p->hist_len - 1] = d;
  p->in_count++;
}

/* compute output sample for position pos (in input sample index units, relative to total input consumed) */
static double interp_at(priv_t *p, double pos)
{
  /* The newest sample in hist is index in_count-1; hist[hist_len-1] */
  double ipos = floor(pos);
  double frac = pos - ipos;
  int64_t base = (int64_t)ipos;  /* input index of the sample at phase 0 */
  int j;
  double sum = 0;
  if (!p->L) {
    /* cubic (quick) */
    int64_t newest = (int64_t)p->in_count - 1;
    double y0, y1, y2, y3, a, b, c;
    int64_t off = newest - (base + 2);
    size_t idx = p->hist_len - 1 - (size_t)off;
    y3 = p->hist[idx]; y2 = p->hist[idx - 1]; y1 = p->hist[idx - 2]; y0 = p->hist[idx - 3];
    a = (3 * (y1 - y2) - y0 + y3) * .5;
    b = 2 * y2 + y0 - (5 * y1 + y3) * .5;
    c = (y2 - y0) * .5;
    return ((a * frac + b) * frac + c) * frac + y1;
  }
  {
    double ph = frac * p->L;
    int phase = (int)ph;
    double pfrac = ph - phase;
    const double *c0 = p->coefs + (size_t)phase * p->tpp, *c1 = c0 + p->tpp;
    int64_t newest = (int64_t)p->in_count - 1;
    /* taps: coef j applies to input sample base + half - j, where half = tpp/2 */
    int half = p->tpp / 2;
    for (j = 0; j < p->tpp; ++j) {
      int64_t si = base + half - j;
      int64_t off = newest - si;
      double x;
      if (off < 0 || off >= (int64_t)p->hist_len) x = 0;
      else x = p->hist[p->hist_len - 1 - (size_t)off];
      sum += x * (p->interp_phases ? c0[j] + (c1[j] - c0[j]) * pfrac : c0[j]);
    }
  }
  return sum;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t i = 0, o = 0;
  int half = p->L ? p->tpp / 2 : 2;
  while (i < *isamp && o < *osamp) {
    push_sample(p, (double)ibuf[i++]);
    /* produce all outputs whose required newest input is available */
    while (o < *osamp && (int64_t)floor(p->next_pos) + half + (p->L ? 0 : 1) <= (int64_t)p->in_count - 1) {
      double d = interp_at(p, p->next_pos);
      obuf[o++] = SOX_ROUND_CLIP_COUNT(d, effp->clips);
      p->out_count++;
      p->next_pos = p->out_count * p->factor;
    }
  }
  *isamp = i; *osamp = o;
  return SOX_SUCCESS;
}

static int drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t o = 0;
  uint64_t total_out;
  int half = p->L ? p->tpp / 2 : 2;
  if (!p->drained) { p->drained = sox_true; p->in_total = p->in_count; }
  total_out = (uint64_t)ceil(p->in_total / p->factor - 1e-9);
  while (o < *osamp && p->out_count < total_out) {
    while ((int64_t)floor(p->next_pos) + half + (p->L ? 0 : 1) > (int64_t)p->in_count - 1) push_sample(p, 0);
    {
      double d = interp_at(p, p->next_pos);
      obuf[o++] = SOX_ROUND_CLIP_COUNT(d, effp->clips);
      p->out_count++;
      p->next_pos = p->out_count * p->factor;
    }
  }
  *osamp = o;
  return p->out_count < total_out ? SOX_SUCCESS : SOX_EOF;
}

static int stop(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  free(p->coefs); free(p->hist);
  p->coefs = NULL; p->hist = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_rate_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "rate", "[-q|-l|-m|-h|-v] [override-options] RATE[k]\n                    BAND-\n     QUALITY        WIDTH  REJ dB   TYPICAL USE\n -q  quick          n/a  ~30 @ Fs/4 playback on ancient hardware\n -l  low            80%     100     playback on old hardware\n -m  medium         95%     100     audio playback\n -h  high (default) 95%     125     16-bit mastering (use with dither)\n -v  very high      95%     175     24-bit mastering\n              OVERRIDE OPTIONS (only with -m, -h, -v)\n -M/-I/-L     Phase response = minimum/intermediate/linear(default)\n -s           Steep filter (band-width = 99%)\n -a           Allow aliasing above the pass-band\n -b 74-99.7   Any band-width %\n -p 0-100     Any phase response (0 = minimum, 25 = intermediate,\n              50 = linear, 100 = maximum)",
    SOX_EFF_RATE, create, start, flow, drain, stop, NULL, sizeof(priv_t) };
  return &handler;
}

/* ---------- speed ---------- */
typedef struct { double factor; } speed_priv_t;

static int speed_create(sox_effect_t *effp, int argc, char **argv)
{
  speed_priv_t *p = (speed_priv_t *)effp->priv;
  sox_bool is_cents = sox_false;
  --argc, ++argv;
  if (argc == 1) {
    char c, dummy;
    int scanned = sscanf(*argv, "%lf%c %c", &p->factor, &c, &dummy);
    if (scanned == 1 || (scanned == 2 && c == 'c')) {
      is_cents |= scanned == 2;
      if (is_cents || p->factor > 0) {
        p->factor = is_cents ? pow(2., p->factor / 1200) : p->factor;
        return SOX_SUCCESS;
      }
    }
  }
  return lsx_usage(effp);
}

static int speed_start(sox_effect_t *effp)
{
  speed_priv_t *p = (speed_priv_t *)effp->priv;
  if (p->factor == 1) return SOX_EFF_NULL;
  effp->out_signal.rate = effp->in_signal.rate * p->factor;
  effp->out_signal.length = effp->in_signal.length;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_speed_effect_fn(void)
{
  static sox_effect_handler_t handler = { "speed", "factor[c]", SOX_EFF_RATE | SOX_EFF_LENGTH, speed_create, speed_start, lsx_flow_copy, NULL, NULL, NULL, sizeof(speed_priv_t) };
  return &handler;
}

/* ---------- upsample / downsample ---------- */
typedef struct { unsigned factor; unsigned pos; } ud_priv_t;

static int ud_create(sox_effect_t *effp, int argc, char **argv)
{
  ud_priv_t *p = (ud_priv_t *)effp->priv;
  char dummy;
  --argc, ++argv;
  p->factor = 2;
  if (argc) {
    if (sscanf(*argv, "%u %c", &p->factor, &dummy) != 1 || p->factor < 1) return lsx_usage(effp);
    --argc, ++argv;
  }
  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int up_start(sox_effect_t *effp)
{
  ud_priv_t *p = (ud_priv_t *)effp->priv;
  if (p->factor == 1) return SOX_EFF_NULL;
  effp->out_signal.rate = effp->in_signal.rate * p->factor;
  return SOX_SUCCESS;
}

static int up_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  ud_priv_t *p = (ud_priv_t *)effp->priv;
  size_t i, j, ilen = min(*isamp, *osamp / p->factor);
  for (i = 0; i < ilen; ++i) {
    *obuf++ = ibuf[i];
    for (j = 1; j < p->factor; ++j) *obuf++ = 0;
  }
  *isamp = ilen; *osamp = ilen * p->factor;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_upsample_effect_fn(void)
{
