  if (sum_in_volume * echo->in_gain > 1.0) lsx_warn("%s: warning >>> gain-out can cause saturation of output <<<", effp->handler.name);
  return SOX_SUCCESS;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *echo = (priv_t *)effp->priv;
  int j;
  double d_in, d_out;
  size_t len = min(*isamp, *osamp);
  *isamp = *osamp = len;
  while (len--) {
    d_in = (double)*ibuf++;
    d_out = d_in * echo->in_gain;
    if (!echo->sequential) {
      for (j = 0; j < echo->num_delays; j++)
        d_out += echo->delay_buf[(echo->counter + echo->maxsamples - echo->samples[j]) % echo->maxsamples] * echo->decay[j];
      d_out = d_out * echo->out_gain;
      *obuf++ = SOX_ROUND_CLIP_COUNT(d_out, effp->clips);
      echo->delay_buf[echo->counter] = d_in;
    } else {
      ptrdiff_t ms = echo->maxsamples;
      for (j = 0; j < echo->num_delays; j++)
        d_out += echo->delay_buf[j * ms + (echo->counter + ms - echo->samples[j]) % ms] * echo->decay[j];
      d_out = d_out * echo->out_gain;
      *obuf++ = SOX_ROUND_CLIP_COUNT(d_out, effp->clips);
      for (j = echo->num_delays - 1; j > 0; j--)
        echo->delay_buf[j * ms + echo->counter] = echo->delay_buf[(j - 1) * ms + (echo->counter + ms - echo->samples[j - 1]) % ms] * echo->decay[j - 1];
      echo->delay_buf[echo->counter] = d_in;
    }
    echo->counter = (int)((echo->counter + 1) % echo->maxsamples);
  }
  return SOX_SUCCESS;
}

static int drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  priv_t *echo = (priv_t *)effp->priv;
  double d_in, d_out;
  int j;
  size_t done = 0;
  while (done < *osamp && echo->fade_out) {
    d_in = 0;
    d_out = 0;
    if (!echo->sequential) {
      for (j = 0; j < echo->num_delays; j++)
        d_out += echo->delay_buf[(echo->counter + echo->maxsamples - echo->samples[j]) % echo->maxsamples] * echo->decay[j];
      d_out = d_out * echo->out_gain;
      *obuf++ = SOX_ROUND_CLIP_COUNT(d_out, effp->clips);
      echo->delay_buf[echo->counter] = d_in;
    } else {
      ptrdiff_t ms = echo->maxsamples;
      for (j = 0; j < echo->num_delays; j++)
        d_out += echo->delay_buf[j * ms + (echo->counter + ms - echo->samples[j]) % ms] * echo->decay[j];
      d_out = d_out * echo->out_gain;
      *obuf++ = SOX_ROUND_CLIP_COUNT(d_out, effp->clips);
      for (j = echo->num_delays - 1; j > 0; j--)
        echo->delay_buf[j * ms + echo->counter] = echo->delay_buf[(j - 1) * ms + (echo->counter + ms - echo->samples[j - 1]) % ms] * echo->decay[j - 1];
      echo->delay_buf[echo->counter] = d_in;
    }
    echo->counter = (int)((echo->counter + 1) % echo->maxsamples);
    done++;
    echo->fade_out--;
  }
  *osamp = done;
  return echo->fade_out ? SOX_SUCCESS : SOX_EOF;
}

static int stop(sox_effect_t *effp)
{
  priv_t *echo = (priv_t *)effp->priv;
  free(echo->delay_buf);
  echo->delay_buf = NULL;
  return SOX_SUCCESS;
}

