#define lsx_subsystem_name "echo"
#include "sox.h"

#define DELAY_BUFSIZ (50 * 50U * 1024)
#define MAX_ECHOS 7

typedef struct {
  int counter;
  int num_delays;
  double *delay_buf;
  float in_gain, out_gain;
  float delay[MAX_ECHOS], decay[MAX_ECHOS];
  ptrdiff_t samples[MAX_ECHOS], maxsamples;
  size_t fade_out;
  sox_bool sequential;
} priv_t;

static int echo_getopts(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *echo = (priv_t *)effp->priv;
  int i;
  echo->num_delays = 0;
  --argc, ++argv;
  if ((argc < 4) || (argc % 2)) return lsx_usage(effp);
  i = 0;
  sscanf(argv[i++], "%f", &echo->in_gain);
  sscanf(argv[i++], "%f", &echo->out_gain);
  while (i < argc) {
    if (echo->num_delays >= MAX_ECHOS) { lsx_fail("too many delays, use less than %i delays", MAX_ECHOS); return SOX_EOF; }
    sscanf(argv[i++], "%f", &echo->delay[echo->num_delays]);
    sscanf(argv[i++], "%f", &echo->decay[echo->num_delays]);
    echo->num_delays++;
  }
  echo->sequential = !strcmp(effp->handler.name, "echos");
  return SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *echo = (priv_t *)effp->priv;
  int i;
  float sum_in_volume;
  echo->maxsamples = 0;
  if (echo->in_gain < 0.0) { lsx_fail("gain-in must be positive!"); return SOX_EOF; }
  if (echo->in_gain > 1.0) { lsx_fail("gain-in must be less than 1.0!"); return SOX_EOF; }
  if (echo->out_gain < 0.0) { lsx_fail("gain-out must be positive!"); return SOX_EOF; }
  for (i = 0; i < echo->num_delays; i++) {
    echo->samples[i] = (ptrdiff_t)(echo->delay[i] * effp->in_signal.rate / 1000.0);
    if (echo->samples[i] < 1) { lsx_fail("delay must be positive!"); return SOX_EOF; }
    if (echo->samples[i] > (ptrdiff_t)DELAY_BUFSIZ) { lsx_fail("delay must be less than %g seconds!", DELAY_BUFSIZ / effp->in_signal.rate); return SOX_EOF; }
    if (echo->decay[i] < 0.0) { lsx_fail("decay must be positive!"); return SOX_EOF; }
    if (echo->decay[i] > 1.0) { lsx_fail("decay must be less than 1.0!"); return SOX_EOF; }
    if (echo->samples[i] > echo->maxsamples) echo->maxsamples = echo->samples[i];
  }
  if (echo->sequential) {
    echo->maxsamples = 0;
    for (i = 0; i < echo->num_delays; i++) echo->maxsamples += echo->samples[i];
    echo->delay_buf = lsx_calloc((size_t)echo->maxsamples * echo->num_delays + 1, sizeof(double));
  } else echo->delay_buf = lsx_calloc((size_t)echo->maxsamples, sizeof(double));
  echo->counter = 0;
  echo->fade_out = (size_t)echo->maxsamples;
  sum_in_volume = 1.0;
  for (i = 0; i < echo->num_delays; i++) sum_in_volume += echo->decay[i];
  if (sum_in_volume * echo->in_gain > 1.0) lsx_warn("%s: warning >>> gain-out can cause saturation of output <<<", effp->handler.name);
  return SOX_SUCCESS;
}

