  if (argc && (sscanf(*argv, "%lf %c", &enhancement, &dummy) != 1 || enhancement < 0 || enhancement > 100)) return lsx_usage(effp);
  p->contrast = enhancement / 750;
  return SOX_SUCCESS;
}

static int contrast_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  contrast_t *p = (contrast_t *)effp->priv;
  size_t len = *isamp = *osamp = min(*isamp, *osamp);
  SOX_SAMPLE_LOCALS;
  while (len--) {
    double d = SOX_SAMPLE_TO_FLOAT_64BIT(*ibuf++, effp->clips) * M_PI_2;
    *obuf++ = SOX_FLOAT_64BIT_TO_SAMPLE(sin(d + p->contrast * sin(d * 4)), effp->clips);
  }
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_contrast_effect_fn(void)
{
  static sox_effect_handler_t handler = { "contrast", "[enhancement (75)]", 0, contrast_getopts, NULL, contrast_flow, NULL, NULL, NULL, sizeof(contrast_t) };
  return &handler;
}

/* ---------------- overdrive ---------------- */
typedef struct { double gain, colour, last_in, last_out, b0, b1, a1; } overdrive_t;

static int overdrive_getopts(sox_effect_t *effp, int argc, char **argv)
{
  overdrive_t *p = (overdrive_t *)effp->priv;
  char dummy;
  p->gain = p->colour = 20;
  --argc, ++argv;
  if (argc > 2) return lsx_usage(effp);
  if (argc && (sscanf(argv[0], "%lf %c", &p->gain, &dummy) != 1 || p->gain < 0)) return lsx_usage(effp);
  if (argc > 1 && (sscanf(argv[1], "%lf %c", &p->colour, &dummy) != 1 || p->colour < 0)) return lsx_usage(effp);
  p->gain = dB_to_linear(p->gain);
  p->colour /= 200;
  return SOX_SUCCESS;
}

static int overdrive_start(sox_effect_t *effp)
{
  overdrive_t *p = (overdrive_t *)effp->priv;
  if (p->gain == 1) return SOX_EFF_NULL;
  p->last_in = p->last_out = 0;
  return SOX_SUCCESS;
}

static int overdrive_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  overdrive_t *p = (overdrive_t *)effp->priv;
  size_t len = *isamp = *osamp = min(*isamp, *osamp);
  SOX_SAMPLE_LOCALS;
  while (len--) {
    double d = SOX_SAMPLE_TO_FLOAT_64BIT(*ibuf++, effp->clips) * p->gain + p->colour;
    d = d < -1 ? -2. / 3 : d > 1 ? 2. / 3 : d - d * d * d * (1. / 3);
    p->last_out = d - p->last_in + .995 * p->last_out;
    p->last_in = d;
    *obuf++ = SOX_FLOAT_64BIT_TO_SAMPLE(p->last_out * .75, effp->clips);
  }
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_overdrive_effect_fn(void)
{
  static sox_effect_handler_t handler = { "overdrive", "[gain [colour]]", 0, overdrive_getopts, overdrive_start, overdrive_flow, NULL, NULL, NULL, sizeof(overdrive_t) };
  return &handler;
}

/* ---------------- earwax ---------------- */
#define EARWAX_NUMTAPS 64
static const sox_sample_t earwax_filt[EARWAX_NUMTAPS] = {
  4, -6, 4, -11, -1, -5, 3, 3, -2, 5, -5, 0, 9, 1, 6, 3, -4, -5, -5, -9, 9, 6, -1, -7, -6, -6, -11, -5, -3, -19, 3, -10,
  -1, -9, -1, -6, 1, -5, -3, 2, 4, -5, -1, -4, 4, 0, -7, 2, -2, -1, -3, 4, 4, 1, 4, 4, 2, 2, 1, -3, 1, 0, 2, 0 };
typedef struct { sox_sample_t tap[EARWAX_NUMTAPS]; } earwax_t;

static int earwax_start(sox_effect_t *effp)
{
  earwax_t *p = (earwax_t *)effp->priv;
  if (effp->in_signal.rate != 44100 || effp->in_signal.channels != 2) {
    lsx_fail("works only with stereo audio sampled at 44100Hz (i.e. CDDA)");
    return SOX_EOF;
  }
  memset(p->tap, 0, sizeof p->tap);
  return SOX_SUCCESS;
}

static int earwax_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  earwax_t *p = (earwax_t *)effp->priv;
  size_t i, len = *isamp = *osamp = min(*isamp, *osamp);
  while (len--) {
    double output = 0;
    for (i = EARWAX_NUMTAPS - 1; i; --i) {
      p->tap[i] = p->tap[i - 1];
      output += p->tap[i] * (double)earwax_filt[i];
    }
    p->tap[0] = *ibuf++ / 64;
    output += p->tap[0] * (double)earwax_filt[0];
    *obuf++ = SOX_ROUND_CLIP_COUNT(output, effp->clips);
  }
  return SOX_SUCCESS;
}

static int earwax_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  earwax_t *p = (earwax_t *)effp->priv;
  size_t i;
  for (i = 0; i < *osamp && i < EARWAX_NUMTAPS - 1; ++i) {
    size_t j;
    double output = 0;
    for (j = EARWAX_NUMTAPS - 1; j; --j) { p->tap[j] = p->tap[j - 1]; output += p->tap[j] * (double)earwax_filt[j]; }
    p->tap[0] = 0;
    *obuf++ = SOX_ROUND_CLIP_COUNT(output, effp->clips);
  }
  *osamp = i;
  return SOX_EOF;
}

const sox_effect_handler_t *lsx_earwax_effect_fn(void)
{
  static sox_effect_handler_t handler = { "earwax", NULL, SOX_EFF_MCHAN, NULL, earwax_start, earwax_flow, earwax_drain, NULL, NULL, sizeof(earwax_t) };
  return &handler;
}

