typedef struct { double last; } divide_t;
static int divide_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  divide_t *p = (divide_t *)effp->priv;
  size_t i, len = *isamp = *osamp = min(*isamp, *osamp) / effp->in_signal.channels * effp->in_signal.channels;
  for (i = 0; i < len; i += effp->in_signal.channels) {
    double divisor = ibuf[i];
    size_t j;
    if (divisor) {
      double out = p->last;
      obuf[i] = SOX_ROUND_CLIP_COUNT(out, effp->clips);
      for (j = 1; j < effp->in_signal.channels; ++j) {
        double d = ibuf[i + j] * SOX_SAMPLE_MAX / divisor;
        obuf[i + j] = SOX_ROUND_CLIP_COUNT(d, effp->clips);
      }
    } else for (j = 0; j < effp->in_signal.channels; ++j) obuf[i + j] = 0;
  }
  return SOX_SUCCESS;
}
