typedef enum { SOX_WAVE_SINE, SOX_WAVE_TRIANGLE } lsx_wave_t;
static const lsx_enum_item lsx_wave_enum[] = { LSX_ENUM_ITEM(SOX_WAVE_, SINE) LSX_ENUM_ITEM(SOX_WAVE_, TRIANGLE) {0, 0} };

static void generate_wave_table_f(lsx_wave_t wave_type, float *table, size_t table_size, double min, double max, double phase)
{
  uint32_t t;
  uint32_t phase_offset = (uint32_t)(phase / M_PI / 2 * table_size + 0.5);
  for (t = 0; t < table_size; t++) {
    uint32_t point = (t + phase_offset) % table_size;
    double d;
    switch (wave_type) {
      case SOX_WAVE_SINE: d = (sin((double)point / table_size * 2 * M_PI) + 1) / 2; break;
      case SOX_WAVE_TRIANGLE:
        d = (double)point * 2 / table_size;
        switch (4 * point / table_size) { case 0: d = d + 0.5; break; case 1: case 2: d = 1.5 - d; break; case 3: d = d - 1.5; break; }
        break;
      default: d = 0;
    }
    table[t] = (float)(d * (max - min) + min);
  }
}

static void generate_wave_table_i(lsx_wave_t wave_type, int *table, size_t table_size, double min, double max, double phase)
{
  uint32_t t;
  uint32_t phase_offset = (uint32_t)(phase / M_PI / 2 * table_size + 0.5);
  for (t = 0; t < table_size; t++) {
    uint32_t point = (t + phase_offset) % table_size;
    double d;
    switch (wave_type) {
      case SOX_WAVE_SINE: d = (sin((double)point / table_size * 2 * M_PI) + 1) / 2; break;
      case SOX_WAVE_TRIANGLE:
        d = (double)point * 2 / table_size;
        switch (4 * point / table_size) { case 0: d = d + 0.5; break; case 1: case 2: d = 1.5 - d; break; case 3: d = d - 1.5; break; }
        break;
      default: d = 0;
    }
    table[t] = (int)(d * (max - min) + min + 0.5);
  }
}

