/* ---------------- flanger ---------------- */
typedef enum { INTERP_LINEAR, INTERP_QUADRATIC } interp_t;
static const lsx_enum_item interp_enum[] = { LSX_ENUM_ITEM(INTERP_, LINEAR) LSX_ENUM_ITEM(INTERP_, QUADRATIC) {0, 0} };
#define MAX_CHANNELS 4

typedef struct {
  double delay_min, delay_depth, feedback_gain, delay_gain, speed, channel_phase;
  lsx_wave_t wave_shape;
  interp_t interpolation;
  double *delay_bufs[MAX_CHANNELS];
  size_t delay_buf_length, delay_buf_pos;
  double delay_last[MAX_CHANNELS];
  float *lfo;
  size_t lfo_length, lfo_pos;
  double in_gain;
} flanger_t;

static int flanger_getopts(sox_effect_t *effp, int argc, char **argv)
{
  flanger_t *p = (flanger_t *)effp->priv;
  --argc, ++argv;
  p->delay_min = 0; p->delay_depth = 2; p->feedback_gain = 0; p->delay_gain = 71; p->speed = .5;
  p->wave_shape = SOX_WAVE_SINE; p->channel_phase = 25; p->interpolation = INTERP_LINEAR;
  do {
    NUMERIC_PARAMETER(delay_min, 0, 30)
    NUMERIC_PARAMETER(delay_depth, 0, 10)
    NUMERIC_PARAMETER(feedback_gain, -95, 95)
    NUMERIC_PARAMETER(delay_gain, 0, 100)
    NUMERIC_PARAMETER(speed, 0.1, 10)
    TEXTUAL_PARAMETER(wave_shape, lsx_wave_enum)
    NUMERIC_PARAMETER(channel_phase, 0, 100)
    TEXTUAL_PARAMETER(interpolation, interp_enum)
  } while (0);
  if (argc != 0) return lsx_usage(effp);
  p->feedback_gain /= 100;
  p->delay_gain /= 100;
  p->channel_phase /= 100;
  p->delay_min /= 1000;
  p->delay_depth /= 1000;
  lsx_report("parameters:\n"
      "delay = %gms\ndepth = %gms\nregen = %g%%\nwidth = %g%%\nspeed = %gHz\nshape = %s\nphase = %g%%\ninterp= %s",
      p->delay_min * 1000, p->delay_depth * 1000, p->feedback_gain * 100, p->delay_gain * 100, p->speed,
      lsx_find_enum_value(p->wave_shape, lsx_wave_enum)->text, p->channel_phase * 100, lsx_find_enum_value(p->interpolation, interp_enum)->text);
  return SOX_SUCCESS;
}

static int flanger_start(sox_effect_t *effp)
{
  flanger_t *f = (flanger_t *)effp->priv;
  int c, channels = effp->in_signal.channels;
  if (channels > MAX_CHANNELS) { lsx_fail("Can not operate with more than %i channels", MAX_CHANNELS); return SOX_EOF; }
  f->in_gain = 1 / (1 + f->delay_gain);
  f->delay_gain /= 1 + f->delay_gain;
  f->delay_gain *= 1 - fabs(f->feedback_gain);
  lsx_debug("in_gain=%g feedback_gain=%g delay_gain=%g\n", f->in_gain, f->feedback_gain, f->delay_gain);
  f->delay_buf_length = (size_t)((f->delay_min + f->delay_depth) * effp->in_signal.rate + 0.5);
  ++f->delay_buf_length;
  ++f->delay_buf_length;
  for (c = 0; c < channels; ++c) f->delay_bufs[c] = lsx_calloc(f->delay_buf_length, sizeof(double));
  f->lfo_length = (size_t)(effp->in_signal.rate / f->speed);
  f->lfo = lsx_calloc(f->lfo_length, sizeof(float));
  generate_wave_table_f(f->wave_shape, f->lfo, f->lfo_length, floor(f->delay_min * effp->in_signal.rate + .5), f->delay_buf_length - 2., 3 * M_PI_2);
  lsx_debug("delay_buf_length=%lu lfo_length=%lu\n", (unsigned long)f->delay_buf_length, (unsigned long)f->lfo_length);
  f->delay_buf_pos = 0; f->lfo_pos = 0;
  memset(f->delay_last, 0, sizeof f->delay_last);
  return SOX_SUCCESS;
}

static int flanger_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  flanger_t *f = (flanger_t *)effp->priv;
  int c, channels = effp->in_signal.channels;
  size_t len = (*isamp > *osamp ? *osamp : *isamp) / channels;
  *isamp = *osamp = len * channels;
  while (len--) {
    f->delay_buf_pos = (f->delay_buf_pos + f->delay_buf_length - 1) % f->delay_buf_length;
    for (c = 0; c < channels; ++c) {
      double delayed_0, delayed_1, delayed, in, out;
      size_t channel_phase = (size_t)(c * f->lfo_length * f->channel_phase + .5);
      double delay = f->lfo[(f->lfo_pos + channel_phase) % f->lfo_length];
      double frac_delay = modf(delay, &delay);
      size_t int_delay = (size_t)delay;
      in = *ibuf++;
      f->delay_bufs[c][f->delay_buf_pos] = in + f->delay_last[c] * f->feedback_gain;
      delayed_0 = f->delay_bufs[c][(f->delay_buf_pos + int_delay++) % f->delay_buf_length];
      delayed_1 = f->delay_bufs[c][(f->delay_buf_pos + int_delay++) % f->delay_buf_length];
      if (f->interpolation == INTERP_LINEAR) delayed = delayed_0 + (delayed_1 - delayed_0) * frac_delay;
      else {
        double a, b;
        double delayed_2 = f->delay_bufs[c][(f->delay_buf_pos + int_delay++) % f->delay_buf_length];
        delayed_2 -= delayed_0;
        delayed_1 -= delayed_0;
        a = delayed_2 * .5 - delayed_1;
        b = delayed_1 * 2 - delayed_2 * .5;
        delayed = delayed_0 + (a * frac_delay + b) * frac_delay;
      }
      f->delay_last[c] = delayed;
      out = in * f->in_gain + delayed * f->delay_gain;
      *obuf++ = SOX_ROUND_CLIP_COUNT(out, effp->clips);
    }
    f->lfo_pos = (f->lfo_pos + 1) % f->lfo_length;
  }
  return SOX_SUCCESS;
}

static int flanger_stop(sox_effect_t *effp)
{
  flanger_t *f = (flanger_t *)effp->priv;
  int c;
  for (c = 0; c < (int)effp->in_signal.channels && c < MAX_CHANNELS; ++c) { free(f->delay_bufs[c]); f->delay_bufs[c] = NULL; }
  free(f->lfo); f->lfo = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_flanger_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "flanger", "[delay depth regen width speed shape phase interp]\n                  .\n                 /|regen\n                / |\n            +--(  |------------+\n            |   \\ |            |   .\n           _V_   \\|  _______   |   |\\ width   ___\n          |   |   ' |       |  |   | \\       |   |\n      +-->| + |---->| DELAY |--+-->|  )----->|   |\n      |   |___|     |_______|      | /       |   |\n      |           delay : depth    |/        |   |\n  In  |                 : interp   '         |   | Out\n  --->+               __:__                  | + |--->\n      |              |     |speed            |   |\n      |              |  ~  |shape            |   |\n      |              |_____|phase            |   |\n      +------------------------------------->|   |\n                                             |___|\n       RANGE DEFAULT DESCRIPTION\ndelay   0 30    0    base delay in milliseconds\ndepth   0 10    2    added swept delay in milliseconds\nregen -95 +95   0    percentage regeneration (delayed signal feedback)\nwidth   0 100   71   percentage of delayed signal mixed with original\nspeed  0.1 10  0.5   sweeps per second (Hz) \nshape    --    sin   swept wave shape: sine|triangle\nphase   0 100   25   swept wave percentage phase-shift for multi-channel\n                     (e.g. stereo) flange; 0 = 100 = same phase on each channel\ninterp   --    lin   delay-line interpolation: linear|quadratic",
    SOX_EFF_MCHAN, flanger_getopts, flanger_start, flanger_flow, NULL, flanger_stop, NULL, sizeof(flanger_t) };
  return &handler;
