/* ---------------- phaser ---------------- */
typedef struct {
  double in_gain, out_gain, delay_ms, decay, mod_speed;
  lsx_wave_t mod_type;
  int *mod_buf;
  size_t mod_buf_len;
  int mod_pos;
  double *delay_buf;
  size_t delay_buf_len;
  int delay_pos;
} phaser_t;

static int phaser_getopts(sox_effect_t *effp, int argc, char **argv)
{
  phaser_t *p = (phaser_t *)effp->priv;
  --argc, ++argv;
  p->mod_type = SOX_WAVE_SINE;
  if (argc < 5 || argc > 6) return lsx_usage(effp);
  do {
    NUMERIC_PARAMETER(in_gain, .0, 1)
    NUMERIC_PARAMETER(out_gain, .0, 1e9)
    NUMERIC_PARAMETER(delay_ms, .0, 5)
    NUMERIC_PARAMETER(decay, .0, .99)
    NUMERIC_PARAMETER(mod_speed, .1, 2)
    if (argc) {
      if (!strcmp(*argv, "-s")) p->mod_type = SOX_WAVE_SINE;
      else if (!strcmp(*argv, "-t")) p->mod_type = SOX_WAVE_TRIANGLE;
      else return lsx_usage(effp);
      --argc, ++argv;
    }
  } while (0);
  if (argc) return lsx_usage(effp);
  if (p->in_gain > (1 - p->decay * p->decay)) lsx_warn("warning: gain-in can cause saturation or clipping of output");
  if (p->in_gain / (1 - p->decay) > 1 / p->out_gain) lsx_warn("warning: gain-out can cause saturation or clipping of output");
  return SOX_SUCCESS;
}

static int phaser_start(sox_effect_t *effp)
{
  phaser_t *p = (phaser_t *)effp->priv;
  p->delay_buf_len = (size_t)(p->delay_ms * .001 * effp->in_signal.rate + .5);
  p->delay_buf = lsx_calloc(p->delay_buf_len ? p->delay_buf_len : 1, sizeof(*p->delay_buf));
  p->mod_buf_len = (size_t)(effp->in_signal.rate / p->mod_speed + .5);
  p->mod_buf = lsx_malloc(p->mod_buf_len * sizeof(*p->mod_buf));
  generate_wave_table_i(p->mod_type, p->mod_buf, p->mod_buf_len, 1., (double)p->delay_buf_len, M_PI / 2);
  p->delay_pos = p->mod_pos = 0;
  return SOX_SUCCESS;
}

static int phaser_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  phaser_t *p = (phaser_t *)effp->priv;
  size_t len = *isamp = *osamp = min(*isamp, *osamp);
  for (; len; --len) {
    double d = *ibuf++ * p->in_gain + (p->delay_buf_len ? p->delay_buf[(p->delay_pos + p->mod_buf[p->mod_pos]) % p->delay_buf_len] * p->decay : 0);
    p->mod_pos = (int)((p->mod_pos + 1) % p->mod_buf_len);
    if (p->delay_buf_len) { p->delay_pos = (int)((p->delay_pos + 1) % p->delay_buf_len); p->delay_buf[p->delay_pos] = d; }
    *obuf++ = SOX_ROUND_CLIP_COUNT(d * p->out_gain, effp->clips);
  }
  return SOX_SUCCESS;
}

static int phaser_stop(sox_effect_t *effp)
{
  phaser_t *p = (phaser_t *)effp->priv;
  free(p->delay_buf); free(p->mod_buf);
  p->delay_buf = NULL; p->mod_buf = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_phaser_effect_fn(void)
{
  static sox_effect_handler_t handler = { "phaser", "gain-in gain-out delay decay speed [ -s | -t ]", 0, phaser_getopts, phaser_start, phaser_flow, NULL, phaser_stop, NULL, sizeof(phaser_t) };
  return &handler;
}

/* ---------------- chorus ---------------- */
#define MOD_SINE 0
#define MOD_TRIANGLE 1
#define MAX_CHORUS 7
typedef struct {
  int num_chorus;
  int modulation[MAX_CHORUS];
  int counter;
  long phase[MAX_CHORUS];
  float *chorusbuf;
  float in_gain, out_gain;
  float delay[MAX_CHORUS], decay[MAX_CHORUS];
  float speed[MAX_CHORUS], depth[MAX_CHORUS];
  long length[MAX_CHORUS];
  int *lookup_tab[MAX_CHORUS];
  int depth_samples[MAX_CHORUS], samples[MAX_CHORUS];
  int maxsamples;
  unsigned fade_out;
} chorus_t;

static int chorus_getopts(sox_effect_t *effp, int argc, char **argv)
{
  chorus_t *chorus = (chorus_t *)effp->priv;
  int i;
  --argc, ++argv;
  chorus->num_chorus = 0;
  i = 0;
  if ((argc < 6) || ((argc + 1) % 5)) return lsx_usage(effp);
  sscanf(argv[i++], "%f", &chorus->in_gain);
  sscanf(argv[i++], "%f", &chorus->out_gain);
  while (i < argc) {
    if (chorus->num_chorus >= MAX_CHORUS) { lsx_fail("too many delays, use less than %i delays", MAX_CHORUS); return SOX_EOF; }
    sscanf(argv[i++], "%f", &chorus->delay[chorus->num_chorus]);
    sscanf(argv[i++], "%f", &chorus->decay[chorus->num_chorus]);
    sscanf(argv[i++], "%f", &chorus->speed[chorus->num_chorus]);
    sscanf(argv[i++], "%f", &chorus->depth[chorus->num_chorus]);
    if (!strcmp(argv[i], "-s")) chorus->modulation[chorus->num_chorus] = MOD_SINE;
    else if (!strcmp(argv[i], "-t")) chorus->modulation[chorus->num_chorus] = MOD_TRIANGLE;
    else return lsx_usage(effp);
    i++;
    chorus->num_chorus++;
  }
  return SOX_SUCCESS;
}

static int chorus_start(sox_effect_t *effp)
{
  chorus_t *chorus = (chorus_t *)effp->priv;
  int i;
  float sum_in_volume;
  chorus->maxsamples = 0;
  if (chorus->in_gain < 0.0) { lsx_fail("gain-in must be positive!"); return SOX_EOF; }
  if (chorus->in_gain > 1.0) { lsx_fail("gain-in must be less than 1.0!"); return SOX_EOF; }
  if (chorus->out_gain < 0.0) { lsx_fail("gain-out must be positive!"); return SOX_EOF; }
  for (i = 0; i < chorus->num_chorus; i++) {
    chorus->samples[i] = (int)((chorus->delay[i] + chorus->depth[i]) * effp->in_signal.rate / 1000.0);
    chorus->depth_samples[i] = (int)(chorus->depth[i] * effp->in_signal.rate / 1000.0);
    if (chorus->delay[i] < 20.0) { lsx_fail("delay must be more than 20.0 msec!"); return SOX_EOF; }
    if (chorus->delay[i] > 100.0) { lsx_fail("delay must be less than 100.0 msec!"); return SOX_EOF; }
    if (chorus->speed[i] < 0.1) { lsx_fail("speed must be more than 0.1 Hz!"); return SOX_EOF; }
    if (chorus->speed[i] > 5.0) { lsx_fail("speed must be less than 5.0 Hz!"); return SOX_EOF; }
    if (chorus->depth[i] < 0.0) { lsx_fail("delay must be positive!"); return SOX_EOF; }
    if (chorus->depth[i] > 10.0) { lsx_fail("delay must be less than 10.0 msec!"); return SOX_EOF; }
    if (chorus->decay[i] < 0.0) { lsx_fail("decay must be positive!"); return SOX_EOF; }
    if (chorus->decay[i] > 1.0) { lsx_fail("decay must be less that 1.0!"); return SOX_EOF; }
    chorus->length[i] = (long)(effp->in_signal.rate / chorus->speed[i]);
    chorus->lookup_tab[i] = lsx_malloc(sizeof(int) * chorus->length[i]);
    if (chorus->modulation[i] == MOD_SINE)
      generate_wave_table_i(SOX_WAVE_SINE, chorus->lookup_tab[i], (size_t)chorus->length[i], 0., (double)chorus->depth_samples[i], 0.);
    else
      generate_wave_table_i(SOX_WAVE_TRIANGLE, chorus->lookup_tab[i], (size_t)chorus->length[i],
          (double)(chorus->samples[i] - 1 - 2 * chorus->depth_samples[i]), (double)(chorus->samples[i] - 1), 3 * M_PI_2);
    chorus->phase[i] = 0;
    if (chorus->samples[i] > chorus->maxsamples) chorus->maxsamples = chorus->samples[i];
  }
  chorus->chorusbuf = lsx_calloc((size_t)chorus->maxsamples, sizeof(float));
  chorus->counter = 0;
  chorus->fade_out = (unsigned)chorus->maxsamples;
  sum_in_volume = 1.0;
  for (i = 0; i < chorus->num_chorus; i++) sum_in_volume += chorus->decay[i];
  if (chorus->in_gain * (sum_in_volume) > 1.0) lsx_warn("chorus: warning >>> gain-out can cause saturation of output <<<");
  return SOX_SUCCESS;
}

static int chorus_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  chorus_t *chorus = (chorus_t *)effp->priv;
  int i;
  float d_in, d_out;
  sox_sample_t out;
  size_t len = min(*isamp, *osamp);
  *isamp = *osamp = len;
  while (len--) {
    d_in = (float)*ibuf++;
    d_out = d_in * chorus->in_gain;
    for (i = 0; i < chorus->num_chorus; i++) {
      d_out += chorus->chorusbuf[(chorus->counter + chorus->maxsamples - chorus->lookup_tab[i][chorus->phase[i]]) % chorus->maxsamples] * chorus->decay[i];
      chorus->phase[i] = (chorus->phase[i] + 1) % chorus->length[i];
    }
    d_out = d_out * chorus->out_gain;
    out = SOX_ROUND_CLIP_COUNT(d_out, effp->clips);
    *obuf++ = out;
    chorus->chorusbuf[chorus->counter] = d_in;
    chorus->counter = (chorus->counter + 1) % chorus->maxsamples;
  }
  return SOX_SUCCESS;
}

static int chorus_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  chorus_t *chorus = (chorus_t *)effp->priv;
  size_t done = 0;
  int i;
  float d_in, d_out;
  sox_sample_t out;
  while (done < *osamp && chorus->fade_out) {
    d_in = 0;
    d_out = 0;
    for (i = 0; i < chorus->num_chorus; i++) {
      d_out += chorus->chorusbuf[(chorus->counter + chorus->maxsamples - chorus->lookup_tab[i][chorus->phase[i]]) % chorus->maxsamples] * chorus->decay[i];
      chorus->phase[i] = (chorus->phase[i] + 1) % chorus->length[i];
    }
    d_out = d_out * chorus->out_gain;
    out = SOX_ROUND_CLIP_COUNT(d_out, effp->clips);
    *obuf++ = out;
    chorus->chorusbuf[chorus->counter] = d_in;
    chorus->counter = (chorus->counter + 1) % chorus->maxsamples;
    done++;
    chorus->fade_out--;
  }
  *osamp = done;
  return chorus->fade_out ? SOX_SUCCESS : SOX_EOF;
}

static int chorus_stop(sox_effect_t *effp)
{
  chorus_t *chorus = (chorus_t *)effp->priv;
  int i;
  free(chorus->chorusbuf); chorus->chorusbuf = NULL;
  for (i = 0; i < chorus->num_chorus; i++) { free(chorus->lookup_tab[i]); chorus->lookup_tab[i] = NULL; }
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_chorus_effect_fn(void)
{
  static sox_effect_handler_t handler = { "chorus", "gain-in gain-out delay decay speed depth [ -s | -t ]", 0, chorus_getopts, chorus_start, chorus_flow, chorus_drain, chorus_stop, NULL, sizeof(chorus_t) };
  return &handler;
}
