cat > compandt.c <<'EOF'
#define lsx_subsystem_name "compandt"
#include "compandt.h"

static sox_bool parse_transfer_value(const char *text, double *value)
{
  char dummy;
  if (!strcmp(text, "-inf")) *value = -HUGE_VAL;
  else if (sscanf(text, "%lf %c", value, &dummy) != 1) {
    lsx_fail("syntax error trying to read transfer function value");
    return sox_false;
  }
  if (*value > 0) {
    lsx_fail("transfer function values are relative to maximum volume so can't exceed 0dB");
    return sox_false;
  }
  return sox_true;
}

#define line1 t->segments[i - 4]
#define curve t->segments[i - 3]
#define line2 t->segments[i - 2]
#define line3 t->segments[i]

static void prepare_transfer_fn(sox_compandt_t *t)
{
  unsigned i;
  double radius = t->curve_dB * M_LN10 / 20;
  for (i = 0; !i || t->segments[i - 2].x; i += 2) {
    t->segments[i].y += t->outgain_dB;
    t->segments[i].x *= M_LN10 / 20;
    t->segments[i].y *= M_LN10 / 20;
  }
  for (i = 4; !i || t->segments[i - 2].x; i += 2) {
    double x, y, cx, cy, in1, in2, out1, out2, theta, len, r;
    line1.a = 0;
    line1.b = (line2.y - line1.y) / (line2.x - line1.x);
    line2.a = 0;
    line2.b = (line3.y - line2.y) / (line3.x - line2.x);
    theta = atan2(line2.y - line1.y, line2.x - line1.x);
    len = sqrt(pow(line2.x - line1.x, 2.) + pow(line2.y - line1.y, 2.));
    r = min(radius, len);
    curve.x = line2.x - r * cos(theta);
    curve.y = line2.y - r * sin(theta);
    theta = atan2(line3.y - line2.y, line3.x - line2.x);
    len = sqrt(pow(line3.x - line2.x, 2.) + pow(line3.y - line2.y, 2.));
    r = min(radius, len / 2);
    x = line2.x + r * cos(theta);
    y = line2.y + r * sin(theta);
    cx = (curve.x + line2.x + x) / 3;
    cy = (curve.y + line2.y + y) / 3;
    line2.x = x;
    line2.y = y;
    in1 = cx - curve.x;
    out1 = cy - curve.y;
    in2 = line2.x - curve.x;
    out2 = line2.y - curve.y;
    curve.a = (out2 / in2 - out1 / in1) / (in2 - in1);
    curve.b = out1 / in1 - curve.a * in1;
  }
  line1.a = 0;
  line1.b = (line2.y - line1.y) / (line2.x - line1.x);
  t->in_min_lin = exp(t->segments[1].x);
  t->out_min_lin = exp(t->segments[1].y);
}
#undef line1
#undef curve
#undef line2
#undef line3

sox_bool lsx_compandt_parse(sox_compandt_t *t, char *points, char *gain)
{
  const char *text = points;
  unsigned i, j, num_points, pairs, commas = 0;
  char dummy;
  double *vals;

  if (sscanf(points, "%lf %c", &t->curve_dB, &dummy) == 2 && dummy == ':') points = strchr(points, ':') + 1;
  else t->curve_dB = 0;
  t->curve_dB = max(t->curve_dB, .01);
  text = points;
  while (*text) commas += *text++ == ',';
  num_points = commas + 1;
  vals = lsx_calloc(num_points + 2, sizeof(double));
  for (i = 0, text = strtok(points, ","); text != NULL; ++i, text = strtok(NULL, ",")) {
    if (!parse_transfer_value(text, &vals[i])) { free(vals); return sox_false; }
  }
  pairs = (num_points + 1) / 2;
  t->segments = lsx_calloc((pairs + 2) * 2, sizeof(*t->segments));
  j = 2;
  i = 0;
  if (num_points % 2) {
    t->segments[j].x = vals[0];
    t->segments[j].y = vals[0];
    j += 2;
    i = 1;
  }
  for (; i < num_points; i += 2, j += 2) {
    t->segments[j].x = vals[i];
    t->segments[j].y = vals[i + 1];
  }
  free(vals);
  for (i = 4; i < j; i += 2) {
    if (t->segments[i].x <= t->segments[i - 2].x) {
      lsx_fail("transfer function input values must be strictly increasing");
      return sox_false;
    }
  }
  if (t->segments[j - 2].x != 0) {
    t->segments[j].x = 0;
    t->segments[j].y = 0;
    j += 2;
  }
  /* Start point */
  t->segments[0].x = t->segments[2].x - 2 * t->curve_dB;
  t->segments[0].y = t->segments[2].y;
  t->num_segments = j;
  t->outgain_dB = 0;
  if (gain && sscanf(gain, "%lf %c", &t->outgain_dB, &dummy) != 1) {
    lsx_fail("syntax error trying to read gain value");
    return sox_false;
  }
  /* convert output levels to gains */
  for (i = 0; i < j; i += 2) t->segments[i].y -= t->segments[i].x;
  prepare_transfer_fn(t);
  return sox_true;
}

sox_bool lsx_compandt_show(sox_compandt_t *t, int plot)
{
  unsigned i;
  for (i = 0; t->segments[i].x; ++i)
    lsx_debug("TF: %g %g %g %g", t->segments[i].x, t->segments[i].y, t->segments[i].a, t->segments[i].b);
  if (plot == sox_plot_octave) {
    printf("%% GNU Octave file (may also work with MATLAB(R) )\n"
        "in=linspace(-99.5,0,200);\nout=[");
    for (i = -199; i <= 0; ++i) {
      double in = i / 2.;
      double in_lin = pow(10., in / 20);
      printf("%g ", in + 20 * log10(lsx_compandt(t, in_lin)));
    }
    printf("];\nplot(in,out)\ntitle('SoX effect: compand')\nxlabel('Input level (dB)')\nylabel('Output level (dB)')\ngrid on\ndisp('Hit return to continue')\npause\n");
    return sox_false;
  }
  if (plot == sox_plot_gnuplot) {
    printf("# gnuplot file\nset title 'SoX effect: compand'\nset xlabel 'Input level (dB)'\nset ylabel 'Output level (dB)'\nset grid xtics ytics\nset key off\nplot '-' with lines\n");
    for (i = -199; i <= 0; ++i) {
      double in = i / 2.;
      double in_lin = pow(10., in / 20);
      printf("%g %g\n", in, in + 20 * log10(lsx_compandt(t, in_lin)));
    }
    printf("e\npause -1 'Hit return to continue'\n");
    return sox_false;
  }
  return sox_true;
}

double lsx_compandt(sox_compandt_t *t, double in_lin)
{
  sox_compandt_segment_t *s;
  double in_log, out_log;
  if (in_lin <= t->in_min_lin) return t->out_min_lin;
  in_log = log(in_lin);
  for (s = t->segments + 1; in_log > s[1].x; ++s);
  in_log -= s->x;
  out_log = s->y + in_log * (s->a * in_log + s->b);
  return exp(out_log);
}

void lsx_compandt_kill(sox_compandt_t *t) { free(t->segments); t->segments = NULL; }
