#define lsx_subsystem_name "compand"
#include "compandt.h"

typedef struct {
  sox_compandt_t transfer_fn;
  struct { double attack_times[2]; double volume; } *channels;
  unsigned expectedChannels;
  double delay;
  sox_sample_t *delay_buf;
  ptrdiff_t delay_buf_size, delay_buf_index, delay_buf_cnt;
  int delay_buf_full;
  char *arg0, *arg1, *arg2;
} priv_t;

static int getopts(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *l = (priv_t *)effp->priv;
  char *s;
  char dummy;
  unsigned pairs, i, j, commas;
  --argc, ++argv;
  if (argc < 2 || argc > 5) return lsx_usage(effp);
  l->arg0 = lsx_strdup(argv[0]);
  l->arg1 = lsx_strdup(argv[1]);
  l->arg2 = argc > 2 ? lsx_strdup(argv[2]) : NULL;
  for (s = l->arg0, commas = 0; *s; ++s) if (*s == ',') ++commas;
  if ((commas % 2) == 0) { lsx_fail("there must be an even number of attack/decay parameters"); return SOX_EOF; }
  pairs = 1 + commas / 2;
  l->channels = lsx_calloc(pairs, sizeof(*l->channels));
  l->expectedChannels = pairs;
  for (i = 0, s = strtok(l->arg0, ","); s != NULL; ++i) {
    for (j = 0; j < 2; ++j) {
      if (sscanf(s, "%lf %c", &l->channels[i].attack_times[j], &dummy) != 1) { lsx_fail("syntax error trying to read attack/decay time"); return SOX_EOF; }
      else if (l->channels[i].attack_times[j] < 0) { lsx_fail("attack & decay times can't be less than 0 seconds"); return SOX_EOF; }
      s = strtok(NULL, ",");
    }
  }
  if (!lsx_compandt_parse(&l->transfer_fn, l->arg1, l->arg2)) return SOX_EOF;
  for (i = 0; i < l->expectedChannels; ++i) {
    double init_vol = 1.0;
    if (argc > 3) {
      if (sscanf(argv[3], "%lf %c", &init_vol, &dummy) != 1) { lsx_fail("syntax error trying to read initial volume"); return SOX_EOF; }
      init_vol = pow(10., init_vol / 20);
    }
    l->channels[i].volume = init_vol;
  }
  if (argc > 4 && sscanf(argv[4], "%lf %c", &l->delay, &dummy) != 1) { lsx_fail("syntax error trying to read delay value"); return SOX_EOF; }
  return SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *l = (priv_t *)effp->priv;
  unsigned i, j;
  lsx_debug("%i input channel(s) expected: actually %i", l->expectedChannels, effp->in_signal.channels);
  for (i = 0; i < l->expectedChannels; ++i) lsx_debug("Channel %i: attack = %g decay = %g", i, l->channels[i].attack_times[0], l->channels[i].attack_times[1]);
  if (!lsx_compandt_show(&l->transfer_fn, sox_effects_globals_s.plot)) return SOX_EOF;
  for (i = 0; i < l->expectedChannels; ++i)
    for (j = 0; j < 2; ++j)
      if (l->channels[i].attack_times[j] > 1.0 / effp->in_signal.rate)
        l->channels[i].attack_times[j] = 1.0 - exp(-1.0 / (effp->in_signal.rate * l->channels[i].attack_times[j]));
      else l->channels[i].attack_times[j] = 1.0;
  l->delay_buf_size = (ptrdiff_t)(l->delay * effp->in_signal.rate * effp->in_signal.channels);
  if (l->delay_buf_size > 0) l->delay_buf = lsx_calloc((size_t)l->delay_buf_size, sizeof(*l->delay_buf));
  l->delay_buf_index = 0;
  l->delay_buf_cnt = 0;
  l->delay_buf_full = 0;
  return SOX_SUCCESS;
}

static void doVolume(double *v, double samp, priv_t *l, int chan)
{
  double s = -samp / SOX_SAMPLE_MIN;
  double delta = s - *v;
  if (delta > 0.0) *v += delta * l->channels[chan].attack_times[0];
  else *v += delta * l->channels[chan].attack_times[1];
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *l = (priv_t *)effp->priv;
  int len = (int)((*isamp > *osamp) ? *osamp : *isamp);
  int filechans = effp->out_signal.channels;
  int idone, odone;
  len -= len % filechans;
  for (idone = 0, odone = 0; idone < len; ibuf += filechans) {
    int chan;
    for (chan = 0; chan < filechans; ++chan) {
      if (l->expectedChannels == 1 && filechans > 1) {
        int i;
        double maxsamp = 0.0;
        for (i = 0; i < filechans; ++i) {
          double rect = fabs((double)ibuf[i]);
          if (rect > maxsamp) maxsamp = rect;
        }
        doVolume(&l->channels[0].volume, maxsamp, l, 0);
        break;
      } else doVolume(&l->channels[chan].volume, fabs((double)ibuf[chan]), l, chan);
    }
    for (chan = 0; chan < filechans; ++chan) {
      int ch = l->expectedChannels > 1 ? chan : 0;
      double level_in_lin = l->channels[ch].volume;
      double level_out_lin = lsx_compandt(&l->transfer_fn, level_in_lin);
      double checkbuf;
      if (l->delay_buf_size <= 0) {
        checkbuf = ibuf[chan] * level_out_lin;
        SOX_SAMPLE_CLIP_COUNT(checkbuf, effp->clips);
        obuf[odone++] = (sox_sample_t)checkbuf;
        idone++;
      } else {
        if (l->delay_buf_cnt >= l->delay_buf_size) {
          l->delay_buf_full = 1;
          checkbuf = l->delay_buf[l->delay_buf_index] * level_out_lin;
          SOX_SAMPLE_CLIP_COUNT(checkbuf, effp->clips);
          obuf[odone] = (sox_sample_t)checkbuf;
          odone++;
          idone++;
        } else {
          l->delay_buf_cnt++;
          idone++;
        }
        l->delay_buf[l->delay_buf_index++] = ibuf[chan];
        l->delay_buf_index %= l->delay_buf_size;
      }
    }
  }
  *isamp = idone; *osamp = odone;
  return SOX_SUCCESS;
}

static int drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  priv_t *l = (priv_t *)effp->priv;
  size_t chan, done = 0;
  if (l->delay_buf_full == 0) l->delay_buf_index = 0;
  while (done < *osamp && l->delay_buf_cnt > 0)
    for (chan = 0; chan < effp->out_signal.channels && done < *osamp && l->delay_buf_cnt > 0; ++chan) {
      int c = l->expectedChannels > 1 ? (int)chan : 0;
      double level_in_lin = l->channels[c].volume;
      double level_out_lin = lsx_compandt(&l->transfer_fn, level_in_lin);
      double d = l->delay_buf[l->delay_buf_index++] * level_out_lin;
      SOX_SAMPLE_CLIP_COUNT(d, effp->clips);
      obuf[done++] = (sox_sample_t)d;
      l->delay_buf_index %= l->delay_buf_size;
      l->delay_buf_cnt--;
    }
  *osamp = done;
  return l->delay_buf_cnt > 0 ? SOX_SUCCESS : SOX_EOF;
}

static int stop(sox_effect_t *effp)
{
  priv_t *l = (priv_t *)effp->priv;
  free(l->delay_buf); l->delay_buf = NULL;
  return SOX_SUCCESS;
}

static int lsx_kill(sox_effect_t *effp)
{
  priv_t *l = (priv_t *)effp->priv;
  lsx_compandt_kill(&l->transfer_fn);
  free(l->channels); free(l->arg0); free(l->arg1); free(l->arg2);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_compand_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "compand", "attack1,decay1{,attack2,decay2} [soft-knee-dB:]in-dB1[,out-dB1]{,in-dB2,out-dB2} [gain [initial-volume-dB [delay]]]\n\twhere {} means optional and repeatable and [] means optional.\n\tdB values are floating point or -inf'; times are in seconds.",
    SOX_EFF_MCHAN, getopts, start, flow, drain, stop, lsx_kill, sizeof(priv_t) };
  return &handler;
}
