  size_t stop_found_periods;
  double *window, *window_current, *window_end;
  size_t window_size;
  double rms_sum;
  char leave_silence;
  char mode;
} priv_t;

static void clear_rms(sox_effect_t *effp)
{
  priv_t *silence = (priv_t *)effp->priv;
  memset(silence->window, 0, silence->window_size * sizeof(double));
  silence->window_current = silence->window;
  silence->window_end = silence->window + silence->window_size;
  silence->rms_sum = 0;
}

static int getopts(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *silence = (priv_t *)effp->priv;
  int parse_count;
  uint64_t temp;
  const char *n;
  --argc, ++argv;
  silence->start_periods = 0; silence->stop_periods = 0; silence->leave_silence = sox_false;
  if (argc < 1) return lsx_usage(effp);
  if (!strcmp(argv[0], "-l")) { silence->leave_silence = sox_true; argc--; argv++; if (argc < 1) return lsx_usage(effp); }
  silence->start_periods = (char)atoi(argv[0]);
  if (silence->start_periods < 0) { lsx_fail("Periods must not be negative"); return SOX_EOF; }
  argv++; argc--;
  if (silence->start_periods > 0) {
    if (argc < 2) return lsx_usage(effp);
    silence->start_duration_str = lsx_strdup(argv[0]);
    if ((n = lsx_parsesamples(0., silence->start_duration_str, &temp, 't')) == NULL || *n) return lsx_usage(effp);
    parse_count = sscanf(argv[1], "%lf%c", &silence->start_threshold, &silence->start_unit);
    if (parse_count < 1) return lsx_usage(effp);
    else if (parse_count < 2) silence->start_unit = '%';
    argv++; argv++; argc -= 2;
  }
  if (argc > 0) {
    silence->stop_periods = (char)atoi(argv[0]);
    if (silence->stop_periods < 0) { silence->stop_periods = (char)-silence->stop_periods; silence->restart = 1; }
    else silence->restart = 0;
    argv++; argc--;
    if (argc < 2) return lsx_usage(effp);
    silence->stop_duration_str = lsx_strdup(argv[0]);
    if ((n = lsx_parsesamples(0., silence->stop_duration_str, &temp, 't')) == NULL || *n) return lsx_usage(effp);
    parse_count = sscanf(argv[1], "%lf%c", &silence->stop_threshold, &silence->stop_unit);
    if (parse_count < 1) return lsx_usage(effp);
    else if (parse_count < 2) silence->stop_unit = '%';
    argv++; argv++; argc -= 2;
  }
  if (argc > 0) return lsx_usage(effp);
  if ((silence->start_unit != '%') && (silence->start_unit != 'd')) { lsx_fail("Invalid unit specified"); return lsx_usage(effp); }
  if ((silence->stop_unit != '%') && (silence->stop_unit != 'd')) { lsx_fail("Invalid unit specified"); return lsx_usage(effp); }
  return SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *silence = (priv_t *)effp->priv;
  uint64_t temp;
  if (silence->start_periods) {
    if (!lsx_parsesamples(effp->in_signal.rate, silence->start_duration_str, &temp, 't')) return lsx_usage(effp);
    silence->start_duration = (size_t)temp * effp->in_signal.channels;
  }
  if (silence->stop_periods) {
    if (!lsx_parsesamples(effp->in_signal.rate, silence->stop_duration_str, &temp, 't')) return lsx_usage(effp);
    silence->stop_duration = (size_t)temp * effp->in_signal.channels;
  }
  if (silence->start_periods) silence->mode = SILENCE_TRIM;
  else if (silence->stop_periods) silence->mode = SILENCE_COPY;
  else silence->mode = SILENCE_STOP; /* no-op? */
  if (!silence->start_periods && !silence->stop_periods) return SOX_EFF_NULL;
  silence->start_holdoff = lsx_malloc(sizeof(sox_sample_t) * (silence->start_duration ? silence->start_duration : 1));
  silence->start_holdoff_offset = 0; silence->start_holdoff_end = 0; silence->start_found_periods = 0;
  silence->stop_holdoff = lsx_malloc(sizeof(sox_sample_t) * (silence->stop_duration ? silence->stop_duration : 1));
  silence->stop_holdoff_offset = 0; silence->stop_holdoff_end = 0; silence->stop_found_periods = 0;
  silence->window_size = (size_t)(effp->in_signal.rate / 50) * effp->in_signal.channels;
  if (!silence->window_size) silence->window_size = effp->in_signal.channels;
  silence->window = lsx_malloc(silence->window_size * sizeof(double));
  clear_rms(effp);
  effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static sox_bool aboveThreshold(sox_effect_t *effp, sox_sample_t value, double threshold, int unit)
{
  double ratio;
  int rc;
  uint64_t dummy = 0;
  SOX_SAMPLE_LOCALS;
  (void)dummy;
  switch (effp->in_signal.precision) {
    case 8: value = SOX_SIGNED_8BIT_TO_SAMPLE(SOX_SAMPLE_TO_SIGNED_8BIT(value, dummy), dummy); break;
    case 16: value = SOX_SIGNED_16BIT_TO_SAMPLE(SOX_SAMPLE_TO_SIGNED_16BIT(value, dummy), dummy); break;
    case 24: value = SOX_SIGNED_24BIT_TO_SAMPLE(SOX_SAMPLE_TO_SIGNED_24BIT(value, dummy), dummy); break;
  }
  ratio = (double)fabs((double)value) / (double)SOX_SAMPLE_MAX;
  if (unit == '%') {
    ratio *= 100.0;
    rc = (ratio >= threshold);
  } else rc = (ratio >= pow(10.0, threshold / 20.0));
  return rc;
}

static sox_sample_t compute_rms(sox_effect_t *effp, sox_sample_t sample)
{
  priv_t *silence = (priv_t *)effp->priv;
  double new_sum;
  sox_sample_t rms;
  new_sum = silence->rms_sum;
  new_sum -= *silence->window_current;
