#define lsx_subsystem_name "dft_filter"
#include "dft_filter.h"

void lsx_fir_init(dft_filter_t *f, double *h, int num_taps, int post_peak)
{
  f->h = h;
  f->num_taps = num_taps;
  f->post_peak = post_peak;
  f->hist_len = (size_t)num_taps;
  f->hist = lsx_calloc(f->hist_len + 1, sizeof(double));
  f->in_count = f->out_count = 0;
  f->drained = sox_false;
}

/* hist holds the last num_taps inputs; hist[hist_len-1] is the newest */
static void push(dft_filter_t *f, double d)
{
  memmove(f->hist, f->hist + 1, (f->hist_len - 1) * sizeof(double));
  f->hist[f->hist_len - 1] = d;
  f->in_count++;
}

static double compute(dft_filter_t *f)
{
  /* output sample corresponds to input index in_count - 1 - post_peak; it needs inputs up to in_count-1 */
  int k;
  double sum = 0;
  const double *x = f->hist + f->hist_len - 1;   /* newest */
  for (k = 0; k < f->num_taps; ++k) sum += f->h[k] * x[-(f->num_taps - 1 - k)];
  return sum;
}

int lsx_fir_flow(sox_effect_t *effp, dft_filter_t *f, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  size_t i = 0, o = 0;
  while (i < *isamp && o < *osamp) {
    push(f, (double)ibuf[i++]);
    if (f->in_count > (uint64_t)f->post_peak) {
      obuf[o++] = SOX_ROUND_CLIP_COUNT(compute(f), effp->clips);
      f->out_count++;
    }
  }
  *isamp = i; *osamp = o;
  return SOX_SUCCESS;
}

int lsx_fir_drain(sox_effect_t *effp, dft_filter_t *f, sox_sample_t *obuf, size_t *osamp)
{
  size_t o = 0;
  uint64_t total = f->in_count;
  if (!f->drained) { f->drained = sox_true; f->in_count = f->in_count; }
  total = f->out_count + (uint64_t)f->post_peak < f->in_count ? f->in_count : f->out_count;
  /* total outputs should equal number of inputs */
  while (o < *osamp && f->out_count < f->in_count) {
    push(f, 0);
    f->in_count--; /* zero padding doesn't count */
    obuf[o++] = SOX_ROUND_CLIP_COUNT(compute(f), effp->clips);
    f->out_count++;
  }
  (void)total;
  *osamp = o;
  return f->out_count < f->in_count ? SOX_SUCCESS : SOX_EOF;
}

void lsx_fir_free(dft_filter_t *f)
{
  free(f->h); free(f->hist);
  f->h = NULL; f->hist = NULL;
}
