#define lsx_subsystem_name "fir"
#include "dft_filter.h"

typedef struct { dft_filter_t f; char const *filename; double *h; int n; } priv_t;

static int create(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *p = (priv_t *)effp->priv;
  double d;
  char c;
  --argc, ++argv;
  if (!argc) p->filename = "-";
  else if (argc == 1 && sscanf(*argv, "%lf%c", &d, &c) != 1) p->filename = argv[0], --argc;
  else {
    int i;
    p->n = argc;
    p->h = lsx_calloc((size_t)argc, sizeof(*p->h));
    for (i = 0; i < argc; ++i) {
      if (sscanf(argv[i], "%lf%c", &p->h[i], &c) != 1) return lsx_usage(effp);
    }
    argc = 0;
  }
  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  double *h = NULL;
  int n = 0, i;
  if (p->filename) {
    FILE *file = strcmp(p->filename, "-") ? fopen(p->filename, "r") : stdin;
    char line[1024];
    double d;
    if (!file) { lsx_fail("could not open file `%s': %s", p->filename, strerror(errno)); return SOX_EOF; }
    while (fgets(line, sizeof line, file)) {
      char *s = line, *end;
      while (*s) {
        while (*s == ' ' || *s == '\t' || *s == '\r' || *s == '\n' || *s == ',') ++s;
        if (!*s || *s == '#' || *s == ';') break;
        d = strtod(s, &end);
        if (end == s) { lsx_fail("file `%s': not a number: %s", p->filename, s); if (file != stdin) fclose(file); return SOX_EOF; }
        h = lsx_realloc(h, (n + 1) * sizeof(*h));
        h[n++] = d;
        s = end;
      }
    }
    if (file != stdin) fclose(file);
  } else {
    n = p->n;
    h = lsx_malloc(n * sizeof(*h));
    for (i = 0; i < n; ++i) h[i] = p->h[i];
  }
  if (!n) { lsx_fail("no coefficients"); return SOX_EOF; }
  if (sox_effects_globals_s.plot != sox_plot_off) {
