/* ---------------- hilbert ---------------- */
typedef struct { dft_filter_t f; int num_taps; } hilbert_t;

static int hilbert_create(sox_effect_t *effp, int argc, char **argv)
{
  hilbert_t *p = (hilbert_t *)effp->priv;
  int c;
  lsx_getopt_t optstate;
  char dummy;
  lsx_getopt_init(argc, argv, "+n:", NULL, lsx_getopt_flag_none, 1, &optstate);
  while ((c = lsx_getopt_s(&optstate)) != -1) switch (c) {
    case 'n':
      if (sscanf(optstate.arg, "%d %c", &p->num_taps, &dummy) != 1 || p->num_taps < 3 || p->num_taps > 32767 || !(p->num_taps & 1)) {
        lsx_fail("number of taps must be odd and in range 3 to 32767"); return lsx_usage(effp);
      }
      break;
    default: lsx_fail("invalid option `-%c'", optstate.curpos ? optstate.curpos[-1] : '?'); return lsx_usage(effp);
  }
  return optstate.ind != argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int hilbert_start(sox_effect_t *effp)
{
  hilbert_t *p = (hilbert_t *)effp->priv;
  double *h;
  int i;
  if (p->num_taps == 0) {
    p->num_taps = (int)(effp->in_signal.rate / 76.5 + 2);
    p->num_taps += 1 - (p->num_taps % 2);
  }
  h = lsx_calloc((size_t)p->num_taps, sizeof(*h));
  for (i = 0; i < p->num_taps; ++i) {
    int d = i - p->num_taps / 2;
    h[i] = (d & 1) ? 2 / (M_PI * d) : 0;
  }
  lsx_apply_blackman(h, p->num_taps, .16);
  if (sox_effects_globals_s.plot != sox_plot_off) {
    lsx_plot_fir(h, p->num_taps, effp->in_signal.rate, sox_effects_globals_s.plot, "SoX effect: hilbert", -30., 30.);
    free(h);
    return SOX_EOF;
  }
  lsx_debug("%i taps", p->num_taps);
  lsx_fir_init(&p->f, h, p->num_taps, p->num_taps / 2);
  return SOX_SUCCESS;
}

static int hilbert_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{ return lsx_fir_flow(effp, &((hilbert_t *)effp->priv)->f, ibuf, obuf, isamp, osamp); }
static int hilbert_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
