/* ---------------- sinc ---------------- */
typedef struct {
  dft_filter_t f;
  double att, beta, phase, Fc0, Fc1, tbw0, tbw1;
  int num_taps[2];
  sox_bool round;
} sinc_t;

static int sinc_create(sox_effect_t *effp, int argc, char **argv)
{
  sinc_t *p = (sinc_t *)effp->priv;
  char *parse_ptr = argv[0];
  int i = 0, c;
  lsx_getopt_t optstate;
  char dummy;
  p->phase = 50;
  p->beta = -1;
  lsx_getopt_init(argc, argv, "+ra:b:p:MILt:n:", NULL, lsx_getopt_flag_none, 1, &optstate);
  while ((c = lsx_getopt_s(&optstate)) != -1) switch (c) {
    case 'r': p->round = sox_true; break;
    case 'a': if (sscanf(optstate.arg, "%lf %c", &p->att, &dummy) != 1 || p->att < 40 || p->att > 180) { lsx_fail("parameter `-a' must be between 40 and 180"); return lsx_usage(effp); } break;
    case 'b': if (sscanf(optstate.arg, "%lf %c", &p->beta, &dummy) != 1 || p->beta < 0 || p->beta > 256) { lsx_fail("parameter `-b' must be between 0 and 256"); return lsx_usage(effp); } break;
    case 'p': if (sscanf(optstate.arg, "%lf %c", &p->phase, &dummy) != 1 || p->phase < 0 || p->phase > 100) { lsx_fail("parameter `-p' must be between 0 and 100"); return lsx_usage(effp); } break;
    case 'M': p->phase = 0; break;
    case 'I': p->phase = 25; break;
    case 'L': p->phase = 50; break;
    case 'n': if (sscanf(optstate.arg, "%d %c", &p->num_taps[1], &dummy) != 1 || p->num_taps[1] < 11 || p->num_taps[1] > 32767) { lsx_fail("parameter `-n' must be between 11 and 32767"); return lsx_usage(effp); } break;
    case 't': if (sscanf(optstate.arg, "%lf %c", &p->tbw1, &dummy) != 1 || p->tbw1 < 1 || p->tbw1 > 1e5) { lsx_fail("parameter `-t' must be between 1 and 1e5"); return lsx_usage(effp); } break;
    default: lsx_fail("invalid option `-%c'", optstate.curpos ? optstate.curpos[-1] : '?'); return lsx_usage(effp);
  }
  if (p->att && p->beta >= 0) { lsx_fail("only one of -a and -b may be given"); return lsx_usage(effp); }
  if (p->num_taps[1] && p->tbw1) { lsx_fail("only one of -t and -n may be given"); return lsx_usage(effp); }
  if (!p->att && p->beta < 0) p->att = 120;
  argc -= optstate.ind, argv += optstate.ind;
  if (argc == 1) {
    parse_ptr = argv[0];
    if (*parse_ptr != '-') p->Fc0 = lsx_parse_frequency(parse_ptr, &parse_ptr);
    if (*parse_ptr == '-') { p->Fc1 = lsx_parse_frequency(parse_ptr + 1, &parse_ptr); }
    if (*parse_ptr) return lsx_usage(effp);
    i = 1;
  }
  argc -= i, argv += i;
  if (argc) {
    /* second set of -t/-n for the lowpass part */
    lsx_getopt_t s2;
    p->num_taps[0] = p->num_taps[1]; p->tbw0 = p->tbw1;
    p->num_taps[1] = 0; p->tbw1 = 0;
    lsx_getopt_init(argc + 1, argv - 1, "+t:n:", NULL, lsx_getopt_flag_none, 1, &s2);
    while ((c = lsx_getopt_s(&s2)) != -1) switch (c) {
      case 'n': if (sscanf(s2.arg, "%d %c", &p->num_taps[1], &dummy) != 1 || p->num_taps[1] < 11 || p->num_taps[1] > 32767) return lsx_usage(effp); break;
      case 't': if (sscanf(s2.arg, "%lf %c", &p->tbw1, &dummy) != 1 || p->tbw1 < 1 || p->tbw1 > 1e5) return lsx_usage(effp); break;
      default: return lsx_usage(effp);
    }
    if (s2.ind != argc + 1) return lsx_usage(effp);
  } else { p->num_taps[0] = p->num_taps[1]; p->tbw0 = p->tbw1; }
  if (!p->Fc0 && !p->Fc1) return lsx_usage(effp);
  return SOX_SUCCESS;
}

static void invert(double *h, int n)
{
  int i;
  for (i = 0; i < n; ++i) h[i] = -h[i];
  h[(n - 1) / 2] += 1;
}

static double *lpf(double Fn, double Fc, double tbw, int *num_taps, double att, double *beta, sox_bool round)
{
  int n = *num_taps;
  if ((Fc /= Fn) <= 0 || Fc >= 1) { *num_taps = 0; return NULL; }
  att = att ? att : 120;
  if (*beta < 0) *beta = lsx_kaiser_beta(att, tbw ? tbw / Fn : .05);
  if (!n) {
    double tr = tbw ? tbw / Fn : .05;
    n = lsx_lpf_num_taps(att, tr / 2, 0);
    if (round) { int b = 1 << (int)(log(n) / log(2.) + .5); n = b | 1; }
  }
  *num_taps = n;
  return lsx_make_lpf(n, Fc, *beta, 0, 1., sox_false);
}

static int sinc_start(sox_effect_t *effp)
{
  sinc_t *p = (sinc_t *)effp->priv;
  double Fn = effp->in_signal.rate * .5;
  double *h[2];
  int i, n, post_peak, longer;
  if (p->Fc0 >= Fn || p->Fc1 >= Fn) { lsx_fail("filter frequency must be less than sample-rate / 2"); return SOX_EOF; }
  h[0] = lpf(Fn, p->Fc0, p->tbw0, &p->num_taps[0], p->att, &p->beta, p->round);
  h[1] = lpf(Fn, p->Fc1, p->tbw1, &p->num_taps[1], p->att, &p->beta, p->round);
  if (h[0]) invert(h[0], p->num_taps[0]);
  longer = p->num_taps[1] > p->num_taps[0];
  n = p->num_taps[longer];
  if (h[0] && h[1]) {
    for (i = 0; i < p->num_taps[!longer]; ++i)
      h[longer][i + (n - p->num_taps[!longer]) / 2] += h[!longer][i];
    if (p->Fc0 < p->Fc1) invert(h[longer], n);
    free(h[!longer]);
  }
  if (p->phase != 50) lsx_fir_to_phase(&h[longer], &n, &post_peak, p->phase);
  else post_peak = n >> 1;
  if (sox_effects_globals_s.plot != sox_plot_off) {
    char title[100];
    sprintf(title, "SoX effect: sinc filter freq=%g-%g", p->Fc0, p->Fc1 ? p->Fc1 : Fn);
    lsx_plot_fir(h[longer], n, effp->in_signal.rate, sox_effects_globals_s.plot, title, -p->att - 10, 10.);
    free(h[longer]);
    return SOX_EOF;
  }
  lsx_debug("%i taps", n);
  lsx_fir_init(&p->f, h[longer], n, post_peak);
  return SOX_SUCCESS;
}

static int sinc_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{ return lsx_fir_flow(effp, &((sinc_t *)effp->priv)->f, ibuf, obuf, isamp, osamp); }
static int sinc_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{ return lsx_fir_drain(effp, &((sinc_t *)effp->priv)->f, obuf, osamp); }
static int sinc_stop(sox_effect_t *effp) { lsx_fir_free(&((sinc_t *)effp->priv)->f); return SOX_SUCCESS; }

const sox_effect_handler_t *lsx_sinc_effect_fn(void)
{
  static sox_effect_handler_t handler = { "sinc", "[-a att|-b beta] [-p phase|-M|-I|-L] [-t tbw|-n taps] [freqHP][-freqLP [-t tbw|-n taps]]", 0, sinc_create, sinc_start, sinc_flow, sinc_drain, sinc_stop, NULL, sizeof(sinc_t) };
  return &handler;
}
