  size_t i, j, k = 0, best_pos = search ? best_overlap_position(f1, f2, overlap, search, channels) : 0;
  f2 += channels * best_pos;
  if (p->fade_type == Cosine_2) {
    double fade_step = M_PI_2 / overlap;
    for (i = 0; i < overlap; ++i) {
      double fade_in = sin(i * fade_step), fade_out = cos(i * fade_step);
      for (j = 0; j < channels; ++j, ++k) { double d = f1[k] * fade_out + f2[k] * fade_in; f1[k] = SOX_ROUND_CLIP_COUNT(d, effp->clips); }
    }
  } else if (p->fade_type == Cosine_4) {
    double fade_step = M_PI / overlap;
    for (i = 0; i < overlap; ++i) {
      double fade_in = (1 - cos(i * fade_step)) * .5, fade_out = 1 - fade_in;
      for (j = 0; j < channels; ++j, ++k) { double d = f1[k] * fade_out + f2[k] * fade_in; f1[k] = SOX_ROUND_CLIP_COUNT(d, effp->clips); }
    }
  } else {
    double fade_step = 1. / overlap;
    for (i = 0; i < overlap; ++i) {
      double fade_in = fade_step * i, fade_out = 1 - fade_in;
      for (j = 0; j < channels; ++j, ++k) { double d = f1[k] * fade_out + f2[k] * fade_in; f1[k] = SOX_ROUND_CLIP_COUNT(d, effp->clips); }
    }
  }
}

static int parse(sox_effect_t *effp, char **argv, double rate)
{
  priv_t *p = (priv_t *)effp->priv;
  const char *next;
  size_t i, buffer_size;
  uint64_t last_seen = 0;
  p->max_buffer_size = 0;
  for (i = 0; i < p->nsplices; ++i) {
    if (argv) p->splices[i].str = lsx_strdup(argv[i]);
    p->splices[i].overlap = (uint64_t)(rate * 0.01 + .5);
    p->splices[i].search = p->splices[i].overlap;
    next = lsx_parseposition(rate, p->splices[i].str, &p->splices[i].start, last_seen, (uint64_t)-1, '=');
    if (next == NULL) break;
    last_seen = p->splices[i].start;
    if (*next == ',') {
      next = lsx_parsesamples(rate, next + 1, &p->splices[i].overlap, 't');
      if (next == NULL) break;
      p->splices[i].overlap *= 2;
      if (*next == ',') {
        next = lsx_parsesamples(rate, next + 1, &p->splices[i].search, 't');
        if (next == NULL) break;
        p->splices[i].search *= 2;
      }
    }
    if (*next != '\0') break;
    p->splices[i].overlap = max(p->splices[i].overlap + 4, 16);
    p->splices[i].overlap &= ~7;
    p->splices[i].search = max(p->splices[i].search, 16) & ~7;
    buffer_size = (size_t)(2 * p->splices[i].overlap + p->splices[i].search);
    p->max_buffer_size = max(p->max_buffer_size, buffer_size);
    if (p->splices[i].start < p->splices[i].overlap + p->splices[i].search) break;
    if (i > 0 && p->splices[i].start <= p->splices[i - 1].start) break;
  }
  if (i < p->nsplices) return lsx_usage(effp);
  return SOX_SUCCESS;
}

static int create(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *p = (priv_t *)effp->priv;
  --argc, ++argv;
  if (argc) {
    if (!strcmp(*argv, "-t")) p->fade_type = Triangular, --argc, ++argv;
    else if (!strcmp(*argv, "-q")) p->fade_type = Cosine_4, --argc, ++argv;
    else if (!strcmp(*argv, "-h")) p->fade_type = Cosine_2, --argc, ++argv;
  }
  p->splices = lsx_calloc(p->nsplices = (unsigned)argc, sizeof(*p->splices));
  return parse(effp, argv, 1e5);
}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  unsigned i;
  parse(effp, 0, effp->in_signal.rate);
  p->buffer = lsx_calloc(p->max_buffer_size * effp->in_signal.channels, sizeof(*p->buffer));
  p->in_pos = p->buffer_pos = p->splices_pos = 0;
  p->state = p->splices_pos != p->nsplices && p->in_pos == p->splices[p->splices_pos].start;
  for (i = 0; i < p->nsplices; ++i)
    if (p->splices[i].start < (p->splices[i].overlap + p->splices[i].search)) {
      lsx_fail("splice overlap and search area must not extend before the start of the audio");
      return SOX_EOF;
    }
  if (effp->in_signal.length != SOX_UNKNOWN_LEN) {
    uint64_t len = effp->in_signal.length / effp->in_signal.channels;
    for (i = 0; i < p->nsplices; ++i) len -= p->splices[i].overlap + p->splices[i].search;
    effp->out_signal.length = len * effp->in_signal.channels;
  }
  return SOX_SUCCESS;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t c, idone = 0, odone = 0;
  *isamp /= effp->in_signal.channels;
  *osamp /= effp->in_signal.channels;
  while (sox_true) {
copying:
    if (p->state == 0) {
      for (; idone < *isamp && odone < *osamp; ++idone, ++odone, ++p->in_pos) {
        if (p->splices_pos != p->nsplices && p->in_pos == p->splices[p->splices_pos].start) {
          p->state = 1;
          goto buffering;
        }
        for (c = 0; c < effp->in_signal.channels; ++c) *obuf++ = *ibuf++;
      }
      break;
    }
buffering:
    if (p->state == 1) {
      size_t buffer_size = (size_t)(2 * p->splices[p->splices_pos].overlap + p->splices[p->splices_pos].search) * effp->in_signal.channels;
      for (; idone < *isamp; ++idone, ++p->in_pos) {
        if (p->buffer_pos == buffer_size) {
          p->buffer_pos = (size_t)(p->splices[p->splices_pos].overlap * effp->in_signal.channels);
          do_splice(effp, p->buffer, p->buffer + p->buffer_pos + p->splices[p->splices_pos].search * effp->in_signal.channels,
              (size_t)p->splices[p->splices_pos].overlap, (size_t)p->splices[p->splices_pos].search, (size_t)effp->in_signal.channels);
          p->state = 2;
          goto flushing;
        }
        for (c = 0; c < effp->in_signal.channels; ++c) p->buffer[p->buffer_pos++] = *ibuf++;
      }
      break;
    }
flushing:
    if (p->state == 2) {
      size_t end = (size_t)(2 * p->splices[p->splices_pos].overlap) * effp->in_signal.channels;
      for (; odone < *osamp && p->buffer_pos < end; ++odone)
        for (c = 0; c < effp->in_signal.channels; ++c) *obuf++ = p->buffer[p->buffer_pos++];
      if (p->buffer_pos == end) {
        p->buffer_pos = 0;
        ++p->splices_pos;
        p->state = p->splices_pos != p->nsplices && p->in_pos == p->splices[p->splices_pos].start;
        goto copying;
      }
      break;
    }
  }
  *isamp = idone * effp->in_signal.channels;
  *osamp = odone * effp->in_signal.channels;
  return SOX_SUCCESS;
}

static int drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t c, odone = 0;
  *osamp /= effp->in_signal.channels;
  if (p->state == 1) {
    lsx_warn("Not enough audio for the splice point(s) - %u splice%s unused", p->nsplices - p->splices_pos, p->nsplices - p->splices_pos == 1 ? "" : "s");
    p->state = 2;
    p->splices_pos = p->nsplices;
    /* flush buffered samples as-is */
    { size_t flushed = 0;
      for (; odone < *osamp && flushed < p->buffer_pos; ++odone)
        for (c = 0; c < effp->in_signal.channels; ++c) *obuf++ = p->buffer[flushed++];
      p->buffer_pos = flushed < p->buffer_pos ? p->buffer_pos : 0;
      if (p->buffer_pos) { memmove(p->buffer, p->buffer + flushed, (p->buffer_pos - flushed) * sizeof(*p->buffer)); p->buffer_pos -= flushed; }
    }
  } else if (p->state == 2) {
    size_t end = (size_t)(2 * p->splices[p->splices_pos < p->nsplices ? p->splices_pos : p->nsplices - 1].overlap) * effp->in_signal.channels;
    for (; odone < *osamp && p->buffer_pos < end; ++odone)
      for (c = 0; c < effp->in_signal.channels; ++c) *obuf++ = p->buffer[p->buffer_pos++];
    if (p->buffer_pos >= end) p->buffer_pos = 0;
  }
  *osamp = odone * effp->in_signal.channels;
  return p->buffer_pos ? SOX_SUCCESS : SOX_EOF;
}

static int stop(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  if (p->splices_pos != p->nsplices && p->state != 1) lsx_warn("Input audio too short; splices not applied: %u", p->nsplices - p->splices_pos);
  free(p->buffer); p->buffer = NULL;
  return SOX_SUCCESS;
}

static int lsx_kill(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  unsigned i;
  for (i = 0; i < p->nsplices; ++i) free(p->splices[i].str);
  free(p->splices);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_splice_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "splice", "[-h|-t|-q] {position[,excess[,leeway]]}\n  -h        Half sine fade (default); constant gain (for correlated audio)\n  -t        Triangular (linear) fade; constant gain (for correlated audio)\n  -q        Quarter sine fade; constant power (for correlated audio e.g. x-fade)\n  position  The length of part 1 (including the excess)\n  excess    At the end of part 1 & the start of part2 (default 0.005)\n  leeway    Before part2 (default 0.005; set to 0 for cross-fade)",
    SOX_EFF_MCHAN | SOX_EFF_LENGTH, create, start, flow, drain, stop, lsx_kill, sizeof(priv_t) };
  return &handler;
}
EOF
