#define lsx_subsystem_name "reverb"
#include "sox.h"

typedef struct { double *data; size_t allocation, item_size, begin, end; } fifo_t;
#define FIFO_MIN 0x4000
static void fifo_clear(fifo_t *f) { f->end = f->begin = 0; }
static void *fifo_reserve(fifo_t *f, size_t n)
{
  n *= f->item_size;
  if (f->begin == f->end) fifo_clear(f);
  while (1) {
    if (f->end + n <= f->allocation) { void *p = (char *)f->data + f->end; f->end += n; return p; }
    if (f->begin > FIFO_MIN) { memmove(f->data, (char *)f->data + f->begin, f->end - f->begin); f->end -= f->begin; f->begin = 0; continue; }
    f->allocation += n;
    f->data = lsx_realloc(f->data, f->allocation);
  }
}
static void *fifo_write(fifo_t *f, size_t n, const void *data)
{
  void *s = fifo_reserve(f, n);
  if (data) memcpy(s, data, n * f->item_size);
  return s;
}
static void *fifo_read_ptr(fifo_t *f) { return (char *)f->data + f->begin; }
static void *fifo_read(fifo_t *f, size_t n, void *data)
{
  char *ret = (char *)f->data + f->begin;
  n *= f->item_size;
  if (n > f->end - f->begin) return NULL;
  if (data) memcpy(data, ret, n);
  f->begin += n;
  return ret;
}
static void fifo_delete(fifo_t *f) { free(f->data); f->data = NULL; }
static void fifo_create(fifo_t *f, size_t item_size)
{
  f->item_size = item_size;
  f->allocation = FIFO_MIN;
  f->data = lsx_malloc(f->allocation);
  fifo_clear(f);
}

typedef struct { size_t size; double *buffer, *ptr; double store; } filter_t;

static double comb_process(filter_t *p, const double *input, const double *feedback, const double *hf_damping)
{
  double output = *p->ptr;
  p->store = output + (p->store - output) * *hf_damping;
  *p->ptr = *input + p->store * *feedback;
  if (++p->ptr >= p->buffer + p->size) p->ptr = p->buffer;
  return output;
}

static double allpass_process(filter_t *p, const double *input)
{
  double output = *p->ptr;
  *p->ptr = *input + output * .5;
  if (++p->ptr >= p->buffer + p->size) p->ptr = p->buffer;
  return output - *input;
}

static const size_t comb_lengths[] = {1116, 1188, 1277, 1356, 1422, 1491, 1557, 1617};
static const size_t allpass_lengths[] = {225, 341, 441, 556};
#define stereo_adjust 12

typedef struct { filter_t comb[array_length(comb_lengths)]; filter_t allpass[array_length(allpass_lengths)]; } filter_array_t;

static void filter_array_create(filter_array_t *p, double rate, double scale, double offset)
{
  size_t i;
  double r = rate * (1 / 44100.);
  for (i = 0; i < array_length(comb_lengths); ++i, offset = -offset) {
    filter_t *pcomb = &p->comb[i];
    pcomb->size = (size_t)(scale * r * (comb_lengths[i] + stereo_adjust * offset) + .5);
    pcomb->ptr = pcomb->buffer = lsx_calloc(pcomb->size, sizeof(*pcomb->buffer));
    pcomb->store = 0;
  }
  for (i = 0; i < array_length(allpass_lengths); ++i, offset = -offset) {
    filter_t *pallpass = &p->allpass[i];
    pallpass->size = (size_t)(r * (allpass_lengths[i] + stereo_adjust * offset) + .5);
    pallpass->ptr = pallpass->buffer = lsx_calloc(pallpass->size, sizeof(*pallpass->buffer));
  }
}

static void filter_array_process(filter_array_t *p, size_t length, const double *input, double *output, const double *feedback, const double *hf_damping, const double *gain)
{
  while (length--) {
    double out = 0, in = *input++;
    size_t i = array_length(comb_lengths) - 1;
    do out += comb_process(p->comb + i, &in, feedback, hf_damping); while (i--);
    i = array_length(allpass_lengths) - 1;
    do out = allpass_process(p->allpass + i, &out); while (i--);
    *output++ = out * *gain;
  }
}

static void filter_array_delete(filter_array_t *p)
{
  size_t i;
  for (i = 0; i < array_length(allpass_lengths); ++i) free(p->allpass[i].buffer);
  for (i = 0; i < array_length(comb_lengths); ++i) free(p->comb[i].buffer);
}

typedef struct {
  double feedback, hf_damping, gain;
  fifo_t input_fifo;
  filter_array_t chan[2];
  double *out[2];
} reverb_t;

static void reverb_create(reverb_t *p, double sample_rate_Hz, double wet_gain_dB, double room_scale, double reverberance, double hf_damping, double pre_delay_ms, double stereo_depth, size_t buffer_size, double **out)
{
  size_t i, delay = (size_t)(pre_delay_ms / 1000 * sample_rate_Hz + .5);
  double scale = room_scale / 100 * .9 + .1;
  double depth = stereo_depth / 100;
  double a = -1 / log(1 - .3);
  double b = 100 / (log(1 - .98) * a + 1);
  memset(p, 0, sizeof(*p));
  p->feedback = 1 - exp((reverberance - b) / (a * b));
  p->hf_damping = hf_damping / 100 * .3 + .2;
  p->gain = dB_to_linear(wet_gain_dB) * .015;
  fifo_create(&p->input_fifo, sizeof(double));
  memset(fifo_write(&p->input_fifo, delay, 0), 0, delay * sizeof(double));
  for (i = 0; i <= ceil(depth); ++i) {
    filter_array_create(p->chan + i, sample_rate_Hz, scale, i * depth);
    out[i] = p->out[i] = lsx_calloc(buffer_size, sizeof(double));
  }
}

static void reverb_process(reverb_t *p, size_t length)
{
  size_t i;
  for (i = 0; i < 2 && p->out[i]; ++i)
    filter_array_process(p->chan + i, length, (double *)fifo_read_ptr(&p->input_fifo), p->out[i], &p->feedback, &p->hf_damping, &p->gain);
  fifo_read(&p->input_fifo, length, NULL);
}

static void reverb_delete(reverb_t *p)
{
  size_t i;
  for (i = 0; i < 2 && p->out[i]; ++i) { free(p->out[i]); filter_array_delete(p->chan + i); }
  fifo_delete(&p->input_fifo);
}

typedef struct {
  double reverberance, hf_damping, pre_delay_ms;
  double stereo_depth, wet_gain_dB, room_scale;
  sox_bool wet_only;
  size_t ichannels, ochannels;
  struct { reverb_t reverb; double *dry, *wet[2]; } chan[2];
} priv_t;

#define NUMERIC_PARAMETER(name, min, max) { \
  char *end_ptr; double d; \
  if (argc == 0) break; \
  d = strtod(*argv, &end_ptr); \
  if (end_ptr != *argv) { \
    if (d < min || d > max || *end_ptr != '\0') { lsx_fail("parameter `%s' must be between %g and %g", #name, (double)min, (double)max); return lsx_usage(effp); } \
    p->name = d; --argc, ++argv; } }

static int getopts(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *p = (priv_t *)effp->priv;
  p->reverberance = p->hf_damping = 50;
  p->stereo_depth = p->room_scale = 100;
  p->wet_gain_dB = 0;
  --argc, ++argv;
  p->wet_only = argc && (!strcmp(*argv, "-w") || !strcmp(*argv, "--wet-only")) && (--argc, ++argv, sox_true);
  do {
    NUMERIC_PARAMETER(reverberance, 0, 100)
    NUMERIC_PARAMETER(hf_damping, 0, 100)
    NUMERIC_PARAMETER(room_scale, 0, 100)
    NUMERIC_PARAMETER(stereo_depth, 0, 100)
    NUMERIC_PARAMETER(pre_delay_ms, 0, 500)
    NUMERIC_PARAMETER(wet_gain_dB, -10, 10)
  } while (0);
  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t i;
  p->ichannels = p->ochannels = 1;
  effp->out_signal.rate = effp->in_signal.rate;
  if (effp->in_signal.channels > 2 && p->stereo_depth) {
    lsx_warn("stereo-depth not applicable with >2 channels");
    p->stereo_depth = 0;
  }
  if (effp->in_signal.channels == 1 && p->stereo_depth) effp->out_signal.channels = p->ochannels = 2;
  else effp->out_signal.channels = p->ochannels = p->ichannels = effp->in_signal.channels;
  for (i = 0; i < p->ichannels; ++i)
    reverb_create(&p->chan[i].reverb, effp->in_signal.rate, p->wet_gain_dB, p->room_scale, p->reverberance, p->hf_damping, p->pre_delay_ms, p->stereo_depth, sox_globals.bufsiz / p->ochannels, p->chan[i].wet);
  return SOX_SUCCESS;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t c, i, w, len = min(*isamp / p->ichannels, *osamp / p->ochannels);
  SOX_SAMPLE_LOCALS;
  *isamp = len * p->ichannels, *osamp = len * p->ochannels;
  for (c = 0; c < p->ichannels; ++c) p->chan[c].dry = fifo_write(&p->chan[c].reverb.input_fifo, len, 0);
  for (i = 0; i < len; ++i) for (c = 0; c < p->ichannels; ++c) p->chan[c].dry[i] = SOX_SAMPLE_TO_FLOAT_64BIT(*ibuf++, effp->clips);
  for (c = 0; c < p->ichannels; ++c) reverb_process(&p->chan[c].reverb, len);
  if (p->ichannels == 2) for (i = 0; i < len; ++i) for (w = 0; w < 2; ++w) {
    double out = (1 - p->wet_only) * p->chan[w].dry[i] + .5 * (p->chan[0].wet[w][i] + p->chan[1].wet[w][i]);
    *obuf++ = SOX_FLOAT_64BIT_TO_SAMPLE(out, effp->clips);
  }
  else for (i = 0; i < len; ++i) for (w = 0; w < p->ochannels; ++w) {
    double out = (1 - p->wet_only) * p->chan[0].dry[i] + p->chan[0].wet[w][i];
    *obuf++ = SOX_FLOAT_64BIT_TO_SAMPLE(out, effp->clips);
  }
  return SOX_SUCCESS;
}

static int stop(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t i;
  for (i = 0; i < p->ichannels; ++i) reverb_delete(&p->chan[i].reverb);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_reverb_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "reverb", "[-w|--wet-only] [reverberance (50%) [HF-damping (50%) [room-scale (100%) [stereo-depth (100%) [pre-delay (0ms) [wet-gain (0dB)]]]]]]",
    SOX_EFF_MCHAN | SOX_EFF_CHAN, getopts, start, flow, NULL, stop, NULL, sizeof(priv_t) };
  return &handler;
}
