#define lsx_subsystem_name "tempo"
#include "sox.h"

typedef struct { char *data; size_t allocation, item_size, begin, end; } fifo_t;
#define FIFO_MIN 0x4000
static void fifo_clear(fifo_t *f) { f->end = f->begin = 0; }
static void *fifo_reserve(fifo_t *f, size_t n)
{
  n *= f->item_size;
  if (f->begin == f->end) fifo_clear(f);
  while (1) {
    if (f->end + n <= f->allocation) { void *p = f->data + f->end; f->end += n; return p; }
    if (f->begin > FIFO_MIN) { memmove(f->data, f->data + f->begin, f->end - f->begin); f->end -= f->begin; f->begin = 0; continue; }
    f->allocation += n;
    f->data = lsx_realloc(f->data, f->allocation);
  }
}
static void *fifo_write(fifo_t *f, size_t n, const void *data)
{
  void *s = fifo_reserve(f, n);
  if (data) memcpy(s, data, n * f->item_size);
  return s;
}
static void fifo_trim_to(fifo_t *f, size_t n) { n *= f->item_size; f->end = f->begin + n; }
static size_t fifo_occupancy(fifo_t *f) { return (f->end - f->begin) / f->item_size; }
static void *fifo_read(fifo_t *f, size_t n, void *data)
{
  char *ret = f->data + f->begin;
  n *= f->item_size;
  if (n > f->end - f->begin) return NULL;
  if (data) memcpy(data, ret, n);
  f->begin += n;
  return ret;
}
#define fifo_read_ptr(f) fifo_read(f, (size_t)0, NULL)
static void fifo_delete(fifo_t *f) { free(f->data); f->data = NULL; }
static void fifo_create(fifo_t *f, size_t item_size)
{
  f->item_size = item_size;
  f->allocation = FIFO_MIN;
  f->data = lsx_malloc(f->allocation);
  fifo_clear(f);
}

typedef struct {
  size_t channels;
  sox_bool quick_search;
  double factor;
  size_t search, segment, overlap, process_size;
  uint64_t samples_in, samples_out;
  size_t segments_total, skip_total;
  fifo_t output_fifo, input_fifo;
  float *overlap_buf;
} tempo_t;

static float difference(const float *a, const float *b, size_t length)
{
  float diff = 0;
  size_t i = 0;
#define _ diff += sqr(a[i] - b[i]), ++i;
  do { _ _ _ _ _ _ _ _ } while (i < length);
#undef _
  return diff;
}

static size_t tempo_best_overlap_position(tempo_t *t, const float *new_win)
{
  float *f = t->overlap_buf;
  size_t j, best_pos, prev_best_pos = (t->search + 1) >> 1, step = 64;
  size_t i = best_pos = t->quick_search ? prev_best_pos : 0;
  float diff, least_diff = difference(new_win + t->channels * i, f, t->channels * t->overlap);
  int k = 0;
  (void)j;
  if (t->quick_search) do {
    for (k = -1; k <= 1; k += 2) for (i = prev_best_pos + k * step; i < t->search; i += step * 2) {
      diff = difference(new_win + t->channels * i, f, t->channels * t->overlap);
      if (diff < least_diff) least_diff = diff, best_pos = i;
    }
    prev_best_pos = best_pos;
  } while (step >>= 2);
  else for (i = 1; i < t->search; i++) {
    diff = difference(new_win + t->channels * i, f, t->channels * t->overlap);
    if (diff < least_diff) least_diff = diff, best_pos = i;
  }
  return best_pos;
}

static void tempo_overlap(tempo_t *t, const float *in1, const float *in2, float *output)
{
  size_t i, j, k = 0;
  float fade_step = 1.0f / (float)t->overlap;
  for (i = 0; i < t->overlap; ++i) {
    float fade_in = fade_step * (float)i;
    float fade_out = 1.0f - fade_in;
    for (j = 0; j < t->channels; ++j, ++k) output[k] = in1[k] * fade_out + in2[k] * fade_in;
  }
}

static void tempo_process(tempo_t *t)
{
  while (fifo_occupancy(&t->input_fifo) >= t->process_size) {
    size_t skip, offset;
    if (!t->segments_total) {
      offset = t->search / 2;
      fifo_write(&t->output_fifo, t->overlap, (float *)fifo_read_ptr(&t->input_fifo) + t->channels * offset);
    } else {
      offset = tempo_best_overlap_position(t, fifo_read_ptr(&t->input_fifo));
      tempo_overlap(t, t->overlap_buf, (float *)fifo_read_ptr(&t->input_fifo) + t->channels * offset, fifo_write(&t->output_fifo, t->overlap, NULL));
    }
    fifo_write(&t->output_fifo, t->segment - 2 * t->overlap, (float *)fifo_read_ptr(&t->input_fifo) + t->channels * (offset + t->overlap));
    memcpy(t->overlap_buf, (float *)fifo_read_ptr(&t->input_fifo) + t->channels * (offset + t->segment - t->overlap), t->channels * t->overlap * sizeof(*t->overlap_buf));
    skip = (size_t)(t->factor * (++t->segments_total * (t->segment - t->overlap)) + 0.5);
    t->skip_total += skip -= t->skip_total;
    fifo_read(&t->input_fifo, skip, NULL);
  }
}

static float *tempo_input(tempo_t *t, const float *samples, size_t n)
{
  t->samples_in += n;
  return fifo_write(&t->input_fifo, n, samples);
}

static const float *tempo_output(tempo_t *t, float *samples, size_t *n)
{
  t->samples_out += *n = min(*n, fifo_occupancy(&t->output_fifo));
  return fifo_read(&t->output_fifo, *n, samples);
}

static void tempo_flush(tempo_t *t)
{
  uint64_t samples_out = (uint64_t)(t->samples_in / t->factor + .5);
  size_t remaining = samples_out > t->samples_out ? (size_t)(samples_out - t->samples_out) : 0;
  float *buff = lsx_calloc(128 * t->channels, sizeof(*buff));
  if (remaining > 0) {
    while (fifo_occupancy(&t->output_fifo) < remaining) {
      tempo_input(t, buff, (size_t)128);
      tempo_process(t);
    }
    fifo_trim_to(&t->output_fifo, remaining);
    t->samples_in = 0;
  }
  free(buff);
}

static void tempo_setup(tempo_t *t, double sample_rate, sox_bool quick_search, double factor, double segment_ms, double search_ms, double overlap_ms)
{
  size_t max_skip;
  t->quick_search = quick_search;
  t->factor = factor;
  t->segment = (size_t)(sample_rate * segment_ms / 1000 + .5);
  t->search = (size_t)(sample_rate * search_ms / 1000 + .5);
  t->overlap = (size_t)max(sample_rate * overlap_ms / 1000 + 4.5, 16);
  t->overlap &= ~7;
  if (t->overlap * 2 > t->segment) t->overlap = t->segment / 2;
  t->overlap_buf = lsx_malloc(t->overlap * t->channels * sizeof(*t->overlap_buf));
  max_skip = (size_t)ceil(factor * (t->segment - t->overlap));
  t->process_size = max(max_skip + t->overlap, t->segment) + t->search;
  memset(fifo_reserve(&t->input_fifo, t->search / 2), 0, (t->search / 2) * t->channels * sizeof(float));
}

static tempo_t *tempo_create(size_t channels)
{
  tempo_t *t = lsx_calloc(1, sizeof(*t));
  t->channels = channels;
  fifo_create(&t->input_fifo, t->channels * sizeof(float));
  fifo_create(&t->output_fifo, t->channels * sizeof(float));
  return t;
}

static void tempo_delete(tempo_t *t)
{
  free(t->overlap_buf);
  fifo_delete(&t->output_fifo);
  fifo_delete(&t->input_fifo);
  free(t);
}

typedef struct {
  tempo_t *tempo;
  sox_bool quick_search;
  double factor, segment_ms, search_ms, overlap_ms;
  sox_bool is_pitch;
  sox_bool flushed;
} priv_t;

static int getopts(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *p = (priv_t *)effp->priv;
  enum { Default, Music, Speech, Linear } profile = Default;
  char dummy;
  p->segment_ms = 82;
  p->search_ms = 14.68;
  p->overlap_ms = 12;
  --argc, ++argv;
  for (; argc && argv[0][0] == '-' && argv[0][1] && !(argv[0][1] >= '0' && argv[0][1] <= '9') && argv[0][1] != '.'; --argc, ++argv) {
    if (!strcmp(*argv, "-q")) p->quick_search = sox_true;
    else if (!strcmp(*argv, "-m")) profile = Music;
    else if (!strcmp(*argv, "-s")) profile = Speech;
    else if (!strcmp(*argv, "-l")) profile = Linear;
    else return lsx_usage(effp);
  }
  if (!argc || sscanf(*argv, "%lf %c", &p->factor, &dummy) != 1 || p->factor <= 0) return lsx_usage(effp);
  --argc, ++argv;
  if (profile != Default) {
    double base = profile == Music ? 82 : profile == Speech ? 40 : 10;
    p->segment_ms = base / max(p->factor, 1 / p->factor);
    if (profile == Linear) p->segment_ms = base;
    p->search_ms = p->segment_ms / 5.6;
    p->overlap_ms = p->segment_ms / 6.8;
  }
  if (argc) { if (sscanf(*argv, "%lf %c", &p->segment_ms, &dummy) != 1 || p->segment_ms <= 0) return lsx_usage(effp); --argc, ++argv; }
  if (argc) { if (sscanf(*argv, "%lf %c", &p->search_ms, &dummy) != 1 || p->search_ms < 0) return lsx_usage(effp); --argc, ++argv; }
  if (argc) { if (sscanf(*argv, "%lf %c", &p->overlap_ms, &dummy) != 1 || p->overlap_ms < 0) return lsx_usage(effp); --argc, ++argv; }
  if (argc) return lsx_usage(effp);
  if (profile == Default && argc == 0) { }
  if (p->search_ms > p->segment_ms / 2 && 0) p->search_ms = p->segment_ms / 2;
  return SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  if (p->factor == 1) return SOX_EFF_NULL;
  p->tempo = tempo_create((size_t)effp->in_signal.channels);
  tempo_setup(p->tempo, effp->in_signal.rate, p->quick_search, p->factor, p->segment_ms, p->search_ms, p->overlap_ms);
  p->flushed = sox_false;
  if (effp->in_signal.length != SOX_UNKNOWN_LEN) effp->out_signal.length = (uint64_t)(effp->in_signal.length / p->factor + .5);
  if (p->is_pitch) {
    effp->out_signal.rate = effp->in_signal.rate * p->factor;
    effp->out_signal.length = effp->in_signal.length;
  }
  return SOX_SUCCESS;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t i, odone = *osamp /= p->tempo->channels;
  const float *s = tempo_output(p->tempo, NULL, &odone);
  SOX_SAMPLE_LOCALS;
  for (i = 0; i < odone * p->tempo->channels; ++i) *obuf++ = SOX_FLOAT_32BIT_TO_SAMPLE(*s++, effp->clips);
  if (*isamp && odone < *osamp) {
    float *t = tempo_input(p->tempo, NULL, *isamp / p->tempo->channels);
    for (i = *isamp; i; --i) *t++ = SOX_SAMPLE_TO_FLOAT_32BIT(*ibuf++, effp->clips);
    tempo_process(p->tempo);
  } else *isamp = 0;
  *osamp = odone * p->tempo->channels;
  return SOX_SUCCESS;
}

static int drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  static size_t isamp = 0;
  if (!p->flushed) { tempo_flush(p->tempo); p->flushed = sox_true; }
  return flow(effp, 0, obuf, &isamp, osamp);
}

static int stop(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  tempo_delete(p->tempo);
  p->tempo = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_tempo_effect_fn(void)
{
  static sox_effect_handler_t handler = {
