typedef struct {
  size_t nBands;
  sox_sample_t *band_buf1, *band_buf2, *band_buf3;
  size_t band_buf_len;
  comp_band_t *bands;
} priv_t;

static int parse_band(sox_effect_t *effp, comp_band_t *l, char *args)
{
  char *argv[16];
  int argc = 0;
  char *s, *save = NULL, dummy;
  size_t i, j, commas, pairs;
  for (s = strtok_r(args, " \t", &save); s && argc < 16; s = strtok_r(NULL, " \t", &save)) argv[argc++] = s;
  if (argc < 2 || argc > 5) return lsx_usage(effp);
  for (s = argv[0], commas = 0; *s; ++s) if (*s == ',') ++commas;
  if ((commas % 2) == 0) { lsx_fail("there must be an even number of attack/decay parameters"); return SOX_EOF; }
  pairs = 1 + commas / 2;
  l->attackRate = lsx_calloc(pairs, sizeof(double));
  l->decayRate = lsx_calloc(pairs, sizeof(double));
  l->volume = lsx_calloc(pairs, sizeof(double));
  l->expectCh = pairs;
  for (i = 0, s = strtok(argv[0], ","); s != NULL; ++i) {
    for (j = 0; j < 2; ++j) {
      double *d = j ? &l->decayRate[i] : &l->attackRate[i];
      if (sscanf(s, "%lf %c", d, &dummy) != 1) { lsx_fail("syntax error trying to read attack/decay time"); return SOX_EOF; }
      else if (*d < 0) { lsx_fail("attack & decay times can't be less than 0 seconds"); return SOX_EOF; }
      s = strtok(NULL, ",");
    }
  }
  if (!lsx_compandt_parse(&l->transfer_fn, argv[1], argc > 2 ? argv[2] : NULL)) return SOX_EOF;
  for (i = 0; i < pairs; ++i) {
    double init_vol = 1.0;
    if (argc > 3) {
      if (sscanf(argv[3], "%lf %c", &init_vol, &dummy) != 1) { lsx_fail("syntax error trying to read initial volume"); return SOX_EOF; }
      init_vol = pow(10., init_vol / 20);
    }
    l->volume[i] = init_vol;
  }
  if (argc > 4 && sscanf(argv[4], "%lf %c", &l->delay, &dummy) != 1) { lsx_fail("syntax error trying to read delay value"); return SOX_EOF; }
  return SOX_SUCCESS;
}

static int getopts(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *c = (priv_t *)effp->priv;
  char *subargs, *end;
  int i;
  --argc, ++argv;
  if (argc < 1 || (argc % 2) == 0) return lsx_usage(effp);
  c->nBands = (size_t)((argc + 1) >> 1);
  c->bands = lsx_calloc(c->nBands, sizeof(comp_band_t));
  for (i = 0; i < argc; i += 2) {
    subargs = lsx_strdup(argv[i]);
    if (parse_band(effp, &c->bands[i >> 1], subargs) != SOX_SUCCESS) { free(subargs); return SOX_EOF; }
    free(subargs);
    if (i + 1 < argc) {
      c->bands[i >> 1].topfreq = lsx_parse_frequency(argv[i + 1], &end);
      if (*end || c->bands[i >> 1].topfreq <= 0) return lsx_usage(effp);
    } else c->bands[i >> 1].topfreq = 0;
  }
  return SOX_SUCCESS;
}

static void butter(double fc, double rate, int hp, double *b0, double *b1, double *b2, double *a1, double *a2)
{
  double w0 = 2 * M_PI * fc / rate, alpha = sin(w0) / (2 * sqrt(.5)), c = cos(w0), a0 = 1 + alpha;
  if (!hp) { *b0 = (1 - c) / 2 / a0; *b1 = (1 - c) / a0; *b2 = (1 - c) / 2 / a0; }
  else { *b0 = (1 + c) / 2 / a0; *b1 = -(1 + c) / a0; *b2 = (1 + c) / 2 / a0; }
  *a1 = -2 * c / a0; *a2 = (1 - alpha) / a0;
}

static int start(sox_effect_t *effp)
{
  priv_t *c = (priv_t *)effp->priv;
  size_t i, j;
  unsigned ch = effp->in_signal.channels;
  for (i = 0; i < c->nBands; ++i) {
    comp_band_t *l = &c->bands[i];
    if (l->expectCh > 1 && l->expectCh != ch) { lsx_fail("number of attack/decay pairs must match channels or be 1"); return SOX_EOF; }
    for (j = 0; j < l->expectCh; ++j) {
      l->attackRate[j] = l->attackRate[j] > 1.0 / effp->in_signal.rate ? 1.0 - exp(-1.0 / (effp->in_signal.rate * l->attackRate[j])) : 1.0;
      l->decayRate[j] = l->decayRate[j] > 1.0 / effp->in_signal.rate ? 1.0 - exp(-1.0 / (effp->in_signal.rate * l->decayRate[j])) : 1.0;
    }
    if (!lsx_compandt_show(&l->transfer_fn, sox_effects_globals_s.plot)) return SOX_EOF;
    if (l->topfreq) {
      if (l->topfreq >= effp->in_signal.rate / 2) { lsx_fail("crossover frequency must be less than half the sample rate"); return SOX_EOF; }
      butter(l->topfreq, effp->in_signal.rate, 0, &l->lb0, &l->lb1, &l->lb2, &l->la1, &l->la2);
      butter(l->topfreq, effp->in_signal.rate, 1, &l->hb0, &l->hb1, &l->hb2, &l->ha1, &l->ha2);
    }
    l->lstate = lsx_calloc(ch * 8, sizeof(double));
    l->hstate = lsx_calloc(ch * 8, sizeof(double));
  }
  c->band_buf_len = 0;
  return SOX_SUCCESS;
}

static double biq(double x, double b0, double b1, double b2, double a1, double a2, double *s)
{
  double y = x * b0 + s[0] * b1 + s[1] * b2 - s[2] * a1 - s[3] * a2;
  s[1] = s[0]; s[0] = x; s[3] = s[2]; s[2] = y;
  return y;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *c = (priv_t *)effp->priv;
  unsigned ch = effp->in_signal.channels, k;
  size_t len = min(*isamp, *osamp) / ch, i, b;
  double *in = lsx_malloc(ch * sizeof(double)), *rest = lsx_malloc(ch * sizeof(double));
  for (i = 0; i < len; ++i) {
    double out[64];
    for (k = 0; k < ch && k < 64; ++k) { rest[k] = ibuf[i * ch + k]; out[k] = 0; }
    for (b = 0; b < c->nBands; ++b) {
      comp_band_t *l = &c->bands[b];
      for (k = 0; k < ch && k < 64; ++k) {
        double band;
        if (l->topfreq) {
          double lo = biq(rest[k], l->lb0, l->lb1, l->lb2, l->la1, l->la2, l->lstate + k * 8);
          lo = biq(lo, l->lb0, l->lb1, l->lb2, l->la1, l->la2, l->lstate + k * 8 + 4);
          double hi = biq(rest[k], l->hb0, l->hb1, l->hb2, l->ha1, l->ha2, l->hstate + k * 8);
          hi = biq(hi, l->hb0, l->hb1, l->hb2, l->ha1, l->ha2, l->hstate + k * 8 + 4);
          band = lo; rest[k] = hi;
        } else band = rest[k];
        in[k] = band;
      }
      /* compand this band */
      for (k = 0; k < ch && k < 64; ++k) {
        size_t cc = l->expectCh > 1 ? k : 0;
        double s = fabs(in[k]) / -(double)SOX_SAMPLE_MIN, delta = s - l->volume[cc];
        if (l->expectCh == 1 && ch > 1) {
          unsigned m; double mx = 0;
          for (m = 0; m < ch && m < 64; ++m) mx = max(mx, fabs(in[m]));
          if (k == 0) { delta = mx / -(double)SOX_SAMPLE_MIN - l->volume[0]; l->volume[0] += delta * (delta > 0 ? l->attackRate[0] : l->decayRate[0]); }
        } else l->volume[cc] += delta * (delta > 0 ? l->attackRate[cc] : l->decayRate[cc]);
        out[k] += in[k] * lsx_compandt(&l->transfer_fn, l->volume[cc]);
      }
    }
    for (k = 0; k < ch && k < 64; ++k) {
      double d = out[k];
      SOX_SAMPLE_CLIP_COUNT(d, effp->clips);
      obuf[i * ch + k] = (sox_sample_t)d;
    }
  }
  free(in); free(rest);
  *isamp = *osamp = len * ch;
  return SOX_SUCCESS;
}

static int stop(sox_effect_t *effp)
{
  priv_t *c = (priv_t *)effp->priv;
  size_t i;
  for (i = 0; i < c->nBands; ++i) { free(c->bands[i].lstate); free(c->bands[i].hstate); c->bands[i].lstate = c->bands[i].hstate = NULL; }
  return SOX_SUCCESS;
}

static int lsx_kill(sox_effect_t *effp)
{
  priv_t *c = (priv_t *)effp->priv;
  size_t i;
  for (i = 0; i < c->nBands; ++i) {
    lsx_compandt_kill(&c->bands[i].transfer_fn);
    free(c->bands[i].attackRate); free(c->bands[i].decayRate); free(c->bands[i].volume);
  }
  free(c->bands);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_mcompand_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "mcompand", "quoted_compand_args [crossover_frequency[k] quoted_compand_args [...]]\n\nquoted_compand_args are as for the compand effect:\n\n  attack1,decay1[,attack2,decay2...]\n                 in-dB1,out-dB1[,in-dB2,out-dB2...]\n                [ gain [ initial-volume [ delay ] ] ]",
    SOX_EFF_MCHAN, getopts, start, flow, NULL, stop, lsx_kill, sizeof(priv_t) };
  return &handler;
}
