static double spl(double f, double phon)
{
  size_t i;
  double af, Lu, Tf, Af, t;
  if (f <= iso226_f[0]) i = 0;
  else if (f >= iso226_f[array_length(iso226_f) - 1]) i = array_length(iso226_f) - 2;
  else for (i = 0; f > iso226_f[i + 1]; ++i);
  t = (log(f) - log(iso226_f[i])) / (log(iso226_f[i + 1]) - log(iso226_f[i]));
  t = range_limit(t, 0, 1);
  af = iso226_af[i] + (iso226_af[i + 1] - iso226_af[i]) * t;
  Lu = iso226_Lu[i] + (iso226_Lu[i + 1] - iso226_Lu[i]) * t;
  Tf = iso226_Tf[i] + (iso226_Tf[i + 1] - iso226_Tf[i]) * t;
