    if (sscanf(argv[4], "%lf", &p->fading_ratio) != 1 || p->fading_ratio <= 0 || p->fading_ratio > 0.5) { lsx_fail("error while parsing fading ratio"); return lsx_usage(effp); }
  }
  return SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t i;
  if (p->factor == 1) return SOX_EFF_NULL;
  p->state = input_state;
  p->size = (size_t)(effp->in_signal.rate * 0.001 * p->window);
  p->index = 0;
  p->ibuf = lsx_malloc(p->size * sizeof(double));
  p->shift = (size_t)(p->shift_ratio * p->size);
  p->fading = (size_t)(p->fading_ratio * p->size);
  if (p->fading >= p->size / 2) p->fading = p->size / 2 - 1;
  p->fade_coefs = lsx_malloc(p->size * sizeof(double));
  for (i = 0; i < p->size; ++i) {
    double c = 1;
    if (i < p->fading) c = (double)i / p->fading;
    else if (i >= p->size - p->fading) c = (double)(p->size - 1 - i) / p->fading;
    p->fade_coefs[i] = c;
  }
  p->obuf = lsx_calloc(p->size * 2 + p->shift + 1, sizeof(double));
  p->oindex = 0;
  p->in_count = p->out_count = 0;
  lsx_debug("start: size=%lu, fading=%lu, shift=%lu", (unsigned long)p->size, (unsigned long)p->fading, (unsigned long)p->shift);
  if (effp->in_signal.length != SOX_UNKNOWN_LEN) effp->out_signal.length = (uint64_t)(effp->in_signal.length * p->factor + .5);
  return SOX_SUCCESS;
}

/* Overlap-add: each input window of `size` is output with fade, output advances by shift*factor, input by shift */
static void combine(priv_t *p)
{
  size_t i;
  size_t oshift = (size_t)(p->shift * p->factor + .5);
  for (i = 0; i < p->size; ++i) p->obuf[i] += p->ibuf[i] * p->fade_coefs[i];
  p->oindex = oshift;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t i = 0, o = 0;
  while (i < *isamp && o < *osamp) {
    if (p->state == input_state) {
      p->ibuf[p->index++] = ibuf[i++];
      p->in_count++;
      if (p->index == p->size) { combine(p); p->state = output_state; }
    } else {
      /* output oindex samples, then shift the input window */
      size_t n = min(p->oindex, *osamp - o), k;
      for (k = 0; k < n; ++k) {
        double d = p->obuf[k];
        obuf[o++] = SOX_ROUND_CLIP_COUNT(d, effp->clips);
      }
      memmove(p->obuf, p->obuf + n, (p->size * 2 + p->shift + 1 - n) * sizeof(double));
      memset(p->obuf + p->size * 2 + p->shift + 1 - n, 0, n * sizeof(double));
      p->out_count += n;
      p->oindex -= n;
      if (!p->oindex) {
        memmove(p->ibuf, p->ibuf + p->shift, (p->size - p->shift) * sizeof(double));
        p->index = p->size - p->shift;
        p->state = input_state;
      }
    }
  }
  *isamp = i; *osamp = o;
  return SOX_SUCCESS;
}

static int drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  uint64_t total = (uint64_t)(p->in_count * p->factor + .5);
  size_t o = 0;
  if (p->state == input_state && p->index) {
    memset(p->ibuf + p->index, 0, (p->size - p->index) * sizeof(double));
    combine(p); p->state = output_state;
  }
  while (o < *osamp && p->out_count < total) {
    double d;
    if (!p->oindex) {
      memset(p->ibuf, 0, p->size * sizeof(double));
      combine(p);
    }
    d = p->obuf[0];
    obuf[o++] = SOX_ROUND_CLIP_COUNT(d, effp->clips);
    memmove(p->obuf, p->obuf + 1, (p->size * 2 + p->shift) * sizeof(double));
    p->obuf[p->size * 2 + p->shift] = 0;
    p->out_count++;
    p->oindex--;
  }
  *osamp = o;
  return p->out_count < total ? SOX_SUCCESS : SOX_EOF;
}

static int stop(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  free(p->ibuf); free(p->obuf); free(p->fade_coefs);
  p->ibuf = p->obuf = p->fade_coefs = NULL;
  return SOX_SUCCESS;
}

