static int parse(sox_effect_t *effp, char **argv, double rate)
{
  priv_t *p = (priv_t *)effp->priv;
  uint64_t last = 0;
  unsigned i;
  for (i = 0; i < p->nbends; ++i) {
    const char *next;
    uint64_t dur;
    if (argv) p->bends[i].str = lsx_strdup(argv[i]);
    next = lsx_parseposition(rate, p->bends[i].str, &p->bends[i].start, last, (uint64_t)-1, '+');
    if (!next || *next != ',') return lsx_usage(effp);
    p->bends[i].cents = strtod(next + 1, (char **)&next);
    if (*next != ',' || !p->bends[i].cents) return lsx_usage(effp);
    next = lsx_parseposition(rate, next + 1, &dur, p->bends[i].start, (uint64_t)-1, '+');
    if (!next || *next) return lsx_usage(effp);
    if (dur < p->bends[i].start) return lsx_usage(effp);
    p->bends[i].duration = dur - p->bends[i].start;
    last = dur;
  }
  return SOX_SUCCESS;
}

static int create(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *p = (priv_t *)effp->priv;
  int c;
  lsx_getopt_t optstate;
  char dummy;
  p->frame_rate = 25;
  p->ovs = 16;
  lsx_getopt_init(argc, argv, "+f:o:", NULL, lsx_getopt_flag_none, 1, &optstate);
  while ((c = lsx_getopt_s(&optstate)) != -1) switch (c) {
    case 'f': if (sscanf(optstate.arg, "%u %c", &p->frame_rate, &dummy) != 1 || p->frame_rate < 10 || p->frame_rate > 80) { lsx_fail("parameter `-f' must be between 10 and 80"); return lsx_usage(effp); } break;
    case 'o': if (sscanf(optstate.arg, "%u %c", &p->ovs, &dummy) != 1 || p->ovs < 4 || p->ovs > 32) { lsx_fail("parameter `-o' must be between 4 and 32"); return lsx_usage(effp); } break;
    default: lsx_fail("invalid option `-%c'", optstate.curpos ? optstate.curpos[-1] : '?'); return lsx_usage(effp);
  }
  argc -= optstate.ind, argv += optstate.ind;
  p->bends = lsx_calloc(p->nbends = (unsigned)argc, sizeof(*p->bends));
  return parse(effp, argv, 1e5);
}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  if (parse(effp, 0, effp->in_signal.rate) != SOX_SUCCESS) return SOX_EOF;
  if (!p->nbends) return SOX_EFF_NULL;
  p->bend = 0; p->in_pos = p->out_pos = 0; p->phase = 0;
  p->hist_len = 8;
  p->hist = lsx_calloc(p->hist_len, sizeof(double));
  p->in_count = 0;
  effp->out_signal.length = effp->in_signal.length;
  return SOX_SUCCESS;
}

/* Simplified pitch bend using a resampling-based granular approach approximation:
 * we approximate by variable-ratio interpolation within each bend segment with length preserved. */
static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t i, len = min(*isamp, *osamp);
  for (i = 0; i < len; ++i) {
    double ratio = 1;
    double d;
    if (p->bend < p->nbends && p->out_pos >= p->bends[p->bend].start + p->bends[p->bend].duration) p->bend++;
    if (p->bend < p->nbends && p->out_pos >= p->bends[p->bend].start) {
      double t = p->bends[p->bend].duration ? (double)(p->out_pos - p->bends[p->bend].start) / p->bends[p->bend].duration : 1;
      ratio = pow(2., p->bends[p->bend].cents * t / 1200);
    }
    memmove(p->hist, p->hist + 1, (p->hist_len - 1) * sizeof(double));
    p->hist[p->hist_len - 1] = ibuf[i];
    /* fractional read-back using linear interpolation; phase tracks pitch ratio deviation */
    p->phase += ratio - 1;
    if (p->phase > 3) p->phase -= 3; if (p->phase < -3) p->phase += 3;
    {
      double pos = (double)(p->hist_len - 4) - p->phase;
      int ip = (int)floor(pos); double fr = pos - ip;
      if (ip < 0) ip = 0; if (ip >= (int)p->hist_len - 1) ip = (int)p->hist_len - 2;
      d = p->hist[ip] + (p->hist[ip + 1] - p->hist[ip]) * fr;
    }
    obuf[i] = SOX_ROUND_CLIP_COUNT(d, effp->clips);
    p->out_pos++;
  }
  *isamp = *osamp = len;
  return SOX_SUCCESS;
}

static int stop(sox_effect_t *effp) { priv_t *p = (priv_t *)effp->priv; free(p->hist); p->hist = NULL; return SOX_SUCCESS; }
static int lsx_kill(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  unsigned i;
  for (i = 0; i < p->nbends; ++i) free(p->bends[i].str);
  free(p->bends);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_bend_effect_fn(void)
{
  static sox_effect_handler_t handler = { "bend", "[-f frame-rate(25)] [-o over-sample(16)] {start,cents,end}", 0, create, start, flow, NULL, stop, lsx_kill, sizeof(priv_t) };
  return &handler;
}
