/* Overlap-add: each input window of `size` is output with fade, output advances by shift*factor, input by shift */
static void combine(priv_t *p)
{
  size_t i;
  size_t oshift = (size_t)(p->shift * p->factor + .5);
  for (i = 0; i < p->size; ++i) p->obuf[i] += p->ibuf[i] * p->fade_coefs[i];
  p->oindex = oshift;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t i = 0, o = 0;
  while (i < *isamp && o < *osamp) {
    if (p->state == input_state) {
      p->ibuf[p->index++] = ibuf[i++];
      p->in_count++;
      if (p->index == p->size) { combine(p); p->state = output_state; }
    } else {
      /* output oindex samples, then shift the input window */
      size_t n = min(p->oindex, *osamp - o), k;
      for (k = 0; k < n; ++k) {
        double d = p->obuf[k];
        obuf[o++] = SOX_ROUND_CLIP_COUNT(d, effp->clips);
      }
      memmove(p->obuf, p->obuf + n, (p->size * 2 + p->shift + 1 - n) * sizeof(double));
      memset(p->obuf + p->size * 2 + p->shift + 1 - n, 0, n * sizeof(double));
      p->out_count += n;
      p->oindex -= n;
      if (!p->oindex) {
        memmove(p->ibuf, p->ibuf + p->shift, (p->size - p->shift) * sizeof(double));
        p->index = p->size - p->shift;
        p->state = input_state;
      }
