#define lsx_subsystem_name "bend"
#include "sox.h"

typedef struct {
  unsigned nbends;
  struct { char *str; uint64_t start, duration; double cents; } *bends;
  unsigned frame_rate, ovs;
  /* state */
  unsigned bend;
  uint64_t in_pos, out_pos;
  double phase;
  double *hist; size_t hist_len;
  uint64_t in_count;
} priv_t;

static int parse(sox_effect_t *effp, char **argv, double rate)
{
  priv_t *p = (priv_t *)effp->priv;
  uint64_t last = 0;
  unsigned i;
  for (i = 0; i < p->nbends; ++i) {
    const char *next;
    uint64_t dur;
    if (argv) p->bends[i].str = lsx_strdup(argv[i]);
    next = lsx_parseposition(rate, p->bends[i].str, &p->bends[i].start, last, (uint64_t)-1, '+');
    if (!next || *next != ',') return lsx_usage(effp);
    p->bends[i].cents = strtod(next + 1, (char **)&next);
    if (*next != ',' || !p->bends[i].cents) return lsx_usage(effp);
    next = lsx_parseposition(rate, next + 1, &dur, p->bends[i].start, (uint64_t)-1, '+');
    if (!next || *next) return lsx_usage(effp);
    if (dur < p->bends[i].start) return lsx_usage(effp);
    p->bends[i].duration = dur - p->bends[i].start;
    last = dur;
  }
  return SOX_SUCCESS;
}

static int create(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *p = (priv_t *)effp->priv;
  int c;
  lsx_getopt_t optstate;
  char dummy;
  p->frame_rate = 25;
  p->ovs = 16;
  lsx_getopt_init(argc, argv, "+f:o:", NULL, lsx_getopt_flag_none, 1, &optstate);
  while ((c = lsx_getopt_s(&optstate)) != -1) switch (c) {
    case 'f': if (sscanf(optstate.arg, "%u %c", &p->frame_rate, &dummy) != 1 || p->frame_rate < 10 || p->frame_rate > 80) { lsx_fail("parameter `-f' must be between 10 and 80"); return lsx_usage(effp); } break;
    case 'o': if (sscanf(optstate.arg, "%u %c", &p->ovs, &dummy) != 1 || p->ovs < 4 || p->ovs > 32) { lsx_fail("parameter `-o' must be between 4 and 32"); return lsx_usage(effp); } break;
