    } else {
      size_t n = min(p->oindex, *osamp - o);
      emit(p, effp, obuf + o, n);
      o += n;
      if (!p->oindex) {
        memmove(p->ibuf, p->ibuf + p->shift, (p->size - p->shift) * sizeof(double));
        p->index = p->size - p->shift;
        p->state = input_state;
      }
    }
  }
  *isamp = i; *osamp = o;
  return SOX_SUCCESS;
}

static int drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  uint64_t total = (uint64_t)(p->in_count * p->factor + .5);
  size_t o = 0;
  if (p->state == input_state && p->index) {
    memset(p->ibuf + p->index, 0, (p->size - p->index) * sizeof(double));
    combine(p); p->state = output_state;
  }
  while (o < *osamp && p->out_count < total) {
    size_t n;
    if (!p->oindex) { memset(p->ibuf, 0, p->size * sizeof(double)); combine(p); }
    n = min(p->oindex, min(*osamp - o, (size_t)(total - p->out_count)));
    emit(p, effp, obuf + o, n);
    o += n;
  }
  *osamp = o;
  return p->out_count < total ? SOX_SUCCESS : SOX_EOF;
}

static int stop(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  free(p->ibuf); free(p->obuf); free(p->fade_coefs);
  p->ibuf = p->obuf = p->fade_coefs = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_stretch_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "stretch", "factor [window fade shift fading]\n       (expansion, frame in ms, lin/..., unit<1.0, unit<0.5)\n       (defaults: 1.0 20 lin ...)",
    SOX_EFF_LENGTH, getopts, start, flow, drain, stop, NULL, sizeof(priv_t) };
  return &handler;
}
