#define lsx_subsystem_name "noiseprof"
#include "sox.h"

#define WINDOWSIZE 2048
#define HALFWINDOW (WINDOWSIZE / 2)
#define FREQCOUNT (HALFWINDOW + 1)

static void power_spectrum_f(int n, const float *in, float *out)
{
  double *work = lsx_malloc(n * sizeof(double));
  int i;
  for (i = 0; i < n; ++i) work[i] = in[i];
  lsx_safe_rdft(n, 1, work);
  out[0] = (float)(work[0] * work[0]);
  for (i = 1; i < n / 2; ++i) out[i] = (float)(work[2 * i] * work[2 * i] + work[2 * i + 1] * work[2 * i + 1]);
  out[n / 2] = (float)(work[1] * work[1]);
  free(work);
}

static void apply_hann_f(float h[], const int num_points)
{
  int i, m = num_points - 1;
  for (i = 0; i < num_points; ++i) { double x = 2 * M_PI * i / m; h[i] = (float)(h[i] * (.5 - .5 * cos(x))); }
}

/* -------- noiseprof -------- */
typedef struct { float *sum; int *profilecount; float *window; } chandata_t;
typedef struct { char *output_filename; FILE *output_file; chandata_t *chandata; size_t bufdata; } prof_t;

static int prof_getopts(sox_effect_t *effp, int argc, char **argv)
{
  prof_t *p = (prof_t *)effp->priv;
  --argc, ++argv;
  if (argc == 1) p->output_filename = argv[0];
  else if (argc > 1) return lsx_usage(effp);
  return SOX_SUCCESS;
}

static int prof_start(sox_effect_t *effp)
{
  prof_t *p = (prof_t *)effp->priv;
  unsigned channels = effp->in_signal.channels, i;
  if (p->output_filename != NULL) {
    if (strcmp(p->output_filename, "-") != 0) p->output_file = fopen(p->output_filename, "wb");
    else p->output_file = stdout;
    if (p->output_file == NULL) { lsx_fail("Couldn't open profile file %s: %s", p->output_filename, strerror(errno)); return SOX_EOF; }
  } else p->output_file = stderr;
  p->chandata = lsx_calloc(channels, sizeof(*p->chandata));
  p->bufdata = 0;
  for (i = 0; i < channels; i++) {
    p->chandata[i].sum = lsx_calloc(FREQCOUNT, sizeof(float));
    p->chandata[i].profilecount = lsx_calloc(FREQCOUNT, sizeof(int));
    p->chandata[i].window = lsx_calloc(WINDOWSIZE, sizeof(float));
  }
  return SOX_SUCCESS;
}

static void collect_data(chandata_t *chan)
{
  float *out = lsx_calloc(FREQCOUNT, sizeof(float));
  int i;
  power_spectrum_f(WINDOWSIZE, chan->window, out);
  for (i = 0; i < FREQCOUNT; i++) {
    if (out[i] > 0) {
      float value = (float)log(out[i]);
      chan->sum[i] += value;
      chan->profilecount[i]++;
    }
  }
  free(out);
}

static int prof_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  prof_t *p = (prof_t *)effp->priv;
  size_t samp = min(*isamp, *osamp);
  size_t tracks = effp->in_signal.channels;
  size_t track_samples = samp / tracks;
  size_t ncopy = 0;
  size_t i;
  SOX_SAMPLE_LOCALS;
  while (track_samples) {
    ncopy = min(track_samples, WINDOWSIZE - p->bufdata);
    for (i = 0; i < tracks; i++) {
      chandata_t *chan = &(p->chandata[i]);
      size_t j;
      for (j = 0; j < ncopy; j++) chan->window[j + p->bufdata] = SOX_SAMPLE_TO_FLOAT_32BIT(ibuf[i + j * tracks], effp->clips);
    }
    p->bufdata += ncopy;
    if (p->bufdata == WINDOWSIZE) {
      for (i = 0; i < tracks; i++) collect_data(&(p->chandata[i]));
      p->bufdata = 0;
    }
    ibuf += ncopy * tracks;
    track_samples -= ncopy;
  }
  memcpy(obuf, ibuf - samp + 0, 0);
  *isamp = *osamp = samp;
  memcpy(obuf, ibuf - samp, samp * sizeof(sox_sample_t));
  return SOX_SUCCESS;
}

static int prof_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  prof_t *p = (prof_t *)effp->priv;
  size_t tracks = effp->in_signal.channels, i;
  (void)obuf;
  *osamp = 0;
  if (p->bufdata == 0) return SOX_EOF;
  for (i = 0; i < tracks; i++) {
    size_t j;
    for (j = p->bufdata; j < WINDOWSIZE; j++) p->chandata[i].window[j] = 0;
    collect_data(&(p->chandata[i]));
  }
  p->bufdata = 0;
  return SOX_EOF;
}

static int prof_stop(sox_effect_t *effp)
{
  prof_t *p = (prof_t *)effp->priv;
  size_t i, j;
  for (i = 0; i < effp->in_signal.channels; i++) {
    chandata_t *chan = &(p->chandata[i]);
    fprintf(p->output_file, "Channel %d: ", (int)i);
    for (j = 0; j < FREQCOUNT; j++)
      fprintf(p->output_file, "%s%f", j == 0 ? "" : ", ", chan->profilecount[j] != 0 ? chan->sum[j] / chan->profilecount[j] : 0);
    fprintf(p->output_file, "\n");
    free(chan->sum); free(chan->profilecount); free(chan->window);
  }
  free(p->chandata);
  if (p->output_file != stderr && p->output_file != stdout) fclose(p->output_file);
  else fflush(p->output_file);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_noiseprof_effect_fn(void)
{
  static sox_effect_handler_t handler = { "noiseprof", "[profile-file]", SOX_EFF_MCHAN | SOX_EFF_MODIFY, prof_getopts, prof_start, prof_flow, prof_drain, prof_stop, NULL, sizeof(prof_t) };
  return &handler;
}

/* -------- noisered -------- */
typedef struct { float *window, *lastwindow, *noisegate, *smoothing; } rchandata_t;
typedef struct { char *profile_filename; float threshold; rchandata_t *chandata; size_t bufdata; } red_t;

static int red_getopts(sox_effect_t *effp, int argc, char **argv)
{
  red_t *p = (red_t *)effp->priv;
  --argc, ++argv;
  p->threshold = 0.5;
  if (argc > 0) { p->profile_filename = argv[0]; ++argv; --argc; }
  if (argc > 0) {
    if (sscanf(argv[0], "%f", &p->threshold) != 1) return lsx_usage(effp);
    if (p->threshold > 1) p->threshold = 1; else if (p->threshold < 0) p->threshold = 0;
    ++argv; --argc;
  }
  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int red_start(sox_effect_t *effp)
{
  red_t *p = (red_t *)effp->priv;
  size_t fchannels = 0, channels = effp->in_signal.channels, i;
  FILE *ifp = NULL;
  p->chandata = lsx_calloc(channels, sizeof(*p->chandata));
  p->bufdata = 0;
  for (i = 0; i < channels; i++) {
    p->chandata[i].noisegate = lsx_calloc(FREQCOUNT, sizeof(float));
    p->chandata[i].smoothing = lsx_calloc(FREQCOUNT, sizeof(float));
    p->chandata[i].lastwindow = NULL;
  }
  if (p->profile_filename != NULL && strcmp(p->profile_filename, "-") != 0) ifp = fopen(p->profile_filename, "r");
  else ifp = stdin;
  if (ifp == NULL) { lsx_fail("Couldn't open profile file %s: %s", p->profile_filename, strerror(errno)); return SOX_EOF; }
  while (1) {
    int i1;
    float f1;
    if (2 != fscanf(ifp, " Channel %d: %f", &i1, &f1)) break;
    if (i1 != (int)fchannels) { lsx_fail("noisered: Got channel %d, expected channel %d.", i1, (int)fchannels); return SOX_EOF; }
    p->chandata[fchannels].noisegate[0] = f1;
    for (i = 1; i < FREQCOUNT; i++) {
      if (1 != fscanf(ifp, ", %f", &f1)) { lsx_fail("noisered: Not enough data for channel %d (expected %d, got %lu)", i1, FREQCOUNT, (unsigned long)i); return SOX_EOF; }
      p->chandata[fchannels].noisegate[i] = f1;
    }
    fchannels++;
    if (fchannels == channels) break;
  }
  if (fchannels != channels) { lsx_fail("noisered: channel mismatch: %lu in input, %lu in profile.", (unsigned long)channels, (unsigned long)fchannels); return SOX_EOF; }
  if (ifp != stdin) fclose(ifp);
  for (i = 0; i < channels; i++) p->chandata[i].window = lsx_calloc(WINDOWSIZE, sizeof(float));
  effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static void reduce_noise(rchandata_t *chan, float *window, double level)
{
  int i;
  double *spec = lsx_malloc(WINDOWSIZE * sizeof(double));
  float *inr = lsx_calloc(WINDOWSIZE, sizeof(float));
  float *power = lsx_calloc(FREQCOUNT, sizeof(float));
  float *smoothing = chan->smoothing;
  for (i = 0; i < WINDOWSIZE; ++i) spec[i] = window[i];
  lsx_safe_rdft(WINDOWSIZE, 1, spec);
  memcpy(inr, window, WINDOWSIZE * sizeof(float));
  apply_hann_f(inr, WINDOWSIZE);
  power_spectrum_f(WINDOWSIZE, inr, power);
  for (i = 0; i < FREQCOUNT; i++) {
    float smooth, plog;
    plog = (float)log(power[i]);
    if (power[i] != 0 && plog < chan->noisegate[i] + level * 8.0) smooth = 0.0f; else smooth = 1.0f;
    smoothing[i] = smooth * 0.5f + smoothing[i] * 0.5f;
  }
  for (i = 2; i < FREQCOUNT - 2; i++)
    if (smoothing[i] >= 0.5 && smoothing[i] <= 0.55 && smoothing[i - 1] < 0.1 && smoothing[i - 2] < 0.1 && smoothing[i + 1] < 0.1 && smoothing[i + 2] < 0.1) smoothing[i] = 0.0;
  spec[0] *= smoothing[0];
  spec[1] *= smoothing[FREQCOUNT - 1];
  for (i = 1; i < FREQCOUNT - 1; i++) { spec[2 * i] *= smoothing[i]; spec[2 * i + 1] *= smoothing[i]; }
  lsx_safe_rdft(WINDOWSIZE, -1, spec);
  for (i = 0; i < WINDOWSIZE; ++i) inr[i] = (float)(spec[i] * 2. / WINDOWSIZE);
  apply_hann_f(inr, WINDOWSIZE);
  memcpy(window, inr, WINDOWSIZE * sizeof(float));
  free(inr); free(power); free(spec);
}

static int process_window(sox_effect_t *effp, red_t *data, unsigned chan_num, unsigned num_chans, sox_sample_t *obuf, unsigned len)
{
  int j;
  float *nextwindow;
  int use = (int)(min(len, WINDOWSIZE) - min(len, HALFWINDOW));
  rchandata_t *chan = &(data->chandata[chan_num]);
  int first = (chan->lastwindow == NULL);
  SOX_SAMPLE_LOCALS;
  nextwindow = lsx_calloc(WINDOWSIZE, sizeof(float));
  memcpy(nextwindow, chan->window + HALFWINDOW, HALFWINDOW * sizeof(float));
  reduce_noise(chan, chan->window, data->threshold);
  if (!first) {
    for (j = 0; j < use; j++) {
      float s = chan->window[j] + chan->lastwindow[HALFWINDOW + j];
      obuf[chan_num + num_chans * j] = SOX_FLOAT_32BIT_TO_SAMPLE(s, effp->clips);
    }
    free(chan->lastwindow);
  } else {
    for (j = 0; j < use; j++) obuf[chan_num + num_chans * j] = SOX_FLOAT_32BIT_TO_SAMPLE(chan->window[j], effp->clips);
  }
  chan->lastwindow = chan->window;
  chan->window = nextwindow;
  return use;
}

static int red_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  red_t *p = (red_t *)effp->priv;
  size_t samp = min(*isamp, *osamp);
  size_t tracks = effp->in_signal.channels;
  size_t track_samples = samp / tracks;
  size_t ncopy = min(track_samples, WINDOWSIZE - p->bufdata);
  size_t whole_window = (ncopy + p->bufdata == WINDOWSIZE);
  int oldbuf = (int)p->bufdata;
  size_t i;
  SOX_SAMPLE_LOCALS;
  if (whole_window) p->bufdata = HALFWINDOW; else p->bufdata += ncopy;
  for (i = 0; i < tracks; i++) {
    rchandata_t *chan = &(p->chandata[i]);
    size_t j;
    for (j = 0; j < ncopy; j++) chan->window[oldbuf + j] = SOX_SAMPLE_TO_FLOAT_32BIT(ibuf[i + tracks * j], effp->clips);
    if (whole_window) process_window(effp, p, (unsigned)i, (unsigned)tracks, obuf, (unsigned)(oldbuf + ncopy));
  }
  *isamp = tracks * ncopy;
  if (whole_window) *osamp = tracks * (WINDOWSIZE - HALFWINDOW);
  else *osamp = 0;
  return SOX_SUCCESS;
}

static int red_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  red_t *p = (red_t *)effp->priv;
  size_t i, tracks = effp->in_signal.channels;
  if (!p->bufdata || *osamp < tracks * WINDOWSIZE) { *osamp = 0; return SOX_EOF; }
  for (i = 0; i < tracks; i++) {
    rchandata_t *chan = &p->chandata[i];
    size_t j;
    for (j = p->bufdata; j < WINDOWSIZE; j++) chan->window[j] = 0;
  }
  {
    int used = 0;
    for (i = 0; i < tracks; i++) used = process_window(effp, p, (unsigned)i, (unsigned)tracks, obuf, (unsigned)p->bufdata);
    *osamp = tracks * used;
  }
  p->bufdata = 0;
  return SOX_EOF;
}

static int red_stop(sox_effect_t *effp)
{
  red_t *p = (red_t *)effp->priv;
  size_t i;
  for (i = 0; i < effp->in_signal.channels; i++) {
    rchandata_t *chan = &(p->chandata[i]);
    free(chan->lastwindow); free(chan->window); free(chan->smoothing); free(chan->noisegate);
  }
  free(p->chandata);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_noisered_effect_fn(void)
{
  static sox_effect_handler_t handler = { "noisered", "[profile-file [amount]]", SOX_EFF_MCHAN | SOX_EFF_LENGTH, red_getopts, red_start, red_flow, red_drain, red_stop, NULL, sizeof(red_t) };
  return &handler;
}
