  p->hpFilterFreq = 50; p->lpFilterFreq = 6000; p->hpLifterFreq = 150; p->lpLifterFreq = 2000;
  p->triggerTc = .25; p->triggerLevel = 7; p->searchTime = 1; p->gapTime = .25; p->preTriggerTime = 0;
