    default: lsx_fail("invalid option `-%c'", optstate.curpos ? optstate.curpos[-1] : '?'); return lsx_usage(effp);
  }
  return optstate.ind != argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  double rate = effp->in_signal.rate;
  unsigned ch = effp->in_signal.channels;
  p->measure_period = (size_t)(rate / p->measureFreq + .5);
  p->measure_len = (size_t)(rate * p->measureDuration + .5);
  p->pre_trigger_len = (size_t)(rate * p->preTriggerTime + .5);
  p->search_len = (size_t)(rate * p->searchTime + .5);
  p->gap_len = (size_t)(rate * p->gapTime + .5);
  p->buffer_len = (p->search_len + p->pre_trigger_len + p->measure_len + p->measure_period * 2) * ch;
  p->buffer = lsx_calloc(p->buffer_len, sizeof(double));
  p->buffer_pos = p->buffer_samples = 0;
  p->level = 0; p->noise_level = 0; p->boot_count = 0;
  p->triggered = 0; p->done = sox_false; p->measure_timer = 0;
  p->meas_count = (size_t)(p->searchTime * p->measureFreq + .5) + 1;
  p->meas_hist = lsx_calloc(p->meas_count, sizeof(double));
  p->measure_idx = 0;
  effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

/* Simplified VAD: RMS-based with adaptive noise floor */
static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  unsigned ch = effp->in_signal.channels;
  size_t i = 0, o = 0;
  if (p->done) { size_t n = min(*isamp, *osamp); memcpy(obuf, ibuf, n * sizeof(*obuf)); *isamp = *osamp = n; return SOX_SUCCESS; }
  while (i + ch <= *isamp && o < *osamp) {
    unsigned c;
    double e = 0;
    for (c = 0; c < ch; ++c) { double d = ibuf[i + c] / (SOX_SAMPLE_MAX + 1.); e += d * d; }
    e /= ch;
    /* ring buffer store */
    for (c = 0; c < ch; ++c) p->buffer[(p->buffer_pos + c) % p->buffer_len] = ibuf[i + c];
    p->buffer_pos = (p->buffer_pos + ch) % p->buffer_len;
    if (p->buffer_samples < p->buffer_len / ch) p->buffer_samples++;
    i += ch;
    /* measurement */
    {
      double tc = exp(-1 / (p->measureTc * effp->in_signal.rate));
      p->level = p->level * tc + e * (1 - tc);
      if (p->boot_count < p->bootTime * effp->in_signal.rate) { p->boot_count++; p->noise_level = p->noise_level * .999 + e * .001; if (p->boot_count == 1) p->noise_level = e; }
      else {
        double tcn = p->level > p->noise_level ? exp(-1 / (p->noiseTcUp * effp->in_signal.rate)) : exp(-1 / (p->noiseTcDown * effp->in_signal.rate));
        p->noise_level = p->noise_level * tcn + p->level * (1 - tcn);
      }
      if (++p->measure_timer >= p->measure_period) {
        double ratio_dB = 10 * log10((p->level + 1e-20) / (p->noise_level * p->noiseReductionAmount + 1e-20));
        p->measure_timer = 0;
        if (p->boot_count >= p->bootTime * effp->in_signal.rate && ratio_dB > p->triggerLevel) {
          /* triggered: output buffered audio from (search back) pre-trigger */
          size_t back = min(p->buffer_samples, p->pre_trigger_len + p->measure_len);
          size_t k, start = (p->buffer_pos + p->buffer_len - back * ch) % p->buffer_len;
          p->done = sox_true;
          for (k = 0; k < back * ch && o < *osamp; ++k) obuf[o++] = (sox_sample_t)p->buffer[(start + k) % p->buffer_len];
          /* remaining buffered beyond osamp are lost in this simplified version; copy rest of input */
          { size_t n = min(*isamp - i, *osamp - o); memcpy(obuf + o, ibuf + i, n * sizeof(*obuf)); o += n; i += n; }
          break;
        }
      }
    }
  }
  *isamp = i; *osamp = o;
  return SOX_SUCCESS;
}

static int stop(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  free(p->buffer); free(p->meas_hist);
  p->buffer = NULL; p->meas_hist = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_vad_effect_fn(void)
