/* -------- firfit (experimental) -------- */
#include "dft_filter.h"
typedef struct { dft_filter_t f; char const *filename; int n; } firfit_t;

static int ff_create(sox_effect_t *effp, int argc, char **argv)
{
  firfit_t *p = (firfit_t *)effp->priv;
  --argc, ++argv;
  p->n = 1023;
  if (argc == 1) p->filename = argv[0], --argc;
  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int ff_start(sox_effect_t *effp)
{
  firfit_t *p = (firfit_t *)effp->priv;
  FILE *file = p->filename && strcmp(p->filename, "-") ? fopen(p->filename, "r") : stdin;
  double *freqs = NULL, *gains = NULL, *work, *h;
  int n = 0, i, N = 4096;
  if (!file) { lsx_fail("could not open file `%s': %s", p->filename, strerror(errno)); return SOX_EOF; }
  {
    double f, g;
    while (fscanf(file, "%lf %lf", &f, &g) == 2) {
      freqs = lsx_realloc(freqs, (n + 1) * sizeof(*freqs));
      gains = lsx_realloc(gains, (n + 1) * sizeof(*gains));
      freqs[n] = f; gains[n] = g; ++n;
    }
  }
  if (file != stdin) fclose(file);
  if (n < 1) { lsx_fail("no knots given"); free(freqs); free(gains); return SOX_EOF; }
  work = lsx_calloc((size_t)N + 2, sizeof(*work));
  for (i = 0; i <= N / 2; ++i) {
    double f = (double)i * effp->in_signal.rate / N, g;
    int k;
    if (f <= freqs[0]) g = gains[0];
    else if (f >= freqs[n - 1]) g = gains[n - 1];
    else { for (k = 0; f > freqs[k + 1]; ++k); g = gains[k] + (gains[k + 1] - gains[k]) * (log(f) - log(freqs[k])) / (log(freqs[k + 1]) - log(freqs[k])); }
    g = dB_to_linear(g);
    if (i == 0) work[0] = g; else if (i == N / 2) work[1] = g; else { work[2 * i] = g; work[2 * i + 1] = 0; }
  }
  lsx_safe_rdft(N, -1, work);
  for (i = 0; i < N; ++i) work[i] *= 2. / N;
  h = lsx_malloc(p->n * sizeof(*h));
  for (i = 0; i < p->n; ++i) h[i] = work[(i - p->n / 2 + N) % N];
  lsx_apply_hann(h, p->n);
  free(work); free(freqs); free(gains);
  if (sox_effects_globals_s.plot != sox_plot_off) {
    lsx_plot_fir(h, p->n, effp->in_signal.rate, sox_effects_globals_s.plot, "SoX effect: firfit", -30., 30.);
    free(h);
    return SOX_EOF;
  }
  lsx_fir_init(&p->f, h, p->n, p->n / 2);
  return SOX_SUCCESS;
}

static int ff_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{ return lsx_fir_flow(effp, &((firfit_t *)effp->priv)->f, ibuf, obuf, isamp, osamp); }
static int ff_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{ return lsx_fir_drain(effp, &((firfit_t *)effp->priv)->f, obuf, osamp); }
static int ff_stop(sox_effect_t *effp) { lsx_fir_free(&((firfit_t *)effp->priv)->f); return SOX_SUCCESS; }

const sox_effect_handler_t *lsx_firfit_effect_fn(void)
{
  static sox_effect_handler_t handler = { "firfit", "[knots-file]", SOX_EFF_ALPHA, ff_create, ff_start, ff_flow, ff_drain, ff_stop, NULL, sizeof(firfit_t) };
