static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  double rate = effp->in_signal.rate;
  unsigned ch = effp->in_signal.channels;
  p->measure_period = (size_t)(rate / p->measureFreq + .5);
  p->measure_len = (size_t)(rate * p->measureDuration + .5);
  p->pre_trigger_len = (size_t)(rate * p->preTriggerTime + .5);
  p->search_len = (size_t)(rate * p->searchTime + .5);
  p->gap_len = (size_t)(rate * p->gapTime + .5);
  p->buffer_len = (p->search_len + p->pre_trigger_len + p->measure_len + p->measure_period * 2) * ch;
  p->buffer = lsx_calloc(p->buffer_len, sizeof(double));
  p->buffer_pos = p->buffer_samples = 0;
