#define lsx_subsystem_name "sox"
#include "sox.h"

typedef struct { uint64_t num_samples; } priv_t;
#define FIXED_HDR (4 + 8 + 8 + 4 + 4)

static int startread(sox_format_t *ft)
{
  priv_t *p = (priv_t *)ft->priv;
  char magic[4];
  uint32_t headers_bytes, num_channels, comments_bytes;
  uint64_t num_samples;
  double rate;
  if (lsx_readchars(ft, magic, sizeof(magic))) return SOX_EOF;
  if (memcmp(magic, ".SoX", sizeof(magic)) && memcmp(magic, "XoS.", sizeof(magic))) {
    lsx_fail_errno(ft, SOX_EHDR, "can't find sox file format identifier");
    return SOX_EOF;
  }
  if (memcmp(magic, ".SoX", 4)) ft->encoding.reverse_bytes = !ft->encoding.reverse_bytes;
  if (lsx_readdw(ft, &headers_bytes) || lsx_readqw(ft, &num_samples) || lsx_readdf(ft, &rate) ||
      lsx_readdw(ft, &num_channels) || lsx_readdw(ft, &comments_bytes)) return SOX_EOF;
  if (((headers_bytes + 4) & 7) || headers_bytes < FIXED_HDR + comments_bytes || (num_channels && num_samples % num_channels)) {
    lsx_fail_errno(ft, SOX_EHDR, "invalid sox file format header");
    return SOX_EOF;
  }
  if (comments_bytes) {
    char *buf = lsx_calloc(1, (size_t)comments_bytes + 1);
    if (lsx_readchars(ft, buf, (size_t)comments_bytes) != SOX_SUCCESS) { free(buf); return SOX_EOF; }
    lsx_append_comments(&ft->oob.comments, buf);
    free(buf);
  }
  if (lsx_skipbytes(ft, (size_t)(headers_bytes - FIXED_HDR - comments_bytes)) != SOX_SUCCESS) return SOX_EOF;
  p->num_samples = num_samples;
  return lsx_check_read_params(ft, num_channels, rate, SOX_ENCODING_SIGN2, 32, num_samples, sox_true);
}

static int write_header(sox_format_t *ft)
{
  char *comments = lsx_cat_comments(ft->oob.comments);
  size_t comments_len = strlen(comments);
  size_t comments_bytes = (comments_len + 7) & ~(size_t)7;
  uint64_t size = ft->olength ? ft->olength : (ft->signal.length != SOX_UNKNOWN_LEN ? ft->signal.length : 0);
  sox_bool error = sox_false
    || lsx_writechars(ft, ".SoX", 4)
    || lsx_writedw(ft, (unsigned)(FIXED_HDR + comments_bytes))
    || lsx_writeqw(ft, size)
    || lsx_writedf(ft, ft->signal.rate)
    || lsx_writedw(ft, ft->signal.channels)
    || lsx_writedw(ft, (unsigned)comments_len)
    || lsx_writechars(ft, comments, comments_len)
    || lsx_padbytes(ft, comments_bytes - comments_len);
  free(comments);
  return error ? SOX_EOF : SOX_SUCCESS;
}

static int startwrite(sox_format_t *ft) { return write_header(ft); }
static int stopwrite(sox_format_t *ft)
{
  if (!ft->seekable) return SOX_SUCCESS;
  if (lsx_seeki(ft, 0, SEEK_SET)) { lsx_fail_errno(ft, SOX_EOF, "can't rewind output file to rewrite header"); return SOX_EOF; }
  return write_header(ft);
}

static size_t read_samples(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  priv_t *p = (priv_t *)ft->priv;
  if (p->num_samples) len = (size_t)min((uint64_t)len, p->num_samples);
  len = lsx_rawread(ft, buf, len);
  if (p->num_samples) p->num_samples -= len;
  return len;
}

static int seek(sox_format_t *ft, uint64_t offset)
{
  priv_t *p = (priv_t *)ft->priv;
  int result = lsx_rawseek(ft, offset);
  if (result == SOX_SUCCESS && ft->signal.length) p->num_samples = ft->signal.length > offset ? ft->signal.length - offset : 0;
  return result;
}

const sox_format_handler_t *lsx_sox_format_fn(void)
{
  static const char *const names[] = {"sox", NULL};
  static const unsigned write_encodings[] = {SOX_ENCODING_SIGN2, 32, 0, 0};
  static const sox_format_handler_t handler = {
    "SoX native intermediate format", names, SOX_FILE_REWIND,
    startread, read_samples, NULL, startwrite, lsx_rawwrite, stopwrite, seek, write_encodings, NULL, sizeof(priv_t) };
  return &handler;
}
