#define lsx_subsystem_name "formats"
#include "sox.h"
#include "g711.h"
#include <time.h>

/* ---------------- cdr / cdda ---------------- */
#define CDR_SECTORSIZE 2352
typedef struct { uint64_t samples; } cdr_priv_t;

static int cdr_startread(sox_format_t *ft)
{
  return lsx_check_read_params(ft, 2, 44100., SOX_ENCODING_SIGN2, 16, (uint64_t)0, sox_true);
}
static int cdr_startwrite(sox_format_t *ft)
{
  cdr_priv_t *p = (cdr_priv_t *)ft->priv;
  p->samples = 0;
  return SOX_SUCCESS;
}
static size_t cdr_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  cdr_priv_t *p = (cdr_priv_t *)ft->priv;
  p->samples += len;
  return lsx_rawwrite(ft, buf, len);
}
static int cdr_stopwrite(sox_format_t *ft)
{
  cdr_priv_t *p = (cdr_priv_t *)ft->priv;
  unsigned i = (unsigned)(p->samples % (CDR_SECTORSIZE / 2));
  if (i) while (i++ < CDR_SECTORSIZE / 2) if (lsx_writew(ft, 0)) return SOX_EOF;
  return SOX_SUCCESS;
}
const sox_format_handler_t *lsx_cdr_format_fn(void)
{
  static const char *const names[] = {"cdda", "cdr", NULL};
  static const unsigned write_encodings[] = {SOX_ENCODING_SIGN2, 16, 0, 0};
  static const double write_rates[] = {44100, 0};
  static const sox_format_handler_t handler = {
    "Red Book Compact Disc Digital Audio", names, SOX_FILE_BIG_END | SOX_FILE_STEREO,
    cdr_startread, lsx_rawread, NULL, cdr_startwrite, cdr_write, cdr_stopwrite, lsx_rawseek, write_encodings, write_rates, sizeof(cdr_priv_t) };
  return &handler;
}

/* ---------------- htk ---------------- */
static int htk_startread(sox_format_t *ft)
{
  uint32_t period_100ns, num_samples;
  uint16_t bytes_per_sample, parmKind;
  if (lsx_readdw(ft, &num_samples) || lsx_readdw(ft, &period_100ns) || lsx_readw(ft, &bytes_per_sample) || lsx_readw(ft, &parmKind)) return SOX_EOF;
  if (parmKind != 0) {
    lsx_report("file not linear PCM");
    lsx_fail_errno(ft, SOX_EFMT, "unsupported HTK parameter kind");
    return SOX_EOF;
  }
  if (!period_100ns) { lsx_fail_errno(ft, SOX_EHDR, "invalid sample period"); return SOX_EOF; }
  return lsx_check_read_params(ft, 1, 1e7 / period_100ns, SOX_ENCODING_SIGN2, (unsigned)bytes_per_sample << 3, (uint64_t)num_samples, sox_true);
}
static int htk_write_header(sox_format_t *ft)
{
  double period_100ns = 1e7 / ft->signal.rate;
  uint64_t len = ft->olength ? ft->olength : (ft->signal.length != SOX_UNKNOWN_LEN ? ft->signal.length : 0);
  if (!ft->olength && floor(period_100ns) != period_100ns) lsx_warn("rounding sample period %f (x 100ns) to nearest integer", period_100ns);
  return lsx_writedw(ft, (unsigned)len) || lsx_writedw(ft, (unsigned)(period_100ns + .5)) || lsx_writew(ft, (unsigned)(ft->encoding.bits_per_sample >> 3)) || lsx_writew(ft, 0) ? SOX_EOF : SOX_SUCCESS;
}
static int htk_startwrite(sox_format_t *ft) { return htk_write_header(ft); }
static int htk_stopwrite(sox_format_t *ft)
{
  if (!ft->seekable) return SOX_SUCCESS;
  if (lsx_seeki(ft, 0, SEEK_SET)) return SOX_EOF;
  return htk_write_header(ft);
}
const sox_format_handler_t *lsx_htk_format_fn(void)
{
  static const char *const names[] = {"htk", NULL};
  static const unsigned write_encodings[] = {SOX_ENCODING_SIGN2, 16, 0, 0};
  static const sox_format_handler_t handler = {
    "PCM format used for Hidden Markov Model speech processing", names, SOX_FILE_BIG_END | SOX_FILE_MONO | SOX_FILE_REWIND,
    htk_startread, lsx_rawread, NULL, htk_startwrite, lsx_rawwrite, htk_stopwrite, lsx_rawseek, write_encodings, NULL, 0 };
  return &handler;
}

/* ---------------- sounder (sndr) ---------------- */
static int sndr_startread(sox_format_t *ft)
{
  uint16_t type, rate;
  if (lsx_readw(ft, &type) || lsx_readw(ft, &rate) || lsx_skipbytes(ft, (size_t)4)) return SOX_EOF;
  if (type) { lsx_fail_errno(ft, SOX_EFMT, "unexpected header data in Sounder file"); return SOX_EOF; }
  return lsx_check_read_params(ft, 1, (double)rate, SOX_ENCODING_UNSIGNED, 8, (uint64_t)0, sox_true);
}
static int sndr_startwrite(sox_format_t *ft)
{
  return lsx_writew(ft, 0) || lsx_writew(ft, (unsigned)min(65535, (unsigned)(ft->signal.rate + .5))) || lsx_writew(ft, 10) || lsx_writew(ft, 4) ? SOX_EOF : SOX_SUCCESS;
}
const sox_format_handler_t *lsx_sounder_format_fn(void)
{
  static const char *const names[] = {"sndr", NULL};
  static const unsigned write_encodings[] = {SOX_ENCODING_UNSIGNED, 8, 0, 0};
  static const sox_format_handler_t handler = {
    "8-bit linear audio as used by Aaron Wallace's `Sounder' of 1991", names, SOX_FILE_LIT_END | SOX_FILE_MONO,
    sndr_startread, lsx_rawread, NULL, sndr_startwrite, lsx_rawwrite, NULL, lsx_rawseek, write_encodings, NULL, 0 };
  return &handler;
}

