  uint64_t len = ft->olength ? ft->olength : (ft->signal.length != SOX_UNKNOWN_LEN ? ft->signal.length : 0);
  char name[14] = "";
  return lsx_writechars(ft, "SOUND\x1a", 6) || lsx_writew(ft, 0) || lsx_writedw(ft, (unsigned)len) || lsx_writedw(ft, 0) || lsx_writedw(ft, (unsigned)len) || lsx_writedw(ft, (unsigned)(ft->signal.rate + .5)) || lsx_writew(ft, 0) || lsx_writew(ft, 10) || lsx_writew(ft, 4) || lsx_writechars(ft, name, 14) || lsx_padbytes(ft, SNDT_HDR - 42) ? SOX_EOF : SOX_SUCCESS;
}
static int sndt_startwrite(sox_format_t *ft) { return sndt_write_header(ft); }
