/* ---------------- avr ---------------- */
typedef struct {
  char magic[5]; char name[8]; unsigned short mono, rez, sign, loop, midi; uint32_t rate; uint32_t size, lbeg, lend;
  unsigned short res1, res2, res3; char ext[20]; char user[64];
} avr_t;
static int avr_startread(sox_format_t *ft)
{
  avr_t *avr = (avr_t *)ft->priv;
  int rc;
  lsx_readchars(ft, avr->magic, 4);
  if (strncmp(avr->magic, "2BIT", 4)) { lsx_fail_errno(ft, SOX_EHDR, "AVR: unknown header"); return SOX_EOF; }
  lsx_readchars(ft, avr->name, 8);
  lsx_readw(ft, &avr->mono);
  if (avr->mono) ft->signal.channels = 2; else ft->signal.channels = 1;
  lsx_readw(ft, &avr->rez);
  if (avr->rez == 8) ft->encoding.bits_per_sample = 8;
  else if (avr->rez == 16) ft->encoding.bits_per_sample = 16;
  else { lsx_fail_errno(ft, SOX_EFMT, "AVR: unsupported sample resolution"); return SOX_EOF; }
  lsx_readw(ft, &avr->sign);
  if (avr->sign) ft->encoding.encoding = SOX_ENCODING_SIGN2; else ft->encoding.encoding = SOX_ENCODING_UNSIGNED;
  lsx_readw(ft, &avr->loop);
  lsx_readw(ft, &avr->midi);
  lsx_readdw(ft, &avr->rate);
  ft->signal.rate = (avr->rate & 0x00ffffff);
  lsx_readdw(ft, &avr->size);
  lsx_readdw(ft, &avr->lbeg);
  lsx_readdw(ft, &avr->lend);
  lsx_readw(ft, &avr->res1);
  lsx_readw(ft, &avr->res2);
  lsx_readw(ft, &avr->res3);
  lsx_readchars(ft, avr->ext, 20);
  lsx_readchars(ft, avr->user, 64);
  rc = lsx_rawstartread(ft);
  if (rc) return rc;
  ft->signal.length = (uint64_t)avr->size * ft->signal.channels;
  return SOX_SUCCESS;
}
static int avr_startwrite(sox_format_t *ft)
{
  avr_t *avr = (avr_t *)ft->priv;
  int rc = lsx_rawstartwrite(ft);
  if (rc) return rc;
  if (!ft->seekable) { lsx_fail_errno(ft, SOX_EOF, "AVR: file is not seekable"); return SOX_EOF; }
  lsx_writechars(ft, "2BIT", 4);
  memset(avr->name, 0, sizeof avr->name);
  lsx_writechars(ft, avr->name, 8);
  lsx_writew(ft, ft->signal.channels == 2 ? 0xffff : 0);
  lsx_writew(ft, ft->encoding.bits_per_sample);
  lsx_writew(ft, ft->encoding.encoding == SOX_ENCODING_SIGN2 ? 0xffff : 0);
  lsx_writew(ft, 0);
  lsx_writew(ft, 0xffff);
  lsx_writedw(ft, (unsigned)(ft->signal.rate + .5) | 0xff000000u);
  lsx_writedw(ft, 0);
  lsx_writedw(ft, 0);
  lsx_writedw(ft, 0);
  lsx_writew(ft, 0); lsx_writew(ft, 0); lsx_writew(ft, 0);
  memset(avr->ext, 0, 20); lsx_writechars(ft, avr->ext, 20);
  memset(avr->user, 0, 64); lsx_writechars(ft, avr->user, 64);
  avr->size = 0;
  return SOX_SUCCESS;
}
static size_t avr_write(sox_format_t *ft, const sox_sample_t *buf, size_t nsamp)
{
  avr_t *avr = (avr_t *)ft->priv;
  avr->size += (uint32_t)(nsamp / ft->signal.channels);
  return lsx_rawwrite(ft, buf, nsamp);
}
static int avr_stopwrite(sox_format_t *ft)
{
  avr_t *avr = (avr_t *)ft->priv;
  if (lsx_seeki(ft, 26, SEEK_SET)) return SOX_EOF;
  lsx_writedw(ft, avr->size);
  lsx_writedw(ft, 0);
  lsx_writedw(ft, avr->size);
  return SOX_SUCCESS;
}
const sox_format_handler_t *lsx_avr_format_fn(void)
{
  static const char *const names[] = {"avr", NULL};
  static const unsigned write_encodings[] = {SOX_ENCODING_SIGN2, 16, 8, 0, SOX_ENCODING_UNSIGNED, 16, 8, 0, 0};
  static const sox_format_handler_t handler = {
    "Audio Visual Research format; used on the Mac", names, SOX_FILE_BIG_END | SOX_FILE_MONO | SOX_FILE_STEREO,
    avr_startread, lsx_rawread, NULL, avr_startwrite, avr_write, avr_stopwrite, NULL, write_encodings, NULL, sizeof(avr_t) };
  return &handler;
}

/* ---------------- smp (SampleVision) ---------------- */
#define SMP_NAMELEN 30
#define SMP_COMMENTLEN 60
#define SMP_MARKS 8
#define SMP_LOOPS 8
typedef struct { uint64_t NoOfSamps; off_t dataStart; } smp_priv_t;
static int smp_startread(sox_format_t *ft)
{
  smp_priv_t *smp = (smp_priv_t *)ft->priv;
  char id[18], version[4], comments[SMP_COMMENTLEN + 1], name[SMP_NAMELEN + 1];
  uint32_t samplecount, rate;
  int i;
  if (lsx_readchars(ft, id, 18) || lsx_readchars(ft, version, 4)) return SOX_EOF;
  if (strncmp(id, "SOUND SAMPLE DATA ", 18) != 0) { lsx_fail_errno(ft, SOX_EHDR, "SMP header does not begin with magic word `SOUND SAMPLE DATA '"); return SOX_EOF; }
  if (strncmp(version, "2.1 ", 4) != 0) { lsx_fail_errno(ft, SOX_EHDR, "SMP header has unknown version"); return SOX_EOF; }
  if (lsx_readchars(ft, comments, SMP_COMMENTLEN) || lsx_readchars(ft, name, SMP_NAMELEN)) return SOX_EOF;
  comments[SMP_COMMENTLEN] = 0; name[SMP_NAMELEN] = 0;
  { int k = SMP_COMMENTLEN; while (k > 0 && (comments[k - 1] == ' ' || comments[k - 1] == 0)) comments[--k] = 0; }
  if (*comments) lsx_append_comments(&ft->oob.comments, comments);
  lsx_report("SMP header name: %.30s", name);
  if (lsx_readdw(ft, &samplecount)) return SOX_EOF;
  /* loops */
  for (i = 0; i < SMP_LOOPS; i++) { uint32_t s, e; uint8_t t; uint16_t c; lsx_readdw(ft, &s); lsx_readdw(ft, &e); lsx_readb(ft, &t); lsx_readw(ft, &c); ft->oob.loops[i].start = s; ft->oob.loops[i].length = e - s; ft->oob.loops[i].type = t; ft->oob.loops[i].count = c; }
  for (i = 0; i < SMP_MARKS; i++) { char mn[10]; uint32_t pos; lsx_readchars(ft, mn, 10); lsx_readdw(ft, &pos); }
  { uint8_t midi; uint32_t r; lsx_readb(ft, &midi); ft->oob.instr.MIDInote = midi; lsx_readdw(ft, &r); rate = r; }
  smp->NoOfSamps = samplecount;
  ft->oob.instr.nloops = 0;
  for (i = 0; i < SMP_LOOPS; i++) if (ft->oob.loops[i].type != 0) ft->oob.instr.nloops++;
  if (ft->oob.instr.nloops > 0) { ft->oob.instr.loopmode = (char)(sox_loop_8 + ft->oob.loops[0].type); } else ft->oob.instr.loopmode = sox_loop_none;
  lsx_report("SMP rate: %u", rate);
  return lsx_check_read_params(ft, 1, (double)rate, SOX_ENCODING_SIGN2, 16, (uint64_t)samplecount, sox_true);
}
static int smp_write_header(sox_format_t *ft)
{
  smp_priv_t *smp = (smp_priv_t *)ft->priv;
  char comments[SMP_COMMENTLEN], name[SMP_NAMELEN];
  char *c = lsx_cat_comments(ft->oob.comments);
  int i;
  memset(comments, ' ', SMP_COMMENTLEN); memset(name, ' ', SMP_NAMELEN);
  strncpy(comments, c, strlen(c) > SMP_COMMENTLEN ? SMP_COMMENTLEN : strlen(c));
  free(c);
  lsx_writechars(ft, "SOUND SAMPLE DATA ", 18);
  lsx_writechars(ft, "2.1 ", 4);
  lsx_writechars(ft, comments, SMP_COMMENTLEN);
  lsx_writechars(ft, name, SMP_NAMELEN);
  lsx_writedw(ft, (unsigned)smp->NoOfSamps);
  for (i = 0; i < SMP_LOOPS; i++) { lsx_writedw(ft, 0); lsx_writedw(ft, 0); lsx_writeb(ft, 0); lsx_writew(ft, 0); }
  for (i = 0; i < SMP_MARKS; i++) { char mn[10]; memset(mn, ' ', 10); lsx_writechars(ft, mn, 10); lsx_writedw(ft, 0xffffffffu); }
  lsx_writeb(ft, 60);
  lsx_writedw(ft, (unsigned)(ft->signal.rate + .5));
  return SOX_SUCCESS;
}
static int smp_startwrite(sox_format_t *ft)
{
  smp_priv_t *smp = (smp_priv_t *)ft->priv;
  smp->NoOfSamps = ft->signal.length != SOX_UNKNOWN_LEN ? ft->signal.length : 0;
  smp_write_header(ft);
  smp->NoOfSamps = 0;
  return SOX_SUCCESS;
}
static size_t smp_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  smp_priv_t *smp = (smp_priv_t *)ft->priv;
  smp->NoOfSamps += len;
  return lsx_rawwrite(ft, buf, len);
}
static int smp_stopwrite(sox_format_t *ft)
{
  if (!ft->seekable) return SOX_SUCCESS;
  if (lsx_seeki(ft, 0, SEEK_SET)) return SOX_EOF;
  return smp_write_header(ft);
}
const sox_format_handler_t *lsx_smp_format_fn(void)
{
  static const char *const names[] = {"smp", NULL};
  static const unsigned write_encodings[] = {SOX_ENCODING_SIGN2, 16, 0, 0};
  static const sox_format_handler_t handler = {
    "Turtle Beach SampleVision", names, SOX_FILE_LIT_END | SOX_FILE_MONO,
    smp_startread, lsx_rawread, NULL, smp_startwrite, smp_write, smp_stopwrite, lsx_rawseek, write_encodings, NULL, sizeof(smp_priv_t) };
  return &handler;
}

/* ---------------- txw (Yamaha TX-16W) ---------------- */
#define TXW_HDR 32
typedef struct { uint64_t samples_left, samples_written; int bytes_out; unsigned char buf[3]; int nbuf; } txw_priv_t;
static int txw_startread(sox_format_t *ft)
{
  txw_priv_t *p = (txw_priv_t *)ft->priv;
  char magic[6];
  unsigned char hdr[TXW_HDR - 6];
  uint32_t num_bytes;
  double rate;
  if (lsx_readchars(ft, magic, 6) || lsx_readbuf(ft, hdr, TXW_HDR - 6) != TXW_HDR - 6) return SOX_EOF;
  if (memcmp(magic, "LM8953", 6)) { lsx_fail_errno(ft, SOX_EHDR, "txw: can't find TX-16W identifier"); return SOX_EOF; }
  switch (hdr[26 - 6 - 6 + 6]) { default: break; }
  /* sample rate code at byte 26 */
  switch (hdr[20]) { case 1: rate = 33333.3; break; case 2: rate = 50000; break; case 3: rate = 16666.7; break; default: rate = 16666.7; }
  num_bytes = (uint32_t)lsx_filelength(ft);
  num_bytes = num_bytes > TXW_HDR ? num_bytes - TXW_HDR : 0;
  p->samples_left = (uint64_t)num_bytes / 3 * 2;
  p->nbuf = 0;
  ft->signal.length = p->samples_left;
  if (ft->seekable) ft->data_start = lsx_tell(ft);
  ft->signal.channels = 1; ft->signal.rate = rate;
  ft->encoding.encoding = SOX_ENCODING_SIGN2; ft->encoding.bits_per_sample = 12;
  return SOX_SUCCESS;
}
static size_t txw_read(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  txw_priv_t *p = (txw_priv_t *)ft->priv;
  size_t done = 0;
  unsigned char b[3];
  while (done < len && p->samples_left) {
    if (lsx_readbuf(ft, b, 3) != 3) break;
    {
      int s1 = (b[0] << 4) | (b[1] >> 4);
      int s2 = (b[2] << 4) | (b[1] & 15);
      if (s1 & 0x800) s1 -= 0x1000;
      if (s2 & 0x800) s2 -= 0x1000;
      buf[done++] = (sox_sample_t)s1 << 20; p->samples_left--;
      if (done < len && p->samples_left) { buf[done++] = (sox_sample_t)s2 << 20; p->samples_left--; }
    }
  }
  return done;
}
static int txw_startwrite(sox_format_t *ft)
{
  txw_priv_t *p = (txw_priv_t *)ft->priv;
  unsigned char hdr[TXW_HDR];
  memset(hdr, 0, sizeof hdr);
  memcpy(hdr, "LM8953", 6);
  hdr[26] = ft->signal.rate == 50000 ? 2 : ft->signal.rate == 33333.3 ? 1 : 3;
  hdr[23] = 0x49; /* "loop" bytes default */
  lsx_writebuf(ft, hdr, TXW_HDR);
  p->samples_written = 0; p->nbuf = 0;
  return SOX_SUCCESS;
}
static size_t txw_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  txw_priv_t *p = (txw_priv_t *)ft->priv;
  size_t i;
  SOX_SAMPLE_LOCALS;
  for (i = 0; i < len; ++i) {
    int s = SOX_SAMPLE_TO_SIGNED(12, buf[i], ft->clips) & 0xfff;
    if (p->nbuf == 0) { p->buf[0] = (unsigned char)(s >> 4); p->buf[1] = (unsigned char)((s & 15) << 4); p->nbuf = 1; }
    else { p->buf[1] |= (unsigned char)(s & 15); p->buf[2] = (unsigned char)(s >> 4); lsx_writebuf(ft, p->buf, 3); p->nbuf = 0; }
    p->samples_written++;
  }
  return len;
}
static int txw_stopwrite(sox_format_t *ft)
{
  txw_priv_t *p = (txw_priv_t *)ft->priv;
  if (p->nbuf) { p->buf[2] = 0; lsx_writebuf(ft, p->buf, 3); p->nbuf = 0; }
  return SOX_SUCCESS;
}
const sox_format_handler_t *lsx_txw_format_fn(void)
{
  static const char *const names[] = {"txw", NULL};
  static const unsigned write_encodings[] = {SOX_ENCODING_SIGN2, 12, 0, 0};
  static const double write_rates[] = {16666.7, 33333.3, 50000, 0};
  static const sox_format_handler_t handler = {
    "Yamaha TX-16W sampler", names, SOX_FILE_MONO,
    txw_startread, txw_read, NULL, txw_startwrite, txw_write, txw_stopwrite, NULL, write_encodings, write_rates, sizeof(txw_priv_t) };
  return &handler;
}
