cat > voc.c <<'EOF'
#define lsx_subsystem_name "voc"
#include "sox.h"

#define VOC_TERM 0
#define VOC_DATA 1
#define VOC_CONT 2
#define VOC_SILENCE 3
#define VOC_MARKER 4
#define VOC_TEXT 5
#define VOC_LOOP 6
#define VOC_LOOPEND 7
#define VOC_EXTENDED 8
#define VOC_DATA_16 9

typedef struct {
  long block_remaining;
  long rate;
  long rest;
  long total_size;
  int extended;
  int format;
  int size;
  int channels;
  int silent;
  int srate;
  int blockseek;
  int samples;
  int has_extended;
} priv_t;

static int getblock(sox_format_t *ft);
static void blockstart(sox_format_t *ft);

static int startread(sox_format_t *ft)
{
  priv_t *v = (priv_t *)ft->priv;
  char header[20];
  uint16_t sbseek, version, check;
  int rc;
  if (lsx_readbuf(ft, header, 20) != 20) { lsx_fail_errno(ft, SOX_EHDR, "unexpected EOF in VOC header"); return SOX_EOF; }
  if (strncmp(header, "Creative Voice File\032", 19)) { lsx_fail_errno(ft, SOX_EHDR, "VOC file header incorrect"); return SOX_EOF; }
  lsx_readw(ft, &sbseek);
  lsx_readw(ft, &version);
  lsx_readw(ft, &check);
  if (check != (~version + 0x1234)) { lsx_fail_errno(ft, SOX_EHDR, "VOC file header checksum incorrect"); return SOX_EOF; }
  lsx_seeki(ft, (int64_t)sbseek, SEEK_SET);
  v->block_remaining = 0;
  v->rate = -1;
  v->rest = 0;
  v->total_size = 0;
  v->extended = 0;
  v->format = 0;
  v->size = 8;
  v->channels = 1;
  v->srate = 0;
  v->silent = 0;
  rc = getblock(ft);
  if (rc) return rc;
  if (v->rate == -1) { lsx_fail_errno(ft, SOX_EOF, "Input .voc file had no sound!"); return SOX_EOF; }
  ft->encoding.bits_per_sample = v->size;
  ft->encoding.encoding = v->size == 8 ? SOX_ENCODING_UNSIGNED : SOX_ENCODING_SIGN2;
  if (v->format == 1) ft->encoding.encoding = SOX_ENCODING_UNSIGNED; /* 8-bit */
  if (v->format == 4) ft->encoding.encoding = SOX_ENCODING_SIGN2;
  if (v->format == 6) ft->encoding.encoding = SOX_ENCODING_ALAW;
  if (v->format == 7) ft->encoding.encoding = SOX_ENCODING_ULAW;
  if (ft->signal.channels == 0) ft->signal.channels = v->channels;
  ft->signal.rate = v->rate;
  ft->signal.length = v->total_size ? (uint64_t)v->total_size : SOX_UNSPEC;
  return SOX_SUCCESS;
}

static size_t read_samples(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  priv_t *v = (priv_t *)ft->priv;
  size_t done = 0;
  int rc = 0;
  int16_t sw;
  unsigned char uc;
  SOX_SAMPLE_LOCALS;
  if (v->rest == 0) {
    rc = getblock(ft);
    if (rc) return 0;
  }
  if (v->rest == 0) return 0;
  if (v->silent) {
    for (; v->rest && (done < len); v->rest--, done++) *buf++ = 0;
  } else {
    for (; v->rest && (done < len); v->rest--, done++) {
      if (v->size == 8) {
        if (lsx_readb(ft, &uc) == SOX_EOF) { lsx_warn("VOC input: short file"); v->rest = 0; return done; }
        if (ft->encoding.encoding == SOX_ENCODING_ULAW) *buf++ = SOX_SIGNED_16BIT_TO_SAMPLE(0, dummy), buf[-1] = 0;
        *buf = SOX_UNSIGNED_8BIT_TO_SAMPLE(uc, ft->clips);
        if (ft->encoding.encoding == SOX_ENCODING_SIGN2) *buf = SOX_SIGNED_8BIT_TO_SAMPLE((int8_t)uc, ft->clips);
        buf++;
      } else {
        lsx_readsw(ft, &sw);
        if (lsx_eof(ft)) { lsx_warn("VOC input: short file"); v->rest = 0; return done; }
        *buf++ = SOX_SIGNED_16BIT_TO_SAMPLE(sw, ft->clips);
      }
    }
  }
  return done;
}

static int getblock(sox_format_t *ft)
{
  priv_t *v = (priv_t *)ft->priv;
  unsigned char uc, block;
  uint32_t sblen;
  uint16_t new_rate_16;
  uint32_t new_rate_32;
  unsigned i;
  v->silent = 0;
  while (v->rest == 0) {
    if (lsx_eof(ft)) return SOX_EOF;
    if (lsx_readb(ft, &block) == SOX_EOF) return SOX_EOF;
    if (block == VOC_TERM) return SOX_EOF;
    if (lsx_eof(ft)) return SOX_EOF;
    lsx_read3(ft, &sblen);
    switch (block) {
    case VOC_DATA:
      lsx_readb(ft, &uc);
      if (!v->extended) {
        if (uc == 0) { lsx_fail_errno(ft, SOX_EFMT, "Sample rate is zero?"); return SOX_EOF; }
        if ((v->rate != -1) && (uc != v->rate)) { lsx_fail_errno(ft, SOX_EFMT, "sample rate codes differ: %ld != %d", v->rate, uc); return SOX_EOF; }
        v->rate = uc;
        ft->signal.rate = 1000000.0 / (256 - v->rate);
        v->channels = 1;
      }
      lsx_readb(ft, &uc);
      if (uc != 0) { lsx_fail_errno(ft, SOX_EFMT, "only interpret 8-bit no-compression packing, not %d", uc); return SOX_EOF; }
      v->rest = sblen - 2;
      v->size = 8;
      v->format = 0;
      v->total_size += v->rest;
      return SOX_SUCCESS;
    case VOC_DATA_16:
      lsx_readdw(ft, &new_rate_32);
      if (new_rate_32 == 0) { lsx_fail_errno(ft, SOX_EFMT, "Sample rate is zero?"); return SOX_EOF; }
      if ((v->rate != -1) && ((long)new_rate_32 != v->rate)) { lsx_fail_errno(ft, SOX_EFMT, "sample rate codes differ: %ld != %d", v->rate, new_rate_32); return SOX_EOF; }
      v->rate = new_rate_32;
      ft->signal.rate = new_rate_32;
      lsx_readb(ft, &uc);
      v->size = uc;
      lsx_readb(ft, &uc);
      v->channels = uc;
      lsx_readw(ft, (uint16_t *)&i); v->format = (int)i;
      lsx_readb(ft, &uc); lsx_readb(ft, &uc); lsx_readb(ft, &uc); lsx_readb(ft, &uc);
      v->rest = sblen - 12;
      v->total_size += v->rest;
      return SOX_SUCCESS;
    case VOC_CONT:
      v->rest = sblen;
      v->total_size += v->rest;
      return SOX_SUCCESS;
    case VOC_SILENCE: {
      unsigned short period;
      lsx_readw(ft, &period);
      lsx_readb(ft, &uc);
      if (uc == 0) { lsx_fail_errno(ft, SOX_EFMT, "Silence sample rate is zero"); return SOX_EOF; }
      if (ft->signal.rate == 0) ft->signal.rate = 1000000.0 / (256 - uc);
      v->rest = period * (ft->signal.rate / (1000000.0 / (256 - uc)));
      v->silent = 1;
      v->total_size += v->rest;
      return SOX_SUCCESS; }
    case VOC_MARKER:
      lsx_readb(ft, &uc); lsx_readb(ft, &uc);
      break;
    case VOC_TEXT: {
      uint32_t i2 = sblen;
      char *text = lsx_malloc(i2 + 1);
      size_t k;
      for (k = 0; k < i2; k++) lsx_readb(ft, (unsigned char *)&text[k]);
      text[i2] = 0;
      lsx_append_comments(&ft->oob.comments, text);
      free(text);
      continue; }
    case VOC_LOOP: case VOC_LOOPEND:
      lsx_debug("skipping repeat loop");
      for (i = 0; i < sblen; i++) lsx_readb(ft, &uc);
      break;
    case VOC_EXTENDED:
      v->extended = 1;
      lsx_readw(ft, &new_rate_16);
      if (new_rate_16 == 0) { lsx_fail_errno(ft, SOX_EFMT, "Sample rate is zero?"); return SOX_EOF; }
      if ((v->rate != -1) && (new_rate_16 != v->rate)) { lsx_fail_errno(ft, SOX_EFMT, "sample rate codes differ: %ld != %d", v->rate, new_rate_16); return SOX_EOF; }
      v->rate = new_rate_16;
      lsx_readb(ft, &uc);
      if (uc != 0) { lsx_fail_errno(ft, SOX_EFMT, "only interpret 8-bit no-compression packing, not %d", uc); return SOX_EOF; }
      lsx_readb(ft, &uc);
      if (uc) v->channels = 2; else v->channels = 1;
      ft->signal.rate = 256000000L / (65536 - v->rate) / v->channels;
      v->extended = 1;
      continue;
    default:
      lsx_debug("skipping unknown block code %d", block);
      for (i = 0; i < sblen; i++) lsx_readb(ft, &uc);
      break;
    }
  }
  return SOX_SUCCESS;
}

static int startwrite(sox_format_t *ft)
{
  priv_t *v = (priv_t *)ft->priv;
  if (!ft->seekable) { lsx_fail_errno(ft, SOX_EOF, "Output .voc file must be a file, not a pipe"); return SOX_EOF; }
  v->samples = 0;
  lsx_writes(ft, "Creative Voice File\032");
  lsx_writew(ft, 26);
  lsx_writew(ft, 0x010a);
  lsx_writew(ft, 0x1129);
  return SOX_SUCCESS;
}

static void blockstart(sox_format_t *ft)
{
  priv_t *v = (priv_t *)ft->priv;
  v->blockseek = (int)lsx_tell(ft);
  if (v->silent) {
    lsx_writeb(ft, VOC_SILENCE);
    lsx_write3(ft, 0);
    lsx_writeb(ft, (unsigned)(256 - (1000000.0 / ft->signal.rate)));
  } else {
    if (ft->encoding.bits_per_sample == 8) {
      lsx_writeb(ft, VOC_DATA);
      lsx_write3(ft, 0);
      lsx_writeb(ft, (unsigned)(256 - (1000000.0 / ft->signal.rate)));
      lsx_writeb(ft, 0);
    } else {
      lsx_writeb(ft, VOC_DATA_16);
      lsx_write3(ft, 0);
      lsx_writedw(ft, (unsigned)ft->signal.rate);
      lsx_writeb(ft, 16);
      lsx_writeb(ft, ft->signal.channels);
      lsx_writew(ft, 4);
      lsx_writedw(ft, 0);
    }
  }
}

static void blockstop(sox_format_t *ft)
{
  priv_t *v = (priv_t *)ft->priv;
  uint32_t datum;
  lsx_writeb(ft, 0);
  if (lsx_seeki(ft, (int64_t)v->blockseek, SEEK_SET)) return;
  v->blockseek += 1;
  if (v->silent) lsx_writew(ft, (unsigned)v->samples);
  else {
    lsx_writeb(ft, 0);
    datum = (uint32_t)(v->samples * (ft->encoding.bits_per_sample >> 3)) + 2 + (ft->encoding.bits_per_sample == 16 ? 10 : 0);
    lsx_write3(ft, datum);
    lsx_seeki(ft, 0, SEEK_END);
  }
}

static size_t write_samples(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  priv_t *v = (priv_t *)ft->priv;
  unsigned char uc;
  int16_t sw;
  size_t done = 0;
  SOX_SAMPLE_LOCALS;
  if (len && v->samples == 0) {
    v->silent = 0;
    blockstart(ft);
  }
  v->samples += (int)len;
  while (done < len) {
    if (ft->encoding.bits_per_sample == 8) {
      uc = SOX_SAMPLE_TO_UNSIGNED_8BIT(*buf++, ft->clips);
      lsx_writeb(ft, uc);
    } else {
      sw = (int16_t)SOX_SAMPLE_TO_SIGNED_16BIT(*buf++, ft->clips);
      lsx_writesw(ft, sw);
    }
    done++;
  }
  return done;
}

static int stopwrite(sox_format_t *ft)
{
  priv_t *v = (priv_t *)ft->priv;
  if (v->samples) blockstop(ft);
  else lsx_writeb(ft, 0);
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_voc_format_fn(void)
{
  static const char *const names[] = {"voc", NULL};
  static const unsigned write_encodings[] = {SOX_ENCODING_SIGN2, 16, 0, SOX_ENCODING_UNSIGNED, 8, 0, 0};
  static const sox_format_handler_t handler = {
    "Creative Technology Sound Blaster format", names, SOX_FILE_LIT_END | SOX_FILE_MONO | SOX_FILE_STEREO,
    startread, read_samples, NULL, startwrite, write_samples, stopwrite, NULL, write_encodings, NULL, sizeof(priv_t) };
  return &handler;
}
