#include "sox.h"

typedef struct { uint64_t num_samples; } priv_t;

static int startread(sox_format_t *ft)
{
  priv_t *p = (priv_t *)ft->priv;
  char fldname[64], fldtype[16], fldsval[128];
  char *buf;
  size_t header_size_u;
  long header_size, num_samples = 0;
  unsigned long bytes_per_sample = 0, channels = 1, rate = 16000;
  sox_encoding_t encoding = SOX_ENCODING_SIGN2;
  char shorten_check[4];
