  header_size_u = (size_t)header_size;
  free(buf);
  buf = lsx_malloc(header_size_u + 1);
  header_size -= 16;
  for (;;) {
    char *s;
    if (header_size <= 0) { lsx_fail_errno(ft, SOX_EHDR, "Error reading Sphere header"); free(buf); return SOX_EOF; }
    /* read a line */
    for (i = 0; i < header_size; ) {
      if (lsx_readchars(ft, buf + i, 1)) { free(buf); return SOX_EOF; }
      header_size--;
      if (buf[i] == '\n') { buf[i] = 0; break; }
      i++;
    }
