  }
  p->num_samples = (uint64_t)num_samples * channels;
  return lsx_check_read_params(ft, (unsigned)channels, (double)rate, encoding, (unsigned)bytes_per_sample << 3, (uint64_t)num_samples * channels, sox_true);
}

static size_t read_samples(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  priv_t *p = (priv_t *)ft->priv;
  if (p->num_samples) len = (size_t)min((uint64_t)len, p->num_samples);
  len = lsx_rawread(ft, buf, len);
  if (p->num_samples) p->num_samples -= len;
  return len;
}

static int write_header(sox_format_t *ft)
{
  char buf[128];
  uint64_t samples = (ft->olength ? ft->olength : (ft->signal.length != SOX_UNKNOWN_LEN ? ft->signal.length : 0)) / ft->signal.channels;
  size_t written = 0;
  lsx_writes(ft, "NIST_1A\n"); written += 8;
  lsx_writes(ft, "   1024\n"); written += 8;
  sprintf(buf, "sample_count -i %" PRIu64 "\n", samples); lsx_writes(ft, buf); written += strlen(buf);
  sprintf(buf, "sample_n_bytes -i %d\n", ft->encoding.bits_per_sample >> 3); lsx_writes(ft, buf); written += strlen(buf);
  sprintf(buf, "channel_count -i %d\n", ft->signal.channels); lsx_writes(ft, buf); written += strlen(buf);
  if (ft->encoding.bits_per_sample == 8) sprintf(buf, "sample_byte_format -s1 1\n");
  else sprintf(buf, "sample_byte_format -s2 %s\n", ft->encoding.reverse_bytes ? "10" : "01");
  lsx_writes(ft, buf); written += strlen(buf);
  sprintf(buf, "sample_rate -i %u\n", (unsigned)(ft->signal.rate + .5)); lsx_writes(ft, buf); written += strlen(buf);
  if (ft->encoding.encoding == SOX_ENCODING_ULAW) sprintf(buf, "sample_coding -s4 ulaw\n");
  else sprintf(buf, "sample_coding -s3 pcm\n");
  lsx_writes(ft, buf); written += strlen(buf);
  lsx_writes(ft, "end_head\n"); written += 9;
  while (written < 1024) { lsx_writeb(ft, 0); written++; }
  return SOX_SUCCESS;
}

static int startwrite(sox_format_t *ft)
{
  if (!ft->seekable) { lsx_fail_errno(ft, SOX_EOF, "sph: Output .sph file must be a file, not a pipe"); return SOX_EOF; }
  return write_header(ft);
}

static int stopwrite(sox_format_t *ft)
{
  if (lsx_seeki(ft, 0, SEEK_SET)) return SOX_EOF;
  return write_header(ft);
}

const sox_format_handler_t *lsx_sphere_format_fn(void)
{
  static const char *const names[] = {"sph", "nist", NULL};
  static const unsigned write_encodings[] = {SOX_ENCODING_SIGN2, 8, 16, 24, 32, 0, SOX_ENCODING_ULAW, 8, 0, 0};
  static const sox_format_handler_t handler = {
    "SPeech HEader Resources; defined by NIST", names, SOX_FILE_LIT_END | SOX_FILE_REWIND,
    startread, read_samples, NULL, startwrite, lsx_rawwrite, stopwrite, lsx_rawseek, write_encodings, NULL, sizeof(priv_t) };
  return &handler;
}
