  }
  if (!found_vhdr) { lsx_fail_errno(ft, SOX_EHDR, "Missing VHDR chunk"); return SOX_EOF; }
  if (!bodysize) { lsx_fail_errno(ft, SOX_EHDR, "Missing BODY chunk"); return SOX_EOF; }
  if (rate == 0) { lsx_fail_errno(ft, SOX_EHDR, "Sample rate is zero"); return SOX_EOF; }
  ft->signal.channels = channels;
  ft->signal.rate = rate;
  ft->encoding.encoding = SOX_ENCODING_SIGN2;
  ft->encoding.bits_per_sample = 8;
  p->nsamples = bodysize;
  ft->signal.length = bodysize;
  /* read planar body and interleave */
  if (ft->seekable) lsx_seeki(ft, (int64_t)body_start, SEEK_SET);
  {
    int8_t *raw = lsx_malloc(bodysize);
    size_t got = (size_t)lsx_readbuf(ft, raw, bodysize), per = bodysize / channels, i;
    unsigned c;
    p->data = lsx_malloc(bodysize * sizeof(sox_sample_t));
    for (i = 0; i < per; ++i) for (c = 0; c < channels; ++c) {
      size_t idx = c * per + i;
      p->data[i * channels + c] = idx < got ? (sox_sample_t)raw[idx] << 24 : 0;
    }
    free(raw);
    if (got < bodysize) lsx_warn("Premature EOF in 8SVX body");
  }
  p->read_pos = 0;
  return SOX_SUCCESS;
}

static size_t svx_read(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  svx_t *p = (svx_t *)ft->priv;
  size_t avail = p->nsamples - p->read_pos;
  if (len > avail) len = avail;
  memcpy(buf, p->data + p->read_pos, len * sizeof(*buf));
  p->read_pos += (uint32_t)len;
  return len;
}

static int svx_stopread(sox_format_t *ft) { svx_t *p = (svx_t *)ft->priv; free(p->data); p->data = NULL; return SOX_SUCCESS; }

static int svx_startwrite(sox_format_t *ft)
{
  svx_t *p = (svx_t *)ft->priv;
  unsigned c;
  if (!ft->seekable) { lsx_fail_errno(ft, SOX_EOF, "Output .8svx file must be a file, not a pipe"); return SOX_EOF; }
  p->ch = lsx_calloc(ft->signal.channels, sizeof(*p->ch));
  p->ch_len = lsx_calloc(ft->signal.channels, sizeof(*p->ch_len));
  p->ch_cap = lsx_calloc(ft->signal.channels, sizeof(*p->ch_cap));
  for (c = 0; c < ft->signal.channels; ++c) { p->ch_cap[c] = 8192; p->ch[c] = lsx_malloc(p->ch_cap[c]); }
  p->nsamples = 0;
  return SOX_SUCCESS;
}

static size_t svx_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  svx_t *p = (svx_t *)ft->priv;
  size_t i;
  unsigned c = 0;
  SOX_SAMPLE_LOCALS;
  for (i = 0; i < len; ++i) {
    if (p->ch_len[c] == p->ch_cap[c]) { p->ch_cap[c] *= 2; p->ch[c] = lsx_realloc(p->ch[c], p->ch_cap[c]); }
    p->ch[c][p->ch_len[c]++] = (int8_t)SOX_SAMPLE_TO_SIGNED_8BIT(buf[i], ft->clips);
    c = (c + 1) % ft->signal.channels;
  }
  p->nsamples += (uint32_t)len;
  return len;
}

static void svx_write_header(sox_format_t *ft, uint32_t nsamples)
{
  char *comment = lsx_cat_comments(ft->oob.comments);
  size_t clen = strlen(comment), cpad = clen & 1;
  uint32_t formsize = 4 + 8 + 20 + 8 + (uint32_t)(clen + cpad) + 8 + 4 + 8 + ((nsamples + 1) & ~1u);
  uint32_t chan = ft->signal.channels == 1 ? 2 : ft->signal.channels == 2 ? 6 : 15;
  lsx_writes(ft, "FORM"); lsx_writedw(ft, formsize); lsx_writes(ft, "8SVX");
  lsx_writes(ft, "VHDR"); lsx_writedw(ft, 20);
  lsx_writedw(ft, nsamples / ft->signal.channels); lsx_writedw(ft, 0); lsx_writedw(ft, 0);
  lsx_writew(ft, (unsigned)(ft->signal.rate + .5)); lsx_writeb(ft, 1); lsx_writeb(ft, 0); lsx_writedw(ft, 1 << 16);
  lsx_writes(ft, "ANNO"); lsx_writedw(ft, (unsigned)clen); lsx_writes(ft, comment); if (cpad) lsx_writeb(ft, 0);
  lsx_writes(ft, "CHAN"); lsx_writedw(ft, 4); lsx_writedw(ft, chan);
  lsx_writes(ft, "BODY"); lsx_writedw(ft, nsamples);
  free(comment);
}

static int svx_stopwrite(sox_format_t *ft)
{
  svx_t *p = (svx_t *)ft->priv;
  unsigned c;
  svx_write_header(ft, p->nsamples);
  for (c = 0; c < ft->signal.channels; ++c) { lsx_writebuf(ft, p->ch[c], p->ch_len[c]); free(p->ch[c]); }
  if (p->nsamples & 1) lsx_writeb(ft, 0);
  free(p->ch); free(p->ch_len); free(p->ch_cap);
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_svx_format_fn(void)
{
  static const char *const names[] = {"8svx", NULL};
  static const unsigned write_encodings[] = {SOX_ENCODING_SIGN2, 8, 0, 0};
  static const sox_format_handler_t handler = {
    "Amiga audio format (a subformat of the Interchange File Format)", names, SOX_FILE_BIG_END | SOX_FILE_MONO | SOX_FILE_STEREO | SOX_FILE_QUAD,
    svx_startread, svx_read, svx_stopread, svx_startwrite, svx_write, svx_stopwrite, NULL, write_encodings, NULL, sizeof(svx_t) };
