}

/* ---------------- MAUD ---------------- */
typedef struct { uint32_t nsamples; } maud_t;

static int maud_startread(sox_format_t *ft)
{
  maud_t *p = (maud_t *)ft->priv;
  char buf[12];
  uint32_t trash32, chunksize, nom, denom = 1, samples = 0;
  uint16_t bitpersam = 0, trash16, chaninf = 0, compression = 0;
  int found_mdat = 0;
  if (lsx_readchars(ft, buf, 4) || strncmp(buf, "FORM", 4) != 0) { lsx_fail_errno(ft, SOX_EHDR, "MAUD: header does not begin with magic word `FORM'"); return SOX_EOF; }
  lsx_readdw(ft, &trash32);
  if (lsx_readchars(ft, buf, 4) || strncmp(buf, "MAUD", 4) != 0) { lsx_fail_errno(ft, SOX_EHDR, "MAUD: `FORM' chunk does not specify `MAUD' as type"); return SOX_EOF; }
  while (1) {
    if (lsx_readchars(ft, buf, 4)) { lsx_fail_errno(ft, SOX_EHDR, "MAUD: missing MDAT chunk"); return SOX_EOF; }
    if (lsx_readdw(ft, &chunksize)) return SOX_EOF;
    if (strncmp(buf, "MHDR", 4) == 0) {
      if (chunksize != 8 * 4) { lsx_fail_errno(ft, SOX_EHDR, "MAUD: MHDR chunk has bad size"); return SOX_EOF; }
      lsx_readdw(ft, &samples);
      lsx_readw(ft, &bitpersam);
      lsx_readw(ft, &trash16);
      lsx_readdw(ft, &nom);
      lsx_readw(ft, (uint16_t *)&trash16); denom = trash16;
      lsx_readw(ft, &chaninf);
      lsx_readw(ft, &trash16);
      lsx_readw(ft, &compression);
      lsx_readdw(ft, &trash32); lsx_readdw(ft, &trash32); lsx_readdw(ft, &trash32);
      if (denom == 0) denom = 1;
      ft->signal.rate = (double)nom / denom;
      ft->signal.channels = chaninf == 0 ? 1 : 2;
      if (bitpersam == 8 && compression == 0) { ft->encoding.encoding = SOX_ENCODING_UNSIGNED; ft->encoding.bits_per_sample = 8; }
      else if (bitpersam == 8 && compression == 2) { ft->encoding.encoding = SOX_ENCODING_ALAW; ft->encoding.bits_per_sample = 8; }
      else if (bitpersam == 8 && compression == 3) { ft->encoding.encoding = SOX_ENCODING_ULAW; ft->encoding.bits_per_sample = 8; }
      else if (bitpersam == 16 && compression == 0) { ft->encoding.encoding = SOX_ENCODING_SIGN2; ft->encoding.bits_per_sample = 16; }
      else { lsx_fail_errno(ft, SOX_EFMT, "MAUD: unsupported compression type detected"); return SOX_EOF; }
      p->nsamples = samples;
      ft->signal.length = samples;
    } else if (strncmp(buf, "ANNO", 4) == 0) {
      char *text = lsx_calloc(1, chunksize + 1);
      lsx_readchars(ft, text, chunksize);
      if (chunksize & 1) lsx_skipbytes(ft, 1);
      if (*text) lsx_append_comments(&ft->oob.comments, text);
      free(text);
    } else if (strncmp(buf, "MDAT", 4) == 0) { found_mdat = 1; break; }
    else lsx_skipbytes(ft, (chunksize + 1) & ~1u);
  }
  if (!found_mdat) { lsx_fail_errno(ft, SOX_EHDR, "MAUD: missing MDAT chunk"); return SOX_EOF; }
  return lsx_rawstartread(ft);
}

static size_t maud_read(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  maud_t *p = (maud_t *)ft->priv;
  if (p->nsamples && len > p->nsamples) len = p->nsamples;
  len = lsx_rawread(ft, buf, len);
  if (p->nsamples) p->nsamples -= (uint32_t)len;
  return len;
}

static void maud_write_header(sox_format_t *ft, uint32_t nsamples)
{
  char *comment = lsx_cat_comments(ft->oob.comments);
  size_t clen = strlen(comment), cpad = clen & 1;
  uint32_t datasize = nsamples * (ft->encoding.bits_per_sample >> 3);
  uint32_t formsize = 4 + 8 + 32 + 8 + (uint32_t)(clen + cpad) + 8 + ((datasize + 1) & ~1u);
  lsx_writes(ft, "FORM"); lsx_writedw(ft, formsize); lsx_writes(ft, "MAUD");
  lsx_writes(ft, "MHDR"); lsx_writedw(ft, 32);
  lsx_writedw(ft, nsamples);
  lsx_writew(ft, ft->encoding.bits_per_sample);
  lsx_writew(ft, ft->encoding.bits_per_sample);
  lsx_writedw(ft, (unsigned)(ft->signal.rate + .5));
  lsx_writew(ft, 1);
  lsx_writew(ft, ft->signal.channels == 1 ? 0 : 1);
  lsx_writew(ft, ft->signal.channels);
  lsx_writew(ft, ft->encoding.encoding == SOX_ENCODING_ALAW ? 2 : ft->encoding.encoding == SOX_ENCODING_ULAW ? 3 : 0);
  lsx_writedw(ft, 0); lsx_writedw(ft, 0); lsx_writedw(ft, 0);
  lsx_writes(ft, "ANNO"); lsx_writedw(ft, (unsigned)clen); lsx_writes(ft, comment); if (cpad) lsx_writeb(ft, 0);
  lsx_writes(ft, "MDAT"); lsx_writedw(ft, datasize);
  free(comment);
}

static int maud_startwrite(sox_format_t *ft)
{
  maud_t *p = (maud_t *)ft->priv;
  int rc = lsx_rawstartwrite(ft);
  if (rc) return rc;
  if (!ft->seekable) { lsx_fail_errno(ft, SOX_EOF, "Output .maud file must be a file, not a pipe"); return SOX_EOF; }
  p->nsamples = 0;
  maud_write_header(ft, 0);
  return SOX_SUCCESS;
}

static size_t maud_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  maud_t *p = (maud_t *)ft->priv;
  p->nsamples += (uint32_t)len;
  return lsx_rawwrite(ft, buf, len);
}

static int maud_stopwrite(sox_format_t *ft)
{
  maud_t *p = (maud_t *)ft->priv;
  if ((p->nsamples * (ft->encoding.bits_per_sample >> 3)) & 1) lsx_writeb(ft, 0);
  if (lsx_seeki(ft, 0, SEEK_SET)) { lsx_fail_errno(ft, SOX_EOF, "can't rewind output file to rewrite MAUD header"); return SOX_EOF; }
  maud_write_header(ft, p->nsamples);
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_maud_format_fn(void)
{
  static const char *const names[] = {"maud", NULL};
  static const unsigned write_encodings[] = {SOX_ENCODING_SIGN2, 16, 0, SOX_ENCODING_UNSIGNED, 8, 0, SOX_ENCODING_ULAW, 8, 0, SOX_ENCODING_ALAW, 8, 0, 0};
  static const sox_format_handler_t handler = {
    "Used with the \342\200\230Toccata\342\200\231 sound-card on the Amiga", names, SOX_FILE_BIG_END | SOX_FILE_MONO | SOX_FILE_STEREO,
    maud_startread, maud_read, NULL, maud_startwrite, maud_write, maud_stopwrite, NULL, write_encodings, NULL, sizeof(maud_t) };
  return &handler;
}
