  while (1) {
    if (lsx_readchars(ft, buf, 4)) { if (bodysize) break; lsx_fail_errno(ft, SOX_EHDR, "Missing BODY chunk"); return SOX_EOF; }
    if (lsx_readdw(ft, &chunksize)) break;
    if (strncmp(buf, "VHDR", 4) == 0) {
      uint32_t d; uint8_t b;
      lsx_readdw(ft, &d); lsx_readdw(ft, &d); lsx_readdw(ft, &d);
