#define min_sample -0x8000
#define max_sample 0x7fff

int lsx_adpcm_decode(int code, adpcm_t *state)
{
  int s = ((code & (state->setup.sign - 1)) << 1) | 1;
  s = ((state->setup.steps[state->step_index] * s) >> (state->setup.shift + 2)) & ~0;
  /* oki: step*s/8 ; ima: step*s/8 effectively (shift+3?) */
  s = (state->setup.steps[state->step_index] * (((code & (state->setup.sign - 1)) << 1) | 1)) >> 3;
