{
  int delta = sample - state->last_output;
  int sign = 0;
  int code;
  if (delta < 0) { sign = state->setup.sign; delta = -delta; }
  code = 4 * delta / state->setup.steps[state->step_index];
  code = code > 7 ? 7 : code;
  code |= sign;
  lsx_adpcm_decode(code, state);
