int lsx_adpcm_ima_start(sox_format_t *ft, adpcm_io_t *state) { return adpcm_start(ft, state, SOX_ENCODING_IMA_ADPCM); }

size_t lsx_adpcm_read(sox_format_t *ft, adpcm_io_t *state, sox_sample_t *buffer, size_t len)
{
  size_t n = 0;
  uint8_t byte;
  SOX_SAMPLE_LOCALS;
  if (len && state->store.flag) {
    *buffer++ = SOX_SIGNED_16BIT_TO_SAMPLE(lsx_adpcm_decode(state->store.byte, &state->encoder), ft->clips);
    state->store.flag = 0;
    ++n;
  }
  while (n < len && lsx_read_b_buf(ft, &byte, (size_t)1) == 1) {
    ++n;
    *buffer++ = SOX_SIGNED_16BIT_TO_SAMPLE(lsx_adpcm_decode(byte >> 4, &state->encoder), ft->clips);
    byte &= 0xf;
    if (n < len) {
      *buffer++ = SOX_SIGNED_16BIT_TO_SAMPLE(lsx_adpcm_decode(byte, &state->encoder), ft->clips);
      ++n;
    } else { state->store.byte = byte; state->store.flag = 1; }
  }
  return n;
}

int lsx_adpcm_stopread(sox_format_t *ft, adpcm_io_t *state)
{
  if (state->encoder.errors) lsx_warn("%s: ADPCM state errors: %u", ft->filename, state->encoder.errors);
  return SOX_SUCCESS;
}

size_t lsx_adpcm_write(sox_format_t *ft, adpcm_io_t *state, const sox_sample_t *buffer, size_t length)
{
  size_t count = 0;
  uint8_t byte = state->store.byte;
  uint8_t flag = state->store.flag;
  SOX_SAMPLE_LOCALS;
  while (count < length) {
    int16_t word = (int16_t)SOX_SAMPLE_TO_SIGNED_16BIT(*buffer++, ft->clips);
    int code = lsx_adpcm_encode(word, &state->encoder);
    if (flag) {
      byte |= (uint8_t)code;
      lsx_writeb(ft, byte);
      byte = 0; flag = 0;
    } else { byte = (uint8_t)(code << 4); flag = 1; }
    count++;
  }
  state->store.byte = byte;
  state->store.flag = flag;
  return count;
}

void lsx_adpcm_flush(sox_format_t *ft, adpcm_io_t *state)
{
  if (state->store.flag) { lsx_writeb(ft, state->store.byte); state->store.flag = 0; state->store.byte = 0; }
}

int lsx_adpcm_stopwrite(sox_format_t *ft, adpcm_io_t *state)
{
  lsx_adpcm_flush(ft, state);
  return SOX_SUCCESS;
}

