/* ---------------- gsrt (Grandstream ring tone) ---------------- */
#define GSRT_HDR 512
typedef struct { uint64_t num_samples; } gsrt_t;
static int gsrt_startread(sox_format_t *ft)
{
  char buf[24];
  uint32_t enc;
  if (lsx_readchars(ft, buf, 24)) return SOX_EOF;
  if (memcmp(buf + 16, "ring.bin", 8)) { lsx_fail_errno(ft, SOX_EHDR, "gsrt: can't find Grandstream ring tone identifier"); return SOX_EOF; }
  if (lsx_readdw(ft, &enc) || lsx_skipbytes(ft, GSRT_HDR - 28)) return SOX_EOF;
  if (enc != 0 && enc != 1) { lsx_fail_errno(ft, SOX_EFMT, "gsrt: unsupported encoding %u", enc); return SOX_EOF; }
  return lsx_check_read_params(ft, 1, 8000., enc == 0 ? SOX_ENCODING_ALAW : SOX_ENCODING_ULAW, 8, (uint64_t)0, sox_true);
