  memcpy(buf + 16, "ring.bin", 8);
  buf[24] = (char)enc;
  buf[28] = (char)(len); buf[29] = (char)(len >> 8); buf[30] = (char)(len >> 16); buf[31] = (char)(len >> 24);
  return lsx_writebuf(ft, buf, GSRT_HDR) == GSRT_HDR ? SOX_SUCCESS : SOX_EOF;
