/* ---------------- prc (Psion Record) ---------------- */
typedef struct { uint32_t nsamples; uint32_t nbytes; adpcm_io_t adpcm; sox_bool is_adpcm; off_t data_start; } prc_t;
static const unsigned char prc_header[] = { 0x37, 0x00, 0x00, 0x10, 0x6d, 0x00, 0x00, 0x10, 0x7e, 0x00, 0x00, 0x10 };
#define PRC_HDR 64
static int prc_startread(sox_format_t *ft)
{
  prc_t *p = (prc_t *)ft->priv;
  unsigned char hdr[PRC_HDR];
  uint32_t enc, nbytes, nsamples;
  if (lsx_readbuf(ft, hdr, PRC_HDR) != PRC_HDR) { lsx_fail_errno(ft, SOX_EHDR, "prc: unexpected EOF in header"); return SOX_EOF; }
  if (memcmp(hdr, prc_header, sizeof prc_header)) { lsx_fail_errno(ft, SOX_EHDR, "prc: not a Psion record file"); return SOX_EOF; }
  enc = hdr[16] | (hdr[17] << 8) | (hdr[18] << 16) | ((uint32_t)hdr[19] << 24);
  nbytes = hdr[20] | (hdr[21] << 8) | (hdr[22] << 16) | ((uint32_t)hdr[23] << 24);
  nsamples = hdr[24] | (hdr[25] << 8) | (hdr[26] << 16) | ((uint32_t)hdr[27] << 24);
  p->nbytes = nbytes; p->nsamples = nsamples;
  if (enc == 0) {
    p->is_adpcm = sox_false;
    return lsx_check_read_params(ft, 1, 8000., SOX_ENCODING_ALAW, 8, (uint64_t)nbytes, sox_false);
  } else if (enc == 1) {
    p->is_adpcm = sox_true;
    ft->signal.rate = 8000; ft->signal.channels = 1;
    lsx_adpcm_ima_start(ft, &p->adpcm);
    ft->signal.length = nsamples;
    return SOX_SUCCESS;
  }
  lsx_fail_errno(ft, SOX_EFMT, "prc: unknown encoding");
  return SOX_EOF;
}
static size_t prc_read(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  prc_t *p = (prc_t *)ft->priv;
  if (p->is_adpcm) {
    if (len > p->nsamples) len = p->nsamples;
    len = lsx_adpcm_read(ft, &p->adpcm, buf, len);
    p->nsamples -= (uint32_t)len;
    return len;
  }
  return lsx_rawread(ft, buf, len);
}
static int prc_write_header(sox_format_t *ft)
{
  prc_t *p = (prc_t *)ft->priv;
  unsigned char hdr[PRC_HDR];
  uint32_t enc = ft->encoding.encoding == SOX_ENCODING_ALAW ? 0 : 1;
  memset(hdr, 0, sizeof hdr);
  memcpy(hdr, prc_header, sizeof prc_header);
  hdr[16] = (unsigned char)enc;
  hdr[20] = p->nbytes; hdr[21] = p->nbytes >> 8; hdr[22] = p->nbytes >> 16; hdr[23] = p->nbytes >> 24;
  hdr[24] = p->nsamples; hdr[25] = p->nsamples >> 8; hdr[26] = p->nsamples >> 16; hdr[27] = p->nsamples >> 24;
  return lsx_writebuf(ft, hdr, PRC_HDR) == PRC_HDR ? SOX_SUCCESS : SOX_EOF;
}
static int prc_startwrite(sox_format_t *ft)
{
  prc_t *p = (prc_t *)ft->priv;
  p->nbytes = p->nsamples = 0;
  p->is_adpcm = ft->encoding.encoding == SOX_ENCODING_IMA_ADPCM;
  if (p->is_adpcm) lsx_adpcm_reset(&p->adpcm, SOX_ENCODING_IMA_ADPCM);
  return prc_write_header(ft);
}
static size_t prc_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  prc_t *p = (prc_t *)ft->priv;
  p->nsamples += (uint32_t)len;
  if (p->is_adpcm) { p->nbytes += (uint32_t)((len + 1) / 2); return lsx_adpcm_write(ft, &p->adpcm, buf, len); }
