  return lsx_rawwrite(ft, buf, len);
}
static int prc_stopwrite(sox_format_t *ft)
{
  prc_t *p = (prc_t *)ft->priv;
  if (p->is_adpcm) lsx_adpcm_flush(ft, &p->adpcm);
  if (!ft->seekable) return SOX_SUCCESS;
  if (lsx_seeki(ft, 0, SEEK_SET)) return SOX_EOF;
  return prc_write_header(ft);
}
