typedef struct {
  uint32_t datasize;
  uint32_t bytesDecoded;
  struct { int32_t curSample, prevSample; int c1, c2, shift; } *state;
  unsigned char *buf;
  size_t bufPos;
  unsigned blocksize;
} xa_t;
static const int xa_K0[4] = {0, 240, 460, 392};
static const int xa_K1[4] = {0, 0, -208, -220};
static int xa_startread(sox_format_t *ft)
{
  xa_t *xa = (xa_t *)ft->priv;
  char magic[4];
  uint32_t datasize, rate;
  uint16_t tag, channels, blockalign, bits;
  uint32_t avgbytes;
  if (lsx_readchars(ft, magic, 4)) return SOX_EOF;
  if (memcmp(magic, "XA\0\0", 4) && memcmp(magic, "XAI\0", 4) && memcmp(magic, "XAJ\0", 4)) { lsx_fail_errno(ft, SOX_EHDR, "XA: Header not found"); return SOX_EOF; }
  lsx_readdw(ft, &datasize);
  lsx_readw(ft, &tag); lsx_readw(ft, &channels); lsx_readdw(ft, &rate); lsx_readdw(ft, &avgbytes); lsx_readw(ft, &blockalign); lsx_readw(ft, &bits);
  if (tag != 1 || bits != 16) { lsx_fail_errno(ft, SOX_EFMT, "XA: unsupported format"); return SOX_EOF; }
  if (!channels) { lsx_fail_errno(ft, SOX_EFMT, "XA: zero channels"); return SOX_EOF; }
  xa->datasize = datasize;
  xa->blocksize = 15 * channels;
  xa->state = lsx_calloc(channels, sizeof(*xa->state));
  xa->buf = lsx_malloc(xa->blocksize);
  xa->bufPos = xa->blocksize;
  xa->bytesDecoded = 0;
  ft->signal.channels = channels; ft->signal.rate = rate;
  ft->encoding.encoding = SOX_ENCODING_SIGN2; ft->encoding.bits_per_sample = 16;
  ft->signal.length = (uint64_t)datasize / 2;
  return SOX_SUCCESS;
}
static size_t xa_read(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  xa_t *xa = (xa_t *)ft->priv;
