  while (done + ch <= len && xa->bytesDecoded < xa->datasize) {
    if (xa->bufPos >= xa->blocksize) {
      if (lsx_readbuf(ft, xa->buf, xa->blocksize) != (int)xa->blocksize) break;
      xa->bufPos = 0;
      for (c = 0; c < ch; ++c) {
        unsigned char b = xa->buf[c];
        xa->state[c].c1 = xa_K0[b >> 4]; xa->state[c].c2 = xa_K1[b >> 4]; xa->state[c].shift = (b & 15) + 8;
      }
      xa->bufPos = ch;
    }
    {
      size_t byteIdx = xa->bufPos;
      int nib;
      for (nib = 0; nib < 2 && done + ch <= len; ++nib) {
        for (c = 0; c < ch; ++c) {
          unsigned char b = xa->buf[byteIdx + c];
          int32_t d = nib == 0 ? (b >> 4) : (b & 15);
          int32_t s;
