static size_t read_samples(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  priv_t *p = (priv_t *)ft->priv;
  int done = 0;
  unsigned char sample_rate;
  SOX_SAMPLE_LOCALS;
  if (p->nrbits < 0) {
    if (lsx_readb(ft, &sample_rate)) return 0;
    p->sample = sample_rate;
    *buf++ = SOX_UNSIGNED_8BIT_TO_SAMPLE(p->sample, ft->clips);
    p->huffcount--;
    p->nrbits = 0;
    done++;
