#define lsx_subsystem_name "cvsd"
#include "sox.h"

typedef struct {
  double step, integrator, filt;
  unsigned char bits;
  int nbits;
  unsigned shift_reg;
  sox_bool filtered;
  uint64_t nsamples;
} priv_t;

static int cvsd_start(sox_format_t *ft, sox_bool filtered)
{
  priv_t *p = (priv_t *)ft->priv;
  if (!ft->signal.rate) ft->signal.rate = 8000;
  ft->signal.channels = 1;
  ft->encoding.encoding = SOX_ENCODING_CVSD;
  ft->encoding.bits_per_sample = 1;
  p->step = 0.01; p->integrator = 0; p->filt = 0; p->bits = 0; p->nbits = 0; p->shift_reg = 0;
  p->filtered = filtered;
  p->nsamples = 0;
  return SOX_SUCCESS;
}
static int cvsd_startread(sox_format_t *ft) { int r = cvsd_start(ft, sox_true); if (r == SOX_SUCCESS) { ft->signal.length = lsx_filelength(ft) * 8; if (ft->seekable) ft->data_start = lsx_tell(ft); } return r; }
static int cvu_startread(sox_format_t *ft) { int r = cvsd_start(ft, sox_false); if (r == SOX_SUCCESS) { ft->signal.length = lsx_filelength(ft) * 8; if (ft->seekable) ft->data_start = lsx_tell(ft); } return r; }
static int cvsd_startwrite(sox_format_t *ft) { return cvsd_start(ft, sox_true); }
static int cvu_startwrite(sox_format_t *ft) { return cvsd_start(ft, sox_false); }

static void adapt(priv_t *p, int bit)
{
  p->shift_reg = ((p->shift_reg << 1) | bit) & 7;
  if (p->shift_reg == 7 || p->shift_reg == 0) p->step = min(p->step * 1.1 + 0.002, 0.5);
  else p->step = max(p->step * 0.95, 0.002);
}

static double decode_bit(priv_t *p, int bit)
{
  adapt(p, bit);
  p->integrator += bit ? p->step : -p->step;
  p->integrator *= 0.999;
  if (p->integrator > 1) p->integrator = 1; else if (p->integrator < -1) p->integrator = -1;
  if (p->filtered) { p->filt = p->filt * 0.7 + p->integrator * 0.3; return p->filt; }
  return p->integrator;
}

static size_t cvsd_read(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  priv_t *p = (priv_t *)ft->priv;
  size_t done = 0;
  SOX_SAMPLE_LOCALS;
  while (done < len) {
    int bit;
    if (p->nbits == 0) { if (lsx_readb(ft, &p->bits)) break; p->nbits = 8; }
    bit = (p->bits >> 7) & 1; p->bits <<= 1; p->nbits--;
    buf[done++] = SOX_FLOAT_64BIT_TO_SAMPLE(decode_bit(p, bit), ft->clips);
  }
  return done;
}

static size_t cvsd_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  priv_t *p = (priv_t *)ft->priv;
  size_t i;
  SOX_SAMPLE_LOCALS;
  for (i = 0; i < len; ++i) {
    double d = SOX_SAMPLE_TO_FLOAT_64BIT(buf[i], ft->clips);
    int bit = d > p->integrator;
    decode_bit(p, bit);
    p->bits = (unsigned char)((p->bits << 1) | bit);
    if (++p->nbits == 8) { lsx_writeb(ft, p->bits); p->nbits = 0; p->bits = 0; }
    p->nsamples++;
  }
  return len;
}

static int cvsd_stopwrite(sox_format_t *ft)
{
  priv_t *p = (priv_t *)ft->priv;
  if (p->nbits) { p->bits <<= (8 - p->nbits); lsx_writeb(ft, p->bits); p->nbits = 0; }
  return SOX_SUCCESS;
}

