  ft->signal.channels = 1;
  ft->encoding.encoding = SOX_ENCODING_CVSD;
  ft->encoding.bits_per_sample = 1;
  p->step = 0.01; p->integrator = 0; p->filt = 0; p->bits = 0; p->nbits = 0; p->shift_reg = 0;
