static void adapt(priv_t *p, int bit)
{
  p->shift_reg = ((p->shift_reg << 1) | bit) & 7;
  if (p->shift_reg == 7 || p->shift_reg == 0) p->step = min(p->step * 1.1 + 0.002, 0.5);
  else p->step = max(p->step * 0.95, 0.002);
}

static double decode_bit(priv_t *p, int bit)
{
  adapt(p, bit);
  p->integrator += bit ? p->step : -p->step;
  p->integrator *= 0.999;
  if (p->integrator > 1) p->integrator = 1; else if (p->integrator < -1) p->integrator = -1;
  if (p->filtered) { p->filt = p->filt * 0.7 + p->integrator * 0.3; return p->filt; }
  return p->integrator;
}

static size_t cvsd_read(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  priv_t *p = (priv_t *)ft->priv;
  size_t done = 0;
  SOX_SAMPLE_LOCALS;
  while (done < len) {
    int bit;
    if (p->nbits == 0) { if (lsx_readb(ft, &p->bits)) break; p->nbits = 8; }
    bit = (p->bits >> 7) & 1; p->bits <<= 1; p->nbits--;
    buf[done++] = SOX_FLOAT_64BIT_TO_SAMPLE(decode_bit(p, bit), ft->clips);
  }
  return done;
}

static size_t cvsd_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  priv_t *p = (priv_t *)ft->priv;
  size_t i;
  SOX_SAMPLE_LOCALS;
  for (i = 0; i < len; ++i) {
    double d = SOX_SAMPLE_TO_FLOAT_64BIT(buf[i], ft->clips);
    int bit = d > p->integrator;
    decode_bit(p, bit);
    p->bits = (unsigned char)((p->bits << 1) | bit);
    if (++p->nbits == 8) { lsx_writeb(ft, p->bits); p->nbits = 0; p->bits = 0; }
    p->nsamples++;
  }
  return len;
}

