    int64_t off0 = newest - (base + half);   /* offset from newest of tap 0's sample */
    const double *x = &HIST(p, off0);        /* x[-j] is the sample for tap j */
    if (p->interp_phases) for (j = 0; j < p->tpp; ++j) sum += x[-j] * (c0[j] + (c1[j] - c0[j]) * pfrac);
